pub(crate) fn bounded_compaction_timestamps(mut timestamps: Vec<String>) -> Vec<String> {
    timestamps.sort();
    timestamps.dedup();
    if timestamps.len() > MAX_COMPACTION_TIMESTAMPS {
        timestamps.split_off(timestamps.len() - MAX_COMPACTION_TIMESTAMPS)
    } else {
        timestamps
    }
}

