#[derive(Debug, Clone)]
struct CandidateFile {
    physical_identity: Option<[u64; 2]>,
    scan_root: PathBuf,
    path: PathBuf,
    size_bytes: u64,
    modified_unix_seconds: u64,
    modified_unix_nanos: u64,
    source_file_fingerprint: String,
    legacy_source_file_fingerprint: String,
    legacy_config_reconciliation_required: bool,
    opened_object_identity: String,
    /// The ctime (unix nanos) in the opened-object identity that
    /// `source_file_fingerprint` used: the live one, or the entry's stored
    /// one when size, mtime and birth are unchanged.
    fingerprint_changed_nanos: u64,
    /// The live file birth (unix nanos) of that open; zero if unavailable.
    fingerprint_birth_nanos: u64,
    /// A withheld-account held key's re-read stamp: content and account
    /// evidence only, never mtime or ctime (`withheld_account.rs`).
    withheld_content_stamp: Option<String>,
}

/// The object inputs of one opened-object identity (unix device, inode and
/// ctime), plus the birth and mtime the content-only re-read rule checks.
/// Never persisted: entries keep only the ctime and birth. A later open of
/// the same object rebuilds
/// the identity from its live device and inode, that stored ctime and fresh
/// content samples, so a ctime-only change (chmod, xattr, hard link,
/// Spotlight, backup) reproduces the stored identity and never triggers a
/// re-read on its own. A wrong or missing stored ctime only causes a read.
/// Device and inode stay triggers (they are hashed live); birth binds the
/// stored ctime to its object generation (a reused inode, even after a clock
/// rollback, has another birth; an unavailable birth never adopts); mtime
/// stays a trigger: it moves only on content writes (truncate/regrow too).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OpenedObjectStat {
    device: u64,
    inode: u64,
    changed_seconds: i64,
    changed_nanos: i64,
    birth_nanos: Option<u64>,
    modified_nanos: Option<u64>,
}

impl OpenedObjectStat {
    /// The ctime as unix nanos; zero (no stored ctime) if not representable.
    fn changed_unix_nanos(&self) -> u64 {
        u64::try_from(self.changed_seconds)
            .ok()
            .and_then(|seconds| seconds.checked_mul(1_000_000_000))
            .zip(u64::try_from(self.changed_nanos).ok())
            .and_then(|(seconds, nanos)| seconds.checked_add(nanos))
            .unwrap_or_default()
    }

    /// This object with the ctime of a stored `changed_unix_nanos`.
    fn with_changed_unix_nanos(self, changed_unix_nanos: u64) -> Self {
        Self {
            changed_seconds: (changed_unix_nanos / 1_000_000_000) as i64,
            changed_nanos: (changed_unix_nanos % 1_000_000_000) as i64,
            ..self
        }
    }

    /// A stored ctime belongs to this object generation only if its stored
    /// birth is known and exactly the live one. Ordering against ctime is no
    /// binding (clock rollback, reused inodes); unavailable never binds.
    fn same_birth(&self, stored_birth_nanos: u64) -> bool {
        stored_birth_nanos != 0 && self.birth_nanos == Some(stored_birth_nanos)
    }
}

#[derive(Debug, Default)]
struct ScanCensus {
    causes: ownership::Counts,
    #[cfg(test)]
    discovered_file_count: usize,
    directory_entry_cap_exceeded_count: usize,
    symlink_rejected_count: usize,
    unreadable_path_count: usize,
    unreadable_causes: UnreadableCauses,

    oversized_file_count: usize,
    disappeared_file_count: usize,
    malformed_json_line_count: usize,
    invalid_utf8_line_count: usize,
    over_line_cap_count: usize,
    recognized_usage_drop_count: usize,
    ownership_incomplete_file_count: usize,
    zero_snapshot_usage_evidence_count: usize,
    dropped_usage_record_count: u64,
    terminal_over_line_cap_count: usize,
    terminal_recognized_usage_drop_count: usize,
    terminal_dropped_usage_record_count: u64,
    observed_index_keys: BTreeSet<String>,
    removed_index_keys: BTreeSet<String>,
    /// The subset of `removed_index_keys` that are Claude census members
    /// found absent beneath a still-present parent (N). Only these may drop
    /// their unverified audit debt with their entry at the page merge.
    claude_vanished_index_keys: BTreeSet<String>,
    /// Count-only parse-selection reasons for this page's candidates. A scan
    /// object has one source; Claude and Codex count here, nothing else does.
    parse_reasons: [usize; CANDIDATE_PARSE_REASON_COUNT],
    /// Count-only Codex selections that carry no `CandidateParseReason`.
    codex_selections: [usize; CODEX_SELECTION_COUNT],
    /// Local-only V2 counting receipts of this scan's finished parses. Boxed
    /// so the census moved through every scan step stays small; allocated
    /// only once a configured counting parse finishes.
    codex_counting_v2: Option<Box<crate::codex_scan_diagnostics::CountingV2Receipts>>,
    /// Count-only: parsed Claude compaction summaries on this page whose
    /// `parentUuid` chain never reached a boundary. Logged, never a decision.
    claude_compaction_unlinked_parent_count: usize,
    /// Count-only: this page's paced growth reads (see `ScanTraversalCounts`).
    growth_deferred: u64,
}

/// Preserve the old scope/open/object short-circuit and its one existing open.
fn sampled_revalidation_cause(
    scope_matches: bool,
    revalidate: impl FnOnce() -> std::io::Result<bool>,
) -> Option<UnreadableCause> {
    if !scope_matches {
        return Some(UnreadableCause::ScopeObject);
    }
    match revalidate() {
        Ok(true) => None,
        Ok(false) => Some(UnreadableCause::ScopeObject),
        Err(_) => Some(UnreadableCause::OpenRead),
    }
}

impl ScanCensus {
    /// Count-only: one Codex selection outcome. An override names why a
    /// skipped candidate was parsed; otherwise a parse counts its reason.
    fn note_codex_selection(
        &mut self,
        decision: CandidateDecision,
        reason: Option<CandidateParseReason>,
        selected_by: Option<CodexSelection>,
    ) {
        let count = match (decision, selected_by, reason) {
            (_, Some(selection), _) => &mut self.codex_selections[selection as usize],
            (CandidateDecision::Parse, None, Some(reason)) => {
                &mut self.parse_reasons[reason as usize]
            }
            (CandidateDecision::Parse, None, None) => {
                &mut self.codex_selections[CodexSelection::ComparisonTarget as usize]
            }
            (CandidateDecision::Skip, None, _) => {
                &mut self.codex_selections[CodexSelection::Skip as usize]
            }
            (CandidateDecision::Migrate, None, _) => {
                &mut self.codex_selections[CodexSelection::Migrate as usize]
            }
            (CandidateDecision::ReconcileLegacy, None, _) => {
                &mut self.codex_selections[CodexSelection::ReconcileLegacy as usize]
            }
        };
        *count = count.saturating_add(1);
    }

    fn note_codex_group(&mut self, selection: CodexSelection, members: usize) {
        let count = &mut self.codex_selections[selection as usize];
        *count = count.saturating_add(members);
    }

    /// The local census line attributing this page's Codex selections, or
    /// `None` when nothing was decided. Counts only: no path or identifier.
    fn codex_parse_reasons_line(&self) -> Option<String> {
        if self.parse_reasons.iter().all(|count| *count == 0)
            && self.codex_selections.iter().all(|count| *count == 0)
        {
            return None;
        }
        Some(format!(
            "local snapshot census codex parse reasons: {} {}",
            census_count_fields(&CANDIDATE_PARSE_REASON_NAMES, &self.parse_reasons),
            census_count_fields(&CODEX_SELECTION_NAMES, &self.codex_selections),
        ))
    }

    #[track_caller]
    fn record_unreadable(&mut self, cause: UnreadableCause, count: usize) {
        self.record_unreadable_sampled(cause, count, None);
    }

    /// One unreadable file: its root class, kind and key digest join the
    /// cause's bounded sample, never its path.
    #[track_caller]
    fn record_unreadable_file(&mut self, cause: UnreadableCause, path: &Path) {
        let key = local_index_key(path);
        self.record_unreadable_sampled(cause, 1, Some((path, key.as_str())));
    }

    #[track_caller]
    fn record_unreadable_sampled(
        &mut self,
        cause: UnreadableCause,
        count: usize,
        file: Option<(&Path, &str)>,
    ) {
        // Preserve the existing public count and operational predicates.
        self.unreadable_path_count += count;
        self.unreadable_causes
            .record_sampled(cause, count as u64, file);
        #[cfg(test)]
        sampled_scan::test_hooks::record_unreadable(cause as usize);
    }

    fn add_terminal_jsonl_loss(&mut self, loss: &TerminalJsonlLoss) {
        self.malformed_json_line_count = self
            .malformed_json_line_count
            .saturating_add(loss.malformed_json_line_count);
        self.invalid_utf8_line_count = self
            .invalid_utf8_line_count
            .saturating_add(loss.invalid_utf8_line_count);
        self.recognized_usage_drop_count = self
            .recognized_usage_drop_count
            .saturating_add(loss.recognized_usage_drop_count);
        self.dropped_usage_record_count = self
            .dropped_usage_record_count
            .saturating_add(loss.dropped_usage_record_count);
        self.terminal_recognized_usage_drop_count = self
            .terminal_recognized_usage_drop_count
            .saturating_add(loss.recognized_usage_drop_count);
        self.terminal_dropped_usage_record_count = self
            .terminal_dropped_usage_record_count
            .saturating_add(loss.dropped_usage_record_count);
    }
}

#[cfg(test)]
#[derive(Debug)]
struct BoundedCandidateSelection {
    cursor: Option<String>,
    upper_bound: Option<String>,
    limit: usize,
    selected: BTreeMap<String, CandidateFile>,
    observed_max: Option<String>,
}

#[cfg(test)]
impl BoundedCandidateSelection {
    fn new(cursor: Option<String>, upper_bound: Option<String>, limit: usize) -> Self {
        // Legacy indexes carried a cursor without a frozen ceiling. Restart a
        // fresh bounded generation once rather than inheriting its starvation
        // semantics.
        let cursor = cursor.filter(|_| upper_bound.is_some());
        Self {
            cursor,
            upper_bound,
            limit,
            selected: BTreeMap::new(),
            observed_max: None,
        }
    }

    fn insert(&mut self, candidate: CandidateFile) {
        let key = local_index_key(&candidate.path);
        if self
            .observed_max
            .as_ref()
            .map_or(true, |maximum| key > *maximum)
        {
            self.observed_max = Some(key.clone());
        }
        if self.limit == 0 {
            return;
        }
        if self
            .upper_bound
            .as_ref()
            .is_some_and(|upper_bound| key > *upper_bound)
            || self.cursor.as_ref().is_some_and(|cursor| key <= *cursor)
        {
            return;
        }
        self.selected.insert(key, candidate);
        if self.selected.len() > self.limit {
            self.selected.pop_last();
        }
    }

    fn finish(
        self,
        discovered: usize,
    ) -> (Vec<CandidateFile>, bool, Option<String>, Option<String>) {
        let upper_bound = self.upper_bound.or(self.observed_max);
        let selected = self.selected.into_values().collect::<Vec<_>>();
        let next_cursor = selected
            .last()
            .map(|candidate| local_index_key(&candidate.path));
        let reached_upper_bound = next_cursor
            .as_ref()
            .zip(upper_bound.as_ref())
            .is_some_and(|(cursor, upper_bound)| cursor >= upper_bound);
        let complete = if self.limit == 0 {
            discovered == 0
        } else {
            selected.len() < self.limit || reached_upper_bound
        };
        (
            selected,
            complete,
            (!complete).then_some(next_cursor).flatten(),
            (!complete).then_some(upper_bound).flatten(),
        )
    }
}

impl CodexTitleMetadata {
    fn has_identity_evidence(&self, identity: &str) -> bool {
        self.titles.contains_key(identity)
            || self.state_threads.contains_key(identity)
            || self.rollout_extents.contains_key(identity)
            || self.state_created_threads.contains(identity)
            || self.spawn_parents.contains_key(identity)
            || self.spawn_parents.values().any(|parent| parent == identity)
            || self.spawn_parent_conflicts.contains(identity)
            || self.identity_conflicts.contains(identity)
    }

    fn identity_from_path_evidence(&self, path: &Path) -> Option<String> {
        let candidates = codex_session_id_candidates_from_path(path);
        if candidates.len() == 1 {
            return candidates.into_iter().next();
        }
        let supported = candidates
            .into_iter()
            .filter(|identity| self.has_identity_evidence(identity))
            .collect::<Vec<_>>();
        (supported.len() == 1).then(|| supported[0].clone())
    }

    fn path_sidecar_fingerprint(&self, path: &Path) -> String {
        self.path_sidecar_fingerprint_for(path, false)
    }

    fn path_reduction_fingerprint(&self, path: &Path) -> String {
        self.path_sidecar_fingerprint_for(path, true)
    }

    fn path_sidecar_fingerprint_for(&self, path: &Path, reduction_only: bool) -> String {
        if let Some(identity) = self.identity_from_path_evidence(path) {
            return self.session_sidecar_fingerprint_in(
                identity.as_str(),
                reduction_only,
                Some(path),
            );
        }
        let parts = codex_session_id_candidates_from_path(path)
            .into_iter()
            .flat_map(|identity| {
                let fingerprint = self.session_sidecar_fingerprint_in(
                    identity.as_str(),
                    reduction_only,
                    Some(path),
                );
                [identity, fingerprint]
            })
            .collect::<Vec<_>>();
        if parts.is_empty() {
            String::new()
        } else {
            sha256_hex_owned(&parts)
        }
    }

    fn family_position(&self, child: &str) -> Option<(String, String, u64)> {
        let child = resolve_codex_identity(child);
        if self.spawn_parent_conflicts.contains(child.as_str()) {
            return None;
        }
        let parent = self.spawn_parents.get(child.as_str())?.clone();
        let mut root = parent.clone();
        let mut depth = 1_u64;
        let mut seen = BTreeSet::from([child]);
        while let Some(next) = self.spawn_parents.get(root.as_str()) {
            if self.spawn_parent_conflicts.contains(root.as_str())
                || !seen.insert(root.clone())
                || depth >= 128
            {
                return None;
            }
            root = next.clone();
            depth += 1;
        }
        Some((parent, root, depth))
    }

    /// The rows `path_reduction_fingerprint(path)` reads: the path's identity
    /// candidates, every spawn edge reachable from them, one child edge each,
    /// every home's sidecar roots and all census flags. Diagnostics are not
    /// carried. Callers compare the two fingerprints before using it.
    fn narrowed_to(&self, path: &Path) -> Self {
        let ids = codex_session_id_candidates_from_path(path)
            .into_iter()
            .flat_map(|id| [resolve_codex_identity(&id), id])
            .collect::<BTreeSet<_>>();
        fn rows<V: Clone>(
            map: &BTreeMap<String, V>,
            ids: &BTreeSet<String>,
        ) -> BTreeMap<String, V> {
            ids.iter()
                .filter_map(|id| map.get_key_value(id))
                .map(|(id, row)| (id.clone(), row.clone()))
                .collect()
        }
        let mut edges = BTreeMap::new();
        for id in &ids {
            if let Some((child, parent)) =
                self.spawn_parents.iter().find(|(_, parent)| *parent == id)
            {
                edges.insert(child.clone(), parent.clone());
            }
            let mut at = id;
            while let Some((child, parent)) = self.spawn_parents.get_key_value(at) {
                if edges.insert(child.clone(), parent.clone()).is_some() {
                    break;
                }
                at = parent;
            }
        }
        let nodes = ids
            .iter()
            .chain(edges.keys())
            .chain(edges.values())
            .cloned()
            .collect::<BTreeSet<_>>();
        let sidecar = |sidecar: &codex_root_copies::RootSidecar| codex_root_copies::RootSidecar {
            threads: rows(&sidecar.threads, &ids),
            extents: rows(&sidecar.extents, &ids),
        };
        Self {
            local_diagnostics: Default::default(),
            titles: rows(&self.titles, &ids),
            state_threads: rows(&self.state_threads, &ids),
            rollout_extents: rows(&self.rollout_extents, &ids),
            root_sidecars: self
                .root_sidecars
                .iter()
                .map(|(root, home)| (root.clone(), sidecar(home)))
                .collect(),
            state_created_threads: self
                .state_created_threads
                .intersection(&ids)
                .cloned()
                .collect(),
            spawn_parent_conflicts: self
                .spawn_parent_conflicts
                .intersection(&nodes)
                .cloned()
                .collect(),
            spawn_parents: edges,
            identity_conflicts: self
                .identity_conflicts
                .intersection(&ids)
                .cloned()
                .collect(),
            state_census_incomplete: self.state_census_incomplete,
            sidecar_census_incomplete: self.sidecar_census_incomplete,
            state_census_unscoped_incomplete: self.state_census_unscoped_incomplete,
            sidecar_census_unscoped_incomplete: self.sidecar_census_unscoped_incomplete,
            created_thread_census_failed_homes: self.created_thread_census_failed_homes.clone(),
            created_thread_scoped: rows(&self.created_thread_scoped, &ids),
            legacy_sidecar_fingerprint: self.legacy_sidecar_fingerprint.clone(),
            legacy_config_file_present: self.legacy_config_file_present,
        }
    }

    #[cfg(test)]
    fn session_sidecar_fingerprint(&self, source_session_id: &str) -> String {
        self.session_sidecar_fingerprint_in(source_session_id, false, None)
    }

    fn thread_extent_for_path(
        &self,
        identity: &str,
        path: &Path,
    ) -> (Option<&CodexStateThread>, Option<CodexRolloutExtent>) {
        if let Some((_, sidecar)) = self
            .root_sidecars
            .iter()
            .filter(|(root, _)| path.starts_with(root))
            .max_by_key(|(root, _)| root.components().count())
        {
            return (
                sidecar.threads.get(identity),
                sidecar.extents.get(identity).copied(),
            );
        }
        (
            self.state_threads.get(identity),
            self.rollout_extents.get(identity).copied(),
        )
    }

    fn session_sidecar_fingerprint_in(
        &self,
        source_session_id: &str,
        reduction_only: bool,
        path: Option<&Path>,
    ) -> String {
        let source_session_id = resolve_codex_identity(source_session_id);
        let title = (!reduction_only)
            .then(|| self.titles.get(source_session_id.as_str()))
            .flatten();
        let (thread, extent) = path.map_or_else(
            || {
                (
                    self.state_threads.get(source_session_id.as_str()),
                    self.rollout_extents
                        .get(source_session_id.as_str())
                        .copied(),
                )
            },
            |path| self.thread_extent_for_path(source_session_id.as_str(), path),
        );
        let decoration = (!reduction_only).then_some(thread).flatten();
        let extent = (!reduction_only).then_some(extent).flatten();
        let family = self.family_position(source_session_id.as_str());
        let fingerprint = sha256_hex(&[
            "codex_session_sidecar:v4",
            source_session_id.as_str(),
            if self
                .state_created_threads
                .contains(source_session_id.as_str())
            {
                "agent_created_thread"
            } else {
                ""
            },
            title.map(|value| value.title.as_str()).unwrap_or(""),
            title.map(|value| value.source.as_str()).unwrap_or(""),
            decoration
                .and_then(|value| value.title.as_deref())
                .unwrap_or(""),
            &decoration
                .map(|value| value.tokens_used)
                .unwrap_or_default()
                .to_string(),
            decoration
                .map(|value| if value.archived { "archived" } else { "active" })
                .unwrap_or(""),
            thread
                .and_then(|value| value.created_at.as_deref())
                .unwrap_or(""),
            decoration
                .and_then(|value| value.updated_at.as_deref())
                .unwrap_or(""),
            decoration
                .and_then(|value| value.model.as_deref())
                .unwrap_or(""),
            thread
                .and_then(|value| value.rollout_path.as_deref())
                .unwrap_or(""),
            &extent
                .map(|value| value.next_byte_offset)
                .unwrap_or_default()
                .to_string(),
            &extent
                .map(|value| value.next_ordinal)
                .unwrap_or_default()
                .to_string(),
            family
                .as_ref()
                .map(|(parent, _, _)| parent.as_str())
                .unwrap_or_else(|| {
                    if self
                        .spawn_parent_conflicts
                        .contains(source_session_id.as_str())
                    {
                        "conflict"
                    } else if self.spawn_parents.contains_key(source_session_id.as_str())
                        && self
                            .state_created_threads
                            .contains(source_session_id.as_str())
                    {
                        // An edge whose ancestor chain cannot be resolved is still
                        // lineage evidence and must reselect a parentless file.
                        "unresolved"
                    } else {
                        ""
                    }
                }),
            family
                .as_ref()
                .map(|(_, root, _)| root.as_str())
                .unwrap_or(""),
            &family
                .as_ref()
                .map(|(_, _, depth)| *depth)
                .unwrap_or_default()
                .to_string(),
        ]);
        // A per-home row can stay byte-identical while another home's row
        // creates a collision. Invalidate paused ownership decisions as well
        // as fresh parsing; census flags alone are not cursor dependencies.
        if self.identity_conflicts.contains(source_session_id.as_str()) {
            sha256_hex(&["codex_identity_conflict:v1", &fingerprint])
        } else {
            fingerprint
        }
    }

    fn load_from_roots(roots: &[PathBuf]) -> Self {
        let mut metadata = Self::default();
        let mut legacy_sidecar_parts = Vec::new();
        let mut parentless_ineligible = BTreeSet::new();
        let mut codex_dirs = BTreeSet::new();
        for root in roots {
            if let Some(parent) = root.parent() {
                codex_dirs.insert(parent.to_path_buf());
            }
        }

        for codex_dir in codex_dirs {
            let config_path = codex_dir.join("config.toml");
            legacy_sidecar_parts.push(sidecar_stat_fingerprint(&config_path));
            metadata.legacy_config_file_present |= config_path.is_file();

            let state_path = codex_dir.join("state_5.sqlite");
            legacy_sidecar_parts.push(sidecar_stat_fingerprint(&state_path));
            let state_conflicts_before = metadata.identity_conflicts.len();
            let mut open = SidecarOpenCounts::default();
            let title_census = load_codex_sqlite_titles(
                &state_path,
                &mut open,
                &mut metadata.titles,
                &mut metadata.identity_conflicts,
            );
            metadata.local_diagnostics.state_titles.observe_root(
                &title_census,
                open,
                metadata.identity_conflicts.len() != state_conflicts_before,
                local_index_key(&codex_dir).as_str(),
            );
            let thread_conflicts_before = metadata.identity_conflicts.len();
            let mut root_sidecar = codex_root_copies::RootSidecar::default();
            let mut open = SidecarOpenCounts::default();
            let state_census = load_codex_sqlite_state_threads(
                &state_path,
                &mut open,
                &mut root_sidecar.threads,
                &mut metadata.identity_conflicts,
                &mut metadata.local_diagnostics.identity_conflict_taxonomy,
            );
            codex_root_copies::merge_threads(&mut metadata, &codex_dir, &root_sidecar.threads);
            metadata.local_diagnostics.state_threads.observe_root(
                &state_census,
                open,
                metadata.identity_conflicts.len() != thread_conflicts_before,
                local_index_key(&codex_dir).as_str(),
            );
            let spawn_conflicts_before = metadata.identity_conflicts.len();
            let mut open = SidecarOpenCounts::default();
            let spawn_census = load_codex_sqlite_spawn_edges(
                &state_path,
                &mut open,
                &mut metadata.state_created_threads,
                &mut metadata.spawn_parents,
                &mut metadata.spawn_parent_conflicts,
                &mut metadata.identity_conflicts,
                &mut parentless_ineligible,
            );
            metadata.local_diagnostics.spawn_edges.observe_root(
                &spawn_census,
                open,
                metadata.identity_conflicts.len() != spawn_conflicts_before,
                local_index_key(&codex_dir).as_str(),
            );
            let title_census_incomplete = title_census.is_err();
            let state_census_incomplete = state_census.is_err();
            let spawn_census_incomplete = spawn_census.is_err();
            if title_census_incomplete || state_census_incomplete || spawn_census_incomplete {
                metadata.state_census_incomplete = true;
                metadata.sidecar_census_incomplete = true;
                metadata.state_census_unscoped_incomplete = true;
                metadata.sidecar_census_unscoped_incomplete = true;
            }
            if spawn_census_incomplete {
                metadata
                    .created_thread_census_failed_homes
                    .insert(codex_dir.clone());
            }
            if metadata.identity_conflicts.len() != state_conflicts_before {
                metadata.state_census_incomplete = true;
                metadata.sidecar_census_incomplete = true;
            }

            let history_path = codex_dir.join("thread_history_1.sqlite");
            legacy_sidecar_parts.push(sidecar_stat_fingerprint(&history_path));
            let history_conflicts_before = metadata.identity_conflicts.len();
            let mut open = SidecarOpenCounts::default();
            let history_census = load_codex_rollout_extents(
                &history_path,
                &mut open,
                &mut root_sidecar.extents,
                &mut metadata.identity_conflicts,
            );
            codex_root_copies::merge_extents(&mut metadata, &root_sidecar.extents);
            metadata.local_diagnostics.rollout_extents.observe_root(
                &history_census,
                open,
                metadata.identity_conflicts.len() != history_conflicts_before,
                local_index_key(&codex_dir).as_str(),
            );
            if history_census.is_err() {
                metadata.sidecar_census_incomplete = true;
                metadata.sidecar_census_unscoped_incomplete = true;
            }
            if metadata.identity_conflicts.len() != history_conflicts_before {
                metadata.sidecar_census_incomplete = true;
            }

            metadata
                .root_sidecars
                .insert(codex_dir.clone(), root_sidecar);
            let index_path = codex_dir.join("session_index.jsonl");
            legacy_sidecar_parts.push(sidecar_stat_fingerprint(&index_path));
            let index_conflicts_before = metadata.identity_conflicts.len();
            let index_census = load_codex_session_index_titles(
                &index_path,
                &mut metadata.titles,
                &mut metadata.identity_conflicts,
            );
            metadata.local_diagnostics.session_index.observe_root(
                &index_census,
                SidecarOpenCounts::default(),
                metadata.identity_conflicts.len() != index_conflicts_before,
                local_index_key(&codex_dir).as_str(),
            );
            if index_census.is_err() {
                metadata.sidecar_census_incomplete = true;
                metadata.sidecar_census_unscoped_incomplete = true;
            }
            if metadata.identity_conflicts.len() != index_conflicts_before {
                metadata.sidecar_census_incomplete = true;
            }
        }
        // Unresolvable lineage evidence blocks only parentless admission. A
        // parent recorded by any home wins, and an id without a parent never
        // appears in a descendant's ancestor walk, so lineage is unaffected.
        for child in parentless_ineligible {
            if metadata.state_created_threads.contains(child.as_str())
                && !metadata.spawn_parents.contains_key(child.as_str())
            {
                metadata.spawn_parent_conflicts.insert(child);
            }
        }
        // A collision found by a later root/loader must also withhold any
        // earlier total-only fallback, even if no rollout can be opened.
        metadata
            .state_threads
            .retain(|id, _| !metadata.identity_conflicts.contains(id));
        metadata
            .rollout_extents
            .retain(|id, _| !metadata.identity_conflicts.contains(id));
        metadata.count_identity_conflict_scope();
        metadata.legacy_sidecar_fingerprint = sha256_hex_owned(&legacy_sidecar_parts);
        metadata
    }

    /// Diagnostics only. Reads the merged maps already in hand; the per-edge
    /// pass runs only when some conflict exists.
    fn count_identity_conflict_scope(&mut self) {
        let conflicts = &self.identity_conflicts;
        let taxonomy = &mut self.local_diagnostics.identity_conflict_taxonomy;
        taxonomy.conflict_keys_total = saturating_count_u32(conflicts.len());
        if conflicts.is_empty() {
            return;
        }
        taxonomy.conflict_keys_state_created = saturating_count_u32(
            conflicts
                .iter()
                .filter(|key| self.state_created_threads.contains(key.as_str()))
                .count(),
        );
        taxonomy.conflict_parent_child_edges = saturating_count_u32(
            self.spawn_parents
                .values()
                .filter(|parent| conflicts.contains(parent.as_str()))
                .count(),
        );
    }

    /// A failed created-thread census holds only
    /// rollouts whose proof could depend on a failing home's state database.
    fn created_thread_census_incomplete_for(&self, path: &Path) -> bool {
        !self.created_thread_census_failed_homes.is_empty()
            && !codex_rollout_thread_id(path).is_some_and(|identity| {
                self.created_thread_scoped
                    .get(&identity)
                    .is_some_and(|rollout| rollout == path)
            })
    }

    /// After a home's created-thread census failed, scope a rollout to
    /// its own home only when the file -> home map is exact. Its one identity
    /// has a state row in exactly one loaded home, whose created-thread census
    /// succeeded, which is the only loaded home containing the row's rollout
    /// path and which locates it exactly (`copy_locator`). Discovery has walked
    /// every failing root (in its scan roots, none pending, no namespace loss)
    /// without finding a rollout of that identity there (a copy whose unread
    /// row could disagree), and every spawn ancestor is scoped too: a spawned
    /// child's lineage (`family_position`) reads every home's edges. Anything
    /// else stays held. Counted in `created_thread_scoped_rollouts`.
    fn scope_created_thread_census(&mut self, index: &ScanIndex, roots: &[PathBuf]) {
        let failed = &self.created_thread_census_failed_homes;
        let under_failed = |path: &Path| failed.iter().any(|home| path.starts_with(home));
        let Some(traversal) = index.traversal.as_ref() else {
            return;
        };
        if failed.is_empty()
            || roots
                .iter()
                .any(|root| under_failed(root) && !traversal.scan_roots.contains(root))
            || traversal
                .pending_directories
                .iter()
                .any(|directory| under_failed(&directory.path))
            || claude_family_census_shadow::Vetoes::current(index, traversal).namespace_loss
        {
            return;
        }
        let in_failed_homes = index
            .files
            .keys()
            .chain(&traversal.observed_index_keys)
            .chain(&traversal.codex_rollout_paths)
            .map(Path::new)
            .chain(
                traversal
                    .pending_candidates
                    .iter()
                    .map(|candidate| candidate.path.as_path()),
            )
            .filter(|path| under_failed(path))
            .flat_map(codex_session_id_candidates_from_path)
            .collect::<BTreeSet<_>>();
        let mut scoped = BTreeMap::new();
        for (home, sidecar) in &self.root_sidecars {
            if failed.contains(home) {
                continue;
            }
            for (identity, thread) in &sidecar.threads {
                let Some(rollout) = thread.rollout_path.as_deref().map(Path::new) else {
                    continue;
                };
                let single_home = self
                    .root_sidecars
                    .iter()
                    .filter(|(other, other_sidecar)| {
                        rollout.starts_with(other) || other_sidecar.threads.contains_key(identity)
                    })
                    .count()
                    == 1;
                if single_home
                    && codex_root_copies::copy_locator(home, identity, thread).is_some()
                    && !in_failed_homes.contains(identity)
                    && !self.identity_conflicts.contains(identity)
                {
                    scoped.insert(identity.clone(), rollout.to_path_buf());
                }
            }
        }
        let held_lineage = |identity: &String| {
            let mut child = resolve_codex_identity(identity);
            let mut seen = BTreeSet::new();
            while let Some(parent) = self.spawn_parents.get(child.as_str()) {
                if self.spawn_parent_conflicts.contains(child.as_str())
                    || !seen.insert(child)
                    || !scoped.contains_key(parent)
                {
                    return true;
                }
                child = parent.clone();
            }
            self.spawn_parent_conflicts.contains(child.as_str())
        };
        let held = scoped
            .keys()
            .filter(|&identity| held_lineage(identity))
            .cloned()
            .collect::<Vec<_>>();
        for identity in held {
            scoped.remove(&identity);
        }
        self.local_diagnostics.created_thread_scoped_rollouts = saturating_count_u32(scoped.len());
        self.created_thread_scoped = scoped;
    }
}

// `logs_2.sqlite` can be ~1GB+ with a live WAL and a concurrent writer (Codex
// itself). The read is best-effort, read-only, time-bounded, and row-capped so
// it can never disrupt Codex or stall the snapshot cycle. Any error (missing
// file, locked DB, schema churn) yields an empty map. Exact file-owned receipts
// retain protected old decisions; absent new signals keep the existing default.
const CODEX_LOGS2_MAX_ROWS: i64 = 50_000;
const CODEX_LOGS2_BUSY_TIMEOUT_MS: u64 = 400;
// The trace read window pads the session backfill window so a turn near a
// window edge still finds its request row. Capped so a stale/huge DB can never
// widen the scan unboundedly.
const CODEX_LOGS2_WINDOW_PAD_DAYS: u64 = 1;
const CODEX_LOGS2_MAX_WINDOW_DAYS: u64 = 14;

impl CodexTurnTraceMap {
    fn load_from_roots(roots: &[PathBuf], backfill_window_days: u64) -> Self {
        let mut map = Self::default();
        let mut codex_dirs = BTreeSet::new();
        for root in roots {
            if let Some(parent) = root.parent() {
                codex_dirs.insert(parent.to_path_buf());
            }
        }
        let since_epoch = codex_logs2_since_epoch(backfill_window_days);
        map.since_epoch = since_epoch;
        for codex_dir in codex_dirs {
            // The live DB lives directly under ~/.codex; a `sqlite/` subdir copy
            // exists on some installs. Read whichever is present.
            for db_path in [
                codex_dir.join("logs_2.sqlite"),
                codex_dir.join("sqlite").join("logs_2.sqlite"),
            ] {
                map.incomplete |= !load_codex_logs2_priority_turns(
                    &db_path,
                    since_epoch,
                    &mut map.priority_turns,
                );
            }
        }
        map
    }
}

fn codex_logs2_since_epoch(backfill_window_days: u64) -> i64 {
    let window_days = backfill_window_days
        .saturating_add(CODEX_LOGS2_WINDOW_PAD_DAYS)
        .min(CODEX_LOGS2_MAX_WINDOW_DAYS);
    let span = window_days.saturating_mul(86_400);
    let now = unix_seconds(SystemTime::now()).unwrap_or(0);
    now.saturating_sub(span) as i64
}

/// False when a present DB could not be read completely (open, prepare,
/// query or row error, or the row cap reached); a missing DB is complete.
fn load_codex_logs2_priority_turns(
    path: &Path,
    since_epoch: i64,
    priority_turns: &mut BTreeSet<String>,
) -> bool {
    if !path.exists() {
        return true;
    }
    let Ok(connection) = codex_sqlite_read::CodexSqliteRead::open(
        path,
        OpenFlags::SQLITE_OPEN_READ_ONLY,
        std::time::Duration::from_millis(CODEX_LOGS2_BUSY_TIMEOUT_MS),
    ) else {
        return false;
    };
    let Ok((turns, complete, read)) = connection.read(|connection| {
        // Only `response.create` request rows carry the *requested* service_tier.
        // The `idx_logs_ts` index bounds the scan to the recent window; the LIKE
        // then filters to the sparse request rows (hundreds, not the full table).
        let mut statement = connection.prepare(
            "SELECT feedback_log_body FROM logs \
             WHERE ts >= ?1 AND feedback_log_body LIKE '%websocket request:%' \
             ORDER BY ts DESC LIMIT ?2",
        )?;
        let rows = statement.query_map(
            rusqlite::params![since_epoch, CODEX_LOGS2_MAX_ROWS],
            |row| row.get::<_, String>(0),
        )?;
        let mut complete = true;
        let mut read = 0_u64;
        let mut turns = Vec::new();
        for body in rows {
            let Ok(body) = body else {
                complete = false;
                continue;
            };
            read += 1;
            turns.extend(codex_logs2_priority_turn_from_body(&body));
        }
        if read == CODEX_LOGS2_MAX_ROWS as u64 {
            CapCounts::record("codex", 3, 1);
        }
        Ok((turns, complete, read))
    }) else {
        return false;
    };
    priority_turns.extend(turns);
    complete && read < CODEX_LOGS2_MAX_ROWS as u64
}

/// Parse one `feedback_log_body` row. Returns the `turn_id` when the row is a
/// `response.create` request that asked for `service_tier="priority"`.
///
/// Privacy: the row's JSON payload contains the full prompt (`input`,
/// `instructions`, `tools`). We read ONLY the `type` and `service_tier` fields
/// and the `turn.id` tracing span; no prompt or output content is retained.
fn codex_logs2_priority_turn_from_body(body: &str) -> Option<String> {
    const MARKER: &str = "websocket request:";
    let idx = body.rfind(MARKER)?;
    let prefix = &body[..idx];
    let json_text = body[idx + MARKER.len()..].trim();
    let value: Value = serde_json::from_str(json_text).ok()?;
    if value.get("type").and_then(Value::as_str) != Some("response.create") {
        return None;
    }
    let tier = value.get("service_tier").and_then(Value::as_str)?;
    if !tier.eq_ignore_ascii_case("priority") {
        return None;
    }
    codex_logs2_span_field(prefix, "turn.id")
        .or_else(|| codex_logs2_span_field(prefix, "turn_id"))
        .filter(|turn_id| !turn_id.is_empty())
}

/// Extract a `key=value` field from a tracing-span prefix, where the value is
/// terminated by whitespace, `,`, `{`, or `}`. The key must sit on an
/// identifier boundary so `turn_id` does not match inside `parent_turn_id`.
fn codex_logs2_span_field(prefix: &str, key: &str) -> Option<String> {
    let needle = format!("{key}=");
    let mut search_start = 0;
    while let Some(rel) = prefix[search_start..].find(&needle) {
        let at = search_start + rel;
        let boundary = at == 0
            || !prefix[..at]
                .chars()
                .next_back()
                .map(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
                .unwrap_or(false);
        let value_start = at + needle.len();
        if boundary {
            let value: String = prefix[value_start..]
                .chars()
                .take_while(|c| !c.is_whitespace() && !matches!(c, ',' | '{' | '}'))
                .collect();
            if !value.is_empty() {
                return Some(value);
            }
        }
        search_start = value_start;
    }
    None
}

fn load_codex_session_index_titles(
    path: &Path,
    titles: &mut BTreeMap<String, CodexTitleCandidate>,
    identity_conflicts: &mut BTreeSet<String>,
) -> Result<()> {
    let file = match File::open(path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => return Err(error).context("open Codex session index"),
    };
    let mut parsed = BTreeMap::new();
    let mut raw_ids_by_key = BTreeMap::new();
    let mut invalid_shape = false;
    let report = read_bounded_jsonl_lines(BufReader::new(file), |value| {
        let Some(id) = codex_identity_at(value, &["id"]) else {
            invalid_shape = true;
            return;
        };
        let id = record_codex_identity_key(&mut raw_ids_by_key, identity_conflicts, id.as_str());
        if identity_conflicts.contains(id.as_str()) {
            parsed.remove(id.as_str());
            titles.remove(id.as_str());
            return;
        }
        insert_codex_sidecar_title(
            &mut parsed,
            id,
            string_at(value, &["thread_name"])
                .or_else(|| string_at(value, &["title"]))
                .or_else(|| string_at(value, &["name"])),
            "session_index",
            true,
        );
    })
    .context("read Codex session index")?;
    if !report.complete() || invalid_shape {
        return Err(anyhow::Error::new(IncompleteShape)
            .context("Codex session index census was incomplete"));
    }
    titles.extend(parsed);
    Ok(())
}

fn load_codex_sqlite_titles(
    path: &Path,
    open: &mut SidecarOpenCounts,
    titles: &mut BTreeMap<String, CodexTitleCandidate>,
    identity_conflicts: &mut BTreeSet<String>,
) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    let connection =
        open_codex_sidecar_database(path, open).context("open Codex title database")?;
    let loaded = connection.read(|connection| {
        census_rows(
            connection,
            "SELECT id, title FROM threads WHERE title IS NOT NULL AND title != ''",
            "Codex title census",
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
    })?;
    let mut raw_ids_by_key = BTreeMap::new();
    for (raw_id, title) in loaded {
        let id =
            record_codex_identity_key(&mut raw_ids_by_key, identity_conflicts, raw_id.as_str());
        if identity_conflicts.contains(id.as_str()) {
            titles.remove(id.as_str());
            continue;
        }
        insert_codex_sidecar_title(titles, id, Some(title), "session_index", false);
    }
    Ok(())
}

fn load_codex_sqlite_state_threads(
    path: &Path,
    open: &mut SidecarOpenCounts,
    state_threads: &mut BTreeMap<String, CodexStateThread>,
    identity_conflicts: &mut BTreeSet<String>,
    taxonomy: &mut IdentityConflictTaxonomy,
) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    let connection =
        open_codex_sidecar_database(path, open).context("open Codex state database")?;
    let rows = connection.read(|connection| {
        let columns = sqlite_table_columns(connection, "threads")?;
        if !columns.contains("id") || !columns.contains("tokens_used") {
            return Err(anyhow::Error::new(IncompleteShape)
                .context("Codex state database is missing required thread census columns"));
        }

        let sql = format!(
            "SELECT id, {}, {}, {}, {}, {}, {}, {}, {}, {} FROM threads WHERE tokens_used > 0",
            sqlite_select_expr(&columns, "title", "NULL"),
            sqlite_select_expr(&columns, "tokens_used", "0"),
            sqlite_select_expr(&columns, "archived", "0"),
            sqlite_select_expr(&columns, "created_at", "NULL"),
            sqlite_select_expr(&columns, "updated_at", "NULL"),
            sqlite_select_expr(&columns, "created_at_ms", "NULL"),
            sqlite_select_expr(&columns, "updated_at_ms", "NULL"),
            sqlite_select_expr(&columns, "model", "NULL"),
            sqlite_select_expr(&columns, "rollout_path", "NULL"),
        );
        census_rows(connection, &sql, "Codex state thread census", |row| {
            let id: String = row.get(0)?;
            let title: Option<String> = row.get(1)?;
            let tokens_used = non_negative_i64_to_u64(row.get::<_, i64>(2)?);
            let archived = row.get::<_, i64>(3)? != 0;
            let created_at = codex_state_timestamp(row.get(6)?, row.get(4)?);
            let updated_at = codex_state_timestamp(row.get(7)?, row.get(5)?);
            let model: Option<String> = row.get(8)?;
            let rollout_path: Option<String> = row.get(9)?;
            Ok((
                id,
                CodexStateThread {
                    title,
                    tokens_used,
                    archived,
                    created_at,
                    updated_at,
                    model,
                    rollout_path,
                },
            ))
        })
    })?;
    let mut loaded = BTreeMap::new();
    let mut raw_ids_by_key = BTreeMap::new();
    for (raw_id, thread) in rows {
        let conflicts_before = identity_conflicts.len();
        let id =
            record_codex_identity_key(&mut raw_ids_by_key, identity_conflicts, raw_id.as_str());
        if identity_conflicts.len() != conflicts_before {
            taxonomy.state_alias_keys = taxonomy.state_alias_keys.saturating_add(1);
        }
        if identity_conflicts.contains(id.as_str()) {
            loaded.remove(id.as_str());
            state_threads.remove(id.as_str());
            continue;
        }
        if loaded
            .insert(id.clone(), thread.clone())
            .is_some_and(|existing| existing != thread)
        {
            loaded.remove(id.as_str());
            state_threads.remove(id.as_str());
            identity_conflicts.insert(id);
            taxonomy.state_intra_root_row_keys =
                taxonomy.state_intra_root_row_keys.saturating_add(1);
        }
    }
    for (id, thread) in loaded {
        if let Some(existing) = state_threads
            .insert(id.clone(), thread.clone())
            .filter(|existing| *existing != thread)
        {
            taxonomy.observe_state_cross_root(codex_state_thread_field_diffs(&existing, &thread));
            state_threads.remove(id.as_str());
            identity_conflicts.insert(id);
        }
    }
    Ok(())
}

/// One unit per differing field. Exhaustive so a new row field must be
/// classified before it can take part in the row comparison above.
fn codex_state_thread_field_diffs(
    existing: &CodexStateThread,
    incoming: &CodexStateThread,
) -> StateRowFieldDiffs {
    let CodexStateThread {
        title,
        tokens_used,
        archived,
        created_at,
        updated_at,
        model,
        rollout_path,
    } = existing;
    StateRowFieldDiffs {
        title: u32::from(*title != incoming.title),
        tokens_used: u32::from(*tokens_used != incoming.tokens_used),
        archived: u32::from(*archived != incoming.archived),
        created_at: u32::from(*created_at != incoming.created_at),
        updated_at: u32::from(*updated_at != incoming.updated_at),
        model: u32::from(*model != incoming.model),
        rollout_path: u32::from(*rollout_path != incoming.rollout_path),
    }
}

fn saturating_count_u32(count: usize) -> u32 {
    u32::try_from(count).unwrap_or(u32::MAX)
}

fn load_codex_rollout_extents(
    path: &Path,
    open: &mut SidecarOpenCounts,
    rollout_extents: &mut BTreeMap<String, CodexRolloutExtent>,
    identity_conflicts: &mut BTreeSet<String>,
) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    let connection =
        open_codex_sidecar_database(path, open).context("open Codex thread-history database")?;
    let Some(rows) = connection.read(|connection| {
        let columns = sqlite_table_columns(connection, "thread_history_projection_state")?;
        if columns.is_empty() {
            return Ok(None);
        }
        if !columns.contains("thread_id")
            || !columns.contains("next_rollout_byte_offset")
            || !columns.contains("next_rollout_ordinal")
        {
            return Err(anyhow::Error::new(IncompleteShape)
                .context("Codex thread-history database has an incomplete projection schema"));
        }
        census_rows(
            connection,
            "SELECT thread_id, next_rollout_byte_offset, next_rollout_ordinal \
             FROM thread_history_projection_state",
            "Codex rollout-extent census",
            |row| {
                let thread_id: String = row.get(0)?;
                let next_byte_offset: i64 = row.get(1)?;
                let next_ordinal: i64 = row.get(2)?;
                Ok((thread_id, next_byte_offset, next_ordinal))
            },
        )
        .map(Some)
    })?
    else {
        return Ok(());
    };
    let mut loaded = BTreeMap::new();
    let mut raw_ids_by_key = BTreeMap::new();
    for (raw_thread_id, next_byte_offset, next_ordinal) in rows {
        let thread_id = record_codex_identity_key(
            &mut raw_ids_by_key,
            identity_conflicts,
            raw_thread_id.as_str(),
        );
        if identity_conflicts.contains(thread_id.as_str()) {
            loaded.remove(thread_id.as_str());
            rollout_extents.remove(thread_id.as_str());
            continue;
        }
        let next_byte_offset =
            u64::try_from(next_byte_offset).context("negative Codex rollout byte offset")?;
        let next_ordinal = u64::try_from(next_ordinal).context("negative Codex rollout ordinal")?;
        let extent = CodexRolloutExtent {
            next_byte_offset,
            next_ordinal,
        };
        if loaded
            .insert(thread_id.clone(), extent)
            .is_some_and(|existing| existing != extent)
        {
            loaded.remove(thread_id.as_str());
            rollout_extents.remove(thread_id.as_str());
            identity_conflicts.insert(thread_id);
        }
    }
    for (thread_id, extent) in loaded {
        if rollout_extents
            .insert(thread_id.clone(), extent)
            .is_some_and(|existing| existing != extent)
        {
            rollout_extents.remove(thread_id.as_str());
            identity_conflicts.insert(thread_id);
        }
    }
    Ok(())
}

/// `parentless_ineligible` collects ids whose lineage evidence exists but could
/// not be resolved here (delegation text the strict parser refused, an unknown
/// `first_user_message`, a malformed edge row, or no edge table). The caller
/// applies it only after every home is loaded, and only to ids that still have
/// no parent, so it can never remove a parent recorded elsewhere.
fn load_codex_sqlite_spawn_edges(
    path: &Path,
    open: &mut SidecarOpenCounts,
    state_created_threads: &mut BTreeSet<String>,
    spawn_parents: &mut BTreeMap<String, String>,
    spawn_parent_conflicts: &mut BTreeSet<String>,
    identity_conflicts: &mut BTreeSet<String>,
    parentless_ineligible: &mut BTreeSet<String>,
) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    let connection =
        open_codex_sidecar_database(path, open).context("open Codex spawn-edge database")?;

    // Newer Codex Desktop builds can create a child task without populating
    // `thread_spawn_edges`. The equivalent provider-native relationship lives
    // in the child row. Only the exact machine-owned source kind and wrapper
    // are eligible: ordinary user prompt text must never manufacture lineage.
    let rows = connection.read(|connection| {
        let thread_columns = sqlite_table_columns(connection, "threads")?;
        for required in ["id", "thread_source", "first_user_message"] {
            if !thread_columns.contains(required) {
                return Err(anyhow::Error::new(IncompleteShape).context(format!(
                    "Codex state database is missing required created-thread census column {required}"
                )));
            }
        }
        census_rows(
            connection,
            "SELECT id, first_user_message FROM threads \
             WHERE thread_source = 'agent_created_thread'",
            "Codex created-thread census",
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<String>>(1)?)),
        )
    })?;
    let mut raw_created_ids_by_key = BTreeMap::new();
    let mut created_in_database = Vec::new();
    for (raw_child, first_user_message) in rows {
        let child = record_codex_identity_key(
            &mut raw_created_ids_by_key,
            identity_conflicts,
            raw_child.as_str(),
        );
        if identity_conflicts.contains(child.as_str()) {
            state_created_threads.remove(child.as_str());
            spawn_parents.remove(child.as_str());
            spawn_parent_conflicts.insert(child);
            continue;
        }
        state_created_threads.insert(child.clone());
        created_in_database.push(child.clone());
        if first_user_message
            .as_deref()
            .map(codex_created_thread_mentions_delegation)
            .unwrap_or(true)
        {
            parentless_ineligible.insert(child.clone());
        }
        if let Some(parent) = first_user_message
            .as_deref()
            .and_then(|message| codex_created_thread_parent(&child, message))
        {
            record_codex_spawn_parent(spawn_parents, spawn_parent_conflicts, child, parent);
        }
    }

    let Some(loaded) = connection.read(|connection| {
        let columns = sqlite_table_columns(connection, "thread_spawn_edges")?;
        if !columns.contains("parent_thread_id") || !columns.contains("child_thread_id") {
            return Ok(None);
        }
        census_rows(
            connection,
            "SELECT parent_thread_id, child_thread_id FROM thread_spawn_edges",
            "Codex spawn-edge census",
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
        .map(Some)
    })?
    else {
        // Without the edge table, a missing edge is not evidence of no parent.
        parentless_ineligible.extend(created_in_database);
        return Ok(());
    };
    let mut raw_parent_ids_by_key = BTreeMap::new();
    let mut raw_child_ids_by_key = BTreeMap::new();
    for (raw_parent, raw_child) in loaded {
        let parent = record_codex_identity_key(
            &mut raw_parent_ids_by_key,
            identity_conflicts,
            raw_parent.as_str(),
        );
        let child = record_codex_identity_key(
            &mut raw_child_ids_by_key,
            identity_conflicts,
            raw_child.as_str(),
        );
        if identity_conflicts.contains(child.as_str())
            || identity_conflicts.contains(parent.as_str())
        {
            spawn_parents.remove(child.as_str());
            spawn_parent_conflicts.insert(child);
            continue;
        }
        if !parent.is_empty() && !child.is_empty() && parent != child {
            record_codex_spawn_parent(spawn_parents, spawn_parent_conflicts, child, parent);
        } else if !child.is_empty() {
            // A self or empty-parent edge is broken lineage, not its absence.
            parentless_ineligible.insert(child);
        }
    }
    Ok(())
}

/// Any delegation wrapper text, wherever it appears and in any case, is
/// lineage evidence. Only the strict parser above may turn it into a parent.
fn codex_created_thread_mentions_delegation(first_user_message: &str) -> bool {
    first_user_message
        .to_ascii_lowercase()
        .contains("<codex_delegation")
}

fn record_codex_spawn_parent(
    spawn_parents: &mut BTreeMap<String, String>,
    spawn_parent_conflicts: &mut BTreeSet<String>,
    child: String,
    parent: String,
) {
    let child = resolve_codex_identity(child.as_str());
    let parent = resolve_codex_identity(parent.as_str());
    if spawn_parent_conflicts.contains(child.as_str()) {
        return;
    }
    match spawn_parents.get(child.as_str()) {
        Some(existing) if existing != &parent => {
            spawn_parents.remove(child.as_str());
            spawn_parent_conflicts.insert(child);
        }
        Some(_) => {}
        None => {
            spawn_parents.insert(child, parent);
        }
    }
}

/// Extract the provider-owned parent id from Codex Desktop's create-thread
/// wrapper without retaining or interpreting the delegated prompt body.
///
/// Callers must already have verified `thread_source=agent_created_thread`.
/// The exact wrapper shape, a single UUID-like source id, and a different child
/// id are required so user-authored lookalike text fails closed.
fn codex_created_thread_parent(child: &str, first_user_message: &str) -> Option<String> {
    const OPEN: &str = "<codex_delegation>\n  <source_thread_id>";
    const SOURCE_CLOSE_AND_INPUT_OPEN: &str = "</source_thread_id>\n  <input>";
    const CLOSE: &str = "</input>\n</codex_delegation>";

    let message = first_user_message.trim();
    let remainder = message.strip_prefix(OPEN)?;
    let (parent, input_and_close) = remainder.split_once(SOURCE_CLOSE_AND_INPUT_OPEN)?;
    if !input_and_close.ends_with(CLOSE)
        || input_and_close[..input_and_close.len() - CLOSE.len()].contains(CLOSE)
        || !codex_identity_is_uuid_shaped(parent)
        || !codex_identity_is_uuid_shaped(child)
        || resolve_codex_identity(parent) == resolve_codex_identity(child)
    {
        return None;
    }
    Some(resolve_codex_identity(parent))
}

/// Record one raw identifier at a sidecar-ingress boundary. A single
/// uppercase/mixed-case UUID row is accepted and normalized; distinct raw rows
/// that collapse to the same key are retained in `identity_conflicts` so that
/// key fails closed while unrelated census entries remain usable.
fn record_codex_identity_key(
    raw_ids_by_key: &mut BTreeMap<String, String>,
    identity_conflicts: &mut BTreeSet<String>,
    raw_id: &str,
) -> String {
    let key = resolve_codex_identity(raw_id);
    if raw_ids_by_key
        .get(key.as_str())
        .is_some_and(|existing| existing != raw_id)
    {
        identity_conflicts.insert(key.clone());
    }
    raw_ids_by_key
        .entry(key.clone())
        .or_insert_with(|| raw_id.to_string());
    key
}

/// Bounded retries of a transient sidecar open: on a real install (2026-10-31)
/// `~/.codex/state_5.sqlite` failed SQLITE_CANTOPEN at its first prepare on 11
/// of 175 Codex pages while Codex itself kept it open. BUSY at the open's
/// schema probe, which never waits, is retried too: it usually means Codex
/// is closing the database, and the retry re-checks whether it is now idle.
/// So does CANTOPEN when Codex removed the `-wal` after that check.
const CODEX_SIDECAR_OPEN_RETRIES: u32 = 3;
const CODEX_SIDECAR_OPEN_BACKOFF: std::time::Duration = std::time::Duration::from_millis(100);
/// How long a sidecar census statement waits on a lock Codex holds.
const CODEX_SIDECAR_BUSY_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);

/// Open a Codex sidecar database read-only and read its schema, which opens
/// the WAL and its index for the connection's later statements. A transient
/// CANTOPEN or BUSY is retried; `open` counts the extra attempts and an idle
/// WAL database read as a snapshot, whose rows the caller reads through
/// `CodexSqliteRead::read`.
fn open_codex_sidecar_database(
    path: &Path,
    open: &mut SidecarOpenCounts,
) -> Result<codex_sqlite_read::CodexSqliteRead> {
    let connection = retry_transient_sqlite(&mut open.retries, || {
        codex_sqlite_read::CodexSqliteRead::open(
            path,
            OpenFlags::SQLITE_OPEN_READ_ONLY,
            CODEX_SIDECAR_BUSY_TIMEOUT,
        )
    })?;
    if connection.is_snapshot() {
        open.snapshots = open.snapshots.saturating_add(1);
    }
    Ok(connection)
}

/// Run `attempt` until it succeeds, fails other than SQLITE_CANTOPEN or
/// SQLITE_BUSY, or has been retried `CODEX_SIDECAR_OPEN_RETRIES` times.
fn retry_transient_sqlite<T>(
    retries: &mut u32,
    mut attempt: impl FnMut() -> Result<T>,
) -> Result<T> {
    let mut retried = 0;
    loop {
        match attempt() {
            Err(error)
                if retried < CODEX_SIDECAR_OPEN_RETRIES
                    && matches!(
                        error.downcast_ref::<rusqlite::Error>(),
                        Some(rusqlite::Error::SqliteFailure(failure, _))
                            if matches!(
                                failure.code,
                                rusqlite::ErrorCode::CannotOpen | rusqlite::ErrorCode::DatabaseBusy
                            )
                    ) =>
            {
                retried += 1;
                *retries = retries.saturating_add(1);
                std::thread::sleep(CODEX_SIDECAR_OPEN_BACKOFF * retried);
            }
            result => return result,
        }
    }
}

fn sqlite_table_columns(connection: &Connection, table_name: &str) -> Result<BTreeSet<String>> {
    let columns = census_rows(
        connection,
        &format!("PRAGMA table_info({table_name})"),
        "SQLite table census",
        |row| row.get::<_, String>(1),
    )?;
    Ok(columns.into_iter().collect())
}

/// Every row of one census query. Failures carry their loader stage and
/// "prepare {label}" or "read {label} row".
fn census_rows<T>(
    connection: &Connection,
    sql: &str,
    label: &str,
    map: impl FnMut(&rusqlite::Row<'_>) -> rusqlite::Result<T>,
) -> Result<Vec<T>> {
    use crate::codex_scan_diagnostics::LoaderStage;
    let mut statement = connection
        .prepare(sql)
        .context(LoaderStage::Prepare)
        .with_context(|| format!("prepare {label}"))?;
    let rows = statement.query_map([], map).context(LoaderStage::Query)?;
    rows.collect::<rusqlite::Result<Vec<_>>>()
        .context(LoaderStage::Row)
        .with_context(|| format!("read {label} row"))
}

fn sqlite_select_expr(columns: &BTreeSet<String>, column: &str, fallback: &str) -> String {
    if columns.contains(column) {
        column.to_string()
    } else {
        format!("{fallback} AS {column}")
    }
}

fn non_negative_i64_to_u64(value: i64) -> u64 {
    u64::try_from(value).unwrap_or_default()
}

fn codex_state_timestamp(ms: Option<i64>, seconds: Option<i64>) -> Option<String> {
    let timestamp_ms = ms.or_else(|| seconds.map(|value| value.saturating_mul(1_000)))?;
    bounded_rfc3339_millis(timestamp_ms)
}

fn codex_config_selector(document: &DocumentMut) -> SelectorCapture {
    let mut selector = SelectorCapture::default();
    if let Some(service_tier) = document
        .get("service_tier")
        .and_then(Item::as_value)
        .and_then(|value| value.as_str())
    {
        let value = Value::String(service_tier.to_string());
        insert_selector_raw(
            &mut selector,
            "service_tier",
            "codex.config.service_tier",
            &value,
        );
    }
    if let Some(fast_mode) = document
        .get("features")
        .and_then(Item::as_table_like)
        .and_then(|table| table.get("fast_mode"))
        .and_then(Item::as_value)
        .and_then(|value| value.as_bool())
    {
        let value = Value::Bool(fast_mode);
        insert_selector_raw(
            &mut selector,
            "mode",
            "codex.config.features.fast_mode",
            &value,
        );
    }
    let top_level_fast_default_opt_out = document
        .get("fast_default_opt_out")
        .and_then(Item::as_value)
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    let notice_fast_default_opt_out = document
        .get("notice")
        .and_then(Item::as_table_like)
        .and_then(|table| table.get("fast_default_opt_out"))
        .and_then(Item::as_value)
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    let fast_default_opt_out_source = if top_level_fast_default_opt_out {
        Some("codex.config.fast_default_opt_out")
    } else if notice_fast_default_opt_out {
        Some("codex.config.notice.fast_default_opt_out")
    } else {
        None
    };
    if selector.is_empty() {
        let Some(source) = fast_default_opt_out_source else {
            return selector;
        };
        let standard = Value::String("standard".to_string());
        insert_selector_raw(&mut selector, "service_tier", source, &standard);
        insert_selector_raw(&mut selector, "mode", source, &standard);
    }
    selector
}

pub(crate) use sources::claude::settings_defaults::{
    load_claude_settings_defaults, read_claude_settings_document, ClaudeConfigDefaultsOutcome,
    ClaudeSettingsDocument, ClaudeSettingsScope,
};
pub(crate) use sources::codex::config_defaults::parse_codex_config_defaults;

fn insert_codex_sidecar_title(
    titles: &mut BTreeMap<String, CodexTitleCandidate>,
    id: String,
    title: Option<String>,
    source: &str,
    overwrite: bool,
) {
    if id.is_empty() {
        return;
    }
    let id = resolve_codex_identity(id.as_str());
    let Some(title) = title.and_then(|value| normalize_display_title(value, source)) else {
        return;
    };
    if !overwrite && titles.contains_key(id.as_str()) {
        return;
    }
    titles.insert(
        id,
        CodexTitleCandidate {
            title,
            source: source.to_string(),
        },
    );
}

// Pre-semantic-sync indexes embedded one source-wide sidecar stat digest in
// every file fingerprint. Retain this derivation only to prove whether a legacy
// entry can be migrated without parsing; new entries never use it.
fn sidecar_stat_fingerprint(path: &Path) -> String {
    match fs::metadata(path) {
        Ok(metadata) => {
            let modified_unix_seconds = metadata
                .modified()
                .ok()
                .and_then(unix_seconds)
                .unwrap_or_default();
            format!(
                "{}:{}:{}",
                path.to_string_lossy(),
                metadata.len(),
                modified_unix_seconds
            )
        }
        Err(_) => format!("{}:missing", path.to_string_lossy()),
    }
}

fn scan_traversal_context_fingerprint(
    source: SnapshotSource,
    roots: &[PathBuf],
    backfill_window_days: u64,
) -> String {
    scan_traversal_context_fingerprint_with(source, roots, None, backfill_window_days)
}

/// A traversal or carry origin saved under the earlier form, which also bound
/// the delivery context and the replay generation, consumed its queue under
/// the same walk when that form equals the active one: keep it under the new
/// form. Anything else stays a mismatch and starts the walk as before.
fn adopt_legacy_traversal_fingerprint(
    source: SnapshotSource,
    roots: &[PathBuf],
    index: &mut ScanIndex,
    backfill_window_days: u64,
) {
    let legacy = scan_traversal_context_fingerprint_with(
        source,
        roots,
        Some([
            index.active_upload_context_fingerprint.as_deref(),
            index.historical_replay_generation.as_deref(),
        ]),
        backfill_window_days,
    );
    let current = scan_traversal_context_fingerprint(source, roots, backfill_window_days);
    if let Some(fingerprint) = index
        .traversal
        .as_mut()
        .map(|t| &mut t.context_fingerprint)
        .filter(|fingerprint| **fingerprint == legacy)
    {
        fingerprint.clone_from(&current);
    }
}

/// The walk's identity: what decides which files are discovered and how a
/// queue resumes. No setting, capability or replay directive is an input; a
/// replay clears the traversal itself. `legacy` reproduces the earlier form,
/// which bound the delivery context and the replay generation, for adoption.
fn scan_traversal_context_fingerprint_with(
    source: SnapshotSource,
    roots: &[PathBuf],
    legacy: Option<[Option<&str>; 2]>,
    backfill_window_days: u64,
) -> String {
    let mut digest = Sha256::new();
    update_length_prefixed(
        &mut digest,
        if legacy.is_some() {
            b"ottto:snapshot-bounded-traversal:v1"
        } else {
            b"ottto:snapshot-bounded-traversal:v2"
        },
    );
    update_length_prefixed(&mut digest, source.api_slug().as_bytes());
    // A persisted queue contains paths already consumed under the scanner that
    // created it. Resuming that queue after an upgrade without binding these
    // derivations can skip the consumed prefix under the new identity and
    // publish a mixed old/new terminal census. Parser-only releases remain
    // resumable; reviewed scan/open identity changes start a fresh bounded
    // traversal so every pre-existing candidate is reconsidered.
    update_length_prefixed(&mut digest, source.scan_identity_version().as_bytes());
    if source == SnapshotSource::Codex {
        update_length_prefixed(&mut digest, CODEX_CONTEXT_BUCKET_REVISIT.as_bytes());
    }
    update_length_prefixed(&mut digest, LOCAL_SCAN_INDEX_IDENTITY_VERSION.as_bytes());
    update_length_prefixed(&mut digest, OPENED_OBJECT_IDENTITY_VERSION.as_bytes());
    update_length_prefixed(
        &mut digest,
        JSONL_TERMINAL_DISPOSITION_GENERATION.as_bytes(),
    );
    update_length_prefixed(&mut digest, &backfill_window_days.to_be_bytes());
    for value in legacy.into_iter().flatten() {
        update_length_prefixed(&mut digest, value.unwrap_or("none").as_bytes());
    }
    for root in roots {
        update_length_prefixed(&mut digest, root.to_string_lossy().as_bytes());
    }
    format!("{:x}", digest.finalize())
}

pub(crate) fn rfc3339_unix_seconds(value: &str) -> Option<u64> {
    OffsetDateTime::parse(value, &Rfc3339)
        .ok()?
        .unix_timestamp()
        .try_into()
        .ok()
}

fn rfc3339_unix_nanos(value: &str) -> Option<i128> {
    Some(
        OffsetDateTime::parse(value, &Rfc3339)
            .ok()?
            .unix_timestamp_nanos(),
    )
}

fn unhealthy_scan_retry_delay_seconds(attempt: u8) -> u64 {
    let exponent = u32::from(attempt.saturating_sub(1)).min(6);
    UNHEALTHY_SCAN_RETRY_BASE_SECONDS
        .saturating_mul(2_u64.saturating_pow(exponent))
        .min(UNHEALTHY_SCAN_RETRY_MAX_SECONDS)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TraversalProgress {
    Started,
    Resumed,
}

fn ensure_bounded_traversal(
    source: SnapshotSource,
    roots: &[PathBuf],
    index: &mut ScanIndex,
    collected_at: &str,
    backfill_window_days: u64,
) -> TraversalProgress {
    if source == SnapshotSource::ClaudeCode {
        rearm_cause::retain(index);
    }
    adopt_legacy_traversal_fingerprint(source, roots, index, backfill_window_days);
    let context_fingerprint =
        scan_traversal_context_fingerprint(source, roots, backfill_window_days);
    let context_observation = (source == SnapshotSource::ClaudeCode).then(|| {
        claude_contract::compare_context(claude_contract::TraversalContext {
            retained: index
                .traversal
                .as_ref()
                .map(|t| t.context_fingerprint.as_str()),
            backfill: backfill_window_days,
            active: index.active_upload_context_fingerprint.as_deref(),
            replay: index.historical_replay_generation.as_deref(),
            roots,
        })
    });
    let prior_traversal_context_matches = index
        .traversal
        .as_ref()
        .is_some_and(|traversal| traversal.context_fingerprint == context_fingerprint);
    let retry_attempt = if let Some(traversal) = index
        .traversal
        .as_ref()
        .filter(|traversal| traversal.context_fingerprint == context_fingerprint)
    {
        // Pending re-reads do not hold the bounded retry. Every remaining
        // read/discovery error keeps its existing clock retry.
        let family_retry_due = rfc3339_unix_seconds(collected_at).is_some_and(|now| {
            source == SnapshotSource::ClaudeCode
                        && index.claude_usage_authority_quarantine.iter().any(|(root, record)| {
                            record.disposition == ClaudeUsageAuthorityQuarantineDisposition::RetryPending
                                && record.retry_after_unix_seconds <= now
                                // A start already served all deadlines at or
                                // before it, even if a held/deleted member
                                // yielded no item and retained its old record.
                                && rfc3339_unix_seconds(&traversal.census_window_end)
                                    .is_some_and(|started| record.retry_after_unix_seconds > started)
                                && index.claude_usage_family_witnesses.get(root).is_some_and(|witness| {
                                    claude_usage_authority_preserves_pending(record, witness)
                                })
                        })
        });
        let terminal_unhealthy = traversal.pending_directories.is_empty()
            && !traversal
                .pending_candidates
                .iter()
                .any(|candidate| candidate.census_member)
            && traversal.counts.has_errors();
        // What clears the latch: a generation that completes drops the
        // traversal, and a changed scan context takes the `else` branch below;
        // both start the next traversal at attempt zero. What bounds it: the
        // attempt saturates at `UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS`, the delay
        // at `UNHEALTHY_SCAN_RETRY_MAX_SECONDS`, and a deadline that is past,
        // absurdly far ahead, or missing altogether (an index persisted before
        // the deadline existed) is due now. The retry depends on the clock
        // alone, never on new input arriving.
        let retry_due = match rfc3339_unix_seconds(collected_at) {
            Some(now) => {
                traversal
                    .unhealthy_retry_not_before_unix_seconds
                    .map_or(true, |deadline| {
                        now >= deadline
                            || deadline > now.saturating_add(UNHEALTHY_SCAN_RETRY_MAX_SECONDS)
                    })
                    || family_retry_due
            }
            // A malformed or backwards observation clock must not turn the
            // durable red witness into a permanent fence. Retrying remains
            // bounded by the per-tick traversal limits.
            None => true,
        };
        (terminal_unhealthy && retry_due).then(|| {
            traversal
                .unhealthy_retry_attempt
                .min(UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS)
        })
    } else {
        Some(0)
    };
    let Some(retry_attempt) = retry_attempt else {
        return TraversalProgress::Resumed;
    };

    // Capture only fixed counters before the existing reset/rearm. A missing
    // prior traversal does not explain why it was removed; the retirement
    // record, when available, supplies that independent witness.
    let transition = traversal_transition::Starting::capture(
        source,
        index,
        collected_at,
        prior_traversal_context_matches,
        retry_attempt,
    );

    // A prior partially settled page may have advanced its traversal past an
    // entity whose replacement was not accepted. Finishing that generation
    // deliberately leaves this marker set and drops the traversal so the next
    // cycle starts one clean follow-up walk. Reaching this point means that
    // follow-up (or another explicit fresh generation) is now starting. Any
    // new partial settlement stamps the marker again before persistence.
    index.bounded_sweep_had_unsettled_upload = false;
    index.bounded_sweep_unsettled_causes = 0;

    transition.emit(source);

    let mut census = ScanCensus::default();
    let resolved_roots = roots
        .iter()
        .map(|root| {
            let problems_before = census
                .unreadable_path_count
                .saturating_add(census.disappeared_file_count);
            let resolved = resolve_configured_scan_root(source, root, &mut census);
            let problems_after = census
                .unreadable_path_count
                .saturating_add(census.disappeared_file_count);
            (root, resolved, problems_after > problems_before)
        })
        .collect::<Vec<_>>();
    let currently_resolved = resolved_roots
        .iter()
        .filter_map(|(_, resolved, _)| resolved.as_ref())
        .collect::<Vec<_>>();
    let missing_roots = resolved_roots
        .iter()
        .filter(|(_, resolved, _)| resolved.is_none())
        .map(|(root, _, _)| *root)
        .collect::<Vec<_>>();
    let missing_root_reported_problem = resolved_roots
        .iter()
        .any(|(_, resolved, reported_problem)| resolved.is_none() && *reported_problem);
    // Upgrade compatibility: indexes written before the durable root witness
    // existed can still prove that a now-missing root was previously observed.
    // Direct roots are inferred by lexical containment below. A vanished
    // configured symlink has no recoverable canonical target, so retain the
    // exact prior index paths until a future resolved root covers them. This
    // avoids falsely promoting every unrelated optional root to required.
    if prior_traversal_context_matches {
        index.legacy_unresolved_root_file_witnesses.retain(|key| {
            index.files.contains_key(key)
                && !currently_resolved
                    .iter()
                    .any(|root| Path::new(key).starts_with(root))
        });
    } else {
        // A changed root set is an explicit new census scope, not evidence that
        // one of its absent optional roots owns every old out-of-scope path.
        index.legacy_unresolved_root_file_witnesses.clear();
    }
    if prior_traversal_context_matches && !missing_roots.is_empty() {
        index.legacy_unresolved_root_file_witnesses.extend(
            index
                .files
                .keys()
                .filter(|key| {
                    !currently_resolved
                        .iter()
                        .any(|root| Path::new(key).starts_with(root))
                        && !missing_roots
                            .iter()
                            .any(|root| Path::new(key).starts_with(root))
                })
                .cloned(),
        );
    }
    let mut scan_roots = Vec::new();
    let mut pending_directories = VecDeque::new();
    for (root, resolved, resolver_reported_problem) in resolved_roots {
        let root_key = local_index_key(root);
        if let Some(scan_root) = resolved {
            index.known_configured_scan_roots.insert(root_key);
            scan_roots.push(scan_root.clone());
            pending_directories.push_back(ScanTraversalPath {
                scan_root: scan_root.clone(),
                path: scan_root,
                census_member: true,
                watcher_hint: false,
            });
            continue;
        }
        let inferred_from_old_index = index
            .files
            .keys()
            .any(|key| Path::new(key).starts_with(root));
        if inferred_from_old_index {
            index.known_configured_scan_roots.insert(root_key.clone());
        }
        if index.known_configured_scan_roots.contains(&root_key) && !resolver_reported_problem {
            disappearance_diagnostics::increment(
                &mut census.disappeared_file_count,
                source,
                disappearance_diagnostics::Cause::RootResolutionUnresolved,
            );
        }
    }
    if !index.legacy_unresolved_root_file_witnesses.is_empty() && !missing_root_reported_problem {
        disappearance_diagnostics::increment(
            &mut census.disappeared_file_count,
            source,
            disappearance_diagnostics::Cause::RootResolutionUnresolved,
        );
    }
    let counts = ScanTraversalCounts {
        directory_entry_cap_exceeded_count: census.directory_entry_cap_exceeded_count,
        symlink_rejected_count: census.symlink_rejected_count,
        unreadable_path_count: census.unreadable_path_count,
        unreadable_causes: census.unreadable_causes,
        retired_parent_unresolvable: serde::de::IgnoredAny,
        oversized_file_count: census.oversized_file_count,
        disappeared_file_count: census.disappeared_file_count,
        malformed_json_line_count: census.malformed_json_line_count,
        invalid_utf8_line_count: census.invalid_utf8_line_count,
        over_line_cap_count: census.over_line_cap_count,
        recognized_usage_drop_count: census.recognized_usage_drop_count,
        ownership_incomplete_file_count: census.ownership_incomplete_file_count,
        ..ScanTraversalCounts::default()
    };
    if let Some(parts) = context_observation {
        claude_contract::started_context(&context_fingerprint, parts, roots);
    }
    index.traversal = Some(ScanTraversalCheckpoint {
        context_fingerprint,
        census_window_end: collected_at.to_string(),
        scan_roots,
        pending_directories,
        pending_candidates: VecDeque::new(),
        observed_index_keys: Default::default(),

        oversized_discovery: Default::default(),

        codex_rollout_paths: BTreeSet::new(),
        codex_join_directory_census: (source == SnapshotSource::Codex)
            .then(codex_file_join::DirectoryCensus::new),
        reconciliation_upper_bound: index.files.keys().next_back().into_iter().max().cloned(),
        reconciliation_after: None,
        reconciliation_started: false,
        watcher_hint_seen: false,
        codex_freshness_yield: false,
        retired_codex_parent_resolution_retry_required: serde::de::IgnoredAny,
        unhealthy_retry_attempt: retry_attempt,
        unhealthy_retry_not_before_unix_seconds: None,
        counts,
        residue: ScanTraversalResidue::default(),
        listing_started_unix_seconds: rfc3339_unix_seconds(collected_at),
        listing_owed_requeued_unix_seconds: Default::default(),
    });
    TraversalProgress::Started
}

/// Keep fitting pages together. Dedicated scheduling is only useful when
/// the queued population could spend the file or singleton byte allowance.
/// The estimate mirrors `PageBudget::plan`: a file larger than the singleton
/// allowance is cursor work with its own per-page budget, so it cannot spend
/// this one. Each indexed singleton also counts one sample pair for its memo
/// check. It never grants a read or increases a budget; an underestimate
/// only defers a file to the next page. Metadata failure keeps the ordinary
/// path and its existing error handling.
fn codex_selection_may_exhaust_page(
    traversal: &ScanTraversalCheckpoint,
    file_limit: usize,
    files: &SharedMap<String, ScanIndexEntry>,
) -> bool {
    if traversal.pending_candidates.len() > file_limit {
        return true;
    }
    let byte_limit = sampled_scan::codex_cursor::Limits::current().singleton();
    let mut expected = 0_u64;
    for candidate in &traversal.pending_candidates {
        let Ok(metadata) = fs::symlink_metadata(&candidate.path) else {
            continue;
        };
        if !metadata.is_file() || metadata.file_type().is_symlink() || metadata.len() > byte_limit {
            continue;
        }
        let samples = if files.contains_key(&local_index_key(&candidate.path)) {
            sampled_scan::codex_cursor::SAMPLE_READ_BYTES
        } else {
            0
        };
        expected = expected
            .saturating_add(metadata.len())
            .saturating_add(samples);
        if expected > byte_limit {
            return true;
        }
    }
    false
}

/// Codex scan-root sets whose last non-fresh selecting page was a census turn.
/// Scheduling only and RAM only: the index is reloaded every page, and a
/// restart costs at most one rotation. One entry per configured root set.
static CODEX_CENSUS_TURN_LAST: Mutex<BTreeSet<Vec<PathBuf>>> = Mutex::new(BTreeSet::new());

fn codex_census_turns() -> std::sync::MutexGuard<'static, BTreeSet<Vec<PathBuf>>> {
    CODEX_CENSUS_TURN_LAST.lock().unwrap_or_else(|poisoned| {
        CODEX_CENSUS_TURN_LAST.clear_poison();
        poisoned.into_inner()
    })
}

fn codex_census_turn_was_last(roots: &[PathBuf]) -> bool {
    codex_census_turns().contains(roots)
}

fn note_codex_census_turn(roots: &[PathBuf], census: bool) {
    let mut turns = codex_census_turns();
    if !census {
        turns.remove(roots);
    } else if !turns.contains(roots) {
        turns.insert(roots.to_vec());
    }
}

/// Priority only, never read admission. Byte length is content-relevant;
/// ctime, inode, permissions and mtime alone cannot promote an unchanged file.
/// New paths need a watcher/roster hint so a cold history walk stays FIFO.
fn codex_fresh_data_pending(candidate: &ScanTraversalPath, index: &ScanIndex) -> bool {
    let key = local_index_key(&candidate.path);
    let entry = index.files.get(&key);
    if entry.is_none() && !candidate.watcher_hint {
        return false;
    }
    fs::symlink_metadata(&candidate.path).is_ok_and(|metadata| {
        metadata.is_file()
            && !metadata.file_type().is_symlink()
            && index
                .codex_physical_matches(&key, &metadata)
                .ok()
                .flatten()
                .map(|(matched, _)| matched)
                .map_or_else(
                    || entry.map_or(true, |entry| entry.size_bytes != metadata.len()),
                    |unchanged| !unchanged,
                )
    })
}

// One boundary for fresh, persisted and held work, including compressed rollouts.
// Every encoding uses ordinary continuation budgets and funded input memory.
fn transcript_path_admitted(source: SnapshotSource, path: &Path) -> bool {
    path.extension().and_then(|value| value.to_str()) == Some("jsonl")
        || (source == SnapshotSource::Codex && codex_archive_path(path))
}

/// Once a kept generation's latest walk has finished, re-list its roots
/// every `LISTING_INTERVAL_SECONDS`, metadata only, or at once when the
/// watcher cannot vouch for what changed (`list_all`). The pass queues only
/// changed or owed files (`ScanIndex::listing_unchanged`) and never starts a
/// generation, so it re-arms nothing; it can only delay this generation's
/// discovery, never complete it. A walk this page started has passed no
/// directory yet, so it serves the request itself; any other running walk is
/// never restarted, and the request stays in `list_all` for after it.
fn start_due_listing_pass(
    source: SnapshotSource,
    traversal: &mut ScanTraversalCheckpoint,
    collected_at: &str,
    walk_started: bool,
    list_all: &mut ListingRequest,
) {
    let Some(now) = rfc3339_unix_seconds(collected_at) else {
        return;
    };
    let requested =
        list_all.requested() && (walk_started || traversal.pending_directories.is_empty());
    if requested {
        let request = std::mem::take(list_all);
        eprintln!(
            "local snapshot listing for {}: {request}",
            source.api_slug()
        );
    }
    if !traversal.pending_directories.is_empty() {
        return;
    }
    if !requested {
        let Some(started) = traversal.listing_started_unix_seconds else {
            traversal.listing_started_unix_seconds = Some(now);
            return;
        };
        if now < started.saturating_add(LISTING_INTERVAL_SECONDS) {
            return;
        }
    }
    traversal.listing_started_unix_seconds = Some(now);
    traversal.counts.listing_generations += 1;
    let roots = traversal.scan_roots.clone();
    traversal
        .pending_directories
        .extend(roots.into_iter().map(|root| ScanTraversalPath {
            scan_root: root.clone(),
            path: root,
            census_member: false,
            watcher_hint: false,
        }));
}

/// Whether this re-listing pass may queue an owed file whose stamp is
/// unchanged: once per file per `LISTING_OWED_PACE_SECONDS`, measured from
/// the start of the pass that queued it.
fn pace_listing_owed(traversal: &mut ScanTraversalCheckpoint, key: &str) -> bool {
    let Some(now) = traversal.listing_started_unix_seconds else {
        return true;
    };
    let fresh = |at: &u64| now < at.saturating_add(LISTING_OWED_PACE_SECONDS);
    let paced = &mut traversal.listing_owed_requeued_unix_seconds;
    if paced.get(key).is_some_and(&fresh) {
        return false;
    }
    paced.retain(|_, at| fresh(at));
    paced.insert(key.to_owned(), now);
    true
}

/// Watcher hints go through `ScanIndex::hint_settled`: a settled file
/// (ctime-only events included) is dropped; a vanished one is kept for the
/// exact removal path. Owner requests keep their unchanged files: a leased reason re-offer
/// here, the audit retry by calling the queue directly. A hint never admits a
/// first read past the first-read bound.
fn changed_watcher_hints(index: &ScanIndex, hinted_paths: &[PathBuf]) -> Vec<PathBuf> {
    let census_unix_seconds = index
        .traversal
        .as_ref()
        .and_then(|walk| rfc3339_unix_seconds(&walk.census_window_end));
    hinted_paths
        .iter()
        .filter(|path| {
            index.reason_reoffer_leased(&local_index_key(path))
                || !fs::symlink_metadata(path).is_ok_and(|metadata| {
                    metadata.is_file()
                        && (index.hint_settled(path, &metadata)
                            || first_read_aged(
                                index,
                                path,
                                metadata
                                    .modified()
                                    .ok()
                                    .and_then(unix_seconds)
                                    .unwrap_or_default(),
                                census_unix_seconds,
                            ))
                })
        })
        .cloned()
        .collect()
}

/// A hinted or re-listed path joins the census unless this generation
/// already observed it on Codex (its growth is next-generation evidence).
fn fresh_path_census_member(
    source: SnapshotSource,
    traversal: &ScanTraversalCheckpoint,
    path: &Path,
) -> bool {
    source != SnapshotSource::Codex
        || !traversal
            .observed_index_keys
            .contains(&local_index_key(path))
}

/// Returns how many Codex hints re-entered as next-generation evidence.
fn enqueue_watcher_hints(
    source: SnapshotSource,
    traversal: &mut ScanTraversalCheckpoint,
    hinted_paths: &[PathBuf],
    watcher_overflowed: bool,
) -> u64 {
    // Ordinary, bounded watcher paths are exact path hints. They join the
    // durable traversal census and are revalidated by the same no-follow open
    // and post-read identity checks as directory-discovered candidates. Only
    // overflow/backend loss makes the watcher evidence incomplete and forces a
    // following clean generation.
    traversal.watcher_hint_seen |= watcher_overflowed;
    let mut next_generation = 0_u64;
    let mut pending = traversal
        .pending_candidates
        .iter()
        .enumerate()
        .map(|(position, candidate)| (candidate.path.clone(), position))
        .collect::<BTreeMap<_, _>>();
    let ordered = hinted_paths.iter();
    for path in ordered {
        if !transcript_path_admitted(source, path)
            || (source == SnapshotSource::ClaudeCode
                && claude_transcript_excluded_from_snapshots(path))
        {
            continue;
        }

        if let Some(&position) = pending.get(path) {
            let member = fresh_path_census_member(source, traversal, path);
            if let Some(candidate) = traversal.pending_candidates.get_mut(position) {
                if source == SnapshotSource::Codex {
                    candidate.watcher_hint = true;
                }
                // Claude/Pi: the hint joins the census as it would if nothing
                // were queued for it (a re-listed or re-read non-member).
                if source != SnapshotSource::Codex {
                    candidate.census_member |= member;
                }
            }
            continue;
        }
        let Some(scan_root) = traversal
            .scan_roots
            .iter()
            .find(|root| path.starts_with(root))
            .cloned()
        else {
            continue;
        };
        // A Codex path this generation already processed (observed and no
        // longer pending) was read after `census_window_end`, so its growth
        // is next-generation evidence. It is still read when the page budget
        // allows, but it no longer holds the census; the next generation's
        // walk re-reads it if it is stale.
        let census_member = fresh_path_census_member(source, traversal, path);
        next_generation += u64::from(source == SnapshotSource::Codex && !census_member);
        // FIFO keeps an actively rewritten path from repeatedly jumping ahead
        // of an older remove/rename hint in a small bounded page.
        pending.insert(path.clone(), traversal.pending_candidates.len());
        traversal.pending_candidates.push_back(ScanTraversalPath {
            scan_root,
            path: path.clone(),
            census_member,
            watcher_hint: true,
        });
    }
    next_generation
}

/// Keep a retained Codex generation's roster current without a re-walk.
///
/// A generation whose discovery finished but whose census is incomplete is
/// kept: a red one until its bounded retry, a green-but-incomplete one until it
/// completes. Its roster and directory witness are the ownership evidence for
/// every later page. Left frozen, one rollout created after the walk made each
/// page that selected it unprovable, and the whole page was held until the next
/// walk. Here only directories whose witness moved are re-listed, one level
/// deep: rollouts that appeared join the roster and the census candidates
/// exactly as the walk adds them, rollouts that left drop out of the roster,
/// and new subdirectories go through the ordinary bounded walk. Files already
/// in the roster are not re-selected here: the re-listing pass queues their
/// growth. A listing the walk would turn red (a
/// symlink, an unreadable entry, a change during the listing, a vanished
/// entry) refreshes nothing: that directory keeps its old witness and the
/// existing holds apply until a later tick or the next walk.
fn refresh_retained_codex_roster(
    source: SnapshotSource,
    index: &mut ScanIndex,
    backfill_window_days: u64,
    growth: Option<&discovery_growth::Page>,
) {
    let mut traversal = index.traversal.take().expect("traversal initialized");
    refresh_retained_codex_directories(source, &mut traversal, backfill_window_days, index, growth);
    index.traversal = Some(traversal);
}

fn refresh_retained_codex_directories(
    source: SnapshotSource,
    traversal: &mut ScanTraversalCheckpoint,
    backfill_window_days: u64,
    index: &ScanIndex,
    growth: Option<&discovery_growth::Page>,
) {
    if source != SnapshotSource::Codex || !traversal.pending_directories.is_empty() {
        return;
    }
    let recovery = DiscoveryRecovery::from(&index.files);
    let retention = DiscoveryRetention {
        growth,
        ..discovery_retention!(index)
    };
    let moved = match traversal.codex_join_directory_census.as_ref() {
        // An unproved walk stays unproved until a fresh generation.
        Some(census) if census.local_diagnostic_counts().0 => census.moved_directories(),
        _ => return,
    };
    let census_unix_seconds = rfc3339_unix_seconds(&traversal.census_window_end);
    for directory in moved {
        let Some(scan_root) = traversal.owning_scan_root(&directory).cloned() else {
            continue;
        };
        let census = traversal
            .codex_join_directory_census
            .as_mut()
            .expect("census checked above");
        let (before, (present, appeared, new_directories)) =
            match census.relist(&directory, &traversal.codex_rollout_paths) {
                Ok(Some(listing)) => listing,
                Ok(None) if directory != scan_root => {
                    census.retire(&directory);
                    traversal
                        .codex_rollout_paths
                        .retain(|key| !Path::new(key).starts_with(&directory));
                    continue;
                }
                _ => continue,
            };
        census.refresh(&directory, &before);
        traversal.codex_rollout_paths.retain(|key| {
            Path::new(key).parent() != Some(directory.as_path()) || present.contains(key)
        });
        for (path, metadata) in appeared {
            traversal.codex_rollout_paths.insert(local_index_key(&path));
            let modified_unix_seconds = metadata
                .modified()
                .ok()
                .and_then(unix_seconds)
                .unwrap_or_default();
            retention.observe_stamped_growth(
                &path,
                metadata.len(),
                modified_unix_seconds,
                codex_fragment::Stamp::metadata(&metadata),
            );
            let aged = census_unix_seconds.is_some_and(|now| {
                !is_recent_enough_at(modified_unix_seconds, now, backfill_window_days)
            });
            let owes_stamped = aged
                && retention.owes_stamped(
                    source,
                    &path,
                    metadata.len(),
                    codex_fragment::Stamp::metadata(&metadata),
                );
            let requires_recovery = recovery.requires(source, &path, metadata.len());
            if !requires_recovery && aged && !owes_stamped {
                line_delivery_unselected(source.api_slug(), UnselectedReason::Age);
                continue;
            }
            if first_read_aged(index, &path, modified_unix_seconds, census_unix_seconds) {
                line_delivery_unselected(source.api_slug(), UnselectedReason::FirstReadAge);
                continue;
            }
            crate::local_resource_diagnostics::observe_file_size(source, metadata.len());
            traversal.counts.max_unread_bytes = traversal.counts.max_unread_bytes.max(
                metadata.len().saturating_sub(
                    retention
                        .files
                        .get(&local_index_key(&path))
                        .map_or(0, |entry| entry.size_bytes),
                ),
            );
            traversal.counts.discovered_file_count += 1;
            traversal.observed_index_keys.insert(local_index_key(&path));

            if let Some(existing) = traversal
                .pending_candidates
                .iter_mut()
                .find(|candidate| candidate.path == path)
            {
                existing.census_member = true;
                existing.watcher_hint = true;
            } else {
                traversal.pending_candidates.push_back(ScanTraversalPath {
                    scan_root: scan_root.clone(),
                    path,
                    census_member: true,
                    watcher_hint: true,
                });
            }
        }
        // A directory that appeared after the walk (a new Codex day) carries
        // the same freshness provenance as a rollout that appeared directly;
        // the walk hands it to every file beneath. Scheduling only.
        traversal
            .pending_directories
            .extend(new_directories.into_iter().map(|path| ScanTraversalPath {
                scan_root: scan_root.clone(),
                path,
                census_member: true,
                watcher_hint: true,
            }));
    }
}

/// F5: queue `keys` again as census members of the generation that observed
/// them. Each passes the ordinary candidate gate on a later page: one counted
/// read. Keys not observed, already queued or outside every root are skipped.
fn requeue_observed_keys(
    source: SnapshotSource,
    traversal: &mut ScanTraversalCheckpoint,
    keys: Vec<String>,
    cause: &'static str,
) {
    let queued = traversal
        .pending_candidates
        .iter()
        .map(|candidate| local_index_key(&candidate.path))
        .collect::<BTreeSet<_>>();
    let owed = keys
        .into_iter()
        .filter(|key| traversal.observed_index_keys.contains(key) && !queued.contains(key))
        .filter_map(|key| {
            let path = PathBuf::from(key);
            Some(ScanTraversalPath {
                scan_root: traversal.owning_scan_root(&path)?.clone(),
                path,
                census_member: true,
                watcher_hint: false,
            })
        })
        .collect::<Vec<_>>();
    if owed.is_empty() {
        return;
    }
    crate::local_resource_diagnostics::traversal_point(
        "discovery_requeue",
        source.api_slug(),
        &json!({"cause": cause, "requeued": owed.len()}),
    );
    traversal.pending_candidates.extend(owed);
}

/// F5, checkpoints an older binary wrote: once per process, queue again the
/// files a retained generation observed but never indexed. Its partial
/// checkpoint kept the page's traversal (file dequeued and observed) without
/// the unacknowledged entry, so the file waited for the next generation (K7).
/// Files another record owns (residue, inventory hold, terminal disposition,
/// decode hold), or gone are left alone.
fn requeue_unindexed_observed(source: SnapshotSource, index: &mut ScanIndex) {
    let Some(traversal) = index.traversal.as_ref() else {
        return;
    };
    let orphans = traversal
        .observed_index_keys
        .iter()
        .filter(|key| {
            !index.files.contains_key(*key)
                && !traversal.residue.index_keys.contains(*key)
                && !traversal
                    .residue
                    .codex_inventory_hold
                    .as_ref()
                    .is_some_and(|hold| hold.owed.contains(*key))
                && !index.terminal_jsonl_dispositions.contains_key(*key)
                && !index.claude_account_deferred_holds.contains_key(*key)
                && !index.decode_holds_file(key)
                && fs::symlink_metadata(key)
                    .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        })
        .cloned()
        .collect::<Vec<_>>();
    let traversal = index.traversal.as_mut().expect("traversal checked above");
    requeue_observed_keys(source, traversal, orphans, "load");
}

/// Remember the candidates an incomplete Codex header inventory held on this
/// page, with what made it incomplete. With an incomplete inventory every
/// selected candidate is held, so this page's residue is exactly the held
/// set. An inventory that hit a population or read bound, or had no stable
/// census, records nothing: only a fresh walk changes that, and the walk
/// selects them again.
fn record_codex_inventory_hold(
    traversal: &mut ScanTraversalCheckpoint,
    inventory: &codex_file_join::HeaderInventory,
    held: &BTreeSet<String>,
) {
    if held.is_empty() {
        return;
    }
    let outside_roster = held
        .iter()
        .filter(|key| !traversal.codex_rollout_paths.contains(*key))
        .map(|key| (key.clone(), codex_file_join::path_witness(Path::new(key))))
        .collect::<Vec<_>>();
    let hold = traversal
        .residue
        .codex_inventory_hold
        .get_or_insert_with(CodexInventoryHold::default);
    // Without a refused record or an unlisted candidate, the walk's open
    // directories were what kept the roster from proving the page.
    hold.awaiting_directories |= !traversal.pending_directories.is_empty()
        || (inventory.refused.is_empty() && outside_roster.is_empty());
    hold.owed.extend(held.iter().cloned());
    // The newest witness is the one a later tick has to see move.
    hold.refused_headers.extend(
        inventory
            .refused
            .iter()
            .map(|(key, witness)| (key.clone(), witness.clone())),
    );
    hold.outside_roster.extend(outside_roster);
}

/// Queue the candidates of a `CodexInventoryHold` again once its evidence
/// has moved: a refused first record changed, was replaced, is gone or left
/// the roster; a held
/// candidate outside the roster joined it or is gone; or the walk finished its
/// directories. The check costs one `lstat` per recorded path. Unmoved
/// evidence queues nothing, so a hold that cannot be resolved re-reads no
/// transcript. Only candidates still in the roster are queued, at the back,
/// after any watcher hints, and they meet the same inventory, ownership,
/// capture, send and checkpoint gates as any candidate. If the evidence still
/// does not prove the page, it is held and recorded again.
fn release_codex_inventory_hold(source: SnapshotSource, traversal: &mut ScanTraversalCheckpoint) {
    if source != SnapshotSource::Codex || !traversal.pending_directories.is_empty() {
        return;
    }
    let Some(hold) = traversal.residue.codex_inventory_hold.as_ref() else {
        return;
    };
    let moved = |key: &String, witness: &Option<String>| {
        codex_file_join::path_witness(Path::new(key)) != *witness
    };
    let released = hold.awaiting_directories
        || hold.refused_headers.iter().any(|(key, witness)| {
            // A record that vanished before its read has no witness to move;
            // leaving the roster is its evidence.
            !traversal.codex_rollout_paths.contains(key) || moved(key, witness)
        })
        || hold.outside_roster.iter().any(|(key, witness)| {
            traversal.codex_rollout_paths.contains(key) || moved(key, witness)
        });
    if !released {
        return;
    }
    let hold = traversal
        .residue
        .codex_inventory_hold
        .take()
        .expect("hold checked above");
    let mut pending = traversal
        .pending_candidates
        .iter()
        .map(|candidate| local_index_key(&candidate.path))
        .collect::<BTreeSet<_>>();
    let mut unlisted = CodexInventoryHold::default();
    for key in hold.owed {
        if !traversal.codex_rollout_paths.contains(&key) {
            // Selecting a file the roster cannot prove would hold the page
            // again. One that still exists stays owed until it is listed.
            if let Some(witness) = codex_file_join::path_witness(Path::new(&key)) {
                unlisted.outside_roster.insert(key.clone(), Some(witness));
                unlisted.owed.insert(key);
            }
            continue;
        }
        if !pending.insert(key.clone()) {
            continue;
        }
        let path = PathBuf::from(key);
        let Some(scan_root) = traversal.owning_scan_root(&path).cloned() else {
            continue;
        };
        traversal.pending_candidates.push_back(ScanTraversalPath {
            scan_root,
            path,
            census_member: true,
            watcher_hint: false,
        });
    }
    if !unlisted.owed.is_empty() {
        traversal.residue.codex_inventory_hold = Some(unlisted);
    }
}

#[derive(Clone, Copy)]
struct DiscoveryRecovery<'a> {
    files: &'a SharedMap<String, ScanIndexEntry>,
}
impl<'a> From<&'a SharedMap<String, ScanIndexEntry>> for DiscoveryRecovery<'a> {
    fn from(files: &'a SharedMap<String, ScanIndexEntry>) -> Self {
        Self { files }
    }
}
impl DiscoveryRecovery<'_> {
    fn requires(&self, source: SnapshotSource, path: &Path, length: u64) -> bool {
        sampled_audit::path_requires_recovery(source, self.files, path, length)
    }
}

/// Returns the indexed keys this tick's directory reads did not list.
#[cfg(test)]
fn advance_bounded_directory_traversal(
    source: SnapshotSource,
    index: &mut ScanIndex,
    backfill_window_days: u64,
    growth: Option<&discovery_growth::Page>,
) -> BTreeSet<String> {
    advance_bounded_directory_traversal_with_budget(
        source,
        index,
        backfill_window_days,
        directory_entries_per_tick(),
        growth,
    )
}

/// Adds to `unlisted` each indexed key beneath `directory` whose first
/// component there is not in `names`, the names listed in `directory`
/// (empty for a directory now gone). A listed child's subtree is skipped by
/// seeking past its prefix; its own read covers it. Nomination only: the
/// secure absence proof decides.
fn unlisted_index_keys(
    files: &SharedMap<String, ScanIndexEntry>,
    directory: &Path,
    names: &BTreeSet<String>,
    unlisted: &mut BTreeSet<String>,
) {
    use std::ops::Bound;
    use std::path::MAIN_SEPARATOR;
    let prefix = format!("{}{MAIN_SEPARATOR}", directory.to_string_lossy());
    let mut keys = files.range::<str, _>((Bound::Included(prefix.as_str()), Bound::Unbounded));
    while let Some((key, _)) = keys.next() {
        let Some(rest) = key.strip_prefix(prefix.as_str()) else {
            break;
        };
        let child = rest.split(MAIN_SEPARATOR).next().unwrap_or(rest);
        if !names.contains(child) {
            unlisted.insert(key.clone());
        } else if child.len() < rest.len() {
            let past = format!("{prefix}{child}{}", char::from(MAIN_SEPARATOR as u8 + 1));
            keys = files.range::<str, _>((Bound::Included(past.as_str()), Bound::Unbounded));
        }
    }
}

fn directory_entries_per_tick() -> usize {
    #[cfg(test)]
    if let Some(budget) = TEST_DIRECTORY_ENTRIES.with(std::cell::Cell::get) {
        return budget;
    }
    MAX_SCAN_DIRECTORY_ENTRIES_PER_TICK
}

#[cfg(test)]
thread_local! {
    static TEST_DIRECTORY_ENTRIES: std::cell::Cell<Option<usize>> =
        const { std::cell::Cell::new(None) };
}

/// Scaled per-tick directory budget for tests only, so a walk spans pages.
#[cfg(test)]
fn with_test_directory_entries<T>(budget: usize, run: impl FnOnce() -> T) -> T {
    struct Reset;
    impl Drop for Reset {
        fn drop(&mut self) {
            TEST_DIRECTORY_ENTRIES.with(|slot| slot.set(None));
        }
    }
    TEST_DIRECTORY_ENTRIES.with(|slot| slot.set(Some(budget)));
    let _reset = Reset;
    run()
}

#[cfg(test)]
type DirectoryReadFault = Box<dyn FnMut(&Path, bool) -> bool>;

#[cfg(test)]
thread_local! {
    static TEST_DIRECTORY_READ_FAULT: std::cell::RefCell<Option<DirectoryReadFault>> =
        const { std::cell::RefCell::new(None) };
}

/// `result` itself outside tests. A test fault sees each listed entry's read
/// (`false`) and type read (`true`) of `directory` and fails it with `true`.
#[cfg_attr(
    not(test),
    allow(unused_variables, reason = "only a test fault reads them")
)]
fn directory_read_fault<T>(
    directory: &Path,
    type_read: bool,
    result: std::io::Result<T>,
) -> std::io::Result<T> {
    #[cfg(test)]
    if TEST_DIRECTORY_READ_FAULT.with(|slot| {
        slot.borrow_mut()
            .as_mut()
            .is_some_and(|fault| fault(directory, type_read))
    }) {
        return Err(std::io::Error::other("injected directory read fault"));
    }
    result
}

/// Runs `run` with a directory entry/type read fault, for tests only.
#[cfg(test)]
fn with_directory_read_fault<T>(
    fault: impl FnMut(&Path, bool) -> bool + 'static,
    run: impl FnOnce() -> T,
) -> T {
    struct Reset;
    impl Drop for Reset {
        fn drop(&mut self) {
            TEST_DIRECTORY_READ_FAULT.with(|slot| slot.borrow_mut().take());
        }
    }
    TEST_DIRECTORY_READ_FAULT.with(|slot| *slot.borrow_mut() = Some(Box::new(fault)));
    let _reset = Reset;
    run()
}

fn advance_bounded_directory_traversal_with_budget(
    source: SnapshotSource,
    index: &mut ScanIndex,
    backfill_window_days: u64,
    max_entries: usize,
    growth: Option<&discovery_growth::Page>,
) -> BTreeSet<String> {
    let mut traversal = index
        .traversal
        .take()
        .expect("bounded traversal initialized");
    let mut unlisted = BTreeSet::new();
    let walk_issues = |counts: &ScanTraversalCounts| {
        (
            counts.directory_entry_cap_exceeded_count,
            counts.symlink_rejected_count,
            counts.unreadable_path_count,
            counts.disappeared_file_count,
        )
    };
    let issues_before = walk_issues(&traversal.counts);
    // Eligibility belongs to the frozen census generation, not to whichever
    // later tick happens to reach a directory. Otherwise a multi-page walk can
    // silently age boundary files out while still publishing the earlier
    // `census_window_end` as its agreement scope.
    let census_unix_seconds = rfc3339_unix_seconds(&traversal.census_window_end);
    let growth_retention = sampled_audit::growth_active(index);
    let move_sources = index.held_move_sources();
    let mut pending = traversal.pending_candidates.iter().enumerate().fold(
        BTreeMap::new(),
        |mut pending, (i, p)| {
            // Match main's .find(): first duplicate owns the role update.
            pending.entry(p.path.clone()).or_insert(i);
            pending
        },
    );
    let mut remaining = max_entries;
    // Marked directories are Codex days that appeared after a walk, not a walk.
    let root_walk = traversal
        .pending_directories
        .iter()
        .any(|directory| !directory.watcher_hint);
    let mut freshness = money_freshness::WalkFold::resume(source);
    let mut debt = g7_debt::Page::begin(source, index, &traversal, root_walk, &mut freshness);
    // A re-listing pass (directories without census membership) only queues
    // files that need a read. Its walk problems and counts belong to the next
    // generation's first walk: it never turns this generation red or green,
    // moves its census counts or touches the Codex directory census.
    // Except discovery of the members it adds: a path that joins this
    // generation's census pending set was discovered by it, so pending never
    // exceeds discovered (the status wire rejects skipped > discovered).
    let mut relisted_counts = None;
    let mut relisted_members = 0;
    let restore = |counts: &mut ScanTraversalCounts,
                   saved: Option<ScanTraversalCounts>,
                   members: &mut usize| {
        if let Some(mut saved) = saved {
            saved.listing_changes_without_hint = counts.listing_changes_without_hint;
            saved.listing_owed_requeued = counts.listing_owed_requeued;
            saved.discovered_file_count += std::mem::take(members);
            *counts = saved;
        }
    };
    while remaining > 0 {
        debt.counts(&traversal.counts, relisted_counts.as_ref());
        restore(
            &mut traversal.counts,
            relisted_counts.take(),
            &mut relisted_members,
        );
        let Some(directory) = traversal.pending_directories.pop_front() else {
            break;
        };
        let relisting = !directory.census_member;
        relisted_counts = relisting.then(|| traversal.counts.clone());
        let metadata = match fs::symlink_metadata(&directory.path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                // A queued directory gone mid-walk still counts as a lost
                // listing; its indexed subtree is offered to the absence proof.
                debt.unlisted();
                disappearance_diagnostics::not_found(
                    &mut traversal.counts.disappeared_file_count,
                    source,
                    disappearance_diagnostics::Site::WalkDirectory,
                );
                unlisted_index_keys(
                    &index.files,
                    &directory.path,
                    &BTreeSet::new(),
                    &mut unlisted,
                );
                continue;
            }
            Err(_) => {
                traversal
                    .counts
                    .record_unreadable(UnreadableCause::Metadata, 1);
                continue;
            }
        };
        if metadata.file_type().is_symlink() {
            traversal.counts.symlink_rejected_count += 1;
            continue;
        }
        if !metadata.is_dir() {
            continue;
        }
        let mut listing = match fs::read_dir(&directory.path) {
            Ok(listing) => listing,
            Err(_) => {
                traversal
                    .counts
                    .record_unreadable(UnreadableCause::Directory, 1);
                continue;
            }
        };
        // Pacing budget, never a refusal: read the budget still available in
        // this tick plus one entry. A directory that does not fit a partly
        // spent tick resumes first next tick; on a fresh tick it is listed in
        // full and the overdraw ends the tick.
        let mut entries = listing.by_ref().take(remaining + 1).collect::<Vec<_>>();
        if let Some(census) = traversal
            .codex_join_directory_census
            .as_mut()
            .filter(|_| !relisting)
        {
            census.observe(&directory.path, &metadata);
        }
        if entries.len() > remaining {
            if remaining < max_entries {
                traversal.pending_directories.push_front(directory);
                break;
            }
            entries.extend(listing);
        }
        remaining = remaining.saturating_sub(entries.len());
        entries.sort_by(|left, right| {
            left.as_ref()
                .map(|entry| entry.file_name())
                .ok()
                .cmp(&right.as_ref().map(|entry| entry.file_name()).ok())
        });
        let sibling_paths: BTreeSet<_> = traversal
            .codex_rollout_paths
            .iter()
            .cloned()
            .chain(
                entries
                    .iter()
                    .filter_map(|entry| entry.as_ref().ok())
                    .map(|entry| local_index_key(&entry.path())),
            )
            .collect();
        // Listed names. A key missing only from a partial listing is just a
        // nominee: the absence proof refuses any key still present.
        let mut names = BTreeSet::new();
        for entry in entries {
            let entry = match directory_read_fault(&directory.path, false, entry) {
                Ok(entry) => entry,
                Err(_) => {
                    traversal
                        .counts
                        .record_unreadable(UnreadableCause::Directory, 1);
                    continue;
                }
            };
            let path = entry.path();
            names.insert(entry.file_name().to_string_lossy().into_owned());
            let file_type = match directory_read_fault(&directory.path, true, entry.file_type()) {
                Ok(file_type) => file_type,
                Err(_) => {
                    traversal
                        .counts
                        .record_unreadable(UnreadableCause::Metadata, 1);
                    continue;
                }
            };
            if file_type.is_symlink() {
                traversal.counts.symlink_rejected_count += 1;
                continue;
            }
            // Only retained-roster refresh marks a directory; the initial
            // history walk starts unmarked, so cold history stays FIFO.
            if file_type.is_dir() {
                traversal.pending_directories.push_back(ScanTraversalPath {
                    scan_root: directory.scan_root.clone(),
                    path,
                    census_member: directory.census_member,
                    watcher_hint: directory.watcher_hint,
                });
                continue;
            }
            if !file_type.is_file() || !transcript_path_admitted(source, &path) {
                continue;
            }
            if source == SnapshotSource::ClaudeCode
                && claude_transcript_excluded_from_snapshots(&path)
            {
                debt.excluded(&path, entry.metadata().ok().as_ref());
                continue;
            }
            if source == SnapshotSource::Codex {
                traversal.codex_rollout_paths.insert(local_index_key(&path));
                if codex_file_join::shadowed_compressed_path(&path, &sibling_paths) {
                    continue;
                }
            }
            let metadata = match entry.metadata() {
                Ok(metadata) => metadata,
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                    disappearance_diagnostics::not_found(
                        &mut traversal.counts.disappeared_file_count,
                        source,
                        disappearance_diagnostics::Site::WalkEntry,
                    );
                    continue;
                }
                Err(_) => {
                    traversal
                        .counts
                        .record_unreadable(UnreadableCause::Metadata, 1);
                    continue;
                }
            };
            if source == SnapshotSource::ClaudeCode {
                index.rehome_discovered_account_hold(
                    &mut traversal,
                    &move_sources,
                    &path,
                    &metadata,
                );
            }
            let recovery = DiscoveryRecovery::from(&index.files);
            let retention = DiscoveryRetention {
                growth,
                ..discovery_retention!(index)
            };
            let modified_unix_seconds = metadata
                .modified()
                .ok()
                .and_then(unix_seconds)
                .unwrap_or_default();
            retention.observe_stamped_growth(
                &path,
                metadata.len(),
                modified_unix_seconds,
                codex_fragment::Stamp::metadata(&metadata),
            );
            let aged = census_unix_seconds.is_some_and(|now| {
                !is_recent_enough_at(modified_unix_seconds, now, backfill_window_days)
            });
            let first_read_aged = !pending.contains_key(&path)
                && first_read_aged(index, &path, modified_unix_seconds, census_unix_seconds);
            let listing = g7_debt::Listing {
                path: &path,
                metadata: &metadata,
                in_window: !(aged || first_read_aged),
            };
            debt.listed(index, listing);
            let owes_stamped = aged
                && retention.owes_stamped(
                    source,
                    &path,
                    metadata.len(),
                    codex_fragment::Stamp::metadata(&metadata),
                );
            let requires_recovery = recovery.requires(source, &path, metadata.len());
            if !requires_recovery
                && aged
                && !owes_stamped
                && !sampled_audit::growth_selectable(
                    source,
                    &path,
                    growth_retention.then(|| &index.v2().growth_retention),
                )
            {
                if !relisting {
                    line_delivery_unselected(source.api_slug(), UnselectedReason::Age);
                }
                continue;
            }
            if first_read_aged {
                if !relisting {
                    line_delivery_unselected(source.api_slug(), UnselectedReason::FirstReadAge);
                }
                continue;
            }
            let mut owed_unchanged = false;
            if relisting {
                let key = local_index_key(&path);
                // Unchanged and not owed: seen, never queued. A file this
                // generation already saw with no entry (held) has
                // no stamp; its owner's floor re-offers it. A Codex inventory
                // hold is released only by its own evidence.
                let seen = if traversal
                    .residue
                    .codex_inventory_hold
                    .as_ref()
                    .is_some_and(|hold| hold.owed.contains(&key))
                {
                    true
                } else if index.files.contains_key(&key) {
                    index.listing_unchanged(&path, &metadata)
                } else {
                    traversal.observed_index_keys.contains(&key)
                };
                if seen {
                    traversal.observed_index_keys.insert(key);
                    continue;
                }

                owed_unchanged = index.listing_stamp_matches(&path, &metadata);
                if owed_unchanged
                    && !pending.contains_key(&path)
                    && !pace_listing_owed(&mut traversal, &key)
                {
                    traversal.observed_index_keys.insert(key);
                    continue;
                }
            }
            let census_member = !relisting || fresh_path_census_member(source, &traversal, &path);
            // Presence and enqueue authority are separate. A new-round walk
            // sees pending/floor-blocked files even when it adds no read work.
            crate::local_resource_diagnostics::observe_file_size(source, metadata.len());
            traversal.counts.max_unread_bytes = traversal.counts.max_unread_bytes.max(
                metadata.len().saturating_sub(
                    index
                        .files
                        .get(&local_index_key(&path))
                        .map_or(0, |entry| entry.size_bytes),
                ),
            );
            traversal.counts.discovered_file_count += 1;
            let first_observed = traversal.observed_index_keys.insert(local_index_key(&path));

            if let Some(&position) = pending.get(&path) {
                if !relisting {
                    let existing = traversal
                        .pending_candidates
                        .get_mut(position)
                        .expect("walk queue position");
                    existing.census_member = true;
                    existing.watcher_hint |= directory.watcher_hint;
                }
            } else {
                // A re-listed change is fresh data and joins the census by
                // the watcher-hint rule.
                traversal.counts.listing_changes_without_hint +=
                    u64::from(relisting && !owed_unchanged);
                traversal.counts.listing_owed_requeued += u64::from(owed_unchanged);
                relisted_members += usize::from(relisting && census_member && first_observed);
                pending.insert(path.clone(), traversal.pending_candidates.len());
                traversal.pending_candidates.push_back(ScanTraversalPath {
                    scan_root: directory.scan_root.clone(),
                    path,
                    census_member,
                    watcher_hint: relisting || directory.watcher_hint,
                });
            }
        }
        unlisted_index_keys(&index.files, &directory.path, &names, &mut unlisted);
    }
    debt.counts(&traversal.counts, relisted_counts.as_ref());
    restore(
        &mut traversal.counts,
        relisted_counts,
        &mut relisted_members,
    );
    if walk_issues(&traversal.counts) != issues_before {
        debt.walk_issue();
        if let Some(census) = traversal.codex_join_directory_census.as_mut() {
            census.invalidate_walk();
        }
    }
    let walk_ended = traversal.pending_directories.is_empty();
    let debt = debt.end(index, walk_ended);
    if root_walk {
        freshness.page_end(source, walk_ended, debt);
    }
    index.traversal = Some(traversal);
    unlisted
}

/// A Claude transcript that is NotFound while its parent is still a real
/// directory (not a symlink) was deleted or renamed: no retry can recover it,
/// so the census settles it as a removal, the same as a watcher remove hint.
/// A missing, renamed or unmounted parent is not evidence of removal and keeps
/// the NotFound as loss.
fn claude_absence_is_removal(source: SnapshotSource, path: &Path) -> Parent {
    if source != SnapshotSource::ClaudeCode {
        return Parent::OtherSource;
    }
    #[cfg(test)]
    disappearance_diagnostics::before_absence_parent_probe();
    match path.parent().map(fs::symlink_metadata) {
        Some(Ok(parent)) if parent.file_type().is_symlink() => Parent::Symlink,
        Some(Ok(parent)) if parent.is_dir() => Parent::Live,
        Some(Ok(_)) => Parent::NotDirectory,
        Some(Err(error)) if error.kind() != std::io::ErrorKind::NotFound => Parent::MetadataError,
        _ => Parent::Missing,
    }
}

/// Mutable candidate-boundary owner plus the same bounded member view used by
/// discovery. Built once per selection batch; no filesystem work or move authority.
struct CandidateDiscovery<'a> {
    index: &'a mut ScanIndex,
    sources: std::borrow::Cow<'a, BTreeMap<String, Option<String>>>,
    growth: Option<&'a discovery_growth::Page>,
}
impl<'a> CandidateDiscovery<'a> {
    fn new(index: &'a mut ScanIndex, growth: Option<&'a discovery_growth::Page>) -> Self {
        let sources = index.held_move_sources();
        Self {
            index,
            sources: std::borrow::Cow::Owned(sources),
            growth,
        }
    }
}

fn candidate_from_traversal_path(
    source: SnapshotSource,
    pending: ScanTraversalPath,
    census: &mut ScanCensus,
    census_unix_seconds: Option<u64>,
    backfill_window_days: u64,
    discovery: &mut CandidateDiscovery<'_>,
) -> Option<CandidateFile> {
    candidate_from_traversal_path_at(
        source,
        disappearance_diagnostics::Site::CandidateWalk,
        pending,
        census,
        census_unix_seconds,
        backfill_window_days,
        discovery,
    )
}

/// Open-admission inputs: census clock, backfill window, main's owed-key
/// retention and v2 growth debt (None for a v1 graph).
#[derive(Clone, Copy)]
struct CandidateWindow<'a> {
    census_unix_seconds: Option<u64>,
    backfill_window_days: u64,
    retention: DiscoveryRetention<'a>,
    growth: Option<&'a BTreeMap<String, sampled_audit::GrowthRetention>>,
}

fn candidate_from_traversal_path_at(
    source: SnapshotSource,
    site: disappearance_diagnostics::Site,
    pending: ScanTraversalPath,
    census: &mut ScanCensus,
    census_unix_seconds: Option<u64>,
    backfill_window_days: u64,
    discovery: &mut CandidateDiscovery<'_>,
) -> Option<CandidateFile> {
    let metadata = match fs::symlink_metadata(&pending.path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            if pending.watcher_hint {
                // Remove/rename events legitimately name an object that no
                // longer exists. They are not lossy census failures; remove an
                // earlier observation so terminal reconciliation can delete
                // the stale entry exactly.
                census
                    .removed_index_keys
                    .insert(local_index_key(&pending.path));
            } else if pending.census_member {
                let parent = claude_absence_is_removal(source, &pending.path);
                if parent.is_removal(&pending.path) {
                    // The same exact retirement as a remove hint, whichever
                    // order the hint and the queued member arrived in.
                    disappearance_diagnostics::not_found_removal(source, site);
                    let index_key = local_index_key(&pending.path);
                    census.claude_vanished_index_keys.insert(index_key.clone());
                    census.removed_index_keys.insert(index_key);
                } else {
                    disappearance_diagnostics::not_found(
                        &mut census.disappeared_file_count,
                        source,
                        site,
                    );
                }
            }
            return None;
        }
        Err(_) => {
            if pending.census_member {
                census.record_unreadable(UnreadableCause::Metadata, 1);
            }
            return None;
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        if pending.census_member && metadata.file_type().is_symlink() {
            census.symlink_rejected_count += 1;
        }
        return None;
    }
    if source == SnapshotSource::ClaudeCode {
        if let Some(mut walk) = discovery.index.traversal.take() {
            discovery.index.rehome_discovered_account_hold(
                &mut walk,
                &discovery.sources,
                &pending.path,
                &metadata,
            );
            discovery.index.traversal = Some(walk);
        }
    }
    let recovery = DiscoveryRecovery::from(&discovery.index.files);
    let retention = DiscoveryRetention {
        growth: discovery.growth,
        ..discovery_retention!(discovery.index)
    };
    retention.observe_stamped_growth(
        &pending.path,
        metadata.len(),
        metadata
            .modified()
            .ok()
            .and_then(unix_seconds)
            .unwrap_or_default(),
        codex_fragment::Stamp::metadata(&metadata),
    );

    let modified_unix_seconds = metadata
        .modified()
        .ok()
        .and_then(unix_seconds)
        .unwrap_or_default();
    let aged = census_unix_seconds
        .is_some_and(|now| !is_recent_enough_at(modified_unix_seconds, now, backfill_window_days));
    let owes_stamped = aged
        && retention.owes_stamped(
            source,
            &pending.path,
            metadata.len(),
            codex_fragment::Stamp::metadata(&metadata),
        );
    let requires_recovery = recovery.requires(source, &pending.path, metadata.len());
    if !requires_recovery
        && aged
        && !owes_stamped
        && !sampled_audit::growth_selectable(
            source,
            &pending.path,
            sampled_audit::growth_active(discovery.index)
                .then(|| &discovery.index.v2().growth_retention),
        )
    {
        // Watcher hints must not widen the configured activity window. The
        // same revalidation also handles an ordinary candidate whose mtime was
        // restored behind the cutoff after directory discovery.
        if pending.census_member {
            census
                .removed_index_keys
                .insert(local_index_key(&pending.path));
        }
        return None;
    }
    let modified_unix_nanos = metadata
        .modified()
        .ok()
        .and_then(unix_nanos)
        .unwrap_or_else(|| modified_unix_seconds.saturating_mul(1_000_000_000));
    if pending.census_member {
        census
            .observed_index_keys
            .insert(local_index_key(&pending.path));
    }
    Some(CandidateFile {
        physical_identity: None,
        scan_root: pending.scan_root,
        source_file_fingerprint: String::new(),
        path: pending.path,
        size_bytes: metadata.len(),
        modified_unix_seconds,
        modified_unix_nanos,
        legacy_source_file_fingerprint: String::new(),
        legacy_config_reconciliation_required: false,
        opened_object_identity: String::new(),
        fingerprint_changed_nanos: 0,
        fingerprint_birth_nanos: 0,
        withheld_content_stamp: None,
    })
}

#[inline(never)]
fn reconcile_missing_index_entries_bounded(index: &mut ScanIndex, source: SnapshotSource) -> bool {
    reconcile_missing_index_entries_with_side(index, MAX_BACKFILL_FILES_PER_SOURCE, source)
}

#[cfg(test)]
fn reconcile_missing_index_entries_with_limit(index: &mut ScanIndex, limit: usize) -> bool {
    reconcile_missing_index_entries_with_side(index, limit, SnapshotSource::ClaudeCode)
}

fn reconcile_missing_index_entries_with_side(
    index: &mut ScanIndex,
    limit: usize,
    source: SnapshotSource,
) -> bool {
    let Some(snapshot) = index.traversal.as_ref() else {
        return false;
    };
    let Some(upper_bound) = snapshot.reconciliation_upper_bound.clone() else {
        return true;
    };
    let after = snapshot.reconciliation_after.clone();
    let lower_bound = after
        .clone()
        .map_or(std::ops::Bound::Unbounded, std::ops::Bound::Excluded);
    let growth_roots = (source == SnapshotSource::ClaudeCode
        && sampled_audit::growth_active(index))
    .then(|| snapshot.scan_roots.clone());
    // Restored residue whose status is unknown shares this page's limit.
    // It can lie behind a saved cursor; no separate metadata sweep runs.
    let mut page = if growth_roots.is_some() {
        snapshot
            .residue
            .index_keys
            .iter()
            .filter(|key| {
                index.files.contains_key(*key)
                    && index
                        .v2()
                        .growth_retention
                        .get(*key)
                        .map_or(true, |state| state.checked_generation.is_none())
            })
            .take(limit)
            .cloned()
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let residue_count = page.len();
    let mut regular = index
        .files
        .range((
            lower_bound.clone(),
            std::ops::Bound::Included(upper_bound.clone()),
        ))
        .filter(|(key, _)| page.binary_search(key).is_err())
        .take(limit.saturating_sub(residue_count))
        .map(|(key, _)| key.clone())
        .collect::<Vec<_>>();
    regular.sort();
    regular.dedup();
    regular.truncate(limit.saturating_sub(residue_count));
    let regular_after = regular.last().cloned().or(after.clone());
    let regular_done =
        regular.last() == Some(&upper_bound) || regular.len() < limit.saturating_sub(residue_count);
    page.extend(regular);
    if page.is_empty() {
        return growth_roots.is_none()
            || !index.traversal.as_ref().is_some_and(|walk| {
                walk.pending_candidates
                    .iter()
                    .any(|path| path.census_member)
            });
    }
    let mut growth_queued = false;
    let account_members = index.observed_account_members();
    let unacked = index.unacked_bodies(&page);
    for key in &page {
        let observed = index
            .traversal
            .as_ref()
            .is_some_and(|traversal| traversal.observed_index_keys.contains(key));
        if let Some(roots) = growth_roots.as_ref() {
            if sampled_audit::revalidate_growth(index, key, roots) {
                growth_queued = true;
                continue;
            }
        }
        // The existing reconciliation page bounds these index-driven absence
        // probes. Missing roots or unsafe ancestors keep the hold; a missing
        // intermediate component beneath the validated root proves absence.
        if !observed && index.claude_account_deferred_holds.contains_key(key) {
            index.retire_absent_account_hold(key, &account_members);
            // Complete this item, preserving incidence handling. An unsafe
            // or uncertain ancestor keeps its obligation and also stops here.
            continue;
        }
        // An unobserved marked entry still needs positive filesystem proof;
        // unsafe ancestors, missing roots and permission failures keep debt.
        if !observed
            && index
                .files
                .get(key)
                .is_some_and(ScanIndexEntry::has_unverified_source)
            && index
                .traversal
                .as_ref()
                .is_some_and(|walk| sampled_audit::proven_absent(Path::new(key), &walk.scan_roots))
        {
            if index
                .files
                .get(key)
                .is_some_and(ScanIndexEntry::codex_history_is_protected)
                || (source == SnapshotSource::Codex
                    && !codex_counting_version::tombstone_before_retire(index, key))
            {
                index
                    .files
                    .get_mut(key)
                    .expect("protected audit")
                    .scan_identity_version = Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
            } else {
                index.retire_vanished_claude_audit_debt_entry(key);
            }
            crate::local_resource_diagnostics::audit_retired_absent(source.api_slug());
            continue; // SOURCE: debt retirement alone does not prune incidence.
        }
        if !observed
            && !index.decode_holds_file(key)
            && !index
                .files
                .get(key)
                .is_some_and(ScanIndexEntry::retain_history_evidence)
            && codex_counting_version::tombstone_before_retire(index, key)
        {
            index.drop_file_entry(key);
            index.file_snapshot_fingerprints.remove(key);
        }
    }
    index.count_unacked_retired(source, unacked);
    let done = regular_done && residue_count < limit;
    if let Some(traversal) = index.traversal.as_mut() {
        traversal.reconciliation_started = true;
        traversal.reconciliation_after = regular_after;
    }
    done && !growth_queued
}

#[cfg(test)]
fn collect_recent_jsonl_files(
    source: SnapshotSource,
    scan_root: &Path,
    root: &Path,
    selection: &mut BoundedCandidateSelection,
    census: &mut ScanCensus,
    backfill_window_days: u64,
) {
    let root_metadata = match fs::symlink_metadata(root) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return,
        Err(_) => {
            census.record_unreadable(UnreadableCause::Metadata, 1);
            return;
        }
    };
    if root_metadata.file_type().is_symlink() {
        census.symlink_rejected_count += 1;
        return;
    }
    if !root_metadata.is_dir() {
        return;
    }
    let entries = match fs::read_dir(root) {
        Ok(entries) => entries,
        Err(_) => {
            census.record_unreadable(UnreadableCause::Directory, 1);
            return;
        }
    };
    for entry in entries {
        let entry = match entry {
            Ok(entry) => entry,
            Err(_) => {
                census.record_unreadable(UnreadableCause::Directory, 1);
                continue;
            }
        };
        let path = entry.path();
        let file_type = match entry.file_type() {
            Ok(file_type) => file_type,
            Err(_) => {
                census.record_unreadable(UnreadableCause::Metadata, 1);
                continue;
            }
        };
        if file_type.is_symlink() {
            census.symlink_rejected_count += 1;
            continue;
        }
        if file_type.is_dir() {
            collect_recent_jsonl_files(
                source,
                scan_root,
                &path,
                selection,
                census,
                backfill_window_days,
            );
            continue;
        }
        if !file_type.is_file() {
            continue;
        }
        if !transcript_path_admitted(source, &path) {
            continue;
        }
        // Claude's Workflow-tool journal is bookkeeping, never a session. Drop
        // it before it can be fingerprinted, indexed, or parsed.
        if source == SnapshotSource::ClaudeCode && claude_transcript_excluded_from_snapshots(&path)
        {
            continue;
        }
        let metadata = match entry.metadata() {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                disappearance_diagnostics::increment(
                    &mut census.disappeared_file_count,
                    source,
                    disappearance_diagnostics::Cause::NotFound,
                );
                continue;
            }
            Err(_) => {
                census.record_unreadable(UnreadableCause::Metadata, 1);
                continue;
            }
        };
        let modified_unix_seconds = metadata
            .modified()
            .ok()
            .and_then(unix_seconds)
            .unwrap_or_default();
        let modified_unix_nanos = metadata
            .modified()
            .ok()
            .and_then(unix_nanos)
            .unwrap_or_else(|| modified_unix_seconds.saturating_mul(1_000_000_000));
        if !is_recent_enough(modified_unix_seconds, backfill_window_days) {
            continue;
        }
        census.discovered_file_count += 1;
        census.observed_index_keys.insert(local_index_key(&path));
        selection.insert(CandidateFile {
            physical_identity: None,
            scan_root: scan_root.to_path_buf(),
            source_file_fingerprint: String::new(),
            path,
            size_bytes: metadata.len(),
            modified_unix_seconds,
            modified_unix_nanos,
            legacy_source_file_fingerprint: String::new(),
            legacy_config_reconciliation_required: false,
            opened_object_identity: String::new(),
            fingerprint_changed_nanos: 0,
            fingerprint_birth_nanos: 0,
            withheld_content_stamp: None,
        });
    }
}

#[cfg(test)]
fn is_recent_enough(modified_unix_seconds: u64, backfill_window_days: u64) -> bool {
    let Some(now) = unix_seconds(SystemTime::now()) else {
        return true;
    };
    is_recent_enough_at(modified_unix_seconds, now, backfill_window_days)
}

fn is_recent_enough_at(
    modified_unix_seconds: u64,
    now_unix_seconds: u64,
    backfill_window_days: u64,
) -> bool {
    let window_seconds = effective_backfill_window_days(backfill_window_days) * 24 * 60 * 60;
    modified_unix_seconds >= now_unix_seconds.saturating_sub(window_seconds)
}

/// The first-read bound in days. It is in no walk identity: the walk, its
/// pruning and the uploaded window keep `backfill_window_days`.
const FIRST_READ_WINDOW_DAYS: u64 = 60;

/// First-seen bound: a file never read, whose mtime is older than
/// `FIRST_READ_WINDOW_DAYS` at the census time, is not admitted for a first
/// read. Any read evidence keeps the walk window: an index entry (it also
/// carries every recovery and verification debt), confirmed-empty, an account
/// hold, a committed Tail head (G7 debt included; an unreadable store counts
/// as one), or a legacy held archive member key. The latter grants eligibility
/// only; ordinary header and ownership admission still apply.
/// Checked where a file is first admitted (the walk, a watcher hint, the Codex
/// roster refresh). Queued work and the open recheck keep the walk window.
fn first_read_aged(
    index: &ScanIndex,
    path: &Path,
    modified_unix_seconds: u64,
    census_unix_seconds: Option<u64>,
) -> bool {
    if census_unix_seconds.map_or(true, |now| {
        is_recent_enough_at(modified_unix_seconds, now, FIRST_READ_WINDOW_DAYS)
    }) {
        return false;
    }
    let key = local_index_key(path);
    let read = index.files.contains_key(&key)
        || index.confirmed_empty_files.contains(&key)
        || index.claude_account_deferred_holds.contains_key(&key)
        || (!matches!(state_v2::tail_route_path(index), Ok(None))
            && (!matches!(state_v2::load_head(index, &key, u32::MAX), Ok(None))
                || (codex_archive_path(path)
                    && !matches!(state_v2::legacy_archive_was_seen(index, &key), Ok(false)))));
    !read
}

/// Per-caller derived view, bounded by the held inventory; never move proof.
struct AccountMoveObservations {
    paths: BTreeMap<String, Vec<String>>,
    through: Option<String>,
}

/// Owed-key discovery retention, the one shared exemption from the discovery
/// window (`docs/diagnostics.md`, "Owed-key discovery retention"). Contract: a
/// key owed by any registered source stays discoverable and observed whatever
/// its age while owed, so reconciliation never prunes it; its growth takes the
/// counted Tail path; only a validated catch-up or a proven, counted removal
/// releases it; it is never a Full cause. File-size caps still apply.
/// Grown since committed: retention ends when the growth is committed
/// (`size_bytes` catches up). Equal and truncated lengths gain no exemption.
/// Source-agnostic (the Claude walk, candidate and open gates, the Codex roster).
/// Register a source with its field, its
/// line in `discovery_retention!` and `unverified`, and its line in `owes`.
#[derive(Clone, Copy)]
struct DiscoveryRetention<'a> {
    /// Entries; an unverified sampled generation (`sampled_audit`) is owed.
    files: &'a SharedMap<String, ScanIndexEntry>,
    /// Correctness hold: unresolved ownership debt stays discoverable, including growth.
    /// Only the approved interim withheld_reparse{start,evidence,growth} exception may Full.
    /// At the hold cap no new exemption is invented; unknown identity cannot memo-Skip.
    account_holds: &'a BTreeMap<String, String>,
    memo: Option<&'a withheld_account::Memo>,
    /// Bounded page diagnostics only; never a retention/selection input.
    growth: Option<&'a discovery_growth::Page>,
}

impl<'a> DiscoveryRetention<'a> {
    fn observe_stamped_growth(
        &self,
        path: &Path,
        len: u64,
        modified: u64,
        stamp: Option<codex_fragment::Stamp>,
    ) {
        let key = local_index_key(path);
        if self.account_holds.contains_key(&key) {
            // This gate already has physical presence; invalidate an earlier
            // absence even if the file disappears again before page completion.
            if let Some(memo) = self.memo {
                memo.reset_absence(&key);
            }
        }
        if let Some(page) = self.growth {
            if self
                .files
                .get(&key)
                .is_some_and(|entry| codex_fragment::grown(entry, len, stamp))
            {
                page.observe_stamped(key, len, modified, stamp);
            }
        }
    }

    /// Owed by a registered source: the discovery window does not apply.
    fn owes(&self, path: &Path) -> bool {
        sampled_audit::path_requires_verification(self.files, path)
            || self.account_holds.contains_key(&local_index_key(path))
    }

    fn owes_stamped(
        &self,
        source: SnapshotSource,
        path: &Path,
        current_len: u64,
        stamp: Option<codex_fragment::Stamp>,
    ) -> bool {
        let grown = self
            .files
            .get(&local_index_key(path))
            .is_some_and(|entry| codex_fragment::grown(entry, current_len, stamp));
        if grown {
            crate::local_resource_diagnostics::discovery_retained_grown(source.api_slug());
        }
        grown || self.owes(path)
    }
}

#[cfg(test)]
mod discovery_support {
    use super::*;
    impl<'a> DiscoveryRetention<'a> {
        /// Use the current metadata already held by the gate, never another stat.
        /// Count an aged growth-retention decision once, even if another arm owes it.
        pub(in crate::snapshots) fn owes_with_len(
            &self,
            source: SnapshotSource,
            path: &Path,
            current_len: u64,
        ) -> bool {
            self.owes_stamped(source, path, current_len, None)
        }
        /// Entries only: no other owed source (tests and index-free callers).
        pub(in crate::snapshots) fn unverified(
            files: &'a SharedMap<String, ScanIndexEntry>,
        ) -> Self {
            static NONE: BTreeMap<String, String> = BTreeMap::new();
            Self {
                files,
                account_holds: &NONE,
                memo: None,
                growth: None,
            }
        }
    }
}

fn opened_candidate_is_within_frozen_window(
    candidate: &CandidateFile,
    census_unix_seconds: Option<u64>,
    backfill_window_days: u64,
) -> bool {
    census_unix_seconds.map_or(true, |now| {
        is_recent_enough_at(candidate.modified_unix_seconds, now, backfill_window_days)
    })
}

fn effective_backfill_window_days(requested_backfill_window_days: u64) -> u64 {
    requested_backfill_window_days.min(BACKFILL_WINDOW_DAYS)
}

