struct CheckpointLock {
    file: File,
    priority_path: Option<PathBuf>,
    maintenance: bool,
    custody: bool,
}

impl CheckpointLock {
    fn acquire(path: &Path) -> Result<Self> {
        Self::acquire_mode(path, false)
    }
    fn acquire_mode(path: &Path, maintenance: bool) -> Result<Self> {
        Self::acquire_with_custody(path, maintenance, None)
    }
    fn acquire_with_custody(path: &Path, maintenance: bool, custody: Option<bool>) -> Result<Self> {
        let lock_path = path.with_extension("lock");
        if let Some(parent) = lock_path.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create checkpoint directory {}", parent.display()))?;
        }
        let file = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&lock_path)
            .context("open local snapshot checkpoint lock")?;
        // Custody is the single authority for v2 maintenance priority. Routes
        // the store does not serve keep main's nonblocking flock behavior,
        // including when the v2 checkpoint-owner registry is poisoned.
        // Maintenance already owns a reservation even if its runtime was
        // invalidated while it waited for the previous checkpoint owner.
        let custody = match custody {
            Some(value) => value,
            None => state_v2::published(path)?,
        };
        let priority = maintenance || custody;
        let mut owners = if priority {
            Some(
                checkpoint_owners()
                    .0
                    .lock()
                    .map_err(|_| anyhow::anyhow!("checkpoint_owner_registry"))?,
            )
        } else {
            None
        };
        if !maintenance
            && owners
                .as_ref()
                .is_some_and(|o| o.maintenance.contains(path))
        {
            anyhow::bail!("state_v2_maintenance_pause");
        }
        #[cfg(unix)]
        {
            let status = unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) };
            if status != 0 {
                return Err(std::io::Error::last_os_error())
                    .context("local snapshot checkpoint is owned by another daemon");
            }
        }
        if let Some(owners) = owners.as_mut() {
            owners.owned.insert(path.to_owned());
        }
        Ok(Self {
            file,
            priority_path: priority.then(|| path.to_owned()),
            maintenance,
            custody,
        })
    }
}

impl Drop for CheckpointLock {
    fn drop(&mut self) {
        let mut owners = self
            .priority_path
            .as_ref()
            .and_then(|_| checkpoint_owners().0.lock().ok());
        #[cfg(unix)]
        unsafe {
            libc::flock(self.file.as_raw_fd(), libc::LOCK_UN);
        }
        if let (Some(owners), Some(path)) = (owners.as_mut(), self.priority_path.as_ref()) {
            owners.owned.remove(path);
            if self.maintenance {
                owners.maintenance.remove(path);
            }
            checkpoint_owners().1.notify_all();
        }
    }
}

fn sync_checkpoint_parent(path: &Path) -> Result<()> {
    let Some(parent) = path.parent() else {
        return Ok(());
    };
    File::open(parent)
        .and_then(|directory| directory.sync_all())
        .with_context(|| format!("sync checkpoint directory {}", parent.display()))
}

fn unique_checkpoint_sibling(path: &Path, kind: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    path.with_extension(format!("{kind}.{}.{nanos}.json", std::process::id()))
}

/// A malformed stored Claude history cutoff decodes as this; the load drops
/// it with the gate marker (`drop_malformed_claude_history_cutoff`). A real
/// cutoff is clamped to the clock, so it never reaches this value.
const MALFORMED_CLAUDE_HISTORY_CUTOFF: u64 = u64::MAX;

/// Lenient decode: a non-number cutoff never fails the
/// whole index decode.
fn deserialize_lenient_claude_history_cutoff<'de, D>(
    deserializer: D,
) -> std::result::Result<Option<u64>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    Ok(match Value::deserialize(deserializer)? {
        Value::Null => None,
        value => Some(value.as_u64().unwrap_or(MALFORMED_CLAUDE_HISTORY_CUTOFF)),
    })
}

/// Lenient decode: any stored value but `true` is `false`,
/// never a failed index decode.
fn deserialize_lenient_true<'de, D>(deserializer: D) -> std::result::Result<bool, D::Error>
where
    D: serde::Deserializer<'de>,
{
    Ok(matches!(
        Value::deserialize(deserializer)?,
        Value::Bool(true)
    ))
}

/// K4: a malformed move hold must not release history after bootstrap.
/// Missing fields keep the legacy default; explicit booleans keep their value.
fn deserialize_lenient_move_hold<'de, D>(deserializer: D) -> std::result::Result<bool, D::Error>
where
    D: serde::Deserializer<'de>,
{
    Ok(!matches!(
        Value::deserialize(deserializer)?,
        Value::Bool(false)
    ))
}

fn valid_snapshot_activity(value: &Option<String>) -> bool {
    match value.as_deref() {
        Some(timestamp) => OffsetDateTime::parse(timestamp, &Rfc3339).is_ok(),
        None => true,
    }
}

fn move_set(set: &mut BTreeSet<String>, from: &str, to: &str) {
    if set.remove(from) {
        set.insert(to.to_owned());
    }
}
fn move_map<T>(map: &mut BTreeMap<String, T>, from: &str, to: &str) {
    if let Some(value) = map.remove(from) {
        map.insert(to.to_owned(), value);
    }
}
fn move_option(value: &mut Option<String>, from: &str, to: &str) {
    if value.as_deref() == Some(from) {
        *value = Some(to.to_owned());
    }
}

impl ScanIndex {
    /// Mark the sweep unsettled by a path that does not name itself.
    pub fn mark_bounded_sweep_unsettled(&mut self) {
        self.mark_bounded_sweep_unsettled_by(UnsettledUploadCause::Unattributed);
    }

    /// Mark the sweep unsettled and record which path did it, for transition
    /// diagnostics and retry scheduling. A flag with no recorded cause stays
    /// `Unattributed` beside this one.
    pub(crate) fn mark_bounded_sweep_unsettled_by(&mut self, cause: UnsettledUploadCause) {
        self.bounded_sweep_unsettled_causes = self.unsettled_cause_bits() | cause.bit();
        self.bounded_sweep_had_unsettled_upload = true;
    }

    /// The flag is authoritative: no cause without it, and
    /// `Unattributed` for a flag with no recorded cause.
    fn unsettled_cause_bits(&self) -> u16 {
        match (
            self.bounded_sweep_had_unsettled_upload,
            self.bounded_sweep_unsettled_causes,
        ) {
            (false, _) => 0,
            (true, 0) => UnsettledUploadCause::Unattributed.bit(),
            (true, causes) => causes,
        }
    }

    /// Claude only, before scanning, every cycle. With prior history on this
    /// Mac, a fresh index, a replay that dropped entries or the
    /// first gated load of an index with no cutoff records the history
    /// cutoff; a new file born before it (or at an unknown time) is history.
    /// The cutoff is the last moment this destination is known
    /// to have received history: on the first gated load of
    /// an intact index, the newest activity clock among its accepted
    /// entities, so a session created while a pre-gate daemon was down is
    /// new, not history. A fresh index or a replay drop re-reads files this
    /// destination did receive, and an index with no accepted activity knows
    /// no better, so those record now. The first-load rule covers an index a
    /// pre-gate daemon built, rebuilt or replayed only partly, re-pairs
    /// included; an index a gated daemon built,
    /// such as a fresh install's after its bootstrap, records none. A stored
    /// cutoff ahead of the clock is pulled back to now, so a forward clock
    /// jump is not kept. A fresh install records none.
    ///
    /// It also sets this cycle's `NoListPolicy`: an unverified Mac holds, a
    /// move under a claim policy other than an explicit `full` holds (and the
    /// index keeps that until a `full` claim), everything else is paced.
    pub(crate) fn note_claude_history_cutoff(
        &mut self,
        prior_history: PriorHistory,
        claim_policy_full: bool,
        entries_lost: bool,
    ) {
        if !self.persistence_available() {
            return;
        }

        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or_default();
        if let Some(cutoff) = self.claude_history_cutoff_unix_seconds.as_mut() {
            *cutoff = (*cutoff).min(now);
        }
        let first_gated_load = !std::mem::replace(&mut self.claude_history_gate_loaded, true);
        // An explicit `full` claim releases a move hold for good: a later
        // claim with another policy does not bring it back, even while the
        // evidence still reads as a move.
        if claim_policy_full {
            self.claude_history_move_not_full = false;
            self.claude_history_move_released = true;
        }
        let moved_not_full =
            prior_history == PriorHistory::Moved && !self.claude_history_move_released;
        if prior_history.any()
            && (entries_lost
                || (first_gated_load && self.claude_history_cutoff_unix_seconds.is_none()))
        {
            // No entry was dropped on this path, so the index is as loaded.
            let received = (!entries_lost)
                .then(|| self.last_received_activity_unix_seconds())
                .flatten();
            self.claude_history_cutoff_unix_seconds =
                Some(received.map_or(now, |received| received.min(now)));
            self.claude_history_move_not_full |= moved_not_full;
        }
        self.claude_no_list_policy = if prior_history == PriorHistory::Unverified {
            NoListPolicy::HoldUnverified
        } else if moved_not_full || self.claude_history_move_not_full {
            NoListPolicy::HoldMoveNotFull
        } else {
            NoListPolicy::Pace
        };
    }

    /// The newest valid activity clock among this index's accepted entities,
    /// in unix seconds: the last moment the index records this destination
    /// receiving history (StateMissing N1). `None` when it records none.
    fn last_received_activity_unix_seconds(&self) -> Option<u64> {
        self.accepted_snapshot_fingerprints
            .iter()
            .filter_map(|fingerprint| self.snapshot_activity_at.get(fingerprint)?.as_deref())
            .filter_map(|at| OffsetDateTime::parse(at, &Rfc3339).ok())
            .filter_map(|at| u64::try_from(at.unix_timestamp()).ok())
            .max()
    }

    /// Lenient decode: a malformed stored cutoff is dropped
    /// with the gate marker, so the next gated load re-derives both.
    fn drop_malformed_claude_history_cutoff(&mut self) {
        if self.claude_history_cutoff_unix_seconds == Some(MALFORMED_CLAUDE_HISTORY_CUTOFF) {
            self.claude_history_cutoff_unix_seconds = None;
            self.claude_history_gate_loaded = false;
        }
    }

    /// The one reason-independent history decision for a Claude candidate,
    /// against its entry before this parse. Every caller (the candidate loop,
    /// MONEY's emitter) uses it; the parse reason stays diagnostic only.
    fn claude_history_upgrade_decision(
        &mut self,
        candidate: &CandidateFile,
        birth_unix_seconds: Option<u64>,
        page: &mut HistoryPage,
    ) -> HistoryDecision {
        self.close_claude_reemission_list_over_family_members(candidate);
        let key = local_index_key(&candidate.path);
        let extent = |size_bytes, modified_unix_seconds, modified_unix_nanos| {
            claude_history_upgrade::FileExtent {
                size_bytes,
                modified_unix_seconds,
                modified_unix_nanos,
            }
        };
        let kind = claude_history_upgrade::classify(
            self.files.get(&key).map(|entry| {
                extent(
                    entry.size_bytes,
                    entry.modified_unix_seconds,
                    entry.modified_unix_nanos,
                )
            }),
            extent(
                candidate.size_bytes,
                candidate.modified_unix_seconds,
                Some(candidate.modified_unix_nanos),
            ),
            self.effective_upload_body_witness_revision_requires_adoption(&key),
            self.claude_history_cutoff_unix_seconds,
            birth_unix_seconds,
        );

        claude_request_money::e2::timed("e2.stage_twins", || {
            self.stage_claude_history_twins(&key, page)
        });

        let decision = claude_history_upgrade::decide(
            kind,
            &claude_history_upgrade::PolicyInputs {
                exclusions: &self.claude_reemission_exclusions,
                listed: self.claude_family_listed(&candidate.path),
                birth_unix_seconds,
                latched: claude_reemission_stop_latched(),
                active_revision: self.active_effective_upload_body_witness_revision,
                history_cutoff_unix_seconds: self.claude_history_cutoff_unix_seconds,
                no_list_policy: self.claude_no_list_policy,
            },
            page,
            &key,
            candidate.size_bytes,
        );
        if matches!(decision, HistoryDecision::Held(HistoryHold::Listed))
            && self.claude_reemission_held_through_absent_root(candidate)
        {
            page.note_family_closure_root_absent();
        }
        if decision == HistoryDecision::LiteralDenied {
            if let Some(member) = claude_index_path_member_ref(&candidate.path) {
                page.note_listed_literal_root(member.root);
            }
        }
        decision
    }

    /// A subagent member listed only through its family root, whose root
    /// file `<root>.jsonl` is absent: the closure alone holds it. Counted
    /// for diagnostics; only held members pay this lookup.
    fn claude_reemission_held_through_absent_root(&self, candidate: &CandidateFile) -> bool {
        let Some(member) = claude_index_path_member_ref(&candidate.path) else {
            return false;
        };
        let Some(stem) = member.subagent_stem else {
            return false;
        };
        if self
            .claude_reemission_exclusions
            .lists_member(member.root, stem)
        {
            return false;
        }
        claude_family_root_path(&candidate.path, member.root).is_some_and(|root| {
            matches!(
                fs::symlink_metadata(root),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound
            )
        })
    }

    /// A list line may name only a member (`root_stem`). On a
    /// fresh or replayed index the family's members are not indexed yet when
    /// one of them is decided, so the load-time closure cannot list the root.
    /// Before the decision of any family candidate, root or subagent, whether
    /// or not the root file exists and in whatever order the family arrives:
    /// a listed member lists its root, and otherwise the list is closed over
    /// the members on disk under `<root>/subagents/`. The walk is bounded;
    /// past the bound, or on a directory or entry it cannot read, the root is
    /// treated as listed (held, never sent).
    ///
    /// A walk that found no listed member is remembered for the rest of the
    /// pass (`begin_pass` clears it), with the directory stamp taken before
    /// it; a later candidate of the family stats the directory again and
    /// walks again unless the stamp is unchanged. A member created after the
    /// walk changes the directory's modification time, so it cannot hide
    /// behind the memo. Only a flat walk of a directory last modified well
    /// before the walk began is remembered, so nested directories and a
    /// coarse filesystem clock fall back to walking every time.
    fn close_claude_reemission_list_over_family_members(&mut self, candidate: &CandidateFile) {
        const MAX_MEMBER_ENTRIES: usize = 4_096;
        /// A member directory modified this close to the walk is not
        /// remembered: on a coarse filesystem clock (whole or even seconds) a
        /// change after the walk could keep the same stamp.
        const QUIET_BEFORE_WALK: std::time::Duration = std::time::Duration::from_secs(10);
        if self.claude_reemission_exclusions.is_empty() {
            return;
        }
        let Some(member) = claude_index_path_member_ref(&candidate.path) else {
            return;
        };
        let root = member.root;
        if let Some(stem) = member.subagent_stem {
            // A listed member lists its root, so a later sibling is held
            // even when its own walk is remembered or never runs.
            self.claude_reemission_exclusions
                .close_over_roots(std::iter::once((root, stem)));
        }
        if self.claude_family_listed(&candidate.path) {
            return;
        }
        let root_directory;
        let subagents = if member.subagent_stem.is_some() {
            let Some(subagents) = claude_family_subagents_dir(&candidate.path, root) else {
                self.claude_reemission_exclusions.list_root(root);
                return;
            };
            subagents
        } else {
            root_directory = candidate.path.with_extension("").join("subagents");
            root_directory.as_path()
        };
        // `None` when the directory cannot be stamped: it is walked, never
        // remembered.
        let walk_started = SystemTime::now();
        let stamp: Option<MemberDirStamp> = match fs::metadata(subagents) {
            Ok(metadata) => metadata
                .modified()
                .ok()
                .map(|modified| Some((modified, metadata.ino()))),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Some(None),
            Err(_) => None,
        };
        if stamp.is_some_and(|stamp| {
            self.claude_reemission_exclusions
                .members_walked(root, &stamp)
        }) {
            return;
        }
        let mut pending = vec![subagents.to_path_buf()];
        let mut members = Vec::new();
        let mut visited = 0_usize;
        let mut flat = true;
        while let Some(directory) = pending.pop() {
            let entries = match fs::read_dir(&directory) {
                Ok(entries) => entries,
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
                Err(_) => {
                    self.claude_reemission_exclusions.list_root(root);
                    return;
                }
            };
            for entry in entries {
                visited += 1;
                let readable = entry
                    .ok()
                    .and_then(|entry| Some((entry.path(), entry.file_type().ok()?)))
                    .filter(|_| visited <= MAX_MEMBER_ENTRIES);
                // Past the bound, or an entry that cannot be read (it may be
                // a listed member): hold the root.
                let Some((path, kind)) = readable else {
                    self.claude_reemission_exclusions.list_root(root);
                    return;
                };
                if kind.is_dir() {
                    flat = false;
                    pending.push(path);
                } else if kind.is_file() {
                    members.push(path);
                }
            }
        }
        self.claude_reemission_exclusions.close_over_roots(
            members
                .iter()
                .map(PathBuf::as_path)
                .filter_map(claude_index_path_member_ref)
                .filter(|member| member.root == root)
                .filter_map(|member| Some((member.root, member.subagent_stem?))),
        );
        if !flat
            || self.claude_reemission_exclusions.excludes(root, None)
            || self.claude_reemission_exclusions.state() == ListState::ClosureOverflow
        {
            return;
        }
        let quiet = |stamp: &MemberDirStamp| {
            stamp.map_or(true, |(modified, _)| {
                modified
                    .checked_add(QUIET_BEFORE_WALK)
                    .is_some_and(|quiet_at| quiet_at <= walk_started)
            })
        };
        if let Some(stamp) = stamp.filter(quiet) {
            self.claude_reemission_exclusions
                .note_members_walked(root, stamp);
        }
    }

    /// Record a gated candidate before its parse, with the entry's upload
    /// tuple as it stands now. `hold: None` marks a permitted upgrade, which
    /// the emission seam still rechecks against the stop latch.
    fn gate_claude_history_candidate(
        &mut self,
        candidate: &CandidateFile,
        hold: Option<HistoryHold>,
    ) {
        let key = local_index_key(&candidate.path);
        let previous = self
            .files
            .get(&key)
            .map(|entry| claude_history_upgrade::HeldUploadTuple {
                last_snapshot_fingerprint: entry.last_snapshot_fingerprint.clone(),
                last_upload_body_witness: entry.last_upload_body_witness.clone(),
                file_snapshot_fingerprints: self.file_snapshot_fingerprints.get(&key).cloned(),
                confirmed_empty: self.confirmed_empty_files.contains(&key),
            });
        let gated = self
            .claude_history_emission
            .files
            .entry(candidate.source_file_fingerprint.clone())
            .or_insert_with(|| claude_history_upgrade::GatedHistory {
                index_key: key,
                held: None,
                permitted: hold.is_none(),
                literal_denied: false,
                previous,
                local: BTreeSet::new(),
            });
        if gated.held.is_none() {
            gated.held = hold;
        }
    }

    /// Record a literal-only denial before its parse: the file's ordinary
    /// body emits, its request-owned literal items do not, and it does not
    /// stamp the active revision, so it stays owed and gated.
    fn deny_claude_history_literal(&mut self, candidate: &CandidateFile) {
        self.gate_claude_history_candidate(candidate, None);
        if let Some(gated) = self
            .claude_history_emission
            .files
            .get_mut(&candidate.source_file_fingerprint)
        {
            gated.literal_denied = true;
            gated.permitted = false;
        }
    }

    /// A permissive load can succeed while one root's API or trace read
    /// failed. Hold every permitted owed file of that root (including path
    /// twins and agents) without changing unrelated history or live uploads.
    pub(crate) fn hold_claude_history_for_unhealthy_telemetry_roots(
        &mut self,
        roots: &BTreeSet<String>,
    ) {
        if roots.is_empty() {
            return;
        }
        for gated in self.claude_history_emission.files.values_mut() {
            if gated.held.is_none()
                && !gated.literal_denied
                && claude_index_path_member_ref(Path::new(&gated.index_key))
                    .is_some_and(|member| roots.contains(member.root))
            {
                gated.held = Some(HistoryHold::TelemetryUnread);
            }
        }
    }

    /// The hold on this source file's history this cycle, if any.
    pub(crate) fn claude_history_emission_held(
        &self,
        source_file_fingerprint: &str,
    ) -> Option<HistoryHold> {
        self.claude_history_emission.held(source_file_fingerprint)
    }

    /// The one emission seam (idempotent): remove every body of a held
    /// history file from `snapshots`, before account binding, cutoff
    /// corrections, cache-head and proof capture, native corrections and
    /// finalization, so neither the ordinary nor a correction upload can carry
    /// it. A latch set by a fold after the candidate loop holds every
    /// permitted upgrade too. A held new file's local entity fingerprints are
    /// kept to name its semantic group. Returns how many bodies were removed.
    pub(crate) fn veto_claude_history_emission(
        &mut self,
        source: SnapshotSource,
        snapshots: &mut Vec<SnapshotItem>,
    ) -> usize {
        if source != SnapshotSource::ClaudeCode {
            return 0;
        }
        let guard = self.claude_literal_guard(snapshots);
        if self.claude_history_emission.files.is_empty()
            && guard == claude_history_upgrade::LiteralGuard::Open
        {
            return 0;
        }
        if claude_reemission_stop_latched() {
            self.claude_history_emission.hold_permitted_for_latch();
        }
        let emission = &mut self.claude_history_emission;
        let before = snapshots.len();
        snapshots.retain(|snapshot| {
            if emission.permits(snapshot, &guard) {
                return true;
            }
            if let Some(gated) = snapshot
                .source_file_fingerprint
                .as_ref()
                .and_then(|fingerprint| emission.files.get_mut(fingerprint))
                .filter(|gated| gated.held.is_some())
            {
                gated.local.insert(snapshot.snapshot_fingerprint.clone());
            }
            false
        });
        before - snapshots.len()
    }

    /// Hook for resend paths outside the page (StateMissing #706 re-offer
    /// leases, #692 in-place resends) and for MONEY's literal items, which
    /// are built after the emission seam: drop every item of a source file
    /// the history gate holds this cycle, every request-owned literal item
    /// of a literal-denied file, and every literal the guard denies whether
    /// or not its file was decided this cycle (C2). They must call it on what
    /// they send.
    pub(crate) fn retain_claude_history_emission_permitted(&self, items: &mut Vec<SnapshotItem>) {
        let guard = self.claude_literal_guard(items);
        items.retain(|item| self.claude_history_emission.permits(item, &guard));
    }

    /// The request-owned literal guard for `items`, from the
    /// active row, the list and the index only.
    fn claude_literal_guard(&self, items: &[SnapshotItem]) -> claude_history_upgrade::LiteralGuard {
        claude_history_upgrade::LiteralGuard::for_items(
            items,
            self.active_effective_upload_body_witness_revision,
            &self.claude_reemission_exclusions,
            self.files
                .iter()
                .map(|(key, entry)| (key.as_str(), entry.source_file_fingerprint.as_str())),
            |key| self.claude_family_listed(key),
        )
    }

    /// The re-emission list's status reason (`missing_after_install` raises
    /// the local alarm each cycle).
    #[cfg(test)]
    pub(crate) fn claude_reemission_list_status_for_test(&self) -> &'static str {
        self.claude_reemission_exclusions.status()
    }

    /// True when the list names the family of this Claude file (its root or
    /// the member itself): the one listed predicate for candidates, indexed
    /// keys and the `e2` fold.
    fn claude_family_listed(&self, path: impl AsRef<Path>) -> bool {
        !self.claude_reemission_exclusions.is_empty()
            && claude_index_path_member_ref(path.as_ref()).is_some_and(|member| {
                self.claude_reemission_exclusions
                    .excludes(member.root, member.subagent_stem)
            })
    }

    /// Finalize a held history file without its new bodies: an existing entry
    /// keeps its upload tuple (revision, semantic group, body witness,
    /// membership); a new one gets the semantic group of its local bodies, an
    /// empty exact membership, no body witness and revision 0, so it stays
    /// owed, is not re-read and is not advertised. Its new
    /// source identity, size and mtime stay recorded. Returns false when the
    /// gate does not hold this file.
    fn finalize_claude_held_history(
        &mut self,
        index_key: &str,
        source_file_fingerprint: &str,
    ) -> bool {
        if !self.persistence_available() {
            return false;
        }

        let Some(gated) = self
            .claude_history_emission
            .files
            .get(source_file_fingerprint)
            .filter(|gated| gated.held.is_some() && gated.index_key == index_key)
            .cloned()
        else {
            return false;
        };
        let key = index_key.to_owned();
        let (last_snapshot_fingerprint, last_upload_body_witness, members, empty) =
            match gated.previous {
                Some(previous) => (
                    previous.last_snapshot_fingerprint,
                    previous.last_upload_body_witness,
                    previous.file_snapshot_fingerprints,
                    previous.confirmed_empty,
                ),
                // The group names the local bodies, so the file is not an
                // unknown outcome. Its exact membership is empty: none of
                // these bodies passed upload policy or reached this
                // destination, so the source manifest does not advertise
                // them, and a partial checkpoint keeps the entry (nothing
                // in it awaits acceptance).
                None => {
                    let group = (!gated.local.is_empty())
                        .then(|| snapshot_file_entity_set_hex(&gated.local));
                    let empty = gated.local.is_empty();
                    (group, None, (!empty).then(BTreeSet::new), empty)
                }
            };
        if let Some(entry) = self.files.get_mut(&key) {
            entry.last_snapshot_fingerprint = last_snapshot_fingerprint;
            entry.last_upload_body_witness = last_upload_body_witness;
        }
        match members {
            Some(members) => {
                self.file_snapshot_fingerprints.insert(key.clone(), members);
            }
            None => {
                self.file_snapshot_fingerprints.remove(&key);
            }
        }
        if empty {
            self.confirmed_empty_files.insert(key);
        } else {
            self.confirmed_empty_files.remove(&key);
        }
        true
    }

    /// The one writer of a settled file's `effective_upload_body_witness_revision`.
    /// Claude never downgrades (`max(stored, allowed_active)`); Codex and Pi
    /// keep the exact stamp. Refuses a zero revision, a file excluded for a
    /// local hold, a file the history gate holds, a literal-denied file, and
    /// under a row that denies the literal any listed family or, while the
    /// list is paused, any file: a protected root never stamps to a new
    /// revision. Request-owned money routes
    /// its covering-ACK, below-floor and confirmed-empty settlements here.
    /// The only other writer is `re_owe_effective_upload_body_witness_revision`.
    pub(crate) fn stamp_effective_upload_body_witness_revision(
        &mut self,
        index_key: &str,
        source_file_fingerprint: &str,
        allowed_active: u64,
    ) -> bool {
        if allowed_active == 0
            || self
                .effective_upload_body_witness_revision_excluded_source_files
                .contains(source_file_fingerprint)
            || self
                .claude_history_emission_held(source_file_fingerprint)
                .is_some()
            || self
                .claude_history_emission
                .literal_denied(source_file_fingerprint)
        {
            return false;
        }
        // A revision whose row denies the request-owned
        // literal never stamps a listed family, or any file while the list is
        // paused, whatever this cycle decided (a covering ACK, below-floor or
        // confirmed-empty settlement of a file that was not a candidate).
        // The pause holds adoption only: a file that uploads `e2` under it
        // keeps its stamp and is owed again once the list is back.
        if claude_history_upgrade::denies_request_owned_literal(allowed_active)
            && (self.claude_reemission_exclusions.pauses_adoption()
                || self.claude_family_listed(index_key))
        {
            return false;
        }
        let monotone = self.active_effective_upload_body_witness_revision_monotone;
        // No Claude file is stamped above the last revision the
        // history gate is complete for.
        if monotone && allowed_active > claude_history_upgrade::max_gated_claude_revision() {
            return false;
        }
        let Some(entry) = self.files.get_mut(index_key) else {
            return false;
        };
        entry.effective_upload_body_witness_revision = if monotone {
            entry
                .effective_upload_body_witness_revision
                .max(allowed_active)
        } else {
            allowed_active
        };
        true
    }

    /// The only way to lower a file's `effective_upload_body_witness_revision`
    /// (owner B): only downward, and only below the active revision (before
    /// any activation, below the highest revision with a policy row), so the
    /// file is owed again and goes back through the history gate. Counts
    /// `history_reowed`. Returns false and writes nothing otherwise. MONEY's
    /// census 3 -> 2 path calls it.
    pub(crate) fn re_owe_effective_upload_body_witness_revision(
        &mut self,
        index_key: &str,
        to: u64,
    ) -> bool {
        let active = self.active_effective_upload_body_witness_revision;
        self.files.get_mut(index_key).is_some_and(|entry| {
            claude_history_upgrade::re_owe(
                &mut entry.effective_upload_body_witness_revision,
                to,
                active,
            )
        })
    }

    /// Counts only (#799 page carrier): each upgrade the history gate
    /// permitted this page that finalized below the active revision, by its
    /// hold.
    fn note_claude_history_not_stamped(&self) {
        use crate::local_resource_diagnostics::claude_reread::{self, NotStamped};
        if !claude_reread::active() {
            return;
        }
        let active = self.active_effective_upload_body_witness_revision;
        for gated in self.claude_history_emission.files.values() {
            if !gated.permitted
                || self
                    .files
                    .get(&gated.index_key)
                    .map_or(0, |entry| entry.effective_upload_body_witness_revision)
                    >= active
            {
                continue;
            }
            claude_reread::history_permitted_not_stamped(match gated.held {
                Some(HistoryHold::TelemetryUnread) => NotStamped::TelemetryUnread,
                Some(_) => NotStamped::Held,
                None => NotStamped::Other,
            });
        }
    }

    /// A partial save keeps the committed entry of each `restored` key.
    /// An upgrade the history gate permitted that stamped on this page but
    /// does not commit counts as not accepted.
    fn note_claude_history_not_accepted<'a>(
        &self,
        previous: &ScanIndex,
        restored: impl IntoIterator<Item = &'a String>,
    ) {
        let active = self.active_effective_upload_body_witness_revision;
        let revision = |index: &ScanIndex, key: &String| {
            index
                .files
                .get(key)
                .map_or(0, |entry| entry.effective_upload_body_witness_revision)
        };
        for key in restored {
            if revision(self, key) >= active
                && revision(previous, key) < active
                && self.files.get(key).is_some_and(|entry| {
                    self.claude_history_emission
                        .files
                        .get(&entry.source_file_fingerprint)
                        .is_some_and(|gated| gated.permitted)
                })
            {
                crate::local_resource_diagnostics::claude_reread::history_permitted_not_stamped(
                    crate::local_resource_diagnostics::claude_reread::NotStamped::NotAccepted,
                );
            }
        }
    }

    /// Record the contract-5 contract a prepared Claude cycle builds bodies
    /// under. A contract change re-owes no history (card G): a record that
    /// never captured waits for real content change or already-authorized
    /// debt.
    pub(crate) fn observe_claude_request_identity_contract(&mut self, captured: bool) {
        let contract = claude_request_identity::cycle_contract(captured);
        if self.claude_request_identity_contract.as_deref() == Some(contract) {
            return;
        }
        use claude_request_identity::{COLLECTOR, E2_GROUPING};
        claude_contract::note(|counts| {
            let prior = self.claude_request_identity_contract.as_deref();
            let transitions = &mut counts.identity_contract_transition;
            transitions.from_empty += u64::from(prior == Some("") && !contract.is_empty());
            transitions.to_empty +=
                u64::from(matches!(prior, Some(COLLECTOR | E2_GROUPING)) && contract.is_empty());
            transitions.collector_e2_grouping += u64::from(matches!(
                (prior, contract),
                (Some(COLLECTOR), E2_GROUPING) | (Some(E2_GROUPING), COLLECTOR)
            ));
        });
        self.claude_request_identity_contract = Some(contract.to_owned());
    }

    /// Record (or clear) the residue the completing generation disclosed, and
    /// say so once per change rather than once per cycle. The log names counts
    /// only; the index keys stay in the local index.
    fn record_scan_residue_witness(
        &mut self,
        source: SnapshotSource,
        traversal: &ScanTraversalCheckpoint,
    ) {
        let next = traversal
            .counts
            .settled_residue()
            .map(|residue| ScanResidueWitness {
                census_window_end: traversal.census_window_end.clone(),
                ownership_incomplete_file_count: residue.ownership_incomplete_file_count,
                zero_snapshot_usage_evidence_count: residue.zero_snapshot_usage_evidence_count,
                dropped_usage_record_count: residue.dropped_usage_record_count,
                index_keys: traversal.residue.index_keys.clone(),
            });
        match (self.scan_residue_witness.as_ref(), next.as_ref()) {
            (Some(previous), Some(next)) if previous.same_residue(next) => {}
            (None, None) => {}
            (_, Some(next)) => eprintln!(
                "ottto-service: {} census completed with non-progressing residue: {} \
                 ownership-incomplete Codex rollout(s) ({} under an archived root), {} file(s) \
                 with usage evidence but no entity, {} dropped usage record(s); the residue is \
                 re-derived every generation and clears only when its files, their sidecar, or \
                 the parser change",
                source.api_slug(),
                next.ownership_incomplete_file_count,
                next.archived_residue_file_count(),
                next.zero_snapshot_usage_evidence_count,
                next.dropped_usage_record_count,
            ),
            (Some(_), None) => eprintln!(
                "ottto-service: {} census residue cleared; every previously non-progressing \
                 file now checkpoints",
                source.api_slug()
            ),
        }
        self.scan_residue_witness = next;
    }

    pub(crate) fn claude_usage_authority_pending_count(&self) -> usize {
        self.claude_usage_authority_quarantine
            .values()
            .filter(|record| {
                record.disposition == ClaudeUsageAuthorityQuarantineDisposition::RetryPending
            })
            .count()
    }

    pub(crate) fn claude_usage_authority_terminal_entity_count(&self) -> usize {
        self.claude_usage_authority_quarantine
            .values()
            .filter(|record| {
                record.disposition == ClaudeUsageAuthorityQuarantineDisposition::UnprovenTerminal
            })
            .map(|record| record.member_source_file_fingerprints.len())
            .fold(0_usize, usize::saturating_add)
    }

    pub(crate) fn account_claude_usage_authority_census_health(
        &self,
        scan_result: &mut SourceScanResult,
    ) -> bool {
        let terminal_entity_count = self.claude_usage_authority_terminal_entity_count();
        scan_result.ownership_incomplete_file_count = scan_result
            .ownership_incomplete_file_count
            .saturating_add(terminal_entity_count);
        scan_result.terminal_ownership_incomplete_file_count = scan_result
            .terminal_ownership_incomplete_file_count
            .saturating_add(terminal_entity_count);
        self.claude_usage_authority_pending_count() > 0
    }

    /// Reuse the existing quarantine retry page after a reviewed admission
    /// increase. Legacy records have no rejection reason: re-offer current
    /// refusals, preserving accepted marks and absent/superseded disclosures.
    pub(crate) fn prepare_snapshot_admission_reoffer(&mut self, limit: usize) -> bool {
        let current = self
            .eligible_snapshot_fingerprint_refs()
            .map(str::to_owned)
            .collect::<BTreeSet<_>>();
        let selected = self
            .quarantined_snapshot_fingerprints
            .iter()
            .filter(|(fingerprint, record)| {
                current.contains(*fingerprint)
                    && !self.accepted_snapshot_fingerprints.contains(*fingerprint)
                    && record.witness.item_wire_byte_limit < MAX_SNAPSHOT_ITEM_WIRE_BYTES
                    && record.disposition != SnapshotQuarantineDisposition::SupersededTerminal
            })
            .take(limit)
            .map(|(fingerprint, _)| fingerprint.clone())
            .collect::<Vec<_>>();
        for fingerprint in &selected {
            let record = self
                .quarantined_snapshot_fingerprints
                .get_mut(fingerprint)
                .unwrap();
            record.witness.item_wire_byte_limit = MAX_SNAPSHOT_ITEM_WIRE_BYTES;
            record.retry_after_unix_seconds = 0;
            record.failed_reconstruction_count = 0;
            record.disposition = SnapshotQuarantineDisposition::RetryPending;
        }
        if !selected.is_empty() {
            // Match legacy settlement recovery: only a completed unhealthy
            // traversal needs discovery re-opened. Never restart a live page.
            if self.traversal.as_ref().is_some_and(|t| {
                t.pending_directories.is_empty()
                    && t.pending_candidates.is_empty()
                    && t.counts.has_errors()
            }) {
                self.traversal = None;
            }
            self.mark_bounded_sweep_unsettled_by(UnsettledUploadCause::AdmissionReoffer);
        }
        !selected.is_empty()
    }

    pub(crate) fn snapshot_admission_reoffer_pending(&self) -> bool {
        self.quarantined_snapshot_fingerprints
            .values()
            .any(|record| {
                record.witness.item_wire_byte_limit == MAX_SNAPSHOT_ITEM_WIRE_BYTES
                    && record.disposition == SnapshotQuarantineDisposition::RetryPending
            })
    }

    /// Q-W: every current-limit pending retry uses the same outside/unknown
    /// incidence rule, regardless of which operation created or armed it.
    pub(crate) fn snapshot_admission_reoffer_pending_for_scan(
        &self,
        source: SnapshotSource,
        window_days: u64,
    ) -> bool {
        if source != SnapshotSource::ClaudeCode {
            return self.snapshot_admission_reoffer_pending();
        }
        let Some(now) = unix_seconds(SystemTime::now()) else {
            return self.snapshot_admission_reoffer_pending();
        };
        let (mut outside, mut inside) = (0, 0);
        for (fingerprint, record) in &self.quarantined_snapshot_fingerprints {
            if record.witness.item_wire_byte_limit != MAX_SNAPSHOT_ITEM_WIRE_BYTES
                || record.disposition != SnapshotQuarantineDisposition::RetryPending
            {
                continue;
            }
            // A retry can age out after its refusal. Use the scanner's mtime
            // cutoff on current metadata: committed mtimes can be stale after
            // a restore/copy. Unknown incidence or metadata stays wide.
            let mut found = false;
            let outside_window = self
                .file_snapshot_fingerprints
                .iter()
                .any(|(key, entities)| {
                    if !entities.contains(fingerprint) {
                        return false;
                    }
                    found = true;
                    fs::symlink_metadata(key)
                        .ok()
                        .filter(|metadata| metadata.is_file())
                        .and_then(|metadata| metadata.modified().ok())
                        .and_then(unix_seconds)
                        .map_or(true, |modified| {
                            !is_recent_enough_at(modified, now, window_days)
                        })
                });
            if outside_window || !found {
                outside += 1;
            } else {
                inside += 1;
            }
        }
        if outside + inside > 0 {
            eprintln!(
                "ottto-service: Claude admission scan window: outside_or_unknown={outside} inside={inside}"
            );
        }
        outside > 0
    }

    fn activate_quarantine_witness(&mut self, source: SnapshotSource) {
        self.active_quarantine_witness = Some(
            self.active_upload_context_fingerprint
                .as_deref()
                .filter(|_| self.file_upload_context_enabled())
                .map_or_else(
                    || snapshot_quarantine_witness(source),
                    |context| snapshot_quarantine_witness_for_context(source, context),
                ),
        );
    }

    #[cfg(test)]
    pub(crate) fn activate_quarantine_witness_for_test(&mut self, source: SnapshotSource) {
        self.activate_quarantine_witness(source);
    }

    fn quarantine_requires_retry(&self, fingerprint: &str) -> bool {
        if self.decode_holds_entity(fingerprint) {
            return false;
        }
        if self.reason_reoffer_retries.contains_key(fingerprint) {
            return true;
        }
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or_default();
        self.quarantined_snapshot_fingerprints
            .get(fingerprint)
            .zip(self.active_quarantine_witness.as_ref())
            .is_some_and(|(persisted, active)| {
                if persisted.contract_retry_claims.is_some() {
                    return self.terminal_contract_retries.contains_key(fingerprint);
                }
                persisted.disposition == SnapshotQuarantineDisposition::RetryPending
                    && (self.terminal_contract_retries.contains_key(fingerprint)
                        || !persisted.witness.same_retry_contract_any_context(active)
                        || persisted.retry_after_unix_seconds <= now)
            })
    }

    /// Merge the already saved upload claims before source acquisition. The caller
    /// saves changes before activating these runtime-only leases or reading files.
    pub(crate) fn merge_terminal_contract_claims(
        &mut self,
        records: &BTreeMap<String, SnapshotQuarantineRecord>,
    ) -> bool {
        terminal_contract_retry::merge_maps(&mut self.quarantined_snapshot_fingerprints, records)
    }

    pub(crate) fn activate_terminal_contract_retries(
        &mut self,
        leases: BTreeSet<String>,
    ) -> Vec<PathBuf> {
        self.terminal_contract_retries.clear();
        // A fingerprint can have more than one indexed incidence. One claim
        // selects one owning file, never every duplicate incidence.
        for (key, fingerprints) in &self.file_snapshot_fingerprints {
            for fingerprint in fingerprints.intersection(&leases) {
                self.terminal_contract_retries
                    .entry(fingerprint.clone())
                    .or_insert_with(|| key.clone());
            }
        }
        // Use the same revalidated candidate admission as exact refusal re-offers.
        // Distinct entities in one file and duplicate incidences own one hint.
        self.terminal_contract_retries
            .values()
            .collect::<BTreeSet<_>>()
            .into_iter()
            .map(PathBuf::from)
            .collect()
    }

    /// Mirror the upload ledger's open head-CAS challenge sessions that hold a
    /// saved base, the only ones whose upload can carry the answer.
    pub(crate) fn activate_head_conflict_sessions(&mut self, sessions: BTreeSet<String>) {
        self.head_conflict_sessions = sessions;
    }

    /// The hashed session key owes a head-CAS answer this cycle.
    pub(crate) fn head_conflict_owed(&self, session_key: &str) -> bool {
        self.head_conflict_sessions.contains(session_key)
    }

    /// A leased file still queued for a bounded page has not reached a hold.
    pub(crate) fn quarantine_retry_is_queued(&self, fingerprint: &str) -> bool {
        self.terminal_contract_retries
            .get(fingerprint)
            .is_some_and(|key| {
                self.traversal
                    .iter()
                    .flat_map(|traversal| traversal.pending_candidates.iter())
                    .any(|pending| pending.path == Path::new(key))
            })
    }

    /// Arm this cycle's exact refusal re-offer leases and return the indexed
    /// files that hold them, for the bounded watcher-hint queue. Paths come
    /// only from the committed file/entity incidence table; the scan
    /// revalidates each one like any other hint. Family/account holds keep
    /// their own earlier gates in `candidate_decision`.
    pub(crate) fn activate_reason_reoffer_retries(
        &mut self,
        leases: BTreeMap<String, String>,
    ) -> Vec<PathBuf> {
        self.reason_reoffer_retries = leases;
        if self.reason_reoffer_retries.is_empty() {
            return Vec::new();
        }
        self.file_snapshot_fingerprints
            .keys()
            .filter(|key| self.reason_reoffer_leased(key))
            .map(PathBuf::from)
            .collect()
    }

    /// This cycle leased the file's snapshot for a reason re-offer.
    fn reason_reoffer_leased(&self, key: &str) -> bool {
        !self.reason_reoffer_retries.is_empty()
            && self
                .file_snapshot_fingerprints
                .get(key)
                .is_some_and(|fingerprints| {
                    fingerprints
                        .iter()
                        .any(|fingerprint| self.reason_reoffer_retries.contains_key(fingerprint))
                })
    }

    /// A re-listing pass leaves a file alone when its stamp is unchanged
    /// since the last read and nothing is owed on it (empty fingerprint or an
    /// unverified sampled generation). Other reasons to read an unchanged file
    /// were weighed by this generation's walk; their owners and the next walk
    /// re-offer them, as on main, rather than every pass. Stat-only.
    fn listing_stamp_matches(&self, path: &Path, metadata: &fs::Metadata) -> bool {
        let key = local_index_key(path);
        let entry = self.files.get(&key);
        if entry.is_some_and(|entry| {
            entry.codex_counting_owner.is_some() || entry.codex_protected_owner.is_some()
        }) {
            if let Ok(Some((unchanged, _))) = self.codex_physical_matches(&key, metadata) {
                return unchanged;
            }
        }
        entry.is_some_and(|entry| entry.same_listing_stamp_as(metadata))
    }

    fn listing_unchanged(&self, path: &Path, metadata: &fs::Metadata) -> bool {
        self.listing_stamp_matches(path, metadata)
            && !sampled_audit::path_requires_verification(&self.files, path)
    }

    /// A member of a terminal authority family: a Skip before any growth
    /// handling, and a hold revert that keeps the pre-growth stamp.
    fn authority_terminal_member(&self, path: &Path) -> bool {
        claude_index_path_member_ref(path)
            .and_then(|member| self.claude_usage_authority_quarantine.get(member.root))
            .is_some_and(|record| {
                record.disposition == ClaudeUsageAuthorityQuarantineDisposition::UnprovenTerminal
            })
    }

    /// A watcher hint needs no read: the file is unchanged and not owed, and
    /// the ordinary candidate gate skips it at that stamp. An account-held
    /// key keeps its hint: its gate needs the content stamp, so the gate is
    /// never consulted (or its withheld memo cleared) here. Stat-only.
    fn hint_settled(&self, path: &Path, metadata: &fs::Metadata) -> bool {
        let key = local_index_key(path);
        let Some(entry) = self.files.get(&key) else {
            return false;
        };
        self.listing_unchanged(path, metadata)
            && !self.claude_account_deferred_holds.contains_key(&key)
            && self.candidate_decision(&CandidateFile {
                physical_identity: None,
                scan_root: PathBuf::new(),
                path: path.to_path_buf(),
                size_bytes: metadata.len(),
                modified_unix_seconds: entry.modified_unix_seconds,
                modified_unix_nanos: entry.modified_unix_nanos.unwrap_or_default(),
                source_file_fingerprint: entry.source_file_fingerprint.clone(),
                legacy_source_file_fingerprint: String::new(),
                legacy_config_reconciliation_required: false,
                opened_object_identity: String::new(),
                fingerprint_changed_nanos: 0,
                fingerprint_birth_nanos: entry.opened_birth_nanos,
                withheld_content_stamp: None,
            }) == CandidateDecision::Skip
    }

    fn quarantine_requires_retry_body(&self, fingerprint: &str, body_witness: &str) -> bool {
        if self.decode_holds_entity(fingerprint) {
            return false;
        }
        self.quarantined_snapshot_fingerprints
            .get(fingerprint)
            .is_some_and(|record| {
                record.upload_body_witness.as_deref() != Some(body_witness)
                    || self.quarantine_requires_retry(fingerprint)
            })
    }

    /// Arm this cycle's exact-body cooldown view (fingerprint -> refused
    /// body witness), read from the prepared upload ledger after its leases
    /// and any clock re-clamp. Replaces the previous view and its counts.
    pub(crate) fn activate_reason_reoffer_cooldowns<T: Into<ReasonReofferCooldown>>(
        &mut self,
        cooldowns: BTreeMap<String, T>,
    ) {
        self.reason_reoffer_cooldowns = cooldowns
            .into_iter()
            .map(|(fp, cooldown)| (fp, cooldown.into()))
            .collect();
    }

    /// True when this entity's ordinary retry is only the retained conflict
    /// of its exact refused body, which no lease lets through this cycle:
    /// re-reading the unchanged file cannot send it. A lease, an acceptance,
    /// another body or a changed quarantine witness keeps the retry.
    fn reason_reoffer_cooldown_defers(&self, fingerprint: &str) -> bool {
        if self
            .reason_reoffer_cooldowns
            .get(fingerprint)
            .is_some_and(|c| c.input_change_only)
        {
            return true;
        }
        !self.reason_reoffer_retries.contains_key(fingerprint)
            && !self.accepted_snapshot_fingerprint_recorded(fingerprint)
            && self
                .reason_reoffer_cooldowns
                .get(fingerprint)
                .zip(self.quarantined_snapshot_fingerprints.get(fingerprint))
                .is_some_and(|(body_witness, record)| {
                    record.disposition == SnapshotQuarantineDisposition::RetryPending
                        && record.upload_body_witness.as_deref()
                            == Some(body_witness.body_witness.as_str())
                        && self
                            .active_quarantine_witness
                            .as_ref()
                            .is_some_and(|active| {
                                record.witness.same_retry_contract_any_context(active)
                            })
                })
    }

    /// The ordinary retry gate of candidate selection, without the retry an
    /// exact-body cooldown defers.
    fn quarantine_retry_selects_file(&self, fingerprint: &str, key: &str) -> bool {
        self.quarantine_requires_retry(fingerprint)
            && self
                .terminal_contract_retries
                .get(fingerprint)
                .map_or(true, |owner| owner == key)
            && !self.reason_reoffer_cooldown_defers(fingerprint)
    }

    /// Revoke this cycle's bound if any mapped candidate is selected or
    /// changed. Not-yet-visited entities remain provisional cooldown debt:
    /// only the ordinary complete, clean traversal can settle them. Requiring
    /// a page-local seen set would make multi-page quiet walks block forever.
    fn note_reason_reoffer_cooldown_candidate(&mut self, candidate: &CandidateFile, skipped: bool) {
        if self.reason_reoffer_cooldowns.is_empty() {
            return;
        }
        let key = local_index_key(&candidate.path);
        let unchanged = skipped
            && self.files.get(&key).is_some_and(|entry| {
                entry.size_bytes == candidate.size_bytes
                    && entry.modified_unix_seconds == candidate.modified_unix_seconds
                    && entry.modified_unix_nanos == Some(candidate.modified_unix_nanos)
                    && entry.source_file_fingerprint == candidate.source_file_fingerprint
                    && entry.scan_identity_version.as_deref()
                        == Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION)
            });
        if !unchanged {
            if let Some(fingerprints) = self.file_snapshot_fingerprints.get(&key) {
                for fingerprint in fingerprints {
                    if !skipped
                        || !self
                            .reason_reoffer_cooldowns
                            .get(fingerprint)
                            .is_some_and(|c| c.input_change_only)
                    {
                        self.reason_reoffer_cooldowns.remove(fingerprint);
                    }
                }
            }
        }
    }

    /// This exact runtime bound makes the retained conflict non-blocking for
    /// this page. It never certifies a traversal or changes its prior causes;
    /// every candidate still has to pass the normal clean census boundary.
    pub(crate) fn reason_reoffer_conflict_is_deferred(
        &self,
        fingerprint: &str,
        body: &str,
    ) -> bool {
        self.reason_reoffer_cooldowns
            .get(fingerprint)
            .is_some_and(|cooldown| cooldown.body_witness == body)
            && self.reason_reoffer_cooldown_defers(fingerprint)
    }

    /// Current, distinct cooldown entities, including debt not visited on
    /// this bounded page or whose ordinary timer has not expired. The set is
    /// bounded by the refusal view, never by the whole source corpus.
    pub(crate) fn reason_reoffer_cooldown_deferred_count(&self) -> usize {
        if self.reason_reoffer_cooldowns.is_empty() {
            return 0;
        }
        self.current_snapshot_fingerprint_refs()
            .filter(|fingerprint| self.reason_reoffer_cooldown_defers(fingerprint))
            .collect::<BTreeSet<_>>()
            .len()
    }

    /// The subset of this scan's index that is safe to commit when the upload
    /// did not finish.
    ///
    /// Committing the whole index after a partial upload would drop every entity
    /// the server never received: the next scan skips an unchanged transcript, so
    /// its snapshot would never be re-derived. Committing nothing is the current
    /// behaviour and is just as wrong in the other direction — a shed request
    /// today means the entire cycle replays, forever, every five minutes.
    ///
    /// An entry is safe when the server demonstrably holds its content:
    ///
    /// * it produced no snapshot at all (nothing to lose), or
    /// * its snapshot was accepted in this pass, or
    /// * its fingerprint is unchanged from the committed index, which is what
    ///   "semantic no-op" means — the server already has that exact content.
    ///
    /// Anything else keeps its previously committed entry, so the next scan
    /// re-parses it and re-uploads. `previous` is the index as loaded from disk,
    /// before this scan mutated it.
    /// Stage bounded selector and joined-membership recovery facts without changing any committed
    /// file/body/ACK field. The caller persists this by the existing index CAS
    /// before a protected POST and adopts only that exact saved generation.
    pub(crate) fn stage_codex_recovery_capture(
        &self,
        previous: &ScanIndex,
        snapshots: &[SnapshotItem],
    ) -> (ScanIndex, BTreeSet<String>) {
        let mut staged = previous.clone();
        let mut changed = BTreeSet::new();
        let by_source = snapshots
            .iter()
            .filter_map(|item| {
                item.source_file_fingerprint.as_ref().map(|source| {
                    (
                        source.clone(),
                        resolve_codex_identity(&item.source_session_id),
                    )
                })
            })
            .collect::<BTreeMap<_, _>>();
        let mut by_owner = BTreeMap::<String, Vec<(String, ScanIndexEntry)>>::new();
        for (key, entry) in &self.files {
            let Some(owner) = by_source.get(&entry.source_file_fingerprint) else {
                continue;
            };
            let receipt = entry.codex_applied_tier_receipt.as_ref();
            let marker = entry
                .codex_joined_member_set
                .as_ref()
                .map(|value| codex_file_join::captured_join(value));
            if receipt.is_none() && marker.is_none() {
                continue;
            }
            let previous_entry = previous.files.get(key);
            let tiers_covered = receipt.map_or(true, |receipt| {
                previous_entry
                    .and_then(|entry| {
                        entry
                            .codex_captured_tier_receipt
                            .as_ref()
                            .or(entry.codex_applied_tier_receipt.as_ref())
                    })
                    .is_some_and(|old| receipt.covered_by(old))
            });
            let join_covered = marker.as_ref().map_or(true, |marker| {
                previous_entry.is_some_and(|old| {
                    old.codex_captured_joined_member_set.as_ref() == Some(marker)
                        || (old.codex_captured_joined_member_set.is_none()
                            && old.codex_joined_member_set == entry.codex_joined_member_set)
                })
            });
            if tiers_covered && join_covered {
                continue;
            }
            let mut capture = previous_entry.cloned().unwrap_or_else(|| {
                let mut uncommitted = entry.clone();
                uncommitted.last_snapshot_fingerprint = None;
                uncommitted.last_upload_body_witness = None;
                claude_history_upgrade::re_owe(
                    &mut uncommitted.effective_upload_body_witness_revision,
                    0,
                    self.active_effective_upload_body_witness_revision,
                );
                uncommitted.codex_joined_member_set = None;
                uncommitted.codex_applied_tier_receipt = None;
                uncommitted.codex_applied_tier_receipt_required = false;
                uncommitted.codex_captured_uncommitted = true;
                uncommitted
            });
            capture.codex_protected_owner = Some(codex_protected_owner(owner));
            capture.codex_captured_joined_member_set = marker;
            if let Some(receipt) = receipt {
                capture.codex_captured_tier_receipt = Some(receipt.clone());
                capture.codex_captured_tier_receipt_required = true;
            }
            by_owner
                .entry(owner.clone())
                .or_default()
                .push((key.clone(), capture));
        }
        for (owner, entries) in by_owner {
            changed.insert(owner);
            for (key, entry) in entries {
                staged.files.insert(key, entry);
            }
        }
        (staged, changed)
    }
    pub(crate) fn reconcile_codex_recovery_settlement(
        &mut self,
        previous: &ScanIndex,
        accepted: &BTreeSet<String>,
    ) {
        for (key, slot) in self.files.slots_mut() {
            let entry = &**slot;
            let settled = self
                .file_snapshot_fingerprints
                .get(key)
                .is_some_and(|fingerprints| {
                    !fingerprints.is_empty()
                        && fingerprints
                            .iter()
                            .all(|fingerprint| accepted.contains(fingerprint))
                });
            let old = previous.files.get(key);
            let pending_tiers = old.is_some_and(|old| {
                old.codex_captured_tier_receipt_required
                    || old.codex_captured_tier_receipt.is_some()
                    || (old.codex_captured_uncommitted
                        && old.codex_captured_joined_member_set.is_none())
            });
            let pending_join = old.and_then(|old| old.codex_captured_joined_member_set.as_ref());
            let pending_capture = pending_tiers || pending_join.is_some();
            let capture_covered = (!pending_tiers
                || old
                    .and_then(|old| old.codex_captured_tier_receipt.as_ref())
                    .is_some_and(|captured| {
                        entry
                            .codex_applied_tier_receipt
                            .as_ref()
                            .is_some_and(|applied| captured.covered_by(applied))
                    }))
                && pending_join.map_or(true, |captured| {
                    entry
                        .codex_joined_member_set
                        .as_ref()
                        .is_some_and(|applied| {
                            codex_file_join::valid_captured_join(captured)
                                && *captured == codex_file_join::captured_join(applied)
                        })
                });
            if settled && capture_covered {
                if entry.codex_captured_joined_member_set.is_some()
                    || entry.codex_captured_tier_receipt.is_some()
                    || entry.codex_captured_tier_receipt_required
                    || entry.codex_captured_uncommitted
                {
                    let entry = slot.make_mut();
                    entry.codex_captured_joined_member_set = None;
                    entry.codex_captured_tier_receipt = None;
                    entry.codex_captured_tier_receipt_required = false;
                    entry.codex_captured_uncommitted = false;
                }
            } else if pending_capture {
                // Acceptance of an older body cannot settle newly captured facts.
                // A rollback/quarantine must never replace them with an older,
                // smaller applied receipt, or repair missing facts by guessing.
                let captured_receipt = old
                    .and_then(|old| old.codex_captured_tier_receipt.as_ref())
                    .map(|captured| {
                        entry
                            .codex_applied_tier_receipt
                            .as_ref()
                            .filter(|applied| captured.covered_by(applied))
                            .unwrap_or(captured)
                            .clone()
                    });
                let entry = slot.make_mut();
                entry.codex_captured_tier_receipt = captured_receipt;
                entry.codex_captured_joined_member_set = pending_join.cloned();
                entry.codex_captured_tier_receipt_required = pending_tiers;
                entry.codex_captured_uncommitted =
                    old.is_some_and(|old| old.codex_captured_uncommitted);
                entry.codex_applied_tier_receipt =
                    old.and_then(|old| old.codex_applied_tier_receipt.clone());
                entry.codex_applied_tier_receipt_required =
                    old.is_some_and(|old| old.codex_applied_tier_receipt_required);
            }
        }
    }

    /// Re-decide the durable account-hold disclosure for every key this cycle
    /// parsed to completion: the key is held while one of its current entities
    /// is account-deferred, and leaves as soon as a parse resolves it. Keys
    /// not parsed this cycle keep their entry; only a parse or a proven
    /// absence changes it. Returns false when the bound prevented recording a
    /// hold, in which case account deferrals must stay progress-blocking.
    pub(crate) fn record_claude_account_deferred_holds<'a>(
        &mut self,
        completed_parses: impl IntoIterator<Item = (&'a str, &'a str)>,
        account_deferred_tokens: &BTreeMap<String, u64>,
    ) -> bool {
        use crate::local_resource_diagnostics::{withheld_event, WithheldEvent};
        let mut recorded = true;
        for (index_key, source_file_fingerprint) in completed_parses {
            let was_held = self.claude_account_deferred_holds.contains_key(index_key);
            // Count against the prior witness before resolution removes it.
            // New holds have no reparse event; completion installs CONTENT.
            self.note_withheld_account_parse(index_key, source_file_fingerprint, was_held);
            let (held, tokens) = (self.file_snapshot_fingerprints.get(index_key).into_iter())
                .flatten()
                .filter_map(|fingerprint| account_deferred_tokens.get(fingerprint))
                .fold((false, 0u64), |(_, sum), tokens| {
                    (true, sum.saturating_add(*tokens))
                });
            if !held {
                if self
                    .claude_account_deferred_holds
                    .remove(index_key)
                    .is_some()
                {
                    self.withheld_memo.released_resolved(index_key);
                    withheld_event(WithheldEvent::ReleasedResolved, 1);
                }
            } else if self.claude_account_deferred_holds.len() < MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS
                || self.claude_account_deferred_holds.contains_key(index_key)
            {
                self.claude_account_deferred_holds
                    .insert(index_key.to_string(), source_file_fingerprint.to_string());
                self.withheld_memo.hold_tokens(index_key, tokens);
            } else {
                // Past the cap: withheld and progress-blocking, but unrecorded
                // (no age exemption), so its withheld tokens are disclosed.
                recorded = false;
                withheld_event(WithheldEvent::UnrecordedEvents, 1);
                withheld_event(WithheldEvent::UnrecordedTokens, tokens);
            }
        }
        self.withheld_memo
            .retain_held(&self.claude_account_deferred_holds);
        recorded
    }

    pub(crate) fn claude_account_deferred_hold_count(&self) -> usize {
        self.claude_account_deferred_holds.len()
    }

    /// Derived, bounded lookup only: the BirthStore remains the move authority.
    /// Parse each held member once per discovery tick, not once per discovered file.
    fn held_move_sources(&self) -> BTreeMap<String, Option<String>> {
        let mut members = BTreeMap::new();
        for old in self
            .claude_account_deferred_holds
            .keys()
            .take(MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS)
        {
            let Some((_, member)) = claude_index_path_family_member(Path::new(old)) else {
                continue;
            };
            let owner = self.claude_money_birth_store.live_location(&member);
            let slot = members.entry(member).or_insert(None);
            if owner == Some(claude_money_birth_store::location_key(old)) {
                *slot = Some(old.clone());
            }
        }
        members
    }

    /// At most two observed paths per held member suffice to answer "another
    /// path?" for every key. This is transient derived scratch, never move proof.
    fn observed_account_members(&self) -> AccountMoveObservations {
        let held = self.held_move_sources();
        let mut members: BTreeMap<String, Vec<String>> = BTreeMap::new();
        if !held.is_empty() {
            for key in self
                .traversal
                .iter()
                .flat_map(|walk| &walk.observed_index_keys)
            {
                let Some((_, member)) = claude_index_path_family_member(Path::new(key)) else {
                    continue;
                };
                if held.contains_key(&member) {
                    let paths = members.entry(member).or_default();
                    if paths.len() < 2 {
                        paths.push(key.clone());
                    }
                }
            }
        }
        AccountMoveObservations {
            paths: members,
            through: (self.claude_account_deferred_holds.len() > MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS)
                .then(|| {
                    self.claude_account_deferred_holds
                        .keys()
                        .nth(MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS - 1)
                        .cloned()
                })
                .flatten(),
        }
    }

    /// Correctness custody follows a proven physical generation before the age gate.
    fn rehome_discovered_account_hold(
        &mut self,
        walk: &mut ScanTraversalCheckpoint,
        sources: &BTreeMap<String, Option<String>>,
        path: &Path,
        metadata: &fs::Metadata,
    ) {
        if sources.is_empty() || !walk.scan_roots.iter().any(|root| path.starts_with(root)) {
            return;
        }
        let Some((_, member)) = claude_index_path_family_member(path) else {
            return;
        };
        let Some(old) = sources.get(&member) else {
            return;
        };
        let key = local_index_key(path);
        // Ambiguous same-member presence survives even the age refusal.
        walk.observed_index_keys.insert(key.clone());
        let Some(old) = old
            .as_ref()
            .filter(|old| *old != &key && self.claude_account_deferred_holds.contains_key(*old))
        else {
            return;
        };
        self.withheld_memo.reset_absence(old);
        let opened = claude_context_file_birth::ClaudeOpenedBirth::from_metadata(metadata);
        if walk.observed_index_keys.contains(old)
            || self.decode_holds_file(old)
            || self.decode_holds_file(&key)
            || !self
                .claude_money_birth_store
                .can_record_discovered_move(&member, old, &key, opened)
        {
            return;
        }
        let needs_classification =
            self.files.contains_key(&key) && !self.claude_account_deferred_holds.contains_key(&key);
        self.rekey_account_custody(old, &key, None);
        // Custody is at the destination BEFORE the owner retires the source generation.
        if !self
            .claude_money_birth_store
            .record_discovered_move(&member, old, &key, opened)
        {
            // Roll custody back on an unexpected owner refusal. Existing
            // admitted proof/marks stay retained, and no source hold releases.
            self.rekey_account_custody(&key, old, None);
            return;
        }
        if needs_classification {
            // An already-bound destination needs one real classification of the
            // transferred debt; discovery itself cannot resolve it from an ACK.
            self.forget_withheld_content(&key);
        }
        self.withheld_memo
            .retain_held(&self.claude_account_deferred_holds);
        walk.observed_index_keys.remove(old);
    }

    /// Move, never settle, existing custody. No transcript read or release/ACK credit.
    fn rekey_account_custody(&mut self, from: &str, to: &str, scan_root: Option<&Path>) {
        let from_location = claude_money_birth_store::location_key(from);
        let to_location = claude_money_birth_store::location_key(to);
        self.claude_copy_removals.rekey(from_location, to_location);
        let marks = self.claude_money_birth_store.money_marks(from_location)
            | self.claude_money_birth_store.money_marks(to_location);
        self.claude_money_birth_store.set_money_marks(to, marks);
        self.claude_money_birth_store.set_money_marks(from, 0);
        let indexed = self.files.contains_key(to);
        if let Some(entry) = self.files.remove(from) {
            if let Some(current) = self.files.get_mut(to) {
                current.carry_sampled_audit(&entry);
            } else {
                self.files.insert_shared(to.to_owned(), entry);
            }
        }
        if let Some(incidence) = self.file_snapshot_fingerprints.remove(from) {
            if indexed {
                // The current exact set stays exact. The existing carried-ACK
                // owner keeps prior custody without minting acceptance credit.
                self.accepted_rebuild_incidence
                    .entry(to.to_owned())
                    .or_default()
                    .extend(incidence);
                self.accepted_incidence_pending_census = true;
            } else {
                self.file_snapshot_fingerprints
                    .insert_shared(to.to_owned(), incidence);
            }
        }
        if let Some(incidence) = self.accepted_rebuild_incidence.remove(from) {
            self.accepted_rebuild_incidence
                .entry(to.to_owned())
                .or_default()
                .extend(incidence);
        }
        if let Some(disposition) = self.terminal_jsonl_dispositions.remove(from) {
            self.terminal_jsonl_dispositions
                .entry(to.to_owned())
                .or_insert(disposition);
        }
        if self.confirmed_empty_files.remove(from) && !indexed {
            self.confirmed_empty_files.insert(to.to_owned());
        }
        if let Some(record) = self.claude_request_census.take(from) {
            if self.claude_request_census.get(to).is_none() {
                self.claude_request_census.insert(to.to_owned(), record);
            }
        }
        if let Some(hold) = self.claude_account_deferred_holds.remove(from) {
            self.claude_account_deferred_holds
                .entry(to.to_owned())
                .or_insert(hold);
        }
        self.withheld_memo.rekey(from, to);
        if let Some(scan_root) = scan_root {
            if let Some(claim) = self.v2_mut().growth_retention.remove(from) {
                self.v2_mut().growth_retention.insert(to.to_owned(), claim);
            }
            move_set(&mut self.legacy_unresolved_root_file_witnesses, from, to);
            move_option(&mut self.resume_after_path, from, to);
            move_option(&mut self.resume_upper_bound_path, from, to);
            if let Some(residue) = self.scan_residue_witness.as_mut() {
                move_set(&mut residue.index_keys, from, to);
            }
            if let Some(walk) = self.traversal.as_mut() {
                move_set(walk.observed_index_keys.make_mut(), from, to);
                move_set(&mut walk.codex_rollout_paths, from, to);
                move_set(&mut walk.residue.index_keys, from, to);
                move_map(&mut walk.listing_owed_requeued_unix_seconds, from, to);
                move_map(&mut walk.oversized_discovery, from, to);
                move_option(&mut walk.reconciliation_after, from, to);
                move_option(&mut walk.reconciliation_upper_bound, from, to);
                for pending in &mut walk.pending_candidates {
                    if local_index_key(&pending.path) == from {
                        pending.path = PathBuf::from(to);
                        pending.scan_root = scan_root.to_path_buf();
                    }
                }
                if let Some(hold) = walk.residue.codex_inventory_hold.as_mut() {
                    move_set(&mut hold.owed, from, to);
                    move_map(&mut hold.refused_headers, from, to);
                    move_map(&mut hold.outside_roster, from, to);
                }
            }
        }
    }

    /// Align the already owned committed baseline before held/partial restoration.
    /// The one move owner's generation tombstone is the authority, not a new map.
    pub(crate) fn rehome_withheld_baseline(&mut self, working: &ScanIndex) {
        let destinations = working
            .claude_account_deferred_holds
            .keys()
            .map(|key| (claude_money_birth_store::location_key(key), key))
            .collect::<BTreeMap<_, _>>();
        let moves = self
            .claude_account_deferred_holds
            .keys()
            .take(MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS)
            .filter_map(|old| {
                let (_, member) = claude_index_path_family_member(Path::new(old))?;
                let to = working.claude_money_birth_store.moved_to(&member, old)?;
                let new = *destinations.get(&to)?;
                (!working.claude_account_deferred_holds.contains_key(old))
                    .then(|| (old.clone(), new.clone()))
            })
            .collect::<Vec<_>>();
        for (old, new) in moves {
            self.rekey_account_custody(&old, &new, None);
        }
    }

    /// Inventory includes hold-only keys and needs no census completion credit.
    /// Every caller of retirement uses the same stable-parent eligibility gate.
    fn probe_absent_claude_account_deferred_holds(&mut self) {
        let held = self
            .claude_account_deferred_holds
            .keys()
            .take(MAX_CLAUDE_ACCOUNT_DEFERRED_HOLDS)
            .cloned()
            .collect::<Vec<_>>();
        let account_members = self.observed_account_members();
        for key in held {
            self.retire_absent_account_hold(&key, &account_members);
        }
    }

    /// Keys whose scanned entity set or head names a held revision.
    fn locally_held_keys(&self, held: &BTreeSet<String>) -> BTreeSet<String> {
        self.files
            .iter()
            .filter(|(key, entry)| {
                self.file_snapshot_fingerprints
                    .get(*key)
                    .is_some_and(|fingerprints| !fingerprints.is_disjoint(held))
                    || entry
                        .last_snapshot_fingerprint
                        .as_ref()
                        .is_some_and(|fingerprint| held.contains(fingerprint))
            })
            .map(|(key, _)| key.clone())
            .collect()
    }

    /// Held keys with no committed entry that still name a present member of
    /// a committed Claude family whose terminal authority quarantine is bound
    /// to the retained witness and records exactly this scanned revision. Such
    /// a member cannot progress within the traversal, and its family's root
    /// entry is committed, so the revert keeps a delivery-free membership
    /// entry for it instead of dropping it: the family census then sees every
    /// present member, and the candidate gate skips the unchanged member at
    /// the quarantine gate instead of reparsing it as a new file. The root
    /// itself, a family whose root entry is not committed (as after a
    /// historical replay reset), and account deferrals are never included.
    fn claude_terminal_member_placeholder_keys(
        &self,
        previous: &ScanIndex,
        held_keys: &BTreeSet<String>,
        reparse_held: &BTreeSet<String>,
    ) -> BTreeSet<String> {
        let mut committed_roots = None;
        held_keys
            .iter()
            .filter(|key| !previous.files.contains_key(*key))
            .filter(|key| {
                let Some((root_session_id, member)) =
                    claude_index_path_family_member(Path::new(key.as_str()))
                else {
                    return false;
                };
                let Some(entry) = self.files.get(*key) else {
                    return false;
                };
                let account_held = self
                    .file_snapshot_fingerprints
                    .get(*key)
                    .is_some_and(|fingerprints| !fingerprints.is_disjoint(reparse_held))
                    || entry
                        .last_snapshot_fingerprint
                        .as_ref()
                        .is_some_and(|fingerprint| reparse_held.contains(fingerprint));
                if member == root_session_id
                    || account_held
                    || entry.source_file_fingerprint.is_empty()
                {
                    return false;
                }
                let bound = self
                    .claude_usage_authority_quarantine
                    .get(&root_session_id)
                    .zip(self.claude_usage_family_witnesses.get(&root_session_id))
                    .is_some_and(|(record, witness)| {
                        record.disposition
                            == ClaudeUsageAuthorityQuarantineDisposition::UnprovenTerminal
                            && claude_usage_authority_preserves_pending(record, witness)
                            && record.member_source_file_fingerprints.get(&member)
                                == Some(&entry.source_file_fingerprint)
                    });
                bound
                    && committed_roots
                        .get_or_insert_with(|| {
                            previous
                                .files
                                .keys()
                                .filter_map(|index_key| {
                                    claude_index_path_family_member(Path::new(index_key))
                                })
                                .filter(|(root, member)| root == member)
                                .map(|(root, _)| root)
                                .collect::<BTreeSet<_>>()
                        })
                        .contains(&root_session_id)
            })
            .cloned()
            .collect()
    }

    /// Whether `with_locally_held_keys_reverted` keeps every held Claude
    /// family that still carries authority evidence in the census. The revert
    /// drops a held key that has no committed entry, and a later complete page
    /// of the same traversal would then read its still-present family as
    /// vanished or incomplete: it drops the retained witness, resolves the
    /// quarantine against partial membership, and omits the family from the
    /// manifest. A historical replay reset clears ordinary committed entries
    /// but keeps that evidence, so such a hold must stay progress-blocking
    /// instead. A bound terminal member of a committed family is the one
    /// exception: the revert keeps its delivery-free membership entry.
    pub(crate) fn locally_held_keys_restorable(
        &self,
        previous: &ScanIndex,
        held: &BTreeSet<String>,
        reparse_held: &BTreeSet<String>,
    ) -> bool {
        let held_keys = self.locally_held_keys(held);
        let placeholders =
            self.claude_terminal_member_placeholder_keys(previous, &held_keys, reparse_held);
        held_keys.iter().all(|key| {
            if previous.files.contains_key(key) || placeholders.contains(key) {
                return true;
            }
            let Some((root_session_id, _)) = claude_index_path_family_member(Path::new(key)) else {
                return true;
            };
            [self, previous].iter().all(|index| {
                !index
                    .claude_usage_family_witnesses
                    .contains_key(&root_session_id)
                    && !index
                        .claude_usage_authority_quarantine
                        .contains_key(&root_session_id)
            })
        })
    }

    /// The commit for a `Completed` upload whose only unsettled entities are
    /// locally held, non-progressing revisions. Every uploaded entity was
    /// accepted or unchanged, so each key without a held entity commits
    /// exactly as the no-hold save would, including complete-census pruning
    /// and the adopted upload context. A held key keeps its committed revision
    /// instead: entry, exact entity set, empty marker, terminal disposition,
    /// and the activity and accepted ledger for those
    /// restored entities. A held body therefore never enters the committed
    /// entity set, the manifest, or the accepted ledger, and a held key that
    /// was never committed stays absent; `locally_held_keys_restorable` says
    /// whether that absence is safe to settle. The one exception is a bound
    /// terminal member of a committed family
    /// (`claude_terminal_member_placeholder_keys`): it keeps only its scanned
    /// file identity, with no entity, body witness, activity, or acceptance.
    ///
    /// `reparse_held` names held entities whose key every later generation
    /// must retry (account deferrals). A recorded account hold preserves the
    /// committed fingerprint: its RAM content memo controls ordinary retry.
    /// A genuine external rearm (explicitly empty scanned or committed
    /// fingerprint), or an unrecorded account hold, keeps the reparse debt.
    #[cfg(test)]
    pub(crate) fn with_locally_held_keys_reverted(
        &self,
        previous: &ScanIndex,
        held: &BTreeSet<String>,
        reparse_held: &BTreeSet<String>,
    ) -> ScanIndex {
        self.clone()
            .into_locally_held_keys_reverted(previous, held, reparse_held)
    }

    /// The caller already owns the scanned graph. Restore only held keys in
    /// that allocation.
    pub(crate) fn into_locally_held_keys_reverted(
        mut self,
        previous: &ScanIndex,
        held: &BTreeSet<String>,
        reparse_held: &BTreeSet<String>,
    ) -> ScanIndex {
        self.claude_money_birth_store
            .preserve_missing_from(&previous.claude_money_birth_store);
        let empty_advances = self.claude_empty_map_advances(previous);
        let held_keys = self.locally_held_keys(held);
        self.note_claude_history_not_accepted(previous, &held_keys);
        let placeholders =
            self.claude_terminal_member_placeholder_keys(previous, &held_keys, reparse_held);
        for key in &held_keys {
            let reparse = self
                .files
                .get(key)
                .is_some_and(|entry| entry.source_file_fingerprint.is_empty())
                || self
                    .file_snapshot_fingerprints
                    .get(key)
                    .is_some_and(|fingerprints| !fingerprints.is_disjoint(reparse_held))
                    && !self.claude_account_deferred_holds.contains_key(key);
            match previous.files.get(key) {
                Some(committed) => {
                    let mut committed = committed.clone();
                    // Account retry preserves its sampled audit obligation;
                    // authority/family-only holds keep their existing restore
                    // semantics (#870 owns that separate composition).
                    if let Some(working) = self.files.get(key).filter(|_| {
                        self.claude_account_deferred_holds.contains_key(key)
                            || self
                                .file_snapshot_fingerprints
                                .get(key)
                                .is_some_and(|fingerprints| !fingerprints.is_disjoint(reparse_held))
                    }) {
                        committed.carry_sampled_audit(working);
                    }
                    // A cleared working entry keeps its re-arm debt.
                    if reparse
                        || self
                            .files
                            .get(key)
                            .is_some_and(|working| working.source_file_fingerprint.is_empty())
                    {
                        committed.source_file_fingerprint.clear();
                    }
                    self.files.insert(key.clone(), committed);
                }
                None if placeholders.contains(key) => {
                    if let Some(entry) = self.files.get_mut(key) {
                        entry.last_snapshot_fingerprint = None;
                        entry.last_upload_body_witness = None;
                    }
                    self.re_owe_effective_upload_body_witness_revision(key, 0);
                }
                None => {
                    self.files.remove(key);
                }
            }
            if let Some(carried) = previous.accepted_rebuild_incidence.get(key) {
                self.accepted_rebuild_incidence
                    .insert(key.clone(), carried.clone());
                self.preserve_carried_ack_clock(previous);
            }
            match previous.file_snapshot_fingerprints.get(key) {
                Some(fingerprints) => {
                    self.file_snapshot_fingerprints
                        .insert(key.clone(), fingerprints.clone());
                }
                None => {
                    self.file_snapshot_fingerprints.remove(key);
                }
            }
            if previous.confirmed_empty_files.contains(key) {
                self.confirmed_empty_files.insert(key.clone());
            } else {
                self.confirmed_empty_files.remove(key);
            }
            match previous.terminal_jsonl_dispositions.get(key) {
                Some(disposition) => {
                    self.terminal_jsonl_dispositions
                        .insert(key.clone(), disposition.clone());
                }
                None => {
                    self.terminal_jsonl_dispositions.remove(key);
                }
            }
        }
        let mut restored = BTreeSet::new();
        for key in &held_keys {
            match self.file_snapshot_fingerprints.get(key) {
                Some(fingerprints) => restored.extend(fingerprints.iter().cloned()),
                None => restored.extend(
                    self.files
                        .get(key)
                        .and_then(|entry| entry.last_snapshot_fingerprint.clone()),
                ),
            }
        }
        for fingerprint in &restored {
            if let Some(activity_at) = previous.snapshot_activity_at.get(fingerprint) {
                self.snapshot_activity_at
                    .insert_if_absent(fingerprint.clone(), || activity_at.clone());
            }
            if previous
                .accepted_snapshot_fingerprints
                .contains(fingerprint)
            {
                self.accepted_snapshot_fingerprints
                    .insert(fingerprint.clone());
            }
        }
        self.restore_claude_empty_map_advances(empty_advances);
        let current = self.current_snapshot_fingerprints();
        self.snapshot_activity_at
            .retain(|fingerprint, _| current.contains(fingerprint));
        self
    }

    /// F5 root: a partial checkpoint keeps this pass's traversal, in which
    /// the page already dequeued and observed every file it read. A new Codex
    /// file whose upload is not acknowledged gets no entry in the checkpoint,
    /// so it stays queued instead and a later page reads it once, with or
    /// without a restart. Locally held and decode-held files and entities keep
    /// their holds.
    pub(crate) fn keep_unacknowledged_codex_files_owed(
        &mut self,
        working: &ScanIndex,
        locally_held: &BTreeSet<String>,
    ) {
        let unacknowledged = working
            .files
            .iter()
            .filter(|(key, entry)| {
                !self.files.contains_key(*key) && !working.file_is_held(key, entry, locally_held)
            })
            .map(|(key, _)| key.clone())
            .collect::<Vec<_>>();
        if let Some(traversal) = self.traversal.as_mut() {
            requeue_observed_keys(
                SnapshotSource::Codex,
                traversal,
                unacknowledged,
                "unacknowledged",
            );
        }
    }

    /// One hold test for every source: the file is decode-held, or one of its
    /// entities is locally held or decode-held.
    fn file_is_held(
        &self,
        key: &str,
        entry: &ScanIndexEntry,
        locally_held: &BTreeSet<String>,
    ) -> bool {
        self.decode_holds_file(key)
            || entry
                .last_snapshot_fingerprint
                .iter()
                .chain(
                    self.file_snapshot_fingerprints
                        .get(key)
                        .into_iter()
                        .flatten(),
                )
                .any(|fingerprint| {
                    locally_held.contains(fingerprint) || self.decode_holds_entity(fingerprint)
                })
    }

    #[cfg(test)]
    pub fn committable_subset(
        &self,
        previous: &ScanIndex,
        accepted: &BTreeSet<String>,
        quarantined: &BTreeMap<String, SnapshotQuarantineRecord>,
    ) -> ScanIndex {
        self.committable_subset_with_local_holds(previous, accepted, quarantined, &BTreeSet::new())
    }

    #[cfg(test)]
    pub(crate) fn committable_subset_with_local_holds(
        &self,
        previous: &ScanIndex,
        accepted: &BTreeSet<String>,
        quarantined: &BTreeMap<String, SnapshotQuarantineRecord>,
        locally_held: &BTreeSet<String>,
    ) -> ScanIndex {
        self.committable_subset_for_upload(previous, accepted, quarantined, locally_held, false)
    }

    /// What a save after an upload may commit. Exact ACKs and quarantines
    /// settle; locally held and decode-held entities never do and keep their
    /// committed revision. With `every_batch_sent` (Completed, Deferred and
    /// Rejected: refusals already have quarantine custody) every other entity
    /// settles exactly as on a clean page, including unchanged ones this pass
    /// did not resend. Without it (a shed, interrupted or failed upload) only
    /// this pass's ACKs and quarantines settle.
    pub(crate) fn committable_subset_for_upload(
        &self,
        previous: &ScanIndex,
        accepted: &BTreeSet<String>,
        quarantined: &BTreeMap<String, SnapshotQuarantineRecord>,
        locally_held: &BTreeSet<String>,
        every_batch_sent: bool,
    ) -> ScanIndex {
        if !self.persistence_available() || !previous.persistence_available() {
            let mut held = self.clone();
            held.retain_persistence_baseline_from(previous);
            return held;
        }

        let accepted = accepted
            .iter()
            .filter(|fingerprint| !locally_held.contains(*fingerprint))
            .cloned()
            .collect::<BTreeSet<_>>();
        let quarantined = quarantined
            .iter()
            .filter(|(fingerprint, _)| !locally_held.contains(*fingerprint))
            .map(|(fingerprint, record)| (fingerprint.clone(), record.clone()))
            .collect::<BTreeMap<_, _>>();
        let empty_advances = self.claude_empty_map_advances(previous);
        let settled = |fingerprint: &str| {
            !self.decode_holds_entity(fingerprint)
                && (accepted.contains(fingerprint)
                    || quarantined.contains_key(fingerprint)
                    || (every_batch_sent && !locally_held.contains(fingerprint)))
        };
        let safe = |key: &String, fingerprint: Option<&str>| {
            if self.decode_holds_file(key) {
                return false;
            }
            if self.confirmed_empty_files.contains(key) {
                // A newly discovered empty file has no remote entity to lose.
                // A file that PREVIOUSLY produced an entity is different: a
                // shed/partial pass has not acknowledged removal of that old
                // server entity, so retain the prior checkpoint and retry the
                // complete generation instead of publishing false agreement.
                let previous_had_entity = previous
                    .file_snapshot_fingerprints
                    .get(key)
                    .is_some_and(|fingerprints| !fingerprints.is_empty())
                    || previous
                        .files
                        .get(key)
                        .and_then(|entry| entry.last_snapshot_fingerprint.as_ref())
                        .is_some();
                return !previous_had_entity;
            }
            if let Some(exact) = self.file_snapshot_fingerprints.get(key) {
                return exact.iter().all(|fingerprint| settled(fingerprint));
            }
            match fingerprint {
                None => true,
                Some(fingerprint) => {
                    settled(fingerprint)
                        || previous
                            .files
                            .get(key)
                            .and_then(|entry| entry.last_snapshot_fingerprint.as_deref())
                            == Some(fingerprint)
                }
            }
        };
        let mut files = BTreeMap::<String, Shared<ScanIndexEntry>>::new();
        let mut safe_keys = BTreeSet::new();
        for (key, entry) in self.files.iter_shared() {
            if safe(key, entry.last_snapshot_fingerprint.as_deref()) {
                files.insert(key.clone(), entry.clone());
                safe_keys.insert(key.clone());
            } else if let Some(committed) = previous.files.get_shared(key) {
                if !entry.source_file_fingerprint.is_empty()
                    && crate::local_resource_diagnostics::claude_reread::active()
                {
                    let held = self.file_is_held(key, entry, locally_held);
                    // Exactly the early exact-incidence branch, and the legacy
                    // head/equality fallback would have admitted this sibling.
                    let exact_only = !held
                        && !self.confirmed_empty_files.contains(key)
                        && self
                            .file_snapshot_fingerprints
                            .get(key)
                            .is_some_and(|fps| !fps.iter().all(|fp| settled(fp)))
                        && entry
                            .last_snapshot_fingerprint
                            .as_deref()
                            .map_or(true, |fp| {
                                settled(fp)
                                    || committed.last_snapshot_fingerprint.as_deref() == Some(fp)
                            });
                    crate::local_resource_diagnostics::claude_reread::restored(
                        committed.source_file_fingerprint.is_empty(),
                        held,
                        exact_only,
                    );
                }
                files.insert(key.clone(), committed.clone());
            }
        }
        // A partial save commits a Tail head only for an entry it keeps or a
        // held file's custody: any other restored or omitted file keeps its
        // committed head, and its next read starts there. A route error here
        // also fails the save that would commit.
        if !every_batch_sent {
            if let Ok(Some(route)) = state_v2::runtime_path(self) {
                let unkept = self.files.iter().filter(|(key, entry)| {
                    !safe_keys.contains(*key) && !self.file_is_held(key, entry, locally_held)
                });
                let _ = state_v2::unstage_tail(&route, unkept.map(|(key, _)| key.clone()));
            }
        }

        // A complete census may prune vanished/aged paths from `self`, but a
        // partial upload must never make that deletion durable. Only the final
        // all-accepted save may publish pruning.
        for (key, entry) in previous.files.iter_shared() {
            files.entry(key.clone()).or_insert_with(|| entry.clone());
        }
        let mut confirmed_empty_files = previous.confirmed_empty_files.clone();
        let mut file_snapshot_fingerprints = previous.file_snapshot_fingerprints.clone();
        for key in &safe_keys {
            if self.confirmed_empty_files.contains(key) {
                confirmed_empty_files.insert(key.clone());
            } else {
                confirmed_empty_files.remove(key);
            }
            match self.file_snapshot_fingerprints.get_shared(key) {
                Some(fingerprints) => {
                    if file_snapshot_fingerprints.get_shared(key) != Some(fingerprints) {
                        file_snapshot_fingerprints.insert_shared(key.clone(), fingerprints.clone());
                    }
                }
                None => {
                    file_snapshot_fingerprints.remove(key);
                }
            }
        }
        let committable_fingerprints = file_snapshot_fingerprints
            .values()
            .flat_map(BTreeSet::iter)
            .collect::<BTreeSet<_>>();
        let mut retained_quarantine = quarantined.clone();
        // If an old quarantine was retried under a newer contract but this
        // pass stopped before settlement, preserve the old witness. Its
        // mismatch is the durable instruction to retry again next cycle.
        for (fingerprint, witness) in &previous.quarantined_snapshot_fingerprints {
            if committable_fingerprints.contains(fingerprint)
                && !accepted.contains(fingerprint)
                && !quarantined.contains_key(fingerprint)
            {
                retained_quarantine.insert(fingerprint.clone(), witness.clone());
            }
        }
        let mut accepted_snapshot_fingerprints = previous.accepted_snapshot_fingerprints.clone();
        accepted_snapshot_fingerprints.extend(accepted.iter().cloned());
        // Use the incidence this partial commit will publish, which can still
        // be UNKNOWN even if working state tentatively learned an exact set.
        let opaque_incidence = self
            .decode_held_file_keys()
            .any(|key| !file_snapshot_fingerprints.contains_key(key));
        // Retire carried incidence only for file revisions this partial commit
        // actually publishes. A tentative parse must not consume prior debt.
        let mut accepted_rebuild_incidence = previous.accepted_rebuild_incidence.clone();
        for (key, fingerprints) in &self.accepted_rebuild_incidence {
            accepted_rebuild_incidence
                .entry(key.clone())
                .or_insert_with(|| fingerprints.clone());
        }
        for key in &safe_keys {
            if !self.accepted_rebuild_incidence.contains_key(key) {
                accepted_rebuild_incidence.remove(key);
            }
        }
        let carried = accepted_rebuild_incidence
            .values()
            .flat_map(BTreeSet::iter)
            .collect::<BTreeSet<_>>();
        let accepted_incidence_pending = !accepted_rebuild_incidence.is_empty();
        accepted_snapshot_fingerprints.retain(|fingerprint| {
            (opaque_incidence
                || carried.contains(fingerprint)
                || committable_fingerprints.contains(fingerprint))
                && !retained_quarantine.contains_key(fingerprint)
        });
        let mut snapshot_activity_at = self.snapshot_activity_at.clone();
        snapshot_activity_at
            .retain(|fingerprint, _| committable_fingerprints.contains(fingerprint));
        for fingerprint in committable_fingerprints {
            if let Some(activity_at) = previous.snapshot_activity_at.get(fingerprint) {
                snapshot_activity_at.insert_if_absent(fingerprint.clone(), || activity_at.clone());
            }
        }
        let mut claude_money_birth_store = self.claude_money_birth_store.clone();
        claude_money_birth_store.preserve_missing_from(&previous.claude_money_birth_store);
        self.note_claude_history_not_accepted(
            previous,
            self.files
                .keys()
                .filter(|key| !safe_keys.contains(*key))
                .chain(
                    previous
                        .files
                        .keys()
                        .filter(|key| !self.files.contains_key(*key)),
                ),
        );
        let mut result = ScanIndex {
            claude_money_birth_store,
            codex_counting_moved_evidence: self.codex_counting_moved_evidence.clone(),
            // The working map, bounded: its slots were freed only against the
            // committed state this page loaded or by its eviction order, and a
            // tombstone for a retirement this subset does not publish only
            // repeats the evidence of the entry it keeps.
            codex_counting_tombstones: self.codex_counting_tombstones.clone(),
            codex_counting_evicted_legacy: self.codex_counting_evicted_legacy.clone(),
            codex_counting_evictions: self.codex_counting_evictions,
            v2: previous.v2.as_ref().map(|state| {
                Box::new(state_v2::IndexState {
                    persistence_v2: state.persistence_v2.clone(),
                    growth_claim_context: state.growth_claim_context.clone(),
                    growth_retention: sampled_audit::growth_subset(self, previous, &safe_keys),
                })
            }),
            persistence_root: previous.persistence_root.clone(),
            persistence_controls: previous.persistence_controls.clone(),
            persistence_legacy_recovery: self
                .persistence_legacy_recovery
                .clone()
                .or_else(|| previous.persistence_legacy_recovery.clone()),
            persistence_unavailable: std::array::from_fn(|i| {
                self.persistence_unavailable[i].or(previous.persistence_unavailable[i])
            }),
            decode_holds: self.decode_holds.clone(),
            withheld_memo: self.withheld_memo.clone(),
            schema_version: SCAN_INDEX_SCHEMA_VERSION,
            generation: previous.generation,
            upload_ack_retirement_handoff: previous.upload_ack_retirement_handoff.clone(),
            retired_upload_context_fingerprint: serde::de::IgnoredAny,
            retired_archives: serde::de::IgnoredAny,
            retired_archive_deferred_alarm_count: serde::de::IgnoredAny,
            retired_reread_guard: serde::de::IgnoredAny,
            files: files.into(),
            session_account_bindings: self.session_account_bindings.clone(),
            terminal_jsonl_dispositions: previous.terminal_jsonl_dispositions.clone(),
            known_configured_scan_roots: self.known_configured_scan_roots.clone(),
            legacy_unresolved_root_file_witnesses: self
                .legacy_unresolved_root_file_witnesses
                .clone(),
            retired_codex_state_only_snapshot_fingerprints: serde::de::IgnoredAny,
            retired_codex_state_only_blocked_session_ids: serde::de::IgnoredAny,
            retired_codex_state_only_blocked_by_file: serde::de::IgnoredAny,
            retired_codex_state_only_blocked_unattributed: serde::de::IgnoredAny,
            retired_codex_state_only_blocked_legacy: serde::de::IgnoredAny,
            retired_codex_state_only_blocked_attributed: serde::de::IgnoredAny,
            codex_parent_ownership_refs: Default::default(),
            codex_parent_ownership_ledgers: Default::default(),
            codex_parent_side_requests: Default::default(),
            codex_parent_side: Default::default(),
            codex_parent_side_generation: Default::default(),
            codex_parent_proof_wrap_epoch: Default::default(),
            codex_parent_prefix_proofs: Default::default(),
            codex_parent_proof_cursor: Default::default(),
            codex_parent_side_cursor: Default::default(),
            codex_parent_proof_seq: Default::default(),
            codex_proof_index_incarnation: Default::default(),
            claude_desktop_title_files: self.claude_desktop_title_files.clone(),
            retired_claude_account_family_witnesses: serde::de::IgnoredAny,
            retired_claude_account_family_pending: serde::de::IgnoredAny,
            claude_usage_family_witnesses: self.claude_usage_family_witnesses.clone(),
            retired_claude_usage_family_pending: serde::de::IgnoredAny,
            retired_family_requests: serde::de::IgnoredAny,
            claude_request_census: self.claude_request_census.clone(),
            claude_request_census_shadow: self.claude_request_census_shadow.clone(),
            claude_usage_authority_quarantine: self.claude_usage_authority_quarantine.clone(),
            retired_claude_retired_family_tombstones: serde::de::IgnoredAny,
            retired_claude_retired_family_tombstones_initialized: serde::de::IgnoredAny,
            retired_claude_retired_family_tombstones_uncertain: serde::de::IgnoredAny,
            retired_claude_duplicate_request_owners: serde::de::IgnoredAny,
            retired_claude_duplicate_request_witness_overflowed: serde::de::IgnoredAny,
            retired_claude_owned_start_census: serde::de::IgnoredAny,
            claude_account_deferred_holds: self.claude_account_deferred_holds.clone(),
            retired_claude_duplicate_fence_rearm_attempt: serde::de::IgnoredAny,
            retired_claude_duplicate_fence_next_full_rearm_unix_seconds: serde::de::IgnoredAny,
            retired_claude_full_rearm_progress: serde::de::IgnoredAny,
            claude_request_identity_contract: self.claude_request_identity_contract.clone(),
            retired_claude_request_identity_contract_changed: serde::de::IgnoredAny,
            claude_desktop_store_inventory: self.claude_desktop_store_inventory.clone(),
            claude_copy_removals: self.claude_copy_removals.clone(),
            upload_context_proof: self.upload_context_proof.clone(),
            copy_unproven_enabled: self.copy_unproven_enabled,
            copy_prefix_base_upload_context: self.copy_prefix_base_upload_context.clone(),
            copy_prefix_last_accepted_nonce: self.copy_prefix_last_accepted_nonce.clone(),
            retired_claude_folder_login_ledger: serde::de::IgnoredAny,
            tail_discovery: self.tail_discovery,
            claude_desktop_store_cursor: self.claude_desktop_store_cursor.clone(),
            claude_desktop_store_upper_bound: self.claude_desktop_store_upper_bound.clone(),
            claude_desktop_store_sweep_had_errors: self.claude_desktop_store_sweep_had_errors,
            claude_desktop_identity_census_complete: self.claude_desktop_identity_census_complete,
            claude_desktop_lineage_census_complete: self.claude_desktop_lineage_census_complete,
            retired_claude_desktop_census_witness: serde::de::IgnoredAny,
            claude_desktop_store_retry_attempt: self.claude_desktop_store_retry_attempt,
            claude_desktop_store_retry_not_before_unix_seconds: self
                .claude_desktop_store_retry_not_before_unix_seconds,
            resume_after_path: self.resume_after_path.clone(),
            resume_upper_bound_path: self.resume_upper_bound_path.clone(),
            resume_census_window_end: self.resume_census_window_end.clone(),
            retired_held_audit_progress: serde::de::IgnoredAny,
            bounded_sweep_had_unsettled_upload: self.bounded_sweep_had_unsettled_upload,
            bounded_sweep_unsettled_causes: self.bounded_sweep_unsettled_causes,
            traversal: self.traversal.clone(),
            retired_claude_stale_family_carry: serde::de::IgnoredAny,
            scan_residue_witness: self.scan_residue_witness.clone(),
            historical_replay_generation: self.historical_replay_generation.clone(),
            retired_context_curve_capability_enabled: serde::de::IgnoredAny,
            retired_context_curve_replay_epoch: serde::de::IgnoredAny,
            retired_completed_context_curve_replay_generation: serde::de::IgnoredAny,
            confirmed_empty_files,
            file_snapshot_fingerprints,
            snapshot_activity_at,
            accepted_snapshot_fingerprints,
            accepted_snapshot_fingerprint_ledger_version: self
                .accepted_snapshot_fingerprint_ledger_version
                .max(previous.accepted_snapshot_fingerprint_ledger_version),
            legacy_settlement_reconcile_after_fingerprint: self
                .legacy_settlement_reconcile_after_fingerprint
                .clone()
                .or_else(|| {
                    previous
                        .legacy_settlement_reconcile_after_fingerprint
                        .clone()
                }),
            quarantined_snapshot_fingerprints: retained_quarantine.clone(),
            active_quarantine_witness: self.active_quarantine_witness.clone(),
            active_upload_context_fingerprint: self.active_upload_context_fingerprint.clone(),
            context_read_counts: self.context_read_counts.clone(),
            active_effective_upload_body_witness_revision: self
                .active_effective_upload_body_witness_revision,
            active_effective_upload_body_witness_revision_monotone: self
                .active_effective_upload_body_witness_revision_monotone,
            effective_upload_body_witness_revision_excluded_source_files: self
                .effective_upload_body_witness_revision_excluded_source_files
                .clone(),
            claude_reemission_exclusions: self.claude_reemission_exclusions.clone(),
            reason_reoffer_retries: self.reason_reoffer_retries.clone(),
            terminal_contract_retries: self.terminal_contract_retries.clone(),
            head_conflict_sessions: self.head_conflict_sessions.clone(),
            refusal_exposure: self.refusal_exposure,
            reason_reoffer_cooldowns: self.reason_reoffer_cooldowns.clone(),
            claude_history_cutoff_unix_seconds: self
                .claude_history_cutoff_unix_seconds
                .or(previous.claude_history_cutoff_unix_seconds),
            claude_history_gate_loaded: self.claude_history_gate_loaded
                || previous.claude_history_gate_loaded,
            // Not OR-ed with the previous index: a `full` claim clears it.
            claude_history_move_not_full: self.claude_history_move_not_full,
            claude_history_move_released: self.claude_history_move_released
                || previous.claude_history_move_released,
            accepted_incidence_pending_census: accepted_incidence_pending,
            accepted_rebuild_incidence,
            accepted_rebuild_pending_since_unix_seconds: if accepted_incidence_pending {
                previous
                    .accepted_rebuild_pending_since_unix_seconds
                    .or(self.accepted_rebuild_pending_since_unix_seconds)
            } else {
                None
            },
            accepted_rebuild_last_alarm_unix_seconds: if accepted_incidence_pending {
                previous
                    .accepted_rebuild_last_alarm_unix_seconds
                    .max(self.accepted_rebuild_last_alarm_unix_seconds)
            } else {
                None
            },
            claude_no_list_policy: self.claude_no_list_policy,
            claude_history_emission: self.claude_history_emission.clone(),
        };
        for key in &safe_keys {
            match self.terminal_jsonl_dispositions.get(key) {
                Some(disposition) => {
                    result
                        .terminal_jsonl_dispositions
                        .insert(key.clone(), disposition.clone());
                }
                None => {
                    result.terminal_jsonl_dispositions.remove(key);
                }
            }
        }
        for (key, working) in &self.files {
            // `get_mut` deep-copies an entry still shared with `self` or
            // `previous`, so take it only for an entry a carry changes.
            if !result.files.get(key).is_some_and(|retained| {
                (working.source_file_fingerprint.is_empty()
                    && !retained.source_file_fingerprint.is_empty())
                    || retained.carry_sampled_audit_changes(working)
            }) {
                continue;
            }
            let Some(retained) = result.files.get_mut(key) else {
                continue;
            };
            // A cleared source witness is outstanding reparse work, not a new
            // accepted body. Reverting an unsettled entry must keep that debt;
            // otherwise a partial save can undo a census/fence correction.
            if working.source_file_fingerprint.is_empty() {
                retained.source_file_fingerprint.clear();
            }
            retained.carry_sampled_audit(working);
        }
        result.restore_claude_empty_map_advances(empty_advances);
        result.retain_quarantined_fingerprints(&retained_quarantine);
        result.reconcile_codex_recovery_settlement(previous, &accepted);
        result
    }

    pub fn retain_quarantined_fingerprints(
        &mut self,
        quarantined: &BTreeMap<String, SnapshotQuarantineRecord>,
    ) {
        let current = self
            .file_snapshot_fingerprints
            .values()
            .flat_map(BTreeSet::iter)
            .collect::<BTreeSet<_>>();
        let replay_safe_absent_terminals = self
            .quarantined_snapshot_fingerprints
            .iter()
            .filter(|(fingerprint, record)| {
                !current.contains(*fingerprint)
                    && matches!(
                        record.disposition,
                        SnapshotQuarantineDisposition::UnprovenTerminal
                            | SnapshotQuarantineDisposition::SupersededTerminal
                    )
            })
            .map(|(fingerprint, record)| (fingerprint.clone(), record.clone()))
            .collect::<BTreeMap<_, _>>();
        let previous_claims = self
            .quarantined_snapshot_fingerprints
            .iter()
            .filter(|(_, record)| record.contract_retry_claims.is_some())
            .map(|(fp, record)| (fp.clone(), record.clone()))
            .collect();
        self.quarantined_snapshot_fingerprints = quarantined
            .iter()
            .filter(|(fingerprint, record)| {
                current.contains(*fingerprint)
                    || record.disposition == SnapshotQuarantineDisposition::SupersededTerminal
            })
            .map(|(fingerprint, witness)| (fingerprint.clone(), witness.clone()))
            .collect();
        for (fingerprint, record) in replay_safe_absent_terminals {
            self.quarantined_snapshot_fingerprints
                .entry(fingerprint)
                .or_insert(record);
        }
        terminal_contract_retry::merge_maps(
            &mut self.quarantined_snapshot_fingerprints,
            &previous_claims,
        );
        let opaque_incidence = self.decode_has_opaque_file_incidence();
        let carried = self.carried_ack_fingerprints();
        self.accepted_snapshot_fingerprints.retain(|fingerprint| {
            (opaque_incidence || carried.contains(fingerprint) || current.contains(fingerprint))
                && !self
                    .quarantined_snapshot_fingerprints
                    .contains_key(fingerprint)
        });
    }

    /// Retire only obligations made unfulfillable by positively proven absence.
    /// Codex protection retains the entry and its own lineage/receipt state.
    fn retire_absent_account_hold(&mut self, key: &str, members: &AccountMoveObservations) -> bool {
        if !self.claude_account_deferred_holds.contains_key(key) {
            return false;
        }
        // Reconciliation/hints may name an imported tail outside the view's
        // bounded prefix. Missing lookup coverage is uncertainty, never absence.
        if members
            .through
            .as_ref()
            .is_some_and(|last| key > last.as_str())
        {
            self.withheld_memo.reset_absence(key);
            return false;
        }
        let Some(walk) = self.traversal.as_ref() else {
            self.withheld_memo.reset_absence(key);
            return false;
        };
        let ambiguous =
            claude_index_path_family_member(Path::new(key)).is_some_and(|(_, member)| {
                members
                    .paths
                    .get(&member)
                    .is_some_and(|paths| paths.iter().any(|other| other != key))
            });
        if ambiguous
            || walk.counts.directory_entry_cap_exceeded_count != 0
            || walk.counts.unreadable_path_count != 0
        {
            if ambiguous {
                line_delivery_unselected("claude_code", UnselectedReason::WithheldAbsenceAmbiguous);
            }
            self.withheld_memo.reset_absence(key);
            return false;
        }
        // Keep the first NotFound across an unfinished later walk, but never
        // retire before that walk completes. No added walk or metadata read.
        if !walk.pending_directories.is_empty() {
            return false;
        }
        let Some(walk_window) = rfc3339_unix_seconds(&walk.census_window_end) else {
            self.withheld_memo.reset_absence(key);
            return false;
        };
        let parent = self
            .traversal
            .as_ref()
            .and_then(|walk| sampled_audit::absence_parent(Path::new(key), &walk.scan_roots));
        if !self
            .withheld_memo
            .absence_eligible(key, parent, walk_window)
        {
            return false;
        }
        // A decode hold keeps the entry, its obligation and memo: nothing is
        // released or disclosed as deleted while its stored record is unread.
        if self.decode_holds_file(key) {
            return false;
        }
        let census_record = self.claude_request_census.get(key).is_some();
        let protected = self
            .files
            .get(key)
            .is_some_and(ScanIndexEntry::codex_history_is_protected);
        let audit = self
            .files
            .get(key)
            .is_some_and(ScanIndexEntry::has_unverified_source);
        if audit {
            if protected {
                self.files
                    .get_mut(key)
                    .expect("audit entry")
                    .scan_identity_version = Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
            } else {
                // Preserve incidence handling: retiring audit debt
                // does not itself grant authority to prune its fingerprints.
                self.retire_vanished_claude_audit_debt_entry(key);
            }
            crate::local_resource_diagnostics::audit_retired_absent("claude_code");
            disappearance_diagnostics::vanished(
                SnapshotSource::ClaudeCode,
                disappearance_diagnostics::Vanished::AuditDebtDropped,
            );
        }
        self.claude_account_deferred_holds.remove(key);
        self.withheld_memo.released_deleted(key);
        if !protected && !audit {
            self.remove_file_entry_unless_held(key);
        }
        if census_record && self.claude_request_census.get(key).is_none() {
            disappearance_diagnostics::vanished(
                SnapshotSource::ClaudeCode,
                disappearance_diagnostics::Vanished::RequestCensusRemoved,
            );
        }
        true
    }

    /// Retire a Claude entry whose file vanished beneath its
    /// still-present parent together with its unverified audit marker.
    /// Only the page merge calls this, and only for keys the scanner settled
    /// as such a removal; `remove_file_entry` keeps audit debt for every
    /// other caller. Codex-protected entries are never retired here. The
    /// key's snapshot fingerprints and account hold stay, because each
    /// removal path ends in the state main already reaches for the same key:
    /// main's reconciliation keeps an audit-debt entry and its fingerprints
    /// forever, so this path drops only the entry with its lifetime facts
    /// (`drop_file_entry`) and its marker, while a
    /// vanished entry without audit debt goes through `remove_file_entry`,
    /// which drops its fingerprints and hold just as main's reconciliation
    /// does at the next healthy terminal. The hold is later dropped by a
    /// complete census. Returns false, retiring nothing, for an entry
    /// without audit debt or one a decode hold keeps.
    fn retire_vanished_claude_audit_debt_entry(&mut self, key: &str) -> bool {
        if !self.persistence_available() || self.decode_holds_file(key) {
            return false;
        }

        if !self.files.get(key).is_some_and(|entry| {
            entry.has_unverified_source() && !entry.codex_history_is_protected()
        }) {
            return false;
        }
        self.drop_file_entry(key);
        self.terminal_jsonl_dispositions.remove(key);
        true
    }

    fn remove_file_entry(&mut self, key: &str) {
        self.remove_file_entry_unless_held(key);
    }

    /// Of `keys`, those whose entry holds a parsed, nonempty body witness that
    /// is not ACKed: deleting the file now loses that usage. Withheld-account
    /// keys keep their own deletion count. Taken before a vanished-key retirement.
    fn unacked_bodies<'a>(&self, keys: impl IntoIterator<Item = &'a String>) -> Vec<&'a String> {
        keys.into_iter()
            .filter(|key| {
                !self.claude_account_deferred_holds.contains_key(*key)
                    && self
                        .file_snapshot_fingerprints
                        .get(*key)
                        .is_some_and(|entities| !entities.is_empty())
                    && self.files.get(*key).is_some_and(|entry| {
                        entry.last_upload_body_witness.is_some()
                            && !claude_index_file_body_accepted(self, key, entry)
                    })
            })
            .collect()
    }

    /// Counts each of `unacked` the retirement removed; it holds or resends nothing.
    fn count_unacked_retired(&self, source: SnapshotSource, unacked: Vec<&String>) {
        for key in unacked
            .into_iter()
            .filter(|key| !self.files.contains_key(*key))
        {
            // The committed head carries the totals when the codec stores
            // them.
            let usage = tail_source::stored_usage(source, self, key);
            crate::local_resource_diagnostics::unacked_usage_lost_to_deletion(
                source.api_slug(),
                usage,
            );
        }
    }

    fn remove_file_entry_unless_held(&mut self, key: &str) {
        if !self.persistence_available() {
            return;
        }

        // Account debt leaves only through a resolving parse or F4. Generic
        // age/removal callers cannot bypass the per-key absence sequence.
        if self.claude_account_deferred_holds.contains_key(key) {
            return;
        }

        if self.decode_holds_file(key) {
            return;
        }
        if self
            .files
            .get(key)
            .is_some_and(ScanIndexEntry::has_unverified_source)
        {
            return;
        }
        self.drop_file_entry(key);
        self.terminal_jsonl_dispositions.remove(key);
        self.file_snapshot_fingerprints.remove(key);
        self.claude_account_deferred_holds.remove(key);
    }

    /// The one lifetime core of a positive-absence exit: the index entry and
    /// the facts that live exactly as long as it (confirmed-empty mark,
    /// request census, money marks, stored copy removals). Every exit calls
    /// it after its own guards; dispositions, fingerprints, holds and Codex
    /// proof stay with each caller. Nothing else ends a census record.
    fn drop_file_entry(&mut self, key: &str) {
        self.files.remove(key);
        self.confirmed_empty_files.remove(key);
        self.claude_request_census.remove(key);
        self.claude_money_birth_store.set_money_marks(key, 0);
        self.claude_copy_removals
            .forget(claude_money_birth_store::location_key(key));
    }

    /// Keep move history for 30 days after the last indexed or held member.
    fn prune_claude_money_births(&mut self, now: u64) {
        if self.claude_money_birth_store.is_empty() {
            return;
        }
        let members = self
            .files
            .keys()
            .map(String::as_str)
            .chain(self.decode_holds.file_keys())
            .filter_map(|path| {
                let member = claude_index_path_member_ref(Path::new(path))?;
                let session = match member.subagent_stem {
                    None => std::borrow::Cow::Borrowed(member.root),
                    Some(_) => std::borrow::Cow::Owned(member.into_owned().1),
                };
                Some((session, path))
            });
        self.claude_money_birth_store.prune(now, members);
    }

    /// Retire terminal JSONL dispositions whose file is no longer indexed.
    ///
    /// A disposition is only ever written together with the `files` entry for
    /// the same key, so a key with no entry means the path was renamed, deleted
    /// or reconciled away. Such a record can never be consulted again - a
    /// candidate at that path already takes `CandidateDecision::Parse` through
    /// the missing-entry arm - so dropping it is behaviour-neutral hygiene that
    /// stops this durable map from growing monotonically with every lossy
    /// transcript the user ever moves.
    ///
    /// This is also the whole bound, and it is structural rather than a cap.
    /// `record_terminal_jsonl_disposition` is called from exactly one place,
    /// inside the `parse_complete` block that inserts the `files` entry for the
    /// same `local_index_key` six lines later, and `remove_file_entry` drops
    /// both together; bounded census reconciliation removes from `files` alone,
    /// which is precisely the orphan this retain sweeps. So
    /// `terminal_jsonl_dispositions` is always a subset of `files` - at most
    /// one small fixed-shape record per transcript the traversal currently
    /// observes, alongside the strictly larger `ScanIndexEntry` the same key
    /// already costs. `committable_subset` preserves that inductively: it
    /// carries `previous.terminal_jsonl_dispositions` beside a `files` map that
    /// unions in all of `previous.files`, so a subset stays a subset across a
    /// partial commit. Whatever bounds `files` therefore bounds this map, and a
    /// separate cap on a strict subset of `files` could not bound the index. It
    /// could only evict a live record, which re-arms the child->parent reparse
    /// override for Codex (re-reading an oversized rollout every cycle) or
    /// silently drops that file's disclosed terminal loss for every source
    /// without one.
    fn prune_terminal_jsonl_dispositions(&mut self) {
        let files = &self.files;
        let holds = &self.decode_holds;
        self.terminal_jsonl_dispositions
            .retain(|key, _| files.contains_key(key) || holds.contains("files", key));
    }

    fn effective_upload_body_witness_revision_requires_adoption(&self, key: &str) -> bool {
        let active = self.active_effective_upload_body_witness_revision;
        active != 0
            && self.files.get(key).map_or(true, |entry| {
                let stored = entry.effective_upload_body_witness_revision;
                if self.active_effective_upload_body_witness_revision_monotone {
                    stored < active
                } else {
                    stored != active
                }
            })
    }

    /// Use the existing physical listing stamp, independent of parser, upload
    /// context or retry revisions. A refusal grants no transcript read.
    fn stale_refusal_holds_unchanged_input(&self, candidate: &CandidateFile) -> bool {
        let key = local_index_key(&candidate.path);
        self.file_snapshot_fingerprints
            .get(&key)
            .is_some_and(|fps| {
                fps.iter().any(|fp| {
                    self.reason_reoffer_cooldowns
                        .get(fp)
                        .is_some_and(|c| c.input_change_only)
                })
            })
            && self.files.get(&key).is_some_and(|entry| {
                let modified = Some(candidate.modified_unix_nanos);
                let stored = entry.modified_unix_nanos.or_else(|| {
                    modified.filter(|nanos| nanos / 1_000_000_000 == entry.modified_unix_seconds)
                });
                entry.same_stamp_with_mtime(
                    stored,
                    candidate.size_bytes,
                    modified,
                    Some(candidate.fingerprint_birth_nanos),
                    codex_fragment::Stamp::candidate(candidate),
                )
            })
    }

    fn candidate_decision(&self, candidate: &CandidateFile) -> CandidateDecision {
        self.candidate_decision_with_reason(candidate).0
    }

    fn candidate_decision_with_reason(
        &self,
        candidate: &CandidateFile,
    ) -> (CandidateDecision, Option<CandidateParseReason>) {
        self.candidate_decision_with_reason_at(candidate, sampled_scan::now_seconds())
    }

    fn candidate_decision_in_window(
        &self,
        candidate: &CandidateFile,
        audit_now: u64,
        source_change: &mut Option<change_reason::SourceChange>,
    ) -> (CandidateDecision, Option<CandidateParseReason>) {
        self.candidate_decision_refined(candidate, audit_now, true, source_change)
    }

    #[cfg(test)]
    fn candidate_decision_at(&self, candidate: &CandidateFile, now: u64) -> CandidateDecision {
        self.candidate_decision_with_reason_at(candidate, now).0
    }

    fn candidate_decision_with_reason_at(
        &self,
        candidate: &CandidateFile,
        now: u64,
    ) -> (CandidateDecision, Option<CandidateParseReason>) {
        self.candidate_decision_with_reason_gated(candidate, now, true)
    }

    /// True when only the body-witness revision selects this candidate: the
    /// same decision without that gate skips the file.
    fn candidate_requires_only_body_witness_adoption(
        &self,
        candidate: &CandidateFile,
        now: u64,
    ) -> bool {
        self.effective_upload_body_witness_revision_requires_adoption(&local_index_key(
            &candidate.path,
        )) && self
            .candidate_decision_with_reason_gated(candidate, now, false)
            .0
            == CandidateDecision::Skip
    }

    /// Whether an unindexed member's family holds an authority record (a held
    /// body the committed index does not keep) whose gate would skip it as an
    /// indexed member: its revision unchanged, its witness binding unmoved,
    /// its retry not due and no correction owing it.
    fn claude_unindexed_member_waits_for_authority(&self, candidate: &CandidateFile) -> bool {
        let Some((root_session_id, member)) = claude_index_path_family_member(&candidate.path)
        else {
            return false;
        };
        self.claude_usage_authority_quarantine
            .get(&root_session_id)
            .is_some_and(|record| {
                !record
                    .proof_correction
                    .as_ref()
                    .is_some_and(|correction| correction.owed_member_ids.contains(&member))
                    && self
                        .claude_usage_authority_candidate_requires_family_reparse(candidate)
                        .is_none()
            })
    }

    /// The candidate decision plus, for `Parse`, the first gate that selected
    /// the file. The reason is a count-only diagnostic; only the adoption
    /// page budget reads it. `body_witness_adoption: false` evaluates the
    /// same gates without the body-witness revision.
    ///
    /// Scoped history admission can ignore revision and proven mode-context
    /// debt while checking every independent local refresh reason.
    fn candidate_decision_with_reason_gated(
        &self,
        candidate: &CandidateFile,
        now: u64,
        body_witness_adoption: bool,
    ) -> (CandidateDecision, Option<CandidateParseReason>) {
        self.candidate_decision_refined(candidate, now, body_witness_adoption, &mut None)
    }

    /// The gated decision; `source_change` names the `SourceChanged` arm that
    /// selected the file, for the change-reason counts only.
    fn candidate_decision_refined(
        &self,
        candidate: &CandidateFile,
        now: u64,
        body_witness_adoption: bool,
        source_change: &mut Option<change_reason::SourceChange>,
    ) -> (CandidateDecision, Option<CandidateParseReason>) {
        let key = local_index_key(&candidate.path);
        if self.decode_holds_file(&key) {
            return (CandidateDecision::Skip, None);
        }
        if self.stale_refusal_holds_unchanged_input(candidate) {
            return (CandidateDecision::Skip, None);
        }
        if self
            .terminal_jsonl_dispositions
            .get(&key)
            .is_some_and(|disposition| {
                disposition.source_file_fingerprint != candidate.source_file_fingerprint
                    || disposition.parser_generation != JSONL_TERMINAL_DISPOSITION_GENERATION
            })
        {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::TerminalDisposition),
            );
        }
        let Some(entry) = self.files.get(&key) else {
            if self.claude_unindexed_member_waits_for_authority(candidate)
                || self.withheld_account_unchanged(&key, candidate)
            {
                return (CandidateDecision::Skip, None);
            }
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::NewFile),
            );
        };
        if let Some((root_session_id, member)) = claude_index_path_family_member(&candidate.path) {
            if self
                .claude_usage_authority_quarantine
                .contains_key(&root_session_id)
            {
                if self
                    .claude_usage_authority_candidate_requires_family_reparse(candidate)
                    .is_some()
                    || self
                        .claude_usage_authority_quarantine
                        .get(&root_session_id)
                        .and_then(|record| record.proof_correction.as_ref())
                        .is_some_and(|correction| correction.owed_member_ids.contains(&member))
                {
                    return (
                        CandidateDecision::Parse,
                        Some(CandidateParseReason::AuthorityQuarantine),
                    );
                }
                return (CandidateDecision::Skip, None);
            }
        }
        let withheld_unchanged = !entry.source_file_fingerprint.is_empty()
            && self.withheld_account_unchanged(&key, candidate);
        // A withheld key's audit debt (carried onto its reverted entry) cannot
        // settle while held; an unchanged one defers it to its next counted
        // re-parse, usually the binding read, instead of a Full every pass.
        // A prefix-only hold must survive settlement of the file's own turns.
        // Its persisted attempt counter expires on the third decision pass.
        if self
            .claude_copy_removals
            .pending(claude_money_birth_store::location_key(&key))
        {
            *source_change = Some(change_reason::SourceChange::CopyRemoval);
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::SourceChanged),
            );
        }
        let audit_due = entry.audit_requires_full(now) && !withheld_unchanged;
        if audit_due {
            return (CandidateDecision::Parse, Some(CandidateParseReason::Audit));
        }
        // A locally held Claude family above keeps its existing bounded retry
        // gate. Otherwise a projection change selects even an unchanged v2
        // file under an already admitted context, independently of parser age.
        // Completed restores the old revision while account-held. Its memo is
        // scoped to the active revision/context, so repeating that adoption
        // cannot settle it; a new activation still selects a counted parse.
        if body_witness_adoption
            && !withheld_unchanged
            && self.effective_upload_body_witness_revision_requires_adoption(&key)
        {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::BodyWitnessAdoption),
            );
        }
        // A settings or capability change never selects a read: it applies
        // from the file's next ordinary read on, for every source.
        if self
            .file_snapshot_fingerprints
            .get(&key)
            .is_some_and(|fingerprints| {
                fingerprints.iter().any(|fingerprint| {
                    // Missing activity on the restored tuple cannot settle an
                    // account hold either. An actual quarantine retry remains
                    // independent authority to re-read, even with CONTENT.
                    (!withheld_unchanged
                        && !self
                            .snapshot_activity_at
                            .get(fingerprint)
                            .is_some_and(valid_snapshot_activity))
                        || self.quarantine_retry_selects_file(fingerprint, &key)
                })
            })
        {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::ActivityOrQuarantineRetry),
            );
        }
        // A withheld key keeps its old committed revision; unless re-armed it
        // re-parses only once per process or on a stamp/evidence change.
        if withheld_unchanged {
            return (CandidateDecision::Skip, None);
        }
        let known_fragment = entry.codex_fragment.as_ref().is_some_and(|fragment| {
            fragment.matches(
                entry.size_bytes,
                candidate.size_bytes,
                codex_fragment::Stamp::candidate(candidate),
            ) && entry.source_file_fingerprint == candidate.source_file_fingerprint
        });
        let transcript_changed = !known_fragment
            && (entry.size_bytes != candidate.size_bytes
                || entry.modified_unix_seconds != candidate.modified_unix_seconds
                || entry
                    .modified_unix_nanos
                    .is_some_and(|value| value != candidate.modified_unix_nanos));
        if transcript_changed {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::TranscriptChanged),
            );
        }
        if entry.codex_captured_uncommitted
            || entry.codex_captured_tier_receipt_required
            || entry.codex_captured_joined_member_set.is_some()
        {
            // The independent native quarantine owns its existing retry gate;
            // selector capture never constitutes acceptance or creates a skip.
            let quarantine_holds = entry.source_file_fingerprint
                == candidate.source_file_fingerprint
                && self
                    .file_snapshot_fingerprints
                    .get(&key)
                    .is_some_and(|fingerprints| {
                        !fingerprints.is_empty()
                            && fingerprints.iter().all(|fingerprint| {
                                self.quarantined_snapshot_fingerprints
                                    .get(fingerprint)
                                    .is_some_and(|record| {
                                        self.active_quarantine_witness.as_ref().is_some_and(
                                            |active| {
                                                record
                                                    .witness
                                                    .same_retry_contract_any_context(active)
                                            },
                                        ) && !self.quarantine_retry_selects_file(fingerprint, &key)
                                    })
                            })
                    });
            return if quarantine_holds {
                (CandidateDecision::Skip, None)
            } else {
                (
                    CandidateDecision::Parse,
                    Some(CandidateParseReason::CodexCapture),
                )
            };
        }
        if entry.last_snapshot_fingerprint.is_none() && !self.confirmed_empty_files.contains(&key) {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::UnknownOutcome),
            );
        }
        if !self.file_snapshot_fingerprints.contains_key(&key)
            && entry
                .last_snapshot_fingerprint
                .as_ref()
                .is_some_and(|fingerprint| {
                    !self
                        .snapshot_activity_at
                        .get(fingerprint)
                        .is_some_and(valid_snapshot_activity)
                })
        {
            return (
                CandidateDecision::Parse,
                Some(CandidateParseReason::LegacyActivity),
            );
        }
        if entry.scan_identity_version.as_deref() != Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION)
            && !entry.has_unverified_source()
        {
            // An owed revision is not observed: it parses, never migrates.
            return if entry.source_file_fingerprint.as_str()
                == candidate.legacy_source_file_fingerprint
            {
                if candidate.legacy_config_reconciliation_required {
                    (CandidateDecision::ReconcileLegacy, None)
                } else {
                    (CandidateDecision::Migrate, None)
                }
            } else {
                // The legacy source-wide sidecar identity changed while this
                // entry was not observed. We cannot prove which session was
                // affected from the irreversible old digest, so correctness
                // requires a one-time parse instead of silently absorbing it.
                (
                    CandidateDecision::Parse,
                    Some(CandidateParseReason::LegacyIdentity),
                )
            };
        }
        if entry.source_file_fingerprint != candidate.source_file_fingerprint {
            let reason = if entry.source_file_fingerprint.is_empty() {
                CandidateParseReason::Rearmed
            } else {
                *source_change = Some(change_reason::SourceChange::Fingerprint);
                CandidateParseReason::SourceChanged
            };
            (CandidateDecision::Parse, Some(reason))
        } else if self.claude_account_deferred_holds.contains_key(&key) {
            // Equality of the committed fingerprint cannot settle an account
            // retry. Only the validated CONTENT memo above grants that Skip;
            // missing/refused/poisoned/unstamped advisory state must recover
            // through the existing counted parse, without clearing the tuple.
            // Memo-miss recovery, NOT a source change: SourceChanged is the
            // legacy selector bucket; withheld_reparse{start} names this read.
            (
                CandidateDecision::Parse,
                Some(CandidateParseReason::SourceChanged),
            )
        } else {
            (CandidateDecision::Skip, None)
        }
    }

    /// This file is a family member an owed proof correction names.
    fn claude_authority_correction_owed(&self, path: &Path) -> bool {
        claude_index_path_family_member(path).is_some_and(|(root, member)| {
            self.claude_usage_authority_quarantine
                .get(&root)
                .and_then(|record| record.proof_correction.as_ref())
                .is_some_and(|correction| correction.owed_member_ids.contains(&member))
        })
    }

    /// This member is selected only because its family owes
    /// a proof correction (no witness change and no due retry).
    fn claude_authority_correction_only(&self, candidate: &CandidateFile) -> bool {
        self.claude_authority_correction_owed(&candidate.path)
            && self
                .claude_usage_authority_candidate_requires_family_reparse(candidate)
                .is_none()
    }

    /// Whether an owed proof correction still blocks a fully
    /// settled upload, and how many owed members wait for the history gate
    /// instead. A member whose indexed file still owes the history upgrade is
    /// held by the gate: its correction settles once the gate permits it, so
    /// it is deferred (disclosed), not blocking. A member with no indexed file
    /// blocks.
    pub(crate) fn claude_authority_proof_correction_blocking(&self) -> (bool, usize) {
        let owed = self
            .claude_usage_authority_quarantine
            .values()
            .filter_map(|record| record.proof_correction.as_ref())
            .map(|correction| correction.owed_member_ids.len())
            .sum::<usize>();
        if owed == 0 {
            return (false, 0);
        }
        // By family member identity, not source fingerprint: a re-armed
        // entry keeps its member path with a cleared fingerprint.
        let mut found = 0;
        let mut deferred = 0;
        for key in self.files.keys() {
            let Some((root, member)) = claude_index_path_family_member(Path::new(key)) else {
                continue;
            };
            let owes = self
                .claude_usage_authority_quarantine
                .get(&root)
                .and_then(|record| record.proof_correction.as_ref())
                .is_some_and(|correction| correction.owed_member_ids.contains(&member));
            if owes {
                found += 1;
                if self.effective_upload_body_witness_revision_requires_adoption(key) {
                    deferred += 1;
                }
            }
        }
        (found < owed || deferred < found, deferred)
    }

    fn claude_usage_authority_candidate_requires_family_reparse(
        &self,
        candidate: &CandidateFile,
    ) -> Option<String> {
        let (root_session_id, source_session_id) =
            claude_index_path_family_member(&candidate.path)?;
        let record = self
            .claude_usage_authority_quarantine
            .get(&root_session_id)?;
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or_default();
        let witness_matches = self
            .claude_usage_family_witnesses
            .get(&root_session_id)
            .is_some_and(|witness| {
                claude_usage_family_witness_fingerprint(witness)
                    == record.proven_witness_fingerprint
            });
        let revision_matches = record
            .member_source_file_fingerprints
            .get(&source_session_id)
            == Some(&candidate.source_file_fingerprint);
        let retry_due = record.disposition
            == ClaudeUsageAuthorityQuarantineDisposition::RetryPending
            && record.retry_after_unix_seconds <= now
            || claude_terminal_predates_e2(record);
        (!witness_matches || !revision_matches || retry_due).then_some(root_session_id)
    }

    fn last_snapshot_fingerprint(&self, candidate: &CandidateFile) -> Option<String> {
        self.files
            .get(&local_index_key(&candidate.path))
            .and_then(|entry| entry.last_snapshot_fingerprint.clone())
    }

    fn last_upload_body_witness(&self, candidate: &CandidateFile) -> Option<String> {
        self.files
            .get(&local_index_key(&candidate.path))
            .and_then(|entry| entry.last_upload_body_witness.clone())
    }

    /// A fresh entry for `candidate` that carries `key`'s upload witness,
    /// counting state and upload-context receipt from the entry it replaces.
    /// Callers decide the snapshot fingerprint and identity version.
    fn carried(
        &self,
        key: &str,
        candidate: CandidateFile,
        last_snapshot_fingerprint: Option<String>,
        scan_identity_version: String,
    ) -> ScanIndexEntry {
        let old = self.files.get(key);
        ScanIndexEntry {
            codex_fragment: None,
            size_bytes: candidate.size_bytes,
            modified_unix_seconds: candidate.modified_unix_seconds,
            modified_unix_nanos: Some(candidate.modified_unix_nanos),
            source_file_fingerprint: candidate.source_file_fingerprint,
            last_snapshot_fingerprint,
            last_upload_body_witness: old.and_then(|entry| entry.last_upload_body_witness.clone()),
            effective_upload_body_witness_revision: old
                .map_or(0, |entry| entry.effective_upload_body_witness_revision),
            scan_identity_version: Some(scan_identity_version),
            codex_joined_member_set: None,
            codex_captured_joined_member_set: None,
            codex_protected_owner: None,
            codex_applied_tier_receipt: None,
            codex_applied_tier_receipt_required: false,
            codex_captured_tier_receipt: None,
            codex_captured_tier_receipt_required: false,
            codex_captured_uncommitted: false,
            codex_counting_v2: old.is_some_and(|entry| entry.codex_counting_v2),
            codex_counting_owner: old.and_then(|entry| entry.codex_counting_owner.clone()),
            opened_changed_nanos: candidate.fingerprint_changed_nanos,
            opened_birth_nanos: candidate.fingerprint_birth_nanos,
            upload_context_receipt: old.and_then(|entry| entry.upload_context_receipt.clone()),
        }
    }

    fn migrate(&mut self, candidate: CandidateFile) {
        let key = local_index_key(&candidate.path);
        rearm_cause::reproven(&key);
        let old = self.files.get(&key);
        let last_snapshot_fingerprint =
            old.and_then(|entry| entry.last_snapshot_fingerprint.clone());
        let entry = self.carried(
            &key,
            candidate,
            last_snapshot_fingerprint,
            LOCAL_SCAN_INDEX_IDENTITY_VERSION.to_string(),
        );
        self.files.insert(key, entry);
    }

    fn record(
        &mut self,
        candidate: CandidateFile,
        last_snapshot_fingerprint: Option<String>,
        parse_outcome: ScanParseOutcome,
    ) {
        let key = local_index_key(&candidate.path);
        rearm_cause::reproven(&key);
        let scan_identity_version = self
            .files
            .get(&key)
            .map(ScanIndexEntry::carried_audit_version)
            .unwrap_or_else(|| LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
        // The body witness and `codex_counting_v2` are carried; a configured
        // singleton parse then sets the latter to that parse's decided version.
        let entry = self.carried(
            &key,
            candidate,
            last_snapshot_fingerprint,
            scan_identity_version,
        );
        self.files.insert(key.clone(), entry);
        match parse_outcome {
            ScanParseOutcome::ConfirmedEmpty | ScanParseOutcome::PolicySuppressed => {
                self.claude_copy_removals
                    .clear_hold(claude_money_birth_store::location_key(&key));
                self.note_empty_file_upload_context(&key);
                self.confirmed_empty_files.insert(key);
            }
            ScanParseOutcome::Snapshot | ScanParseOutcome::Unknown => {
                self.clear_empty_file_upload_context(&key);
                self.confirmed_empty_files.remove(&key);
            }
        }
    }

    fn record_terminal_jsonl_disposition(
        &mut self,
        candidate: &CandidateFile,
        loss: Option<TerminalJsonlLoss>,
    ) {
        let key = local_index_key(&candidate.path);
        match loss {
            Some(loss) => {
                self.terminal_jsonl_dispositions.insert(
                    key,
                    TerminalJsonlDisposition {
                        source_file_fingerprint: candidate.source_file_fingerprint.clone(),
                        parser_generation: JSONL_TERMINAL_DISPOSITION_GENERATION.to_string(),
                        loss,
                    },
                );
            }
            None => {
                self.terminal_jsonl_dispositions.remove(&key);
            }
        }
    }

    fn terminal_jsonl_loss(&self, candidate: &CandidateFile) -> Option<&TerminalJsonlLoss> {
        self.terminal_jsonl_dispositions
            .get(&local_index_key(&candidate.path))
            .filter(|disposition| {
                disposition.source_file_fingerprint == candidate.source_file_fingerprint
                    && disposition.parser_generation == JSONL_TERMINAL_DISPOSITION_GENERATION
            })
            .map(|disposition| &disposition.loss)
    }
}

