    /// One owned request as the retired builder emitted it: ordinal 1 carries
    /// the anchor, peak and tail flags.
    fn single_request_context_curve(
        parser_revision: &str,
        ownership_revision: &str,
        model_evidence_revision: &str,
        observed_at: &str,
        effective_input_tokens: u64,
        model: &str,
        context_window_tokens: Option<u64>,
    ) -> SnapshotContextCurve {
        SnapshotContextCurve {
            contract_version: CONTEXT_CURVE_CONTRACT_VERSION.to_string(),
            parser_revision: parser_revision.to_string(),
            ownership_revision: ownership_revision.to_string(),
            sampling_revision: CONTEXT_CURVE_SAMPLING_REVISION.to_string(),
            coverage: "complete".to_string(),
            total_owned_request_count: 1,
            retained_point_count: 1,
            total_compaction_boundary_count: 0,
            retained_boundary_count: 0,
            points: vec![SnapshotContextCurvePoint {
                owned_request_ordinal: 1,
                observed_at: observed_at.to_string(),
                effective_input_tokens,
                model_window_index: 0,
                segment_ordinal: 0,
                retention_flags: CONTEXT_CURVE_RETENTION_ANCHOR
                    | CONTEXT_CURVE_RETENTION_PEAK
                    | CONTEXT_CURVE_RETENTION_TAIL,
                compaction_before_request_boundary_index: None,
                compaction_after_request_boundary_index: None,
            }],
            boundaries: Vec::new(),
            model_windows: vec![SnapshotContextCurveModelWindow {
                model_window_index: 0,
                model: model.to_string(),
                context_window_tokens,
                evidence_kind: if context_window_tokens.is_some() {
                    "provider_reported_window"
                } else {
                    "provider_reported_model"
                }
                .to_string(),
                evidence_revision: model_evidence_revision.to_string(),
            }],
        }
    }

    fn terminal_unhealthy_traversal(context_fingerprint: String) -> ScanTraversalCheckpoint {
        ScanTraversalCheckpoint {
            context_fingerprint,
            census_window_end: "2026-07-31T00:00:00Z".to_string(),
            scan_roots: Vec::new(),
            pending_directories: VecDeque::new(),
            pending_candidates: VecDeque::new(),
            observed_index_keys: Default::default(),

            oversized_discovery: Default::default(),

            codex_rollout_paths: BTreeSet::new(),
            codex_join_directory_census: None,
            reconciliation_upper_bound: None,
            reconciliation_after: None,
            reconciliation_started: false,
            watcher_hint_seen: false,
            codex_freshness_yield: false,
            retired_codex_parent_resolution_retry_required: serde::de::IgnoredAny,
            unhealthy_retry_attempt: 1,
            unhealthy_retry_not_before_unix_seconds: Some(0),
            counts: ScanTraversalCounts {
                disappeared_file_count: 1,
                ..ScanTraversalCounts::default()
            },
            residue: ScanTraversalResidue::default(),
            listing_started_unix_seconds: None,
            listing_owed_requeued_unix_seconds: Default::default(),
        }
    }

    /// [regress] A restored presence-only file is queued once at load for every source.
    #[test]
    fn restored_unindexed_files_are_requeued_for_every_source() {
        for source in [
            SnapshotSource::ClaudeCode,
            SnapshotSource::Codex,
            SnapshotSource::Pi,
        ] {
            let root = temp_dir("restored-file-admission");
            let path = root.join("session.jsonl");
            fs::write(&path, b"{}\n").unwrap();
            let key = local_index_key(&path);
            let mut traversal = terminal_unhealthy_traversal(String::new());
            traversal.counts = ScanTraversalCounts::default();
            traversal.scan_roots = vec![root.clone()];
            traversal.observed_index_keys.insert(key.clone());
            let index = ScanIndex {
                traversal: Some(traversal),
                ..ScanIndex::default()
            };
            let mut old = serde_json::to_value(index).unwrap();
            old["traversal"]["oversized_discovery"] = json!({
                "retired_path_hash": {"content_hash":"retired_content_hash", "observations":1}
            });
            old["traversal"]["counts"]["oversized_file_count"] = json!(1);
            let index_path = root.join("index.json");
            fs::write(&index_path, serde_json::to_vec(&old).unwrap()).unwrap();
            let restored = ScanIndex::load_for_snapshot_source(&index_path, source, &root).unwrap();
            let pending = &restored.traversal.as_ref().unwrap().pending_candidates;
            assert_eq!(
                pending.len(),
                1,
                "{source:?}: previously unread file must not be skipped"
            );
            assert_eq!(pending[0].path, path);
            assert!(pending[0].census_member);
            assert!(!restored.files.contains_key(&key));
            let again = ScanIndex::load_for_snapshot_source(&index_path, source, &root).unwrap();
            assert!(
                again
                    .traversal
                    .as_ref()
                    .unwrap()
                    .pending_candidates
                    .is_empty(),
                "load requeue stays once per process, without a reread loop"
            );
            fs::remove_dir_all(root).unwrap();
        }
    }

    #[test]
    fn codex_sqlite_spawn_edges_restore_nested_subagent_lineage() {
        let home = temp_dir("codex-spawn-lineage");
        let codex_dir = home.join(".codex");
        let sessions_dir = codex_dir.join("sessions");
        fs::create_dir_all(&sessions_dir).expect("create sessions");
        let database = Connection::open(codex_dir.join("state_5.sqlite")).expect("open state db");
        database
            .execute_batch(
                "CREATE TABLE threads (\
                    id TEXT, title TEXT, tokens_used INTEGER,\
                    thread_source TEXT, first_user_message TEXT\
                );\
                CREATE TABLE thread_spawn_edges (\
                    parent_thread_id TEXT NOT NULL, child_thread_id TEXT NOT NULL\
                );\
                INSERT INTO thread_spawn_edges VALUES ('root-session', 'child-session');\
                INSERT INTO thread_spawn_edges VALUES ('child-session', 'grandchild-session');",
            )
            .expect("seed spawn edges");
        drop(database);
        let path = sessions_dir.join("rollout-grandchild-session.jsonl");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-08-02T06:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"grandchild-session\",\"thread_source\":\"subagent\",\"source\":{\"subagent\":{\"thread_spawn\":{\"parent_thread_id\":\"child-session\",\"agent_path\":\"/root/repair_batch_branch_cleanup\",\"agent_nickname\":\"Helmholtz\"}}}}}\n",
                "{\"timestamp\":\"2026-08-02T06:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":10,\"output_tokens\":2,\"request_count\":1},\"model\":\"gpt-5.6\"}}}\n"
            ),
        )
        .expect("write transcript");

        let metadata = CodexTitleMetadata::load_from_roots(std::slice::from_ref(&sessions_dir));
        let mut item = parse_codex_jsonl_file_with_title_metadata(
            &path,
            "2026-08-02T06:02:00Z",
            "fingerprint".to_string(),
            &metadata,
            None,
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        let origin = item.origin.as_ref().expect("subagent origin");
        assert_eq!(origin.thread_source.as_deref(), Some("subagent"));
        assert_eq!(origin.parent_session_ref.as_deref(), Some("child-session"));
        assert!(item
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "root_session_ref" && fact.value == "root-session" }));
        assert!(item
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "spawn_depth" && fact.value == "2" }));
        assert!(item
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "agent_ref" && fact.value == "grandchild-session" }));
        let agent_kind = item
            .attribution_facts
            .iter()
            .find(|fact| fact.field == "agent_kind")
            .expect("agent kind fact");
        assert_eq!(agent_kind.value, "codex_subagent");
        assert_eq!(
            agent_kind.display_label.as_deref(),
            Some("repair batch branch cleanup")
        );
        assert_eq!(
            agent_kind.display_label_source.as_deref(),
            Some("agent_label")
        );

        let local = item.clone();
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut item),
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                session_attribution_labels_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        assert!(item.attribution_facts.iter().any(|fact| {
            fact.field == "agent_kind"
                && fact.display_label.as_deref() == Some("repair batch branch cleanup")
                && fact.display_label_source.as_deref() == Some("agent_label")
        }));
        for policy in [
            SnapshotUploadPolicy {
                session_titles_enabled: false,
                session_attribution_enabled: true,
                session_attribution_labels_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                session_attribution_labels_enabled: false,
                ..SnapshotUploadPolicy::default()
            },
        ] {
            let mut private = local.clone();
            apply_upload_policy(
                SnapshotSource::Codex,
                std::slice::from_mut(&mut private),
                policy,
            );
            let agent_kind = private
                .attribution_facts
                .iter()
                .find(|fact| fact.field == "agent_kind")
                .expect("agent kind remains as a content-free type fact");
            assert_eq!(agent_kind.display_label, None);
            assert_eq!(agent_kind.display_label_source, None);
        }

        let _ = fs::remove_dir_all(home);
    }

