        let item = parse_codex_jsonl_file(&path, "2026-08-02T07:11:00Z", "fp".to_string())
            .expect("parse")
            .into_iter()
            .next()
            .expect("snapshot");
        let summary = item.activity_summary.as_ref().expect("activity summary");
        assert_eq!(summary.tool_calls, 3);
