    #[test]
    fn repeated_watcher_hints_cannot_starve_bounded_census() {
        let root = temp_dir("bounded-repeated-watcher-hint");
        let fixture = |tokens: u64| {
            format!(
                "{{\"type\":\"message_end\",\"message\":{{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{{\"input\":{tokens},\"output\":1}}}}}}\n"
            )
        };
        let active_path = root.join("a-active.jsonl");
        fs::write(&active_path, fixture(1)).expect("write active fixture");
        fs::write(root.join("b.jsonl"), fixture(2)).expect("write second fixture");
        fs::write(root.join("c.jsonl"), fixture(3)).expect("write third fixture");
        let mut index = ScanIndex::default();

        for tick in 0..3 {
            let scan = scan_source_roots_with_limit_and_attribution(
                SnapshotSource::Pi,
                std::slice::from_ref(&root),
                &mut index,
                &format!("2026-07-31T00:0{tick}:00Z"),
                BACKFILL_WINDOW_DAYS,
                1,
                None,
                None,
                std::slice::from_ref(&active_path),
                false,
            )
            .expect("bounded hinted scan");
            if tick < 2 {
                assert!(!scan.census_complete);
                assert_eq!(scan.census_window_end, "2026-07-31T00:00:00Z");
            } else {
                assert!(scan.census_complete);
                assert!(index.traversal.is_none());
            }
        }
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn rename_hint_removes_old_index_key_despite_repeated_active_hints() {
        let root = temp_dir("bounded-watcher-rename");
        let fixture = |tokens: u64| {
            format!(
                "{{\"type\":\"message_end\",\"message\":{{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{{\"input\":{tokens},\"output\":1}}}}}}\n"
            )
        };
        let old_path = root.join("a-old.jsonl");
        let new_path = root.join("b-new.jsonl");
        let active_path = root.join("c-active.jsonl");
        fs::write(&old_path, fixture(1)).expect("write old fixture");
        fs::write(&active_path, fixture(2)).expect("write active fixture");
        let mut index = ScanIndex::default();

        let initial = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("initial complete scan");
        assert!(initial.census_complete);
        assert!(index.files.contains_key(&local_index_key(&old_path)));

        fs::rename(&old_path, &new_path).expect("rename fixture");
        let initial_hints = vec![old_path.clone(), new_path.clone(), active_path.clone()];
        let mut completed = false;
        for tick in 1..=6 {
            let hints = if tick == 1 {
                initial_hints.as_slice()
            } else {
                std::slice::from_ref(&active_path)
            };
            let mut scan = scan_source_roots_with_limit_and_attribution(
                SnapshotSource::Pi,
                std::slice::from_ref(&root),
                &mut index,
                &format!("2026-07-31T00:0{tick}:00Z"),
                BACKFILL_WINDOW_DAYS,
                1,
                None,
                None,
                hints,
                false,
            )
            .expect("bounded rename scan");
            finalize_scan_after_policy(SnapshotSource::Pi, &mut scan, &mut index);
            assert_eq!(scan.disappeared_file_count, 0);
            if scan.census_complete {
                completed = true;
                break;
            }
        }

        assert!(completed, "rename/remove hint must settle under activity");
        assert!(!index.files.contains_key(&local_index_key(&old_path)));
        assert!(index.files.contains_key(&local_index_key(&new_path)));
        assert!(index.files.contains_key(&local_index_key(&active_path)));
        assert_eq!(index.files.len(), 2);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn late_remove_hint_retires_key_already_passed_by_reconciliation() {
        let root = temp_dir("bounded-watcher-late-remove");
        let fixture = |tokens: u64| {
            format!(
                "{{\"type\":\"message_end\",\"message\":{{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{{\"input\":{tokens},\"output\":1}}}}}}\n"
            )
        };
        let removed_path = root.join("a-removed.jsonl");
        let retained_path = root.join("b-retained.jsonl");
        fs::write(&removed_path, fixture(1)).expect("write removed fixture");
        fs::write(&retained_path, fixture(2)).expect("write retained fixture");
        let mut index = ScanIndex::default();

        let initial = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("initial complete scan");
        assert!(initial.census_complete);

        let removed_key = local_index_key(&removed_path);
        let retained_key = local_index_key(&retained_path);
        ensure_bounded_traversal(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:05:00Z",
            BACKFILL_WINDOW_DAYS,
        );
        let traversal = index.traversal.as_mut().expect("traversal");
        traversal.pending_directories.clear();
        traversal.pending_candidates.clear();
        traversal.observed_index_keys =
            BTreeSet::from([removed_key.clone(), retained_key.clone()]).into();
        traversal.reconciliation_upper_bound = Some(retained_key.clone());
        traversal.reconciliation_after = Some(removed_key.clone());
        traversal.reconciliation_started = true;

        fs::remove_file(&removed_path).expect("remove already-reconciled fixture");
        let scan = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:05:30Z",
            BACKFILL_WINDOW_DAYS,
            1,
            None,
            None,
            std::slice::from_ref(&removed_path),
            false,
        )
        .expect("settle late remove hint");

        assert!(scan.census_complete);
        assert!(!index.files.contains_key(&removed_key));
        assert!(index.files.contains_key(&retained_key));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn watcher_overflow_dirties_generation_and_clean_sweep_repairs_missed_change() {
        let root = temp_dir("bounded-watcher-overflow");
        let first_path = root.join("a.jsonl");
        let second_path = root.join("b.jsonl");
        let fixture = |tokens: u64| {
            format!(
                "{{\"type\":\"message_end\",\"message\":{{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{{\"input\":{tokens},\"output\":1}}}}}}\n"
            )
        };
        fs::write(&first_path, fixture(1)).expect("write first fixture");
        fs::write(&second_path, fixture(2)).expect("write second fixture");
        let mut index = ScanIndex::default();

        let mut first = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:00Z",
            BACKFILL_WINDOW_DAYS,
            1,
            None,
            None,
            &[],
            false,
        )
        .expect("start frozen generation");
        finalize_scan_after_policy(SnapshotSource::Pi, &mut first, &mut index);
        assert!(!first.census_complete);
        assert_eq!(first.snapshots[0].input_tokens, 1);

        // The raw watcher overflow loses this exact path after its directory
        // was already traversed. The overflow witness must prevent the current
        // generation from publishing a terminal manifest.
        fs::write(&first_path, fixture(99)).expect("change already traversed file");
        let mut overflowed = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:30Z",
            BACKFILL_WINDOW_DAYS,
            1,
            None,
            None,
            &[],
            true,
        )
        .expect("finish dirty generation");
        finalize_scan_after_policy(SnapshotSource::Pi, &mut overflowed, &mut index);
        assert!(!overflowed.census_complete);
        assert!(overflowed.scan_cap_hit);
        assert!(index.traversal.is_none());

        let mut repaired = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:01:00Z",
            BACKFILL_WINDOW_DAYS,
            1,
            None,
            None,
            &[],
            false,
        )
        .expect("clean repair generation");
        assert_eq!(repaired.snapshots.len(), 1);
        assert_eq!(repaired.snapshots[0].input_tokens, 99);
        finalize_scan_after_policy(SnapshotSource::Pi, &mut repaired, &mut index);
        assert!(!repaired.census_complete);

        let final_page = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:01:30Z",
            BACKFILL_WINDOW_DAYS,
            1,
            None,
            None,
            &[],
            false,
        )
        .expect("finish clean repair generation");
        assert!(final_page.census_complete);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn unhealthy_generation_retries_with_backoff_while_hints_still_progress() {
        let root = temp_dir("bounded-unhealthy-retry");
        let malformed = root.join("a-malformed.jsonl");
        fs::write(&malformed, "not-json\n").expect("write malformed fixture");
        let mut index = ScanIndex::default();
        let first = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("first unhealthy scan");
        assert_eq!(first.scanned_file_count, 1);
        assert!(!first.census_complete);
        assert!(index.traversal.is_some(), "red witness stays durable");

        let quiet = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:30Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("retry remains backed off");
        assert_eq!(quiet.scanned_file_count, 0);
        assert!(!quiet.census_complete);

        let sibling = root.join("z-healthy.jsonl");
        fs::write(
            &sibling,
            "{\"type\":\"message_end\",\"message\":{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{\"input\":7,\"output\":1}}}\n",
        )
        .expect("write healthy sibling");
        let hinted = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:40Z",
            BACKFILL_WINDOW_DAYS,
            MAX_BACKFILL_FILES_PER_SOURCE,
            None,
            None,
            std::slice::from_ref(&sibling),
            false,
        )
        .expect("healthy hint progresses under red witness");
        assert_eq!(hinted.snapshots.len(), 1);
        assert_eq!(hinted.snapshots[0].input_tokens, 7);
        assert!(!hinted.census_complete);

        let retried = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:01:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("bounded retry becomes due");
        assert_eq!(retried.scanned_file_count, 2);
        assert!(!retried.census_complete);
        let _ = fs::remove_dir_all(root);
    }

    // ---------------------------------------------------------------------
    // Non-progressing census residue and the bounded unhealthy-retry latch.
    // ---------------------------------------------------------------------

    /// A Codex home with both configured roots and a state database. A thread
    /// whose state row declares a provider-created thread while its rollout
    /// carries only a file-controlled pagination marker is ownership-incomplete
    /// with no parent evidence outstanding: the exact shape that re-derives
    /// the same residue on every generation.
    struct CodexResidueFixture {
        home: PathBuf,
        sessions: PathBuf,
        archived: PathBuf,
    }

    impl CodexResidueFixture {
        fn create(name: &str) -> Self {
            let home = temp_dir(name);
            let codex_dir = home.join(".codex");
            let sessions = codex_dir.join("sessions");
            let archived = codex_dir.join("archived_sessions");
            fs::create_dir_all(&sessions).expect("create sessions root");
            fs::create_dir_all(&archived).expect("create archived root");
            Connection::open(codex_dir.join("state_5.sqlite"))
                .expect("open state database")
                .execute_batch(
                    "CREATE TABLE threads (\
                        id TEXT NOT NULL, title TEXT, tokens_used INTEGER NOT NULL,\
                        thread_source TEXT, first_user_message TEXT\
                    );",
                )
                .expect("create threads table");
            Self {
                home,
                sessions,
                archived,
            }
        }

        fn roots(&self) -> Vec<PathBuf> {
            vec![self.sessions.clone(), self.archived.clone()]
        }

        fn insert_thread(&self, session_id: &str, tokens_used: i64, thread_source: &str) {
            Connection::open(self.home.join(".codex").join("state_5.sqlite"))
                .expect("open state database")
                .execute(
                    "INSERT INTO threads VALUES (?1, 'Thread', ?2, ?3, NULL)",
                    rusqlite::params![session_id, tokens_used, thread_source],
                )
                .expect("insert thread row");
        }

        fn set_thread_source(&self, session_id: &str, thread_source: &str) {
            Connection::open(self.home.join(".codex").join("state_5.sqlite"))
                .expect("open state database")
                .execute(
                    "UPDATE threads SET thread_source = ?2 WHERE id = ?1",
                    rusqlite::params![session_id, thread_source],
                )
                .expect("update thread row");
        }

        /// A file-controlled paginated rollout with one usage record. With a
        /// `user` state row it is all-local and yields one entity; with an
        /// `agent_created_thread` state row the two declarations disagree and
        /// the rollout is ownership-incomplete with nothing left to wait for.
        fn write_rollout(&self, root: &Path, session_id: &str, stamp: &str) -> PathBuf {
            let path = root.join(format!("rollout-{stamp}-{session_id}.jsonl"));
            let values = [
                json!({"timestamp":"2026-07-30T11:35:45Z","type":"session_meta","payload":{"id":session_id,"session_id":session_id,"history_mode":"paginated","history_base":{"cursor":"file-controlled"},"source":"cli"}}),
                json!({"timestamp":"2026-07-30T11:35:46Z","type":"turn_context","payload":{"turn_id":"residue-turn","model":"gpt-5.6-sol"}}),
                codex_test_token_line(
                    "2026-07-30T11:35:47Z",
                    None,
                    (30, 8, 12, 1),
                    Some((30, 8, 12, 1)),
                ),
            ];
            fs::write(
                &path,
                values
                    .iter()
                    .map(Value::to_string)
                    .collect::<Vec<_>>()
                    .join("\n")
                    + "\n",
            )
            .expect("write rollout");
            path
        }
    }

    const RESIDUE_SESSION: &str = "019fb22a-0000-7000-8000-000000000001";
    const ACTIVE_RESIDUE_SESSION: &str = "019fb22a-0000-7000-8000-000000000002";
    const HEALTHY_SESSIONS: [&str; 3] = [
        "019fb22b-0000-7000-8000-000000000011",
        "019fb22b-0000-7000-8000-000000000012",
        "019fb22b-0000-7000-8000-000000000013",
    ];

    fn cycle_clock(cycle: u64) -> String {
        format!("2026-09-03T00:{:02}:00Z", 5 * cycle)
    }

    #[test]
    fn non_progressing_residue_settles_only_without_retryable_problems() {
        let residue = ScanTraversalCounts {
            ownership_incomplete_file_count: 1,
            zero_snapshot_usage_evidence_count: 1,
            recognized_usage_drop_count: 1_105,
            dropped_usage_record_count: 1_105,
            ..ScanTraversalCounts::default()
        };
        assert!(residue.has_errors());
        assert!(!residue.has_retryable_problems());
        assert!(residue.has_unsettled_residue());

        // Every retryable class vetoes settlement: a walk that could not
        // enter, open, read or parse something has not proved the residue
        // non-progressing.
        let vetoes: [fn(&mut ScanTraversalCounts); 7] = [
            |counts| counts.symlink_rejected_count = 1,
            |counts| counts.directory_entry_cap_exceeded_count = 1,
            |counts| counts.unreadable_path_count = 1,
            |counts| counts.disappeared_file_count = 1,
            |counts| counts.malformed_json_line_count = 1,
            |counts| counts.invalid_utf8_line_count = 1,
            |counts| counts.over_line_cap_count = 1,
        ];
        for veto in vetoes {
            let mut red = residue.clone();
            veto(&mut red);
            assert!(!red.settle_non_progressing_residue());
            assert!(red.has_errors());
            assert!(red.has_unsettled_residue());
            assert_eq!(red.terminal_ownership_incomplete_file_count, 0);
            assert!(red.settled_residue().is_none());
        }

        let mut settled = residue.clone();
        assert!(settled.settle_non_progressing_residue());
        assert!(!settled.has_errors());
        assert_eq!(
            settled.settled_residue(),
            Some(SettledScanResidue {
                ownership_incomplete_file_count: 1,
                zero_snapshot_usage_evidence_count: 1,
                dropped_usage_record_count: 1_105,
            })
        );
        assert!(
            !settled.settle_non_progressing_residue(),
            "settling is idempotent within a generation"
        );

        // Legacy cap fields no longer subtract from the terminal drop residue.
        let mut with_cap_loss = ScanTraversalCounts {
            over_line_cap_count: 11,
            terminal_over_line_cap_count: 11,
            recognized_usage_drop_count: 11 + 577,
            terminal_recognized_usage_drop_count: 11,
            dropped_usage_record_count: 11 + 577,
            terminal_dropped_usage_record_count: 11,
            ownership_incomplete_file_count: 2,
            zero_snapshot_usage_evidence_count: 1,
            ..ScanTraversalCounts::default()
        };
        assert!(with_cap_loss.settle_non_progressing_residue());
        assert!(!with_cap_loss.has_errors());
        assert_eq!(
            with_cap_loss.settled_residue(),
            Some(SettledScanResidue {
                ownership_incomplete_file_count: 2,
                zero_snapshot_usage_evidence_count: 1,
                dropped_usage_record_count: 588,
            })
        );

        let clean = ScanTraversalCounts::default();
        assert!(!clean.has_errors());
        assert!(clean.settled_residue().is_none());
    }

    /// Residue is settled only once discovery has finished: a page that still
    /// has candidates queued keeps the census red and the counts unsettled.
    #[test]
    fn residue_is_not_settled_while_candidates_are_still_pending() {
        let fixture = CodexResidueFixture::create("codex-residue-pending-candidates");
        fixture.insert_thread(ACTIVE_RESIDUE_SESSION, 577, "agent_created_thread");
        // Sorts before the healthy rollouts so the first bounded page parses it.
        fixture.write_rollout(
            &fixture.sessions,
            ACTIVE_RESIDUE_SESSION,
            "2026-07-30T11-35-45",
        );
        for (position, session_id) in HEALTHY_SESSIONS.iter().take(2).enumerate() {
            fixture.insert_thread(session_id, 40, "user");
            fixture.write_rollout(
                &fixture.sessions,
                session_id,
                &format!("2026-08-2{position}T09-00-00"),
            );
        }
        let roots = fixture.roots();
        let mut index = ScanIndex::default();
        let first = scan_source_roots_with_limit(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            &cycle_clock(0),
            BACKFILL_WINDOW_DAYS,
            1,
        )
        .expect("first bounded page");
        assert_eq!(first.scanned_file_count, 1);
        assert_eq!(first.ownership_incomplete_file_count, 1);
        assert!(!first.census_complete);
        assert!(first.scan_cap_hit);
        let traversal = index
            .traversal
            .as_ref()
            .expect("bounded traversal continues");
        assert!(!traversal.pending_candidates.is_empty());
        assert_eq!(traversal.counts.terminal_ownership_incomplete_file_count, 0);
        assert!(traversal.counts.has_unsettled_residue());
        assert_eq!(
            traversal.unhealthy_retry_attempt, 0,
            "not a retry, just paging"
        );
        assert!(index.scan_residue_witness.is_none());

        let mut last = first;
        for cycle in 1..4 {
            last = scan_source_roots_with_limit(
                SnapshotSource::Codex,
                &roots,
                &mut index,
                &cycle_clock(cycle),
                BACKFILL_WINDOW_DAYS,
                1,
            )
            .expect("later bounded page");
            if last.census_complete {
                break;
            }
        }
        assert!(last.census_complete, "{last:#?}");
        assert!(index.traversal.is_none());
        assert_eq!(
            index
                .scan_residue_witness
                .as_ref()
                .map(|witness| witness.ownership_incomplete_file_count),
            Some(1)
        );
        let _ = fs::remove_dir_all(fixture.home);
    }

    /// A genuine retryable problem beside the residue keeps the census red,
    /// leaves the residue unsettled, and re-arms the bounded latch on the
    /// usual backoff - up to the cap, never past it.
    #[cfg(unix)]
    #[test]
    fn retryable_problem_keeps_the_census_red_and_the_latch_bounded() {
        use std::os::unix::fs::symlink;

        let fixture = CodexResidueFixture::create("codex-residue-with-retryable-problem");
        fixture.insert_thread(RESIDUE_SESSION, 1_105, "agent_created_thread");
        fixture.write_rollout(&fixture.archived, RESIDUE_SESSION, "2026-07-30T11-35-45");
        fixture.insert_thread(HEALTHY_SESSIONS[0], 40, "user");
        fixture.write_rollout(
            &fixture.sessions,
            HEALTHY_SESSIONS[0],
            "2026-08-20T09-00-00",
        );
        let outside = temp_dir("codex-residue-symlink-target");
        symlink(&outside, fixture.sessions.join("escape")).expect("create directory symlink");
        let roots = fixture.roots();
        let mut index = ScanIndex::default();

        let started = "2026-09-03T00:00:00Z";
        let first = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            started,
            BACKFILL_WINDOW_DAYS,
        )
        .expect("first unhealthy generation");
        assert_eq!(first.symlink_rejected_count, 1);
        // The rejected directory prevents proving that either physical file is
        // the whole logical session, so both remain held before a replacement.
        assert_eq!(first.ownership_incomplete_file_count, 2);
        assert!(first.snapshots.is_empty());
        assert!(!first.census_complete);
        assert!(first.scan_cap_hit);
        assert!(index.scan_residue_witness.is_none());
        // The receipt-facing view of the same veto: the loss is disclosed,
        // none of it is terminal, and no witness counts describe this scan.
        assert_eq!(first.terminal_ownership_incomplete_file_count, 0);
        assert_eq!(first.terminal_dropped_usage_record_count, 0);
        assert_eq!(first.census_residue_index_key_count, 0);
        assert_eq!(first.census_residue_archived_rollout_count, 0);
        let now = rfc3339_unix_seconds(started).expect("fixture clock");
        {
            let traversal = index.traversal.as_ref().expect("red witness stays durable");
            assert_eq!(traversal.counts.terminal_ownership_incomplete_file_count, 0);
            assert!(traversal.counts.has_retryable_problems());
            assert_eq!(traversal.unhealthy_retry_attempt, 1);
            assert_eq!(
                traversal.unhealthy_retry_not_before_unix_seconds,
                Some(now + 60)
            );
        }

        let quiet = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            "2026-09-03T00:00:30Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("retry not yet due");
        assert_eq!(quiet.scanned_file_count, 0);
        assert!(!quiet.census_complete);
        assert_eq!(
            index
                .traversal
                .as_ref()
                .map(|traversal| traversal.unhealthy_retry_attempt),
            Some(1)
        );

        // Each due retry re-walks, stays red, and re-arms on the next delay;
        // the attempt saturates at the cap and the delay at one hour.
        let expected_attempts = [2_u8, 3, 4, 5, 6, 7, 7, 7, 7];
        for expected in expected_attempts {
            let deadline = index
                .traversal
                .as_ref()
                .and_then(|traversal| traversal.unhealthy_retry_not_before_unix_seconds)
                .expect("an unhealthy traversal always carries a deadline");
            let collected_at = OffsetDateTime::from_unix_timestamp(deadline as i64)
                .expect("deadline")
                .format(&Rfc3339)
                .expect("format");
            let retried = scan_source_roots(
                SnapshotSource::Codex,
                &roots,
                &mut index,
                &collected_at,
                BACKFILL_WINDOW_DAYS,
            )
            .expect("due retry");
            assert!(!retried.census_complete);
            assert_eq!(retried.symlink_rejected_count, 1);
            let traversal = index.traversal.as_ref().expect("still red");
            assert_eq!(
                traversal.census_window_end, collected_at,
                "the retry re-walked"
            );
            assert_eq!(traversal.unhealthy_retry_attempt, expected);
            assert!(traversal.unhealthy_retry_attempt <= UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS);
            let next = traversal
                .unhealthy_retry_not_before_unix_seconds
                .expect("re-armed");
            assert_eq!(
                next,
                deadline + unhealthy_scan_retry_delay_seconds(expected)
            );
            assert!(next <= deadline + UNHEALTHY_SCAN_RETRY_MAX_SECONDS);
        }
        assert_eq!(
            unhealthy_scan_retry_delay_seconds(7),
            UNHEALTHY_SCAN_RETRY_MAX_SECONDS
        );

        // Removing the retryable problem lets the next due retry settle the
        // residue and complete.
        fs::remove_file(fixture.sessions.join("escape")).expect("remove symlink");
        let deadline = index
            .traversal
            .as_ref()
            .and_then(|traversal| traversal.unhealthy_retry_not_before_unix_seconds)
            .expect("deadline");
        let collected_at = OffsetDateTime::from_unix_timestamp(deadline as i64)
            .expect("deadline")
            .format(&Rfc3339)
            .expect("format");
        let repaired = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            &collected_at,
            BACKFILL_WINDOW_DAYS,
        )
        .expect("repaired generation");
        assert!(repaired.census_complete, "{repaired:#?}");
        assert_eq!(repaired.ownership_incomplete_file_count, 1);
        assert!(index.traversal.is_none());
        assert_eq!(
            index
                .scan_residue_witness
                .as_ref()
                .map(|witness| witness.archived_residue_file_count()),
            Some(1)
        );
        let _ = fs::remove_dir_all(fixture.home);
        let _ = fs::remove_dir_all(outside);
    }

    /// The dormant-slot shape - attempt 46 with a deadline fifteen hours stale -
    /// is retried immediately and clamped to the cap, and a persisted witness
    /// with no deadline at all (written before the deadline existed) is due
    /// now rather than fenced forever.
    #[cfg(unix)]
    #[test]
    fn unhealthy_retry_latch_saturates_at_its_cap_and_a_missing_deadline_is_due_now() {
        use std::os::unix::fs::symlink;

        let root = temp_dir("latch-cap-root");
        let outside = temp_dir("latch-cap-outside");
        symlink(&outside, root.join("escape")).expect("create directory symlink");
        fs::write(
            root.join("session.jsonl"),
            "{\"type\":\"message_end\",\"message\":{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{\"input\":3,\"output\":1}}}\n",
        )
        .expect("write healthy transcript");
        let roots = vec![root.clone()];
        let mut index = ScanIndex::default();
        let started = "2026-09-03T00:00:00Z";
        let now = rfc3339_unix_seconds(started).expect("fixture clock");
        let stale_witness =
            |_: &ScanIndex, attempt: u8, deadline: Option<u64>| ScanTraversalCheckpoint {
                context_fingerprint: scan_traversal_context_fingerprint(
                    SnapshotSource::Pi,
                    &roots,
                    BACKFILL_WINDOW_DAYS,
                ),
                census_window_end: "2026-09-02T09:00:00Z".to_string(),
                scan_roots: Vec::new(),
                pending_directories: VecDeque::new(),
                pending_candidates: VecDeque::new(),
                observed_index_keys: Default::default(),

                oversized_discovery: Default::default(),

                codex_rollout_paths: BTreeSet::new(),
                codex_join_directory_census: None,
                reconciliation_upper_bound: None,
                reconciliation_after: None,
                reconciliation_started: false,
                watcher_hint_seen: false,
                codex_freshness_yield: false,
                retired_codex_parent_resolution_retry_required: serde::de::IgnoredAny,
                unhealthy_retry_attempt: attempt,
                unhealthy_retry_not_before_unix_seconds: deadline,
                counts: ScanTraversalCounts {
                    symlink_rejected_count: 1,
                    ..ScanTraversalCounts::default()
                },
                residue: ScanTraversalResidue::default(),
                listing_started_unix_seconds: None,
                listing_owed_requeued_unix_seconds: Default::default(),
            };

        index.traversal = Some(stale_witness(&index, 46, Some(now - 15 * 60 * 60)));
        let scan = scan_source_roots(
            SnapshotSource::Pi,
            &roots,
            &mut index,
            started,
            BACKFILL_WINDOW_DAYS,
        )
        .expect("stale deadline is due now");
        assert!(!scan.census_complete);
        assert_eq!(scan.scanned_file_count, 1, "the retry re-walked the root");
        let traversal = index.traversal.as_ref().expect("still red");
        assert_eq!(traversal.census_window_end, started);
        assert_eq!(
            traversal.unhealthy_retry_attempt,
            UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS
        );
        assert_eq!(
            traversal.unhealthy_retry_not_before_unix_seconds,
            Some(now + UNHEALTHY_SCAN_RETRY_MAX_SECONDS)
        );

        for hour in 1..4_u64 {
            let collected_at = OffsetDateTime::from_unix_timestamp(
                (now + hour * UNHEALTHY_SCAN_RETRY_MAX_SECONDS) as i64,
            )
            .expect("clock")
            .format(&Rfc3339)
            .expect("format");
            let scan = scan_source_roots(
                SnapshotSource::Pi,
                &roots,
                &mut index,
                &collected_at,
                BACKFILL_WINDOW_DAYS,
            )
            .expect("hourly retry");
            assert!(!scan.census_complete);
            let traversal = index.traversal.as_ref().expect("still red");
            assert_eq!(traversal.census_window_end, collected_at);
            assert_eq!(
                traversal.unhealthy_retry_attempt,
                UNHEALTHY_SCAN_RETRY_MAX_ATTEMPTS
            );
            assert_eq!(
                traversal.unhealthy_retry_not_before_unix_seconds,
                Some(now + (hour + 1) * UNHEALTHY_SCAN_RETRY_MAX_SECONDS)
            );
        }

        // No deadline at all: due now, and the counter resumes from where the
        // persisted witness left it.
        index.traversal = Some(stale_witness(&index, 3, None));
        let later = "2026-09-03T06:00:00Z";
        let scan = scan_source_roots(
            SnapshotSource::Pi,
            &roots,
            &mut index,
            later,
            BACKFILL_WINDOW_DAYS,
        )
        .expect("missing deadline is due now");
        assert!(!scan.census_complete);
        let traversal = index.traversal.as_ref().expect("still red");
        assert_eq!(traversal.census_window_end, later, "the retry re-walked");
        assert_eq!(traversal.unhealthy_retry_attempt, 4);
        assert_eq!(
            traversal.unhealthy_retry_not_before_unix_seconds,
            Some(rfc3339_unix_seconds(later).expect("clock") + 480)
        );

        // The latch clears with the problem: the next due retry completes and
        // drops the traversal, so a fresh generation starts at zero.
        fs::remove_file(root.join("escape")).expect("remove symlink");
        let scan = scan_source_roots(
            SnapshotSource::Pi,
            &roots,
            &mut index,
            "2026-09-03T06:08:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("repaired generation");
        assert!(scan.census_complete);
        assert!(index.traversal.is_none());
        let _ = fs::remove_dir_all(root);
        let _ = fs::remove_dir_all(outside);
    }

    /// Residue rollouts under the archived root and under the active root are
    /// handled alike: the witness names which of them sits under an archived
    /// root, and a state row without a rollout emits nothing even once the
    /// census completes.
    #[test]
    fn archived_and_active_residue_is_witnessed_and_state_rows_emit_nothing() {
        let fixture = CodexResidueFixture::create("codex-residue-archived-and-active");
        fixture.insert_thread(RESIDUE_SESSION, 1_105, "agent_created_thread");
        let archived_path =
            fixture.write_rollout(&fixture.archived, RESIDUE_SESSION, "2026-07-30T11-35-45");
        fixture.insert_thread(ACTIVE_RESIDUE_SESSION, 900, "agent_created_thread");
        let active_path = fixture.write_rollout(
            &fixture.sessions,
            ACTIVE_RESIDUE_SESSION,
            "2026-08-01T08-00-00",
        );
        let state_only = "019fb22c-0000-7000-8000-000000000077";
        fixture.insert_thread(state_only, 77, "user");
        fixture.insert_thread(HEALTHY_SESSIONS[0], 40, "user");
        fixture.write_rollout(
            &fixture.sessions,
            HEALTHY_SESSIONS[0],
            "2026-08-20T09-00-00",
        );
        let roots = fixture.roots();
        let mut index = ScanIndex::default();

        let scan = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            &cycle_clock(0),
            BACKFILL_WINDOW_DAYS,
        )
        .expect("scan archived and active residue");
        assert!(scan.census_complete, "{scan:#?}");
        assert_eq!(scan.ownership_incomplete_file_count, 2);
        // What the terminal receipt will read off this scan: every disclosed
        // loss class equals its settled counterpart, and the witness is
        // reported as counts only (two residue keys, one under an archived
        // root).
        assert_eq!(scan.terminal_ownership_incomplete_file_count, 2);
        assert_eq!(
            scan.terminal_zero_snapshot_usage_evidence_count,
            scan.zero_snapshot_usage_evidence_count
        );
        assert_eq!(
            scan.terminal_recognized_usage_drop_count,
            scan.recognized_usage_drop_count
        );
        assert_eq!(
            scan.terminal_dropped_usage_record_count,
            scan.dropped_usage_record_count
        );
        assert_eq!(scan.terminal_over_line_cap_count, scan.over_line_cap_count);
        assert_eq!(scan.census_residue_index_key_count, 2);
        assert_eq!(scan.census_residue_archived_rollout_count, 1);
        let emitted = scan
            .snapshots
            .iter()
            .map(|snapshot| snapshot.source_session_id.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            emitted,
            BTreeSet::from([HEALTHY_SESSIONS[0]]),
            "the file-backed entity only; {state_only} has no rollout"
        );
        let witness = index.scan_residue_witness.clone().expect("residue witness");
        assert_eq!(witness.ownership_incomplete_file_count, 2);
        assert_eq!(
            witness.index_keys,
            BTreeSet::from([
                local_index_key(&archived_path),
                local_index_key(&active_path)
            ])
        );
        assert_eq!(witness.archived_residue_file_count(), 1);

        // The witness survives a round trip and an unchanged generation.
        let persisted = serde_json::to_vec(&index).expect("serialize index");
        let mut index: ScanIndex = serde_json::from_slice(&persisted).expect("restore index");
        assert_eq!(index.scan_residue_witness.as_ref(), Some(&witness));
        let again = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            &cycle_clock(1),
            BACKFILL_WINDOW_DAYS,
        )
        .expect("unchanged generation");
        assert!(again.census_complete);
        assert_eq!(again.ownership_incomplete_file_count, 2);
        assert!(index
            .scan_residue_witness
            .as_ref()
            .is_some_and(|next| next.same_residue(&witness)));

        // New input - the state rows stop declaring provider-created threads -
        // re-derives both files as ordinary all-local rollouts and clears the
        // witness. Nothing about the earlier settlement had to be undone.
        fixture.set_thread_source(RESIDUE_SESSION, "user");
        fixture.set_thread_source(ACTIVE_RESIDUE_SESSION, "user");
        let resolved = scan_source_roots(
            SnapshotSource::Codex,
            &roots,
            &mut index,
            &cycle_clock(2),
            BACKFILL_WINDOW_DAYS,
        )
        .expect("resolved generation");
        assert!(resolved.census_complete, "{resolved:#?}");
        assert_eq!(resolved.ownership_incomplete_file_count, 0);
        assert_eq!(resolved.dropped_usage_record_count, 0);
        // A clean census reports no settled share and no witness counts.
        assert_eq!(resolved.terminal_ownership_incomplete_file_count, 0);
        assert_eq!(resolved.terminal_dropped_usage_record_count, 0);
        assert_eq!(resolved.census_residue_index_key_count, 0);
        assert_eq!(resolved.census_residue_archived_rollout_count, 0);
        let emitted = resolved
            .snapshots
            .iter()
            .map(|snapshot| snapshot.source_session_id.as_str())
            .collect::<BTreeSet<_>>();
        assert!(emitted.contains(RESIDUE_SESSION));
        assert!(emitted.contains(ACTIVE_RESIDUE_SESSION));
        assert!(index.scan_residue_witness.is_none());
        let _ = fs::remove_dir_all(fixture.home);
    }

    #[test]
    fn periodic_scan_discovers_root_created_after_watcher_startup() {
        let parent = temp_dir("late-scan-root-parent");
        let root = parent.join("sessions-created-later");
        let mut index = ScanIndex::default();
        let (absent, disappearance_events) = disappearance_diagnostics::observe(|| {
            scan_source_roots(
                SnapshotSource::Pi,
                std::slice::from_ref(&root),
                &mut index,
                "2026-07-31T00:00:00Z",
                BACKFILL_WINDOW_DAYS,
            )
            .expect("missing optional root is complete-empty")
        });
        assert_eq!(disappearance_events, [[0; 4], [0; 4], [0, 0, 0, 0]]);
        assert!(absent.census_complete);
        assert!(index.known_configured_scan_roots.is_empty());

        fs::create_dir_all(&root).expect("create root after watcher startup");
        fs::write(
            root.join("session.jsonl"),
            "{\"type\":\"message_end\",\"message\":{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{\"input\":3,\"output\":1}}}\n",
        )
        .expect("write late session");
        let found = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:05:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("periodic scan finds late root");
        assert!(found.census_complete);
        assert_eq!(found.snapshots.len(), 1);
        assert!(index
            .known_configured_scan_roots
            .contains(&local_index_key(&root)));
        let _ = fs::remove_dir_all(parent);
    }

    #[test]
    fn previously_observed_root_disappearance_fails_red_until_root_returns() {
        let parent = temp_dir("disappearing-scan-root-parent");
        let root = parent.join("sessions");
        fs::create_dir_all(&root).expect("create observed root");
        fs::write(
            root.join("session.jsonl"),
            "{\"type\":\"message_end\",\"message\":{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{\"input\":3,\"output\":1}}}\n",
        )
        .expect("write observed entity");
        let mut index = ScanIndex::default();
        let first = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:00:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("observe configured root");
        assert!(first.census_complete);
        assert_eq!(index.files.len(), 1);

        let authoritative_files = serde_json::to_vec(&index.files).unwrap();
        fs::remove_dir_all(&root).expect("temporarily remove configured root");
        let (missing, disappearance_events) = disappearance_diagnostics::observe(|| {
            scan_source_roots(
                SnapshotSource::Pi,
                std::slice::from_ref(&root),
                &mut index,
                "2026-07-31T00:05:00Z",
                BACKFILL_WINDOW_DAYS,
            )
            .expect("missing root is a source-local red witness")
        });
        assert_eq!(disappearance_events, [[0; 4], [0; 4], [0, 1, 0, 0]]);
        assert_eq!(
            serde_json::to_vec(&index.files).unwrap(),
            authoritative_files,
            "missing-root diagnostics preserve prior authoritative entries byte-for-byte"
        );
        assert!(!missing.census_complete);
        assert_eq!(missing.disappeared_file_count, 1);
        assert_eq!(index.files.len(), 1, "prior entities remain authoritative");

        fs::create_dir_all(&root).expect("restore configured root empty");
        let restored = scan_source_roots(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-31T00:06:00Z",
            BACKFILL_WINDOW_DAYS,
        )
        .expect("restored root converges through a fresh complete census");
        assert!(restored.census_complete);
        assert!(index.files.is_empty());
        let _ = fs::remove_dir_all(parent);
    }

    #[test]
    fn bounded_reader_step_io_error_cannot_resume_a_partial_line() {
        struct FailingReader {
            data: &'static [u8],
            offset: usize,
            fail_after: usize,
            fills: usize,
            kind: std::io::ErrorKind,
        }
        impl std::io::Read for FailingReader {
            fn read(&mut self, out: &mut [u8]) -> std::io::Result<usize> {
                let bytes = self.fill_buf()?;
                let n = bytes.len().min(out.len());
                out[..n].copy_from_slice(&bytes[..n]);
                self.consume(n);
                Ok(n)
            }
        }
        impl std::io::BufRead for FailingReader {
            fn fill_buf(&mut self) -> std::io::Result<&[u8]> {
                self.fills += 1;
                if self.offset >= self.fail_after {
                    return Err(std::io::Error::new(self.kind, "injected read failure"));
                }
                Ok(&self.data[self.offset..self.fail_after.min(self.data.len())])
            }
            fn consume(&mut self, n: usize) {
                self.offset += n;
            }
        }
        for fail_after in [0, 2] {
            for kind in [std::io::ErrorKind::Interrupted, std::io::ErrorKind::Other] {
                let mut reader = BoundedJsonlReader::new(FailingReader {
                    data: b"{\"n\":1}\n",
                    offset: 0,
                    fail_after,
                    fills: 0,
                    kind,
                });
                assert_eq!(
                    reader
                        .step(|_| panic!("incomplete line"))
                        .unwrap_err()
                        .kind(),
                    kind
                );
                let fills = reader.reader.fills;
                assert!(reader.buf.is_empty());
                assert_eq!(reader.report, JsonlReadReport::default());
                for _ in 0..2 {
                    assert_eq!(
                        reader
                            .step(|_| panic!("error must not replay"))
                            .unwrap_err()
                            .kind(),
                        kind
                    );
                    assert_eq!(
                        reader.reader.fills, fills,
                        "failed reader must not read suffix"
                    );
                }
            }
        }
    }

    #[test]
    fn bounded_traversal_and_watcher_keep_frozen_age_scope() {
        for hinted in [false, true] {
            let root = temp_dir("bounded-watcher-age-cutoff");
            let path = root.join("session.jsonl");
            fs::write(
            &path,
            "{\"type\":\"message_end\",\"message\":{\"model\":\"gpt-5.4\",\"timestamp\":1784707201000,\"usage\":{\"input\":1,\"output\":1}}}\n",
        )
        .expect("write watcher age-cutoff fixture");
            let future_boundary = (OffsetDateTime::now_utc() + time::Duration::days(365))
                .format(&Rfc3339)
                .expect("format future frozen boundary");
            let mut index = ScanIndex::default();

            let scan = scan_source_roots_with_limit_and_attribution(
                SnapshotSource::Pi,
                std::slice::from_ref(&root),
                &mut index,
                &future_boundary,
                1,
                1,
                None,
                None,
                if hinted {
                    std::slice::from_ref(&path)
                } else {
                    &[]
                },
                false,
            )
            .expect("scan out-of-scope watcher hint");

            assert!(scan.census_complete);
            assert_eq!(scan.discovered_file_count, 0);
            assert!(scan.snapshots.is_empty());
            assert!(index.files.is_empty());
            let _ = fs::remove_dir_all(root);
        }
    }

    #[test]
    fn every_lossy_line_class_is_quarantined_or_terminally_disclosed() {
        {
            let session = "{\"type\":\"session\",\"session_id\":\"019e2700-1111-7000-9000-111111111111\",\"cwd\":\"/tmp/ottto\",\"timestamp\":\"2026-07-22T08:00:00Z\"}\n";
            let usage = "{\"type\":\"message_end\",\"message\":{\"provider\":\"openai\",\"model\":\"gpt-5.4\",\"api\":\"responses\",\"timestamp\":1784707201000,\"usage\":{\"input\":12,\"output\":4,\"cacheRead\":0,\"cacheWrite\":0}}}\n";
            let cases = ["invalid-utf8", "recognized-drop"];
            for case in cases {
                let root = temp_dir(case);
                let path = root.join("session.jsonl");
                let mut bytes = format!("{session}{usage}").into_bytes();
                match case {
                "invalid-utf8" => bytes.extend_from_slice(&[0xff, b'\n']),
                "recognized-drop" => bytes.extend_from_slice(
                    b"{\"type\":\"message_end\",\"message\":{\"usage\":{\"input\":\"invalid\"}}}\n",
                ),
                _ => unreachable!(),
            }
                fs::write(&path, bytes).expect("write lossy fixture");
                let mut index = ScanIndex::default();
                let scan = scan_source_roots_with_limit(
                    SnapshotSource::Pi,
                    std::slice::from_ref(&root),
                    &mut index,
                    "2026-07-22T08:02:00Z",
                    BACKFILL_WINDOW_DAYS,
                    MAX_BACKFILL_FILES_PER_SOURCE,
                )
                .expect("lossy file is isolated");
                match case {
                    "invalid-utf8" => {
                        assert!(!scan.census_complete, "{case}");
                        assert_eq!(scan.snapshots.len(), 1, "{case}");
                        assert_eq!(
                            (
                                scan.snapshots[0].input_tokens,
                                scan.snapshots[0].output_tokens
                            ),
                            (12, 4)
                        );
                        assert_eq!(index.files.len(), 1, "{case}");
                        assert_eq!(scan.invalid_utf8_line_count, 1);
                    }
                    "recognized-drop" => {
                        // Discarded records do not withhold healthy siblings.
                        assert!(scan.census_complete, "{case}");
                        assert_eq!(scan.snapshots.len(), 1, "{case}");
                        assert_eq!(
                            (
                                scan.snapshots[0].input_tokens,
                                scan.snapshots[0].output_tokens
                            ),
                            (12, 4)
                        );
                        assert_eq!(index.files.len(), 1, "{case}");
                        assert_eq!(scan.recognized_usage_drop_count, 1);
                    }
                    _ => unreachable!(),
                }
                let _ = fs::remove_dir_all(root);
            }
        };
    }

    /// [format] Historical terminal dispositions retire with moved or deleted files.
    #[test]
    fn terminal_dispositions_are_pruned_when_their_file_moves_or_disappears() {
        {
            let source = SnapshotSource::ClaudeCode;
            let root = temp_dir("terminal-disposition-prune");
            let original = root.join("session-a.jsonl");
            let moved = root.join("session-b.jsonl");
            fs::write(&original, "{\"type\":\"assistant\",\"sessionId\":\"historical-loss\",\"timestamp\":\"2026-07-22T08:00:01Z\",\"message\":{\"id\":\"m1\",\"model\":\"fixture-model\",\"usage\":{\"input_tokens\":12,\"output_tokens\":4}}}\n").unwrap();

            let traverse = |index: &mut ScanIndex, at: &str| {
                let mut result = scan_source_roots_with_limit(
                    source,
                    std::slice::from_ref(&root),
                    index,
                    at,
                    BACKFILL_WINDOW_DAYS,
                    MAX_BACKFILL_FILES_PER_SOURCE,
                )
                .expect("traversal completes");
                assert!(result.census_complete);
                finalize_scan_after_policy(source, &mut result, index);
                result
            };

            let mut index = ScanIndex::default();
            let first = traverse(&mut index, "2026-07-22T08:02:00Z");
            assert_eq!(first.scanned_file_count, 1);
            assert_eq!(first.over_line_cap_count, 0);
            let key = local_index_key(&original);
            let historical: TerminalJsonlDisposition = serde_json::from_value(json!({
                "source_file_fingerprint": index.files[&key].source_file_fingerprint,
                "parser_generation": "bounded_jsonl_terminal:v1:max_line_bytes=16777216",
                "loss": {"over_line_cap_count":1,"recognized_usage_drop_count":1,"dropped_usage_record_count":1}
            })).unwrap();
            index
                .terminal_jsonl_dispositions
                .insert(key, historical.clone());
            assert_eq!(index.terminal_jsonl_dispositions.len(), 1);
            assert!(index
                .terminal_jsonl_dispositions
                .contains_key(&local_index_key(&original)));

            // Moved path: the same bytes are a new object. The new key is recorded
            // and the old key must NOT be carried forward beside it.
            fs::rename(&original, &moved).expect("rename terminal fixture");
            let after_move = traverse(&mut index, "2026-07-22T08:07:00Z");
            assert_eq!(
                after_move.scanned_file_count, 1,
                "moved object is read once"
            );
            assert_eq!(
                after_move.over_line_cap_count, 0,
                "a new path has no new size loss"
            );
            assert!(
                index.terminal_jsonl_dispositions.is_empty(),
                "renamed-away history is pruned"
            );
            let moved_key = local_index_key(&moved);
            index.terminal_jsonl_dispositions.insert(
                moved_key.clone(),
                TerminalJsonlDisposition {
                    source_file_fingerprint: index.files[&moved_key]
                        .source_file_fingerprint
                        .clone(),
                    ..historical
                },
            );
            assert_eq!(index.files.len(), 1);

            // Deleted path: nothing indexed corresponds to the disposition at all.
            fs::remove_file(&moved).expect("remove terminal fixture");
            let after_delete = traverse(&mut index, "2026-07-22T08:12:00Z");
            assert_eq!(after_delete.scanned_file_count, 0);
            assert!(
                index.terminal_jsonl_dispositions.is_empty(),
                "a deleted file leaves no durable disposition behind"
            );
            assert!(index.files.is_empty());
            let _ = fs::remove_dir_all(root);
        };
    }

    #[test]
    fn lossy_file_has_no_finalization_side_effects_while_healthy_sibling_progresses() {
        let root = temp_dir("scan-lossy-with-healthy-sibling");
        let valid_session = |session_id: &str| {
            format!(
                concat!(
                    "{{\"type\":\"session\",\"session_id\":\"{}\",\"cwd\":\"/tmp/ottto\",\"timestamp\":\"2026-07-22T08:00:00Z\"}}\n",
                    "{{\"type\":\"message_end\",\"message\":{{\"provider\":\"openai\",\"model\":\"gpt-5.4\",\"api\":\"responses\",\"timestamp\":1784707201000,\"usage\":{{\"input\":12,\"output\":4,\"cacheRead\":0,\"cacheWrite\":0}}}}}}\n"
                ),
                session_id
            )
        };
        fs::write(
            root.join("a-healthy.jsonl"),
            valid_session("019e2700-1111-7000-9000-111111111111"),
        )
        .expect("write healthy sibling");
        fs::write(
            root.join("b-lossy.jsonl"),
            format!(
                "{}this is not valid json\n",
                valid_session("019e2700-2222-7000-9000-222222222222")
            ),
        )
        .expect("write lossy sibling");

        let mut index = ScanIndex::default();
        let mut scan = scan_source_roots_with_limit(
            SnapshotSource::Pi,
            std::slice::from_ref(&root),
            &mut index,
            "2026-07-22T08:02:00Z",
            BACKFILL_WINDOW_DAYS,
            MAX_BACKFILL_FILES_PER_SOURCE,
        )
        .expect("lossy sibling is isolated");
        assert!(!scan.census_complete);
        assert_eq!(scan.snapshots.len(), 2);
        assert_eq!(index.files.len(), 2);
        assert_eq!(index.file_snapshot_fingerprints.len(), 0);

        finalize_scan_after_policy(SnapshotSource::Pi, &mut scan, &mut index);
        assert_eq!(scan.snapshots.len(), 2);
        assert_eq!(index.files.len(), 2);
        assert_eq!(index.file_snapshot_fingerprints.len(), 2);
        assert_eq!(index.snapshot_activity_at.len(), 2);
        assert!(scan
            .snapshots
            .iter()
            .all(|item| (item.input_tokens, item.output_tokens) == (12, 4)));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_parser_extracts_current_jsonl_shape_without_prompts() {
        let path = temp_file("codex");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-05-06T10:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"019dfb9a-1f58-7580-afe7-e8d4f969b0f7\"}}\n",
                "{\"timestamp\":\"2026-05-06T10:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"thread_name_updated\",\"thread_id\":\"019dfb9a-1f58-7580-afe7-e8d4f969b0f7\",\"thread_name\":\"Improve sessions UI\"}}\n",
                "{\"timestamp\":\"2026-05-06T10:02:00Z\",\"type\":\"turn_context\",\"payload\":{\"model\":\"gpt-5.5\",\"cwd\":\"/Users/example/work\"}}\n",
                "{\"timestamp\":\"2026-05-06T10:03:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"reasoning_effort\":\"high\",\"total_token_usage\":{\"input_tokens\":100,\"cached_input_tokens\":40,\"output_tokens\":25,\"reasoning_output_tokens\":7,\"request_count\":3},\"model_context_window\":258400},\"rate_limits\":{\"limit_id\":\"codex\"}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_codex_jsonl_file(
            &path,
            "2026-05-06T10:04:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(
            item.source_session_id,
            "019dfb9a-1f58-7580-afe7-e8d4f969b0f7"
        );
        assert_eq!(
            item.session_display_name.as_deref(),
            Some("Improve sessions UI")
        );
        assert_eq!(item.input_tokens, 100);
        assert_eq!(item.cache_read_tokens, 40);
        assert_eq!(item.output_tokens, 25);
        assert_eq!(item.reasoning_output_tokens, 7);
        assert_eq!(item.request_count, 3);
        assert_eq!(item.usage_buckets.len(), 1);
        let bucket = &item.usage_buckets[0];
        assert_eq!(bucket.bucket_start, "2026-05-06T10:00:00Z");
        assert_eq!(
            bucket.first_activity_at.as_deref(),
            Some("2026-05-06T10:03:00Z")
        );
        assert_eq!(
            bucket.last_activity_at.as_deref(),
            Some("2026-05-06T10:03:00Z")
        );
        assert_eq!(bucket.model_usage.len(), 1);
        assert_eq!(bucket.model_usage[0].request_count, 3);
        assert_eq!(item.model_usage[0].model, "gpt-5.5");
        // Per-turn reasoning effort tier rides on the model_usage row (item-level
        // aggregate and per-bucket row both carry it).
        assert_eq!(
            item.model_usage[0].reasoning_effort.as_deref(),
            Some("high")
        );
        assert_eq!(
            bucket.model_usage[0].reasoning_effort.as_deref(),
            Some("high")
        );
        assert_eq!(
            item.provenance.input_token_scope.as_deref(),
            Some("inclusive_cached")
        );
        assert!(item.workspace_hash.is_some());

        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_parser_origin_wire_variants() {
        for (source, originator, role) in [
            ("vscode", Some("Codex Desktop"), Some("explorer")),
            ("exec", Some("codex_work_desktop"), None),
            ("cli", None, None),
        ] {
            let path = temp_file("codex-origin");
            let mut payload =
                json!({"id":"019dfb9a-origin-codex", "source":source, "thread_source":"user"});
            if let Some(value) = originator {
                payload["originator"] = json!(value);
            }
            if let Some(value) = role {
                payload["agent_role"] = json!(value);
            }
            fs::write(&path, [json!({"timestamp":"2026-07-21T10:00:00Z","type":"session_meta","payload":payload}), json!({"timestamp":"2026-07-21T10:03:00Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":10,"output_tokens":5,"request_count":1},"model":"gpt-5.5"}}})].into_iter().map(|l|l.to_string()).collect::<Vec<_>>().join("\n")).unwrap();
            let item = parse_codex_jsonl_file(&path, "2026-07-21T10:04:00Z", "fp".into())
                .unwrap()
                .remove(0);
            let origin = item.origin.as_ref().unwrap();
            assert_eq!(origin.thread_source.as_deref(), Some("user"));
            assert_eq!(origin.source.as_deref(), Some(source));
            assert_eq!(origin.originator.as_deref(), originator);
            assert_eq!(origin.agent_role.as_deref(), role);
            assert_eq!(origin.source_subagent, None);
            assert_eq!(item.originator.as_deref(), originator);
            let wire = serde_json::to_value(&item).unwrap();
            assert_eq!(
                wire.get("originator"),
                originator.map(|value| json!(value)).as_ref()
            );
            if role.is_some() {
                assert!(item
                    .attribution_facts
                    .iter()
                    .any(|f| f.field == "provider_surface" && f.value == "codex_desktop"));
                assert!(!item
                    .attribution_facts
                    .iter()
                    .any(|f| f.value == "vscode" || f.field == "origin_kind"));
            }
            let _ = fs::remove_file(path);
        }
    }

    #[test]
    fn codex_parser_emits_direct_scheduled_and_parent_subagent_facts() {
        let automation_path = temp_file("codex-automation-attribution");
        fs::write(
            &automation_path,
            concat!(
                "{\"timestamp\":\"2026-07-19T10:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"automation-session\",\"source\":\"app_server\",\"originator\":\"Codex Desktop\",\"thread_source\":\"automation\"}}\n",
                "{\"timestamp\":\"2026-07-19T10:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":10,\"output_tokens\":5,\"request_count\":1},\"model\":\"gpt-5.6-sol\"}}}\n"
            ),
        )
        .expect("write automation fixture");
        let mut automation = parse_codex_jsonl_file(
            &automation_path,
            "2026-07-19T10:04:00Z",
            "fp-automation".to_string(),
        )
        .expect("parse automation")
        .into_iter()
        .next()
        .expect("automation snapshot");
        assert!(automation.attribution_facts.iter().any(|fact| {
            fact.field == "origin_kind" && fact.value == "provider_scheduled_task"
        }));
        assert!(automation
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "scheduler_kind" && fact.value == "codex_scheduled" }));
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut automation),
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        let automation_wire = serde_json::to_value(&automation).expect("serialize automation");
        assert!(automation_wire["attribution_facts"]
            .as_array()
            .is_some_and(|facts| facts.iter().any(|fact| {
                fact["field"] == "origin_kind" && fact["value"] == "provider_scheduled_task"
            })));
        let mut unattributed = automation.clone();
        let attributed_fingerprint = unattributed.snapshot_fingerprint.clone();
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut unattributed),
            SnapshotUploadPolicy::default(),
        );
        let unattributed_wire = serde_json::to_value(&unattributed).expect("serialize empty facts");
        assert!(unattributed_wire.get("attribution_facts").is_none());
        assert_ne!(unattributed.snapshot_fingerprint, attributed_fingerprint);

        let subagent_path = temp_file("codex-subagent-attribution");
        fs::write(
            &subagent_path,
            concat!(
                "{\"timestamp\":\"2026-07-19T11:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"subagent-session\",\"source\":{\"subagent\":{\"thread_spawn\":{\"parent_thread_id\":\"parent-session\",\"depth\":1}}},\"thread_source\":\"subagent\"}}\n",
                "{\"timestamp\":\"2026-07-19T11:01:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":8,\"output_tokens\":4,\"request_count\":1},\"model\":\"gpt-5.6-sol\"}}}\n"
            ),
        )
        .expect("write subagent fixture");
        let mut subagent = parse_codex_jsonl_file(
            &subagent_path,
            "2026-07-19T11:04:00Z",
            "fp-subagent".to_string(),
        )
        .expect("parse subagent")
        .into_iter()
        .next()
        .expect("subagent snapshot");
        assert!(subagent
            .attribution_facts
            .iter()
            .any(|fact| fact.field == "origin_kind" && fact.value == "subagent"));
        assert!(subagent
            .attribution_facts
            .iter()
            .any(|fact| { fact.field == "parent_session_ref" && fact.value == "parent-session" }));
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut subagent),
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        let subagent_wire = serde_json::to_value(&subagent).expect("serialize subagent");
        assert!(subagent_wire["attribution_facts"]
            .as_array()
            .is_some_and(|facts| facts
                .iter()
                .any(|fact| { fact["field"] == "origin_kind" && fact["value"] == "subagent" })));
        assert!(
            subagent_wire
                .get("origin")
                .and_then(|origin| origin.get("parent_session_ref"))
                .is_none(),
            "dark parent metadata must not extend the v6 origin object"
        );

        let _ = fs::remove_file(automation_path);
        let _ = fs::remove_file(subagent_path);
    }

    #[test]
    fn codex_parser_gates_bounded_template_labels_on_existing_title_consent() {
        let home = temp_dir("codex-attribution-groups");
        let schedule_dir = home.join(".codex/automations/schedule-landing");
        fs::create_dir_all(&schedule_dir).expect("schedule dir");
        let scheduled_prompt =
            "Inspect the landing queue, verify every required check, and report safe results.";
        fs::write(
            schedule_dir.join("automation.toml"),
            format!(
                "id = \"schedule-landing\"\nprompt = \"{scheduled_prompt}\"\nstatus = \"ACTIVE\"\n"
            ),
        )
        .expect("schedule definition");
        let encoded_key = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode([11_u8; 32]);
        let context = crate::session_attribution::SessionAttributionContext::from_activity_hint(
            SnapshotSource::Codex,
            &home,
            true,
            Some(&encoded_key),
            Some(crate::session_attribution::SESSION_ATTRIBUTION_HMAC_KEY_VERSION),
        )
        .expect("attribution context");
        let path = home.join("session.jsonl");
        fs::write(
            &path,
            format!(
                "{{\"timestamp\":\"2026-07-19T10:00:00Z\",\"type\":\"session_meta\",\"payload\":{{\"id\":\"automation-group-session\",\"originator\":\"Codex Desktop\",\"thread_source\":\"automation\"}}}}\n\
                 {{\"timestamp\":\"2026-07-19T10:00:01Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"user_message\",\"message\":\"An automation named Landing has fired. Its prompt is: {scheduled_prompt}\"}}}}\n\
                 {{\"timestamp\":\"2026-07-19T10:01:00Z\",\"type\":\"event_msg\",\"payload\":{{\"type\":\"token_count\",\"info\":{{\"total_token_usage\":{{\"input_tokens\":10,\"output_tokens\":5,\"request_count\":1}},\"model\":\"gpt-5.6-sol\"}}}}}}\n"
            ),
        )
        .expect("session");

        let mut item = parse_codex_jsonl_file_with_title_metadata_and_attribution(
            &path,
            "2026-07-19T10:04:00Z",
            "fp-attribution-groups".to_string(),
            &CodexTitleMetadata::default(),
            None,
            Some(&context),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert!(item
            .attribution_facts
            .iter()
            .any(|fact| fact.field == "template_group_id"));
        assert!(item
            .attribution_facts
            .iter()
            .any(|fact| fact.field == "schedule_definition_id"));
        let local_facts = serde_json::to_string(&item.attribution_facts).expect("local facts");
        assert!(local_facts.contains(scheduled_prompt));
        assert!(!local_facts.contains(path.to_string_lossy().as_ref()));

        let mut labels_disabled = item.clone();
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut labels_disabled),
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        let disabled_wire = serde_json::to_value(&labels_disabled).expect("disabled snapshot wire");
        let disabled_facts = serde_json::to_string(&disabled_wire["attribution_facts"])
            .expect("disabled wire attribution facts");
        assert!(disabled_wire["attribution_facts"].is_array());
        assert!(!disabled_facts.contains("display_label"));
        assert!(!disabled_facts.contains(scheduled_prompt));

        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut item),
            SnapshotUploadPolicy {
                session_attribution_enabled: true,
                session_attribution_labels_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        let enabled_wire = serde_json::to_value(&item).expect("enabled snapshot wire");
        let enabled_facts = serde_json::to_string(&enabled_wire["attribution_facts"])
            .expect("enabled wire attribution facts");
        assert!(enabled_facts.contains(scheduled_prompt));
        assert!(enabled_facts.contains("prompt_prefix"));
        assert!(!enabled_facts.contains(path.to_string_lossy().as_ref()));

        let mut title_opted_out = item.clone();
        apply_upload_policy(
            SnapshotSource::Codex,
            std::slice::from_mut(&mut title_opted_out),
            SnapshotUploadPolicy {
                session_titles_enabled: false,
                session_attribution_enabled: true,
                session_attribution_labels_enabled: true,
                ..SnapshotUploadPolicy::default()
            },
        );
        let opted_out_wire = serde_json::to_string(&title_opted_out).expect("opted out wire");
        assert!(!opted_out_wire.contains("display_label"));
        assert!(!opted_out_wire.contains(scheduled_prompt));

        let _ = fs::remove_dir_all(home);
    }

    #[test]
