    #[test]
    fn codex_config_defaults_capture_service_tier_model_and_selectors() {
        for (raw, tier, fast) in [
            ("model = \"gpt-5.5\"\nservice_tier = \"default\"\nmodel_reasoning_effort = \"high\"\nfast_default_opt_out = true\n[features]\nfast_mode = true\n", Some("default"), Some(false)),
            ("service_tier = \"priority\"\n", Some("priority"), Some(true)),
            ("personality = \"pragmatic\"\n", None, None),
            ("model = \"gpt-5.5\"\n", None, None),
            ("model = \"gpt-5.5\"\n[features]\nfast_mode = false\n", None, Some(false)),
            ("model = \"gpt-5.5\"\n[features]\nfast_mode = true\n", None, Some(true)),
        ] {
            let Some(defaults) = parse_codex_config_defaults(raw) else {
                assert_eq!(raw, "personality = \"pragmatic\"\n");
                continue;
            };
            assert_eq!(defaults.service_tier.as_deref(), tier);
            assert_eq!(defaults.display_fast_mode(), fast);
            if tier == Some("default") {
                assert_eq!(defaults.model.as_deref(), Some("gpt-5.5"));
                assert_eq!(defaults.reasoning_effort.as_deref(), Some("high"));
                assert_eq!(defaults.fast_mode, Some(true));
                assert!(defaults.fast_default_opt_out);
                assert_eq!(defaults.selector_context.get("service_tier").map(String::as_str), Some("standard"));
                assert_eq!(defaults.selector_sources.get("service_tier").map(String::as_str), Some("codex.config.service_tier"));
            }
            if raw == "model = \"gpt-5.5\"\n" { assert!(!defaults.selector_context.contains_key("mode")); }
        }
    }

    /// Build the ordered Claude Code settings chain for a fake home directory.
    fn claude_settings_chain(claude_dir: &Path, managed: &Path) -> Vec<(String, PathBuf)> {
        vec![
            (
                "claude_code.settings".to_string(),
                claude_dir.join("settings.json"),
            ),
            (
                "claude_code.settings_local".to_string(),
                claude_dir.join("settings.local.json"),
            ),
            (
                "claude_code.managed_settings".to_string(),
                managed.to_path_buf(),
            ),
        ]
    }

    fn load_claude_defaults(paths: &[(String, PathBuf)]) -> ClaudeConfigDefaultsOutcome {
        let scopes: Vec<ClaudeSettingsScope<'_>> = paths
            .iter()
            .map(|(label, path)| ClaudeSettingsScope {
                label: label.as_str(),
                path: path.as_path(),
            })
            .collect();
        load_claude_settings_defaults(&scopes)
    }

    #[test]
    fn claude_settings_defaults_prefer_local_then_managed_scope() {
        let root = temp_dir("claude-settings-precedence");
        let claude_dir = root.join(".claude");
        fs::create_dir_all(&claude_dir).expect("create .claude");
        fs::write(
            claude_dir.join("settings.json"),
            "{\"model\": \"claude-haiku-4-5\", \"effortLevel\": \"low\", \"fastMode\": true, \"permissions\": {\"defaultMode\": \"acceptEdits\"}}\n",
        )
        .expect("write user settings");
        fs::write(
            claude_dir.join("settings.local.json"),
            "{\"model\": \"claude-sonnet-4-5\", \"effortLevel\": \"medium\", \"permissions\": {\"defaultMode\": \"plan\"}}\n",
        )
        .expect("write local settings");
        let managed = root.join("managed-settings.json");
        fs::write(
            &managed,
            "{\"model\": \"claude-opus-4-7\", \"effortLevel\": \"xhigh\", \"sandbox\": {\"enabled\": true, \"autoAllowBashIfSandboxed\": false}}\n",
        )
        .expect("write managed settings");

        let paths = claude_settings_chain(&claude_dir, &managed);
        let ClaudeConfigDefaultsOutcome::Configured(defaults) = load_claude_defaults(&paths) else {
            panic!("expected configured Claude defaults");
        };
        // Managed settings win outright for the keys they set.
        assert_eq!(defaults.model.as_deref(), Some("claude-opus-4-7"));
        assert_eq!(
            defaults.selector_sources.get("model").map(String::as_str),
            Some("claude_code.managed_settings.model")
        );
        assert_eq!(defaults.reasoning_effort.as_deref(), Some("xhigh"));
        assert_eq!(
            defaults
                .selector_sources
                .get("reasoning_effort")
                .map(String::as_str),
            Some("claude_code.managed_settings.effortLevel")
        );
        // Local settings win over user settings for a key managed does not set.
        assert_eq!(defaults.approval_policy.as_deref(), Some("plan"));
        assert_eq!(
            defaults
                .selector_sources
                .get("approval_policy")
                .map(String::as_str),
            Some("claude_code.settings_local.permissions.defaultMode")
        );
        // A key only the lowest scope sets still survives.
        assert_eq!(defaults.fast_mode_enabled, Some(true));
        assert_eq!(
            defaults
                .selector_sources
                .get("fast_mode_enabled")
                .map(String::as_str),
            Some("claude_code.settings.fastMode")
        );
        assert_eq!(
            defaults.sandbox_mode.as_deref(),
            Some("regular_permissions")
        );

        let _ = fs::remove_dir_all(root);
    }

    /// Effort and its `selector_sources` key, or `None` when not reported.
    fn claude_effort_with_source(paths: &[(String, PathBuf)]) -> Option<(String, String)> {
        let ClaudeConfigDefaultsOutcome::Configured(defaults) = load_claude_defaults(paths) else {
            panic!("expected configured Claude defaults");
        };
        let source = defaults.selector_sources.get("reasoning_effort").cloned();
        assert_eq!(
            defaults.selector_context.get("reasoning_effort"),
            defaults.reasoning_effort.as_ref()
        );
        defaults.reasoning_effort.zip(source)
    }

    /// Current Claude Code saves `/effort` under `modelSettings.<model>` and
    /// leaves the top-level `effortLevel` stale. The saved model's entry wins,
    /// matched on Claude Code's canonical key.
    #[test]
    fn claude_settings_defaults_read_model_settings_effort_for_saved_model() {
        let root = temp_dir("claude-settings-model-effort");
        let claude_dir = root.join(".claude");
        fs::create_dir_all(&claude_dir).expect("create .claude");
        let paths = claude_settings_chain(&claude_dir, &root.join("managed-settings.json"));
        for model in [
            "claude-opus-5-5",
            "claude-opus-5-5-20261001",
            "claude-opus-5-5[1m]",
            "us.anthropic.claude-opus-5-5-20261001-v1:0",
        ] {
            fs::write(
                claude_dir.join("settings.json"),
                format!(
                    "{{\"model\": \"{model}\", \"effortLevel\": \"low\", \"modelSettings\": {{\"claude-opus-5\": {{\"effortLevel\": \"high\"}}, \"claude-opus-5-5\": {{\"effortLevel\": \"medium\"}}}}}}\n"
                ),
            )
            .expect("write settings");
            assert_eq!(
                claude_effort_with_source(&paths),
                Some((
                    "medium".to_string(),
                    "claude_code.settings.modelSettings.claude-opus-5-5.effortLevel".to_string()
                )),
                "model {model}"
            );
        }

        // A saved older model with no entry of its own falls back to the legacy
        // key; a current model does not, as in Claude Code.
        for (model, expected) in [
            ("claude-sonnet-5", Some("low")),
            ("claude-sonnet-5-5", None),
        ] {
            fs::write(
                claude_dir.join("settings.json"),
                format!(
                    "{{\"model\": \"{model}\", \"effortLevel\": \"low\", \"modelSettings\": {{\"claude-opus-5-5\": {{\"effortLevel\": \"medium\"}}}}}}\n"
                ),
            )
            .expect("rewrite settings");
            assert_eq!(
                claude_effort_with_source(&paths),
                expected.map(|effort| (
                    effort.to_string(),
                    "claude_code.settings.effortLevel".to_string()
                )),
                "model {model}"
            );
        }

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn claude_settings_defaults_never_emit_paths_secrets_or_bypass_permissions() {
        let root = temp_dir("claude-settings-redaction");
        let claude_dir = root.join(".claude");
        fs::create_dir_all(&claude_dir).expect("create .claude");
        fs::write(
            claude_dir.join("settings.json"),
            concat!(
                "{\n",
                "  \"model\": \"claude-opus-4-7\",\n",
                "  \"apiKeyHelper\": \"/Users/someone/bin/print-key.sh\",\n",
                "  \"env\": {\"ANTHROPIC_API_KEY\": \"sk-ant-secret-value\",\n",
                "            \"OTEL_EXPORTER_OTLP_HEADERS\": \"Authorization=Bearer otsi_secret\"},\n",
                "  \"statusLine\": {\"type\": \"command\", \"command\": \"/Users/someone/.claude/statusline.sh\"},\n",
                "  \"permissions\": {\n",
                "    \"defaultMode\": \"bypassPermissions\",\n",
                "    \"allow\": [\"Read(~/.zshrc)\", \"Bash(aws s3 *)\"],\n",
                "    \"deny\": [\"Read(./.env)\"]\n",
                "  },\n",
                "  \"sandbox\": {\n",
                "    \"enabled\": true,\n",
                "    \"filesystem\": {\"allowWrite\": [\"/Users/someone/.kube\"]},\n",
                "    \"credentials\": {\"envVars\": [{\"name\": \"GH_TOKEN\", \"mode\": \"deny\"}],\n",
                "                     \"files\": [{\"path\": \"~/.aws/credentials\", \"mode\": \"deny\"}]}\n",
                "  }\n",
                "}\n"
            ),
        )
        .expect("write settings");

        let paths = claude_settings_chain(&claude_dir, &root.join("managed-settings.json"));
        let ClaudeConfigDefaultsOutcome::Configured(defaults) = load_claude_defaults(&paths) else {
            panic!("expected configured Claude defaults");
        };
        // Only the four mapped keys are read; the sandbox contributes its mode
        // and nothing from filesystem/credentials. Fast is the unset default.
        assert_eq!(defaults.model.as_deref(), Some("claude-opus-4-7"));
        assert_eq!(defaults.sandbox_mode.as_deref(), Some("auto_allow"));
        // `bypassPermissions` is a local safety posture, never uploaded.
        assert_eq!(defaults.approval_policy, None);
        assert!(!defaults.selector_context.contains_key("approval_policy"));
        assert_eq!(
            defaults.selector_context.keys().collect::<Vec<_>>(),
            vec!["fast_mode_enabled", "model", "sandbox_mode"]
        );

        let leaked = defaults
            .selector_context
            .values()
            .chain(defaults.selector_sources.values())
            .find(|value| {
                let lowered = value.to_ascii_lowercase();
                lowered.contains('/')
                    || lowered.contains("sk-")
                    || lowered.contains("bearer")
                    || lowered.contains("token")
                    || lowered.contains("credential")
                    || lowered.contains("bypass")
            });
        assert_eq!(leaked, None, "no path or secret text may ride along");

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn claude_transcript_effort_is_read_without_any_otlp_sidecar() {
        // The whole point: no effort index is threaded in, and the tiers still
        // land, because current Claude Code stamps them on the record itself.
        let path = temp_file("claude-transcript-effort");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-08-04T10:00:00Z\",\"sessionId\":\"transcript-effort-1\",\"summary\":\"t\"}\n",
                "{\"timestamp\":\"2026-08-04T10:01:00Z\",\"sessionId\":\"transcript-effort-1\",\"type\":\"assistant\",\"effort\":\"xhigh\",\"requestId\":\"req_A\",\"message\":{\"id\":\"msg_A\",\"model\":\"claude-opus-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5}}}\n",
                "{\"timestamp\":\"2026-08-04T10:02:00Z\",\"sessionId\":\"transcript-effort-1\",\"type\":\"assistant\",\"effort\":\"low\",\"requestId\":\"req_B\",\"message\":{\"id\":\"msg_B\",\"model\":\"claude-opus-5\",\"usage\":{\"input_tokens\":20,\"output_tokens\":7}}}\n",
                "{\"timestamp\":\"2026-08-04T13:01:00Z\",\"sessionId\":\"transcript-effort-1\",\"type\":\"assistant\",\"effort\":\"hyper\",\"message\":{\"id\":\"msg_C\",\"model\":\"claude-opus-5\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_claude_code_jsonl_file(&path, "2026-08-04T10:04:00Z", "fp".to_string())
            .expect("parse")
            .into_iter()
            .next()
            .expect("snapshot");

        let mut split: Vec<(Option<String>, u64)> = item
            .model_usage
            .iter()
            .map(|row| (row.reasoning_effort.clone(), row.input_tokens))
            .collect();
        split.sort();
        assert_eq!(
            split,
            vec![
                (None, 10),
                (Some("low".to_string()), 20),
                (Some("xhigh".to_string()), 10)
            ]
        );
        let _ = fs::remove_file(&path);
    }

