    #[test]
    fn claude_subagent_sidecar_fingerprint_tracks_naming_material() {
        let root = temp_dir("claude-subagent-sidecar-fp");
        let parent_session = "58e9c6bc-c733-4946-b9e4-aa57c707dbf2";
        let session_dir = root.join(parent_session);
        let workflow_dir = session_dir
            .join("subagents")
            .join("workflows")
            .join("wf_f7ae7a92-02b");
        fs::create_dir_all(&workflow_dir).expect("create dirs");
        let transcript = workflow_dir.join("agent-a09c3096ec4de4f11.jsonl");
        fs::write(&transcript, "{}\n").expect("write transcript");
        let identity = claude_subagent_identity(&transcript).expect("identity");

        let support_dir = root.join("support");
        let baseline =
            claude_subagent_sidecar_fingerprint(&transcript, &identity, Some(&support_dir));
        assert_eq!(
            baseline,
            claude_subagent_sidecar_fingerprint(&transcript, &identity, Some(&support_dir)),
            "fingerprint must be deterministic"
        );

        // A workflow manifest appearing later re-selects the transcript.
        fs::create_dir_all(session_dir.join("workflows")).expect("create manifest dir");
        fs::write(
            session_dir.join("workflows").join("wf_f7ae7a92-02b.json"),
            "{\"workflowProgress\":[]}",
        )
        .expect("write manifest");
        let with_manifest =
            claude_subagent_sidecar_fingerprint(&transcript, &identity, Some(&support_dir));
        assert_ne!(baseline, with_manifest);

        // So does a meta sidecar appearing...
        fs::write(
            workflow_dir.join("agent-a09c3096ec4de4f11.meta.json"),
            "{\"agentType\":\"workflow-subagent\"}",
        )
        .expect("write sidecar");
        let with_meta =
            claude_subagent_sidecar_fingerprint(&transcript, &identity, Some(&support_dir));
        assert_ne!(with_manifest, with_meta);

        // Root-scoped OTLP identity arriving later must also re-select the
        // child; otherwise a child indexed before its final API event would
        // remain unattributed forever.
        let body = format!(
            "{{\"resourceLogs\":[{{\"scopeLogs\":[{{\"logRecords\":[{{\"timeUnixNano\":\"1785654000000000000\",\"body\":{{\"stringValue\":\"claude_code.api_request\"}},\"attributes\":[{{\"key\":\"session.id\",\"value\":{{\"stringValue\":\"{parent_session}\"}}}},{{\"key\":\"user.account_uuid\",\"value\":{{\"stringValue\":\"123E4567-E89B-12D3-A456-426614174000\"}}}},{{\"key\":\"model\",\"value\":{{\"stringValue\":\"claude-opus-4-8\"}}}},{{\"key\":\"input_tokens\",\"value\":{{\"intValue\":\"1\"}}}},{{\"key\":\"output_tokens\",\"value\":{{\"intValue\":\"1\"}}}}]}}]}}]}}]}}"
        );
        assert_eq!(
            crate::claude_local_otel::capture_claude_api_request_logs(
                &support_dir,
                body.as_bytes(),
                "application/json",
            )
            .expect("capture root account evidence"),
            1
        );
        let with_effort =
            claude_subagent_sidecar_fingerprint(&transcript, &identity, Some(&support_dir));
        assert_ne!(with_meta, with_effort);

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn claude_code_duplicate_content_block_records_count_usage_once() {
        // Claude Code writes one JSONL record per assistant content block. All
        // records of one API response share message.id + requestId and resolve
        // to one terminal usage occurrence.
        let path = temp_file("claude-dedup-same-response");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-06-30T10:01:00Z\",\"sessionId\":\"claude-dedup-1\",\"requestId\":\"req_011AAA\",\"message\":{\"id\":\"msg_011AAA\",\"model\":\"claude-sonnet-4-6\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":3}}}\n",
                "{\"timestamp\":\"2026-06-30T10:01:01Z\",\"sessionId\":\"claude-dedup-1\",\"requestId\":\"req_011AAA\",\"message\":{\"id\":\"msg_011AAA\",\"model\":\"claude-sonnet-4-6\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":3}}}\n",
                "{\"timestamp\":\"2026-06-30T10:01:02Z\",\"sessionId\":\"claude-dedup-1\",\"requestId\":\"req_011AAA\",\"isSidechain\":true,\"message\":{\"id\":\"msg_011AAA\",\"model\":\"claude-sonnet-4-6\",\"usage\":{\"input_tokens\":10,\"output_tokens\":5,\"cache_read_input_tokens\":3}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_claude_code_jsonl_file(
            &path,
            "2026-06-30T10:04:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");

        assert_eq!(item.input_tokens, 10);
        assert_eq!(item.output_tokens, 5);
        assert_eq!(item.cache_read_tokens, 3);
        // Dedup fixes request_count implicitly: one counted usage = one request.
        assert_eq!(item.request_count, 1);
        // Duplicate records still contribute NON-usage signals: the sidechain
        // flag rode in on the third (skipped-usage) record.
        assert_eq!(
            item.origin.expect("origin forwarded").is_sidechain,
            Some(true)
        );

        let _ = fs::remove_file(path);
    }

    #[test]
    fn claude_out_of_order_progressive_response_uses_provider_time() {
        let path = temp_file("claude-progressive-provider-time");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-09-11T08:31:20Z\",\"sessionId\":\"claude-progressive-order\",\"type\":\"user\",\"message\":{\"role\":\"user\",\"content\":\"work\"}}\n",
                // Fable appends the terminal observations first, then replays
                // the earlier partial states for those same provider instants.
                "{\"timestamp\":\"2026-09-11T08:31:22.985Z\",\"sessionId\":\"claude-progressive-order\",\"type\":\"assistant\",\"requestId\":\"req_progressive_order\",\"speed\":\"standard\",\"message\":{\"id\":\"msg_progressive_order\",\"model\":\"claude-fable-5-1\",\"usage\":{\"input_tokens\":32,\"output_tokens\":1026,\"cache_read_input_tokens\":960010,\"cache_creation\":{\"ephemeral_1h_input_tokens\":6006}}}}\n",
                "{\"timestamp\":\"2026-09-11T08:31:29.473Z\",\"sessionId\":\"claude-progressive-order\",\"type\":\"assistant\",\"requestId\":\"req_progressive_order\",\"speed\":\"standard\",\"message\":{\"id\":\"msg_progressive_order\",\"model\":\"claude-fable-5-1\",\"usage\":{\"input_tokens\":32,\"output_tokens\":1026,\"cache_read_input_tokens\":960010,\"cache_creation\":{\"ephemeral_1h_input_tokens\":6006}}}}\n",
                "{\"timestamp\":\"2026-09-11T08:31:22.985Z\",\"sessionId\":\"claude-progressive-order\",\"type\":\"assistant\",\"requestId\":\"req_progressive_order\",\"message\":{\"id\":\"msg_progressive_order\",\"model\":\"claude-fable-5-1\",\"usage\":{\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation\":{\"ephemeral_1h_input_tokens\":6006}}}}\n",
                "{\"timestamp\":\"2026-09-11T08:31:29.473Z\",\"sessionId\":\"claude-progressive-order\",\"type\":\"assistant\",\"requestId\":\"req_progressive_order\",\"message\":{\"id\":\"msg_progressive_order\",\"model\":\"claude-fable-5-1\",\"usage\":{\"input_tokens\":0,\"output_tokens\":0,\"cache_read_input_tokens\":0,\"cache_creation\":{\"ephemeral_1h_input_tokens\":6006}}}}\n"
            ),
        )
        .expect("write fixture");

        let item = parse_claude_code_jsonl_file(
            &path,
            "2026-09-11T08:32:00Z",
            "file-fingerprint".to_string(),
        )
        .expect("parse")
        .into_iter()
        .next()
        .expect("snapshot");
        assert_eq!(item.input_tokens, 32);
        assert_eq!(item.output_tokens, 1_026);
        assert_eq!(item.cache_read_tokens, 960_010);
        assert_eq!(item.cache_creation_1h_tokens, 6_006);
        assert_eq!(item.request_count, 1);
        assert_eq!(item.first_turn_context_tokens, Some(966_048));
        assert_eq!(item.peak_context_fill_tokens, Some(966_048));
        assert_eq!(item.avg_duration_ms, Some(2_985));
        assert_eq!(
            item.model_usage[0]
                .selector_context
                .get("context_bucket")
                .map(String::as_str),
            Some("long")
        );
        assert_eq!(
            item.model_usage[0]
                .selector_context
                .get("speed_mode")
                .map(String::as_str),
            Some("standard")
        );
        let _ = fs::remove_file(path);
    }

