    fn codex_test_token_line(
        timestamp: &str,
        ordinal: Option<u64>,
        total: (u64, u64, u64, u64),
        last: Option<(u64, u64, u64, u64)>,
    ) -> Value {
        let mut value = json!({
            "timestamp": timestamp,
            "type": "event_msg",
            "payload": {
                "type": "token_count",
                "info": {
                    "total_token_usage": {
                        "input_tokens": total.0,
                        "cached_input_tokens": total.1,
                        "output_tokens": total.2,
                        "reasoning_output_tokens": total.3,
                    },
                    "model": "gpt-5.6-sol"
                }
            }
        });
        if let Some(ordinal) = ordinal {
            value["ordinal"] = json!(ordinal);
        }
        if let Some(last) = last {
            value["payload"]["info"]["last_token_usage"] = json!({
                "input_tokens": last.0,
                "cached_input_tokens": last.1,
                "output_tokens": last.2,
                "reasoning_output_tokens": last.3,
            });
        }
        value
    }

    fn write_codex_test_values(name: &str, values: &[Value]) -> PathBuf {
        let path = temp_file(name);
        let mut body = values
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n");
        body.push('\n');
        fs::write(&path, body).expect("write Codex fixture");
        path
    }

    fn parse_codex_test(path: &Path) -> ParsedJsonlFile {
        parse_codex_test_with_metadata(path, &CodexTitleMetadata::default())
    }

    fn parse_codex_test_with_metadata(
        path: &Path,
        metadata: &CodexTitleMetadata,
    ) -> ParsedJsonlFile {
        let mut file = File::open(path).expect("open Codex fixture");
        let identity = opened_object_identity(SnapshotSource::Codex, &mut file)
            .expect("identify Codex fixture");
        parse_opened_jsonl_file(
            file,
            &identity,
            path,
            "2026-08-02T09:00:00Z",
            "fp".to_string(),
            SnapshotSource::Codex,
            apply_codex_line,
            Some(metadata),
            None,
            None,
            None,
        )
        .expect("parse Codex fixture")
    }

    fn scan_codex_test_root(root: &Path) -> (SourceScanResult, ScanIndex) {
        let mut index = ScanIndex::default();
        let scan = scan_source_roots_with_limit_and_attribution(
            SnapshotSource::Codex,
            std::slice::from_ref(&root.to_path_buf()),
            &mut index,
            "2026-08-29T12:30:00Z",
            BACKFILL_WINDOW_DAYS,
            MAX_BACKFILL_FILES_PER_SOURCE,
            None,
            None,
            &[],
            false,
        )
        .expect("scan Codex production-path fixture");
        (scan, index)
    }

    fn parse_trusted_created_thread_test(
        name: &str,
        child_id: &str,
        parent_id: &str,
        child_values: &[Value],
    ) -> (PathBuf, ParsedJsonlFile) {
        parse_trusted_created_thread_test_with_extent(name, child_id, parent_id, child_values, None)
    }

    fn parse_trusted_created_thread_test_with_extent(
        name: &str,
        child_id: &str,
        parent_id: &str,
        child_values: &[Value],
        projected_next_ordinal: Option<u64>,
    ) -> (PathBuf, ParsedJsonlFile) {
        let root = temp_dir(name);
        let path = root.join(format!("rollout-{child_id}.jsonl"));
        let mut body = child_values
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n");
        body.push('\n');
        fs::write(&path, body).expect("write trusted created-thread fixture");

        let mut metadata = CodexTitleMetadata::default();
        metadata.state_created_threads.insert(child_id.to_string());
        metadata
            .spawn_parents
            .insert(child_id.to_string(), parent_id.to_string());
        metadata.state_threads.insert(
            child_id.to_string(),
            CodexStateThread {
                tokens_used: 1,
                created_at: child_values.first().and_then(|value| {
                    codex_session_meta_payload(value)
                        .and_then(|meta| string_at(meta, &["timestamp"]))
                        .or_else(|| string_at(value, &["timestamp"]))
                }),
                ..CodexStateThread::default()
            },
        );
        if let Some(next_ordinal) = projected_next_ordinal {
            metadata.rollout_extents.insert(
                child_id.to_string(),
                CodexRolloutExtent {
                    next_byte_offset: fs::metadata(&path)
                        .expect("stat trusted created-thread fixture")
                        .len(),
                    next_ordinal,
                },
            );
        }
        let parsed = parse_codex_test_with_metadata(&path, &metadata);
        (root, parsed)
    }

    #[test]
    fn codex_legacy_full_fork_excludes_inherited_usage_activity_and_posture() {
        let values = vec![
            json!({
                "timestamp":"2026-08-02T06:00:00Z", "type":"session_meta",
                "payload": {
                    "id":"child-full", "forked_from_id":"root",
                    "thread_source":"subagent",
                    "source":{"subagent":{"thread_spawn":{"parent_thread_id":"root"}}}
                }
            }),
            codex_test_token_line(
                "2026-08-02T06:00:01Z",
                None,
                (1_000, 800, 100, 20),
                Some((1_000, 800, 100, 20)),
            ),
            json!({"timestamp":"2026-08-02T06:00:02Z","type":"compacted","payload":{"replacement_history":[]}}),
            json!({"timestamp":"2026-08-02T06:00:03Z","type":"response_item","payload":{"type":"function_call","name":"exec_command","call_id":"inherited"}}),
            json!({"timestamp":"2026-08-02T06:00:04Z","type":"event_msg","payload":{"type":"task_complete","duration_ms":900,"time_to_first_token_ms":90}}),
            // A copied parent header must not overwrite the first physical child envelope.
            json!({"timestamp":"2026-08-02T06:00:05Z","type":"session_meta","payload":{"id":"root","thread_source":"user"}}),
            json!({"timestamp":"2026-08-02T06:00:58Z","type":"event_msg","payload":{"type":"task_started"}}),
            json!({"timestamp":"2026-08-02T06:00:59Z","type":"turn_context","payload":{"model":"gpt-5.6-sol","turn_id":"owned-turn","effort":"high"}}),
            json!({"timestamp":"2026-08-02T06:01:00Z","type":"inter_agent_communication_metadata","payload":{"trigger_turn":true}}),
            codex_test_token_line(
                "2026-08-02T06:01:02Z",
                None,
                (1_100, 880, 110, 22),
                Some((100, 80, 10, 2)),
            ),
            json!({"timestamp":"2026-08-02T06:01:03Z","type":"compacted","payload":{"replacement_history":[]}}),
            json!({"timestamp":"2026-08-02T06:01:04Z","type":"response_item","payload":{"type":"function_call","name":"exec_command","call_id":"owned"}}),
            json!({"timestamp":"2026-08-02T06:01:05Z","type":"event_msg","payload":{"type":"task_complete","duration_ms":100,"time_to_first_token_ms":10}}),
        ];
        let path = write_codex_test_values("codex-legacy-full-exclusive", &values);
        let item = parse_codex_jsonl_file(&path, "2026-08-02T06:02:00Z", "fp".to_string())
            .expect("parse")
            .into_iter()
            .next()
            .expect("exclusive snapshot");

        assert_eq!(item.source_session_id, "child-full");
        assert_eq!(
            item.origin
                .as_ref()
                .and_then(|o| o.parent_session_ref.as_deref()),
            Some("root")
        );
        assert_eq!(
            item.usage_accounting_contract.as_deref(),
            Some("session_exclusive_reported_usage:v1")
        );
        let serialized = serde_json::to_value(&item).expect("serialize exclusive snapshot");
        assert_eq!(
            serialized
                .get("usage_accounting_contract")
                .and_then(Value::as_str),
            Some("session_exclusive_reported_usage:v1")
        );
        let mut legacy_hash_shape = item.clone();
        legacy_hash_shape.usage_accounting_contract = None;
        assert!(serde_json::to_value(&legacy_hash_shape)
            .expect("serialize legacy hash shape")
            .get("usage_accounting_contract")
            .is_none());
        assert_ne!(
            snapshot_semantic_component_hashes(SnapshotSource::Codex, &item)
                .get("usage_accounting"),
            snapshot_semantic_component_hashes(SnapshotSource::Codex, &legacy_hash_shape)
                .get("usage_accounting")
        );
        assert_eq!(
            (
                item.input_tokens,
                item.cache_read_tokens,
                item.output_tokens,
                item.reasoning_output_tokens,
                item.request_count
            ),
            (100, 80, 10, 2, 1)
        );
        assert_eq!(item.first_turn_context_tokens, Some(100));
        assert_eq!(item.peak_context_fill_tokens, Some(100));
        assert_eq!(item.compaction_count, Some(1));
        // The inherited-prefix marker is no event, and the owned marker's
        // `before` is the owned request, never the inherited 1,000.
        assert_eq!(
            item.compaction_events,
            [SnapshotCompactionEvent {
                at: "2026-08-02T06:01:03Z".to_string(),
                before: Some(100),
                after: None,
                trigger: None,
            }]
        );
        assert_eq!(
            item.model_usage[0].reasoning_effort.as_deref(),
            Some("high")
        );
        assert_eq!(item.avg_duration_ms, Some(100));
        assert_eq!(item.avg_time_to_first_token_ms, Some(10));
        assert_eq!(
            item.activity_summary
                .as_ref()
                .map(|summary| summary.shell_commands),
            Some(1)
        );
        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_native_ordinal_boundary_is_exact_and_incomplete_prefix_fails_closed() {
        let values = vec![
            json!({"timestamp":"2026-08-02T08:00:00Z","ordinal":0,"type":"session_meta","payload":{"id":"child-ordinal","forked_from_id":"root","thread_source":"subagent","history_mode":"paginated","subagent_history_start_ordinal":3}}),
            codex_test_token_line(
                "2026-08-02T08:00:01Z",
                Some(1),
                (100, 80, 10, 2),
                Some((100, 80, 10, 2)),
            ),
            json!({"timestamp":"2026-08-02T08:00:02Z","ordinal":2,"type":"compacted","payload":{"replacement_history":[]}}),
            codex_test_token_line(
                "2026-08-02T08:00:03Z",
                Some(3),
                (140, 110, 18, 3),
                Some((40, 30, 8, 1)),
            ),
            json!({"timestamp":"2026-08-02T08:00:04Z","ordinal":4,"type":"compacted","payload":{"replacement_history":[]}}),
        ];
        let path = write_codex_test_values("codex-ordinal-exclusive", &values);
        let item = parse_codex_jsonl_file(&path, "2026-08-02T08:01:00Z", "fp".to_string())
            .expect("parse ordinal")
            .remove(0);
        assert_eq!(
            (
                item.input_tokens,
                item.cache_read_tokens,
                item.output_tokens,
                item.reasoning_output_tokens
            ),
            (40, 30, 8, 1)
        );
        assert_eq!(item.compaction_count, Some(1));

        let incomplete_path = write_codex_test_values(
            "codex-ordinal-incomplete",
            &[
                json!({"timestamp":"2026-08-02T08:10:00Z","ordinal":0,"type":"session_meta","payload":{"id":"child-incomplete","forked_from_id":"root","thread_source":"subagent","history_mode":"paginated","subagent_history_start_ordinal":3}}),
                codex_test_token_line(
                    "2026-08-02T08:10:01Z",
                    Some(1),
                    (100, 80, 10, 2),
                    Some((100, 80, 10, 2)),
                ),
                codex_test_token_line(
                    "2026-08-02T08:10:03Z",
                    Some(3),
                    (140, 110, 18, 3),
                    Some((40, 30, 8, 1)),
                ),
            ],
        );
        assert!(
            parse_codex_jsonl_file(&incomplete_path, "2026-08-02T08:11:00Z", "fp".to_string())
                .expect("parse incomplete")
                .is_empty()
        );

        // `start == next ordinal` means the child-owned suffix has not been
        // observed yet. The file may still be live/partially flushed, so it is
        // retryable rather than authoritative confirmed-empty.
        let zero_owned_path = write_codex_test_values(
            "codex-ordinal-zero-owned",
            &[
                json!({"timestamp":"2026-08-02T08:20:00Z","ordinal":0,"type":"session_meta","payload":{"id":"child-zero-owned","forked_from_id":"root","thread_source":"subagent","subagent_history_start_ordinal":3}}),
                codex_test_token_line(
                    "2026-08-02T08:20:01Z",
                    Some(1),
                    (100, 80, 10, 2),
                    Some((100, 80, 10, 2)),
                ),
                json!({"timestamp":"2026-08-02T08:20:02Z","ordinal":2,"type":"compacted","payload":{"replacement_history":[]}}),
            ],
        );
        assert!(
            parse_codex_jsonl_file(&zero_owned_path, "2026-08-02T08:21:00Z", "fp".to_string())
                .expect("parse zero-owned suffix")
                .is_empty()
        );
        let _ = fs::remove_file(path);
        let _ = fs::remove_file(incomplete_path);
        let _ = fs::remove_file(zero_owned_path);
    }

    #[test]
    fn codex_created_thread_five_native_corpus_shapes_admit_exactly_once() {
        let parent_id = "01a03e96-dd4c-7ad1-b516-9c09fea4732b";

        let shapes = [
            ("01a03e97-49cf-7460-9fd7-f7dbfd2f05e4", 18_u64, 958_u64),
            ("01a03eee-dd5b-7851-a3c6-18caedfc2dfb", 17, 106),
            ("01a03eee-dd5b-7851-a3c6-18e36157f193", 17, 115),
            ("01a03eee-dd5b-7851-a3c6-190c38e68ce8", 16, 59),
            ("01a03f0e-a60a-76e3-9d2b-e612b4488dd8", 17, 139),
        ];
        let mut admitted_records = 0_u64;
        for (child_id, first_usage_ordinal, record_count) in shapes {
            let turn_id = format!("{}-7000-8000-8000-000000000001", &child_id[..8]);
            let mut child = vec![
                json!({"timestamp":"2026-08-26T16:37:18.114Z","ordinal":0,"type":"session_meta","payload":{"id":child_id,"session_id":child_id,"timestamp":"2026-08-26T16:37:17.011Z","thread_source":"agent_created_thread","history_mode":"paginated","source":"vscode"}}),
                json!({"timestamp":"2026-08-26T16:37:18.115Z","ordinal":1,"type":"event_msg","payload":{"type":"task_started","turn_id":turn_id,"trace_id":"0123456789abcdef0123456789abcdef","started_at":1_787_762_237_u64}}),
            ];
            while child.len() < 7 {
                let ordinal = child.len() as u64;
                child.push(json!({"timestamp":"2026-08-26T16:37:19Z","ordinal":ordinal,"type":"response_item","payload":{"type":"message","id":format!("msg-{ordinal}"),"role":"developer","content":[]}}));
            }
            child.push(json!({"timestamp":"2026-08-26T16:37:20Z","ordinal":7,"type":"turn_context","payload":{"turn_id":turn_id,"model":"gpt-5.6-sol"}}));
            while (child.len() as u64) < first_usage_ordinal {
                let ordinal = child.len() as u64;
                child.push(json!({"timestamp":"2026-08-26T16:37:21Z","ordinal":ordinal,"type":"event_msg","payload":{"type":"item_completed","turn_id":turn_id}}));
            }
            for index in 1..=record_count {
                child.push(codex_test_token_line(
                    "2026-08-26T16:37:22Z",
                    Some(first_usage_ordinal + index - 1),
                    (index * 10, index * 8, index * 2, index),
                    Some((10, 8, 2, 1)),
                ));
            }
            let (root, parsed) = parse_trusted_created_thread_test(
                "codex-five-native-shapes",
                child_id,
                parent_id,
                &child,
            );
            assert!(parsed.progress_complete(), "{child_id}: {parsed:#?}");
            assert_eq!(parsed.snapshots.len(), 1, "{child_id}");
            assert_eq!(parsed.snapshots[0].input_tokens, record_count * 10);
            assert!(parsed.snapshots[0].context_curve.is_none());
            assert_eq!(parsed.recognized_usage_drop_count, 0);
            assert_eq!(parsed.ownership_incomplete_file_count, 0);
            admitted_records += record_count;
            let _ = fs::remove_dir_all(root);
        }
        assert_eq!(admitted_records, 1_377);
    }

    #[test]
    fn codex_created_thread_no_marker_internal_parent_omission_never_uses_legacy_prefix() {
        let parent_id = "01a02589-5e24-7f10-8a93-a0c1968d8a3a";
        let child_id = "01a03e98-49cf-7460-9fd7-f7dbfd2f05e4";
        let parent = [
            json!({"timestamp":"2026-08-02T08:00:00Z","type":"session_meta","payload":{"id":parent_id,"thread_source":"user"}}),
            json!({"timestamp":"2026-08-02T08:00:01Z","type":"turn_context","payload":{"turn_id":"parent-first-turn","model":"gpt-5.6-sol"}}),
            codex_test_token_line(
                "2026-08-02T08:00:02Z",
                None,
                (100, 80, 10, 2),
                Some((100, 80, 10, 2)),
            ),
            json!({"timestamp":"2026-08-02T08:10:01Z","type":"turn_context","payload":{"turn_id":"parent-later-turn","model":"gpt-5.6-sol"}}),
            codex_test_token_line(
                "2026-08-02T08:10:02Z",
                None,
                (150, 115, 18, 3),
                Some((50, 35, 8, 1)),
            ),
        ];
        let child = vec![
            json!({
                "timestamp":"2026-08-02T08:20:00Z",
                "type":"session_meta",
                "payload":{"id":child_id,"thread_source":"agent_created_thread","source":"vscode"}
            }),
            parent[1].clone(),
            // Omit parent[2], then copy the later parent turn and usage. The
            // legacy prefix machine used to treat parent[3] as divergence and
            // admit parent[4] as child-owned while later ledger entries existed.
            parent[3].clone(),
            parent[4].clone(),
        ];

        let (root, parsed) = parse_trusted_created_thread_test(
            "codex-created-thread-internal-parent-omission",
            child_id,
            parent_id,
            &child,
        );
        assert!(parsed.snapshots.is_empty(), "{parsed:#?}");
        assert!(parsed.zero_snapshot_usage_evidence);
        assert_eq!(parsed.recognized_usage_drop_count, 1);
        assert_eq!(parsed.ownership_incomplete_file_count, 1);
        assert_eq!(parsed.dropped_usage_record_count, 1);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_created_thread_native_witness_breaks_fail_the_whole_file_closed() {
        let parent_id = "01a02589-5e24-7f10-8a93-a0c1968d8a3a";
        let child_id = "01a03e99-49cf-7460-9fd7-f7dbfd2f05e4";
        let turn_id = "01a03e99-5000-7000-8000-000000000001";

        let valid = vec![
            json!({"timestamp":"2026-08-02T08:20:00.500Z","ordinal":0,"type":"session_meta","payload":{"id":child_id,"session_id":child_id,"timestamp":"2026-08-02T08:20:00Z","thread_source":"agent_created_thread","history_mode":"paginated","source":"vscode"}}),
            json!({"timestamp":"2026-08-02T08:20:00.501Z","ordinal":1,"type":"event_msg","payload":{"type":"task_started","turn_id":turn_id,"trace_id":"0123456789abcdef0123456789abcdef","started_at":1_785_658_800_u64}}),
            json!({"timestamp":"2026-08-02T08:20:01Z","ordinal":2,"type":"turn_context","payload":{"turn_id":turn_id,"model":"gpt-5.6-sol"}}),
            codex_test_token_line(
                "2026-08-02T08:20:03Z",
                Some(3),
                (12, 8, 2, 1),
                Some((12, 8, 2, 1)),
            ),
        ];

        for (name, mut child) in [
            ("native-ordinal-gap", valid.clone()),
            ("native-ordinal-restart", valid.clone()),
            ("native-retrograde-time", valid.clone()),
            ("native-turn-mismatch", valid.clone()),
            ("native-spawn-delay", valid.clone()),
        ] {
            match name {
                "native-ordinal-gap" => child[3]["ordinal"] = json!(4),
                "native-ordinal-restart" => child[3]["ordinal"] = json!(2),
                "native-retrograde-time" => child[3]["timestamp"] = json!("2026-08-02T08:19:59Z"),
                "native-turn-mismatch" => {
                    child[2]["payload"]["turn_id"] = json!("01a03e99-5000-7000-8000-000000000002")
                }
                "native-spawn-delay" => child[0]["timestamp"] = json!("2026-08-02T08:20:10.500Z"),
                _ => unreachable!(),
            }
            let (root, parsed) =
                parse_trusted_created_thread_test(name, child_id, parent_id, &child);
            assert!(parsed.snapshots.is_empty(), "{name}: {parsed:#?}");
            assert!(parsed.report.complete(), "{name}");
            assert!(!parsed.progress_complete(), "{name}");
            assert!(parsed.zero_snapshot_usage_evidence, "{name}");
            assert_eq!(parsed.recognized_usage_drop_count, 1, "{name}");
            assert_eq!(parsed.ownership_incomplete_file_count, 1, "{name}");
            assert_eq!(parsed.dropped_usage_record_count, 1, "{name}");
            let _ = fs::remove_dir_all(root);
        }
    }

