            assert!(!scan.sidecar_census_complete, "{name}");
            assert_eq!(scan.recognized_usage_drop_count, 1, "{name}");
            assert_eq!(scan.ownership_incomplete_file_count, 1, "{name}");
            assert_eq!(scan.dropped_usage_record_count, 1, "{name}");
