    /// [regress] Unfunded archive inventory finishes within a bounded number
    /// of steps even with power allowed, preserving the plain fork child's
    /// exact body and complete parent census through paged restart. Fresh
    /// unfunded censuses sample zero archive bytes, even with a saved header.
    #[test]
    fn codex_archive_inventory_preserves_plain_usage_through_paged_restart() {
        let _lock = codex_compressed_input::tests::DECODER_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let root = temp_dir("codex-archive-paged");
        let child_id = "019fc428-0000-7000-8000-000000000001";
        let parent_id = "019fc428-0000-7000-8000-000000000002";
        let parent_turn = json!({"timestamp":"2026-08-02T08:00:01Z","type":"turn_context","payload":{"turn_id":"paged-parent-turn","model":"gpt-5.6-sol"}});
        let parent_usage = codex_test_token_line(
            "2026-08-02T08:00:02Z",
            None,
            (100, 80, 10, 2),
            Some((100, 80, 10, 2)),
        );
        let parent_later_turn = json!({"timestamp":"2026-08-02T08:30:01Z","type":"turn_context","payload":{"turn_id":"paged-parent-later","model":"gpt-5.6-sol"}});
        let parent_later_usage = codex_test_token_line(
            "2026-08-02T08:30:02Z",
            None,
            (150, 115, 18, 3),
            Some((50, 35, 8, 1)),
        );
        fs::write(
            root.join(format!(
                "rollout-2026-08-02T08-00-00-{child_id}.jsonl"
            )),
            [
                json!({"timestamp":"2026-08-02T08:20:00Z","type":"session_meta","payload":{"id":child_id,"forked_from_id":parent_id,"thread_source":"user"}}),
                parent_turn.clone(),
                parent_usage.clone(),
                json!({"timestamp":"2026-08-02T08:20:01Z","type":"turn_context","payload":{"turn_id":"paged-child-turn","model":"gpt-5.6-sol"}}),
                codex_test_token_line("2026-08-02T08:20:02Z",None,(125,98,14,3),Some((25,18,4,1))),
            ]
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n")
                + "\n",
        )
        .expect("write paged child");
        fs::write(
            root.join(format!(
                "rollout-2026-08-02T08-10-00-{parent_id}.jsonl"
            )),
            [
                json!({"timestamp":"2026-08-02T08:00:00Z","type":"session_meta","payload":{"id":parent_id,"thread_source":"user"}}),
                parent_turn,
                parent_usage,
                parent_later_turn,
                parent_later_usage,
            ]
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n")
                + "\n",
        )
        .expect("write paged parent");

        let mut control = None;
        for with_archive in [false, true] {
            if with_archive {
                let archive = root.join("zz-held.jsonl.zst");
                let header = json!({"timestamp":"2026-08-02T08:00:00Z", "type":"session_meta", "payload":{"id":"independent-compressed-session"}});
                let usage = codex_test_token_line(
                    "2026-08-02T08:00:02Z",
                    None,
                    (100, 80, 10, 2),
                    Some((100, 80, 10, 2)),
                );
                let bytes = format!("{header}\n{usage}\n");
                fs::write(
                    &archive,
                    zstd::stream::encode_all(bytes.as_bytes(), 1).unwrap(),
                )
                .unwrap();
            }
            let checkpoint = root.join("scan-index.json");
            if checkpoint.exists() {
                fs::remove_file(&checkpoint).unwrap();
            }
            let mut index = ScanIndex::default();
            let mut child_snapshot = None;
            for cycle in 0..8 {
                let mut state = OwnedSourceScan::new(
                    SnapshotSource::Codex,
                    std::slice::from_ref(&root),
                    std::mem::take(&mut index),
                    &format!("2026-08-02T09:{cycle:02}:00Z"),
                    BACKFILL_WINDOW_DAYS,
                    1,
                    None,
                    &[],
                    false,
                );
                state = state.with_sampled_acquisition(
                    Arc::new(sampled_scan::SharedCache::default()),
                    crate::transcript_acquisition::Scope("paged-encoding-fixture".into()),
                );
                let mut completed = None;
                for _ in 0..256 {
                    // Reproduce the permitting macOS gate on every platform;
                    // no cache or reservation-save owner exists on this route.
                    match state.step(None) {
                        OwnedSourceScanStep::Pending(next) => state = next,
                        OwnedSourceScanStep::Complete {
                            index: next, scan, ..
                        } => {
                            index = next;
                            completed = Some(scan);
                            break;
                        }
                    }
                }
                let mut scan = completed.expect("paged archive scan makes bounded progress");
                child_snapshot = scan
                    .snapshots
                    .iter()
                    .find(|snapshot| snapshot.source_session_id == child_id)
                    .cloned();
                finalize_scan_after_policy(SnapshotSource::Codex, &mut scan, &mut index);
                index.save(&checkpoint).expect("persist paged scan");
                index = ScanIndex::load(&checkpoint).expect("reload paged scan");
                if child_snapshot.is_some() {
                    break;
                }
            }
            let child = child_snapshot.expect("paged child converges");
            // Two available usage events: the copied prefix and the child's suffix.
            assert_eq!(
                (child.input_tokens, child.output_tokens, child.request_count),
                (125, 14, 2)
            );
            let body = snapshot_upload_body_witness(&child);
            if let Some(expected) = control.as_ref() {
                assert_eq!(
                    &body, expected,
                    "held archive must not alter plain child body"
                );
            } else {
                control = Some(body);
            }
        }
        // Isolate physical archive samples from the plain parent/child reads.
        let archive_root = root.join("unfunded");
        fs::create_dir(&archive_root).unwrap();
        let archive = archive_root.join("unfunded.jsonl.zst");
        let header = json!({"timestamp":"2026-08-02T08:00:00Z","type":"session_meta","payload":{"id":"unfunded-session","thread_source":"user"}}).to_string() + "\n";
        let mut bytes = zstd::stream::encode_all(header.as_bytes(), 1).unwrap();
        bytes.resize(8192, 0); // Both physical identity sample windows exist.
        fs::write(&archive, bytes).unwrap();
        let samples = || START_IDENTITY_SAMPLE_FOR_TEST.with(std::cell::Cell::get);
        let before = samples();
        opened_object_identity_and_stat_retained(
            SnapshotSource::Codex,
            &mut File::open(&archive).unwrap(),
            None,
            false,
            true,
        )
        .unwrap();
        assert_eq!(
            samples().1 - before.1,
            8192,
            "physical-read seam observes head and tail"
        );
        fs::write(
            &archive,
            zstd::stream::encode_all(header.as_bytes(), 1).unwrap(),
        )
        .unwrap();
        for retired_header in [false, true] {
            let checkpoint = root.join(format!("ordinary-index-{retired_header}.json"));
            let mut legacy = serde_json::to_value(ScanIndex::default()).unwrap();
            if retired_header {
                legacy["archives"] = json!({local_index_key(&archive): {"owner":"unfunded-session", "disposition":{"Held":{"cause":"CompressedAdmissionRefused", "quiet":false}}, "work":{"header":{"owner":"unfunded-session"},"attempts":1}}});
            }
            fs::write(&checkpoint, serde_json::to_vec(&legacy).unwrap()).unwrap();
            let index = ScanIndex::load(&checkpoint).unwrap();
            assert!(index.decode_holds.is_empty());
            assert!(serde_json::to_value(&index)
                .unwrap()
                .get("archives")
                .is_none());
            let mut state = OwnedSourceScan::new(
                SnapshotSource::Codex,
                std::slice::from_ref(&archive_root),
                index,
                "2026-08-02T10:00:00Z",
                BACKFILL_WINDOW_DAYS,
                10,
                None,
                &[],
                false,
            )
            .with_sampled_acquisition(
                Arc::new(sampled_scan::SharedCache::default()),
                crate::transcript_acquisition::Scope("ordinary-encoding-fixture".into()),
            );
            let mut completed = None;
            for _ in 0..1024 {
                match state.step(None) {
                    OwnedSourceScanStep::Pending(next) => state = next,
                    OwnedSourceScanStep::Complete {
                        mut index,
                        mut scan,
                        ..
                    } => {
                        assert!(scan.snapshots.is_empty(), "header-only input has no money");
                        assert!(index.accepted_snapshot_fingerprints.is_empty());
                        finalize_scan_after_policy(SnapshotSource::Codex, &mut scan, &mut index);
                        index.save(&checkpoint).unwrap();
                        completed = Some(index);
                        break;
                    }
                }
            }
            assert!(
                completed.is_some(),
                "ordinary encoded input makes bounded progress"
            );
        }
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn codex_north_star_sized_legacy_prefix_emits_only_child_responses() {
        const INHERITED_TURNS: u64 = 15_359;
        const OWN_TURNS: u64 = 156;
        const OWN_INPUT: u64 = 20_681_755;
        const OWN_CACHED: u64 = 20_253_696;
        const OWN_OUTPUT: u64 = 36_892;
        const OWN_REASONING: u64 = 13_359;

        let mut values = Vec::with_capacity((INHERITED_TURNS + OWN_TURNS + 2) as usize);
        values.push(json!({"timestamp":"2026-08-02T09:00:00Z","type":"session_meta","payload":{"id":"sanitized-north-star-child","forked_from_id":"sanitized-root","thread_source":"subagent","source":{"subagent":{"thread_spawn":{"parent_thread_id":"sanitized-root"}}}}}));
        let mut total = (0, 0, 0, 0);
        for _ in 0..INHERITED_TURNS {
            total.0 += 1_000;
            total.1 += 900;
            total.2 += 100;
            total.3 += 10;
            values.push(codex_test_token_line(
                "2026-08-02T09:00:01Z",
                None,
                total,
                Some((1_000, 900, 100, 10)),
            ));
        }
        values.push(json!({"timestamp":"2026-08-02T09:01:00Z","type":"inter_agent_communication_metadata","payload":{"trigger_turn":true}}));
        for turn in 0..OWN_TURNS {
            let remaining = OWN_TURNS - turn;
            let delta = (
                (OWN_INPUT - (total.0 - INHERITED_TURNS * 1_000)) / remaining,
                (OWN_CACHED - (total.1 - INHERITED_TURNS * 900)) / remaining,
                (OWN_OUTPUT - (total.2 - INHERITED_TURNS * 100)) / remaining,
                (OWN_REASONING - (total.3 - INHERITED_TURNS * 10)) / remaining,
            );
            total.0 += delta.0;
            total.1 += delta.1;
            total.2 += delta.2;
            total.3 += delta.3;
            values.push(codex_test_token_line(
                "2026-08-02T09:01:01Z",
                None,
                total,
                Some(delta),
            ));
        }
        let path = write_codex_test_values("codex-north-star-sized-exclusive", &values);
        let item = parse_codex_jsonl_file(&path, "2026-08-02T09:02:00Z", "fp".to_string())
            .expect("parse North Star-sized fixture")
            .remove(0);
        assert_eq!(
            (
                item.input_tokens,
                item.cache_read_tokens,
                item.output_tokens,
                item.reasoning_output_tokens,
                item.request_count
            ),
            (OWN_INPUT, OWN_CACHED, OWN_OUTPUT, OWN_REASONING, OWN_TURNS)
        );
        let _ = fs::remove_file(path);
    }

    #[test]
    fn codex_cumulative_split_across_plan_window_rollover_buckets_correctly() {
        // Regression: a single Codex session that crosses a `secondary.resets_at`
        // day-boundary must not double-count the cumulative. Cumulative
        // 100/40 → 130/55 is monotonic, so no session restart; the delta is
        // 30/15. In v6 the two deltas land in two hour buckets (23:00 and
        // 00:00) under the same RowKey (plan_window_bucket is stripped, so
        // the row identity collapses). Top-level totals: 130/55.
        let path = temp_file("codex-rollover");
        fs::write(
            &path,
            concat!(
                "{\"timestamp\":\"2026-05-31T23:00:00Z\",\"type\":\"session_meta\",\"payload\":{\"id\":\"codex-rollover-session\"}}\n",
                "{\"timestamp\":\"2026-05-31T23:30:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":100,\"output_tokens\":40,\"request_count\":1},\"model\":\"gpt-5.5\"},\"rate_limits\":{\"plan_type\":\"pro\",\"secondary\":{\"resets_at\":1780123199}}}}\n",
                "{\"timestamp\":\"2026-06-01T00:30:00Z\",\"type\":\"event_msg\",\"payload\":{\"type\":\"token_count\",\"info\":{\"total_token_usage\":{\"input_tokens\":130,\"output_tokens\":55,\"request_count\":2},\"model\":\"gpt-5.5\"},\"rate_limits\":{\"plan_type\":\"pro\",\"secondary\":{\"resets_at\":1780209599}}}}\n"
            ),
        )
        .expect("write fixture");

        let items = parse_codex_jsonl_file(
            &path,
            "2026-06-01T00:35:00Z",
            "rollover-fingerprint".to_string(),
        )
        .expect("parse");
        assert_eq!(items.len(), 1);
        let item = &items[0];
        // Top-level totals match the latest cumulative.
        assert_eq!(item.input_tokens, 130);
        assert_eq!(item.output_tokens, 55);
        // Two hour buckets, each with the right per-hour delta.
        assert_eq!(item.usage_buckets.len(), 2);
        let pre = item
            .usage_buckets
            .iter()
            .find(|b| b.bucket_start == "2026-05-31T23:00:00Z")
            .expect("pre-rollover bucket");
        let post = item
            .usage_buckets
            .iter()
            .find(|b| b.bucket_start == "2026-06-01T00:00:00Z")
            .expect("post-rollover bucket");
        assert_eq!(pre.model_usage[0].input_tokens, 100);
        assert_eq!(pre.model_usage[0].output_tokens, 40);
        assert_eq!(
            post.model_usage[0].input_tokens, 30,
            "post-rollover gets only the delta"
        );
        assert_eq!(post.model_usage[0].output_tokens, 15);

        let _ = fs::remove_file(path);
    }

