    #[test]
    fn snapshot_preflight_enforces_item_and_batch_wire_byte_caps() {
        let source = SnapshotSource::ClaudeCode;
        let mut oversized_item = valid_v6_batch_request();
        oversized_item.snapshots[0].session_display_name =
            Some("x".repeat(MAX_SNAPSHOT_ITEM_WIRE_BYTES));
        oversized_item.snapshots[0].snapshot_fingerprint =
            snapshot_fingerprint(source, &oversized_item.snapshots[0]);
        let item_error = validate_snapshot_batch_request(&oversized_item)
            .expect_err("oversized item fails before network I/O");
        assert!(item_error.contains("wire body"), "{item_error}");

        let mut batch = valid_v6_batch_request();
        let mut items = Vec::new();
        for index in 0..40 {
            let mut item = batch.snapshots[0].clone();
            item.source_session_id = format!("large-session-{index}");
            item.session_display_name = Some("y".repeat(300 * 1024));
            item.snapshot_fingerprint = snapshot_fingerprint(source, &item);
            items.push(item);
        }
        batch.snapshots = items;
        let batch_error = validate_snapshot_batch_request(&batch)
            .expect_err("oversized batch fails before network I/O");
        assert!(batch_error.contains("batch wire body"), "{batch_error}");
    }

    #[test]
    fn semantic_envelope_cross_language_golden_covers_all_valid_policies() {
        let mut base = valid_v6_batch_request()
            .snapshots
            .into_iter()
            .next()
            .expect("fixture snapshot");
        base.source_session_id = "session-שלום-東京-null".to_string();
        base.session_display_name = Some("כותרת 東京".to_string());
        base.session_display_name_source = Some("fixture".to_string());
        base.workspace_display_label = Some("workspace-é".to_string());
        base.workspace_label_source = Some("fixture".to_string());
        base.repository_label = Some("repo-東京".to_string());
        base.repository_label_source = Some("fixture".to_string());
        base.session_artifacts = vec![SessionArtifact {
            kind: "pull_request".to_string(),
            value: "https://github.com/example/repo/pull/7".to_string(),
        }];
        base.origin = Some(SnapshotOrigin {
            thread_source: Some("subagent".to_string()),
            originator: Some("codex_work_desktop".to_string()),
            ..SnapshotOrigin::default()
        });

        let mut cases = Vec::new();
        for source in [
            SnapshotSource::Pi,
            SnapshotSource::Codex,
            SnapshotSource::ClaudeCode,
        ] {
            for policy in crate::snapshot_audit::valid_upload_policies() {
                let mut item = base.clone();
                apply_upload_policy(source, std::slice::from_mut(&mut item), policy);
                let component_hashes = snapshot_semantic_component_hashes(source, &item);
                item.snapshot_fingerprint = snapshot_fingerprint_from_component_hashes(
                    source,
                    &item.source_session_id,
                    &component_hashes,
                );
                let envelope = snapshot_semantic_envelope(source, &item, policy);
                let content_body = snapshot_content_identity_body(
                    source,
                    &item.source_session_id,
                    &envelope.component_hashes,
                );
                let canonical_bytes = crate::canonical_json::canonicalize(&content_body)
                    .expect("canonicalize content identity body");
                let revision_v2_body =
                    snapshot_revision_v2_body(source, &item, policy, &envelope.component_hashes);
                cases.push(json!({
                    "source": source.api_slug(),
                    "source_session_id": item.source_session_id,
                    "upload_policy": policy,
                    "component_hashes": envelope.component_hashes,
                    // The `content_hash` inputs travel with the expected hash so
                    // the other language recomputes the canonicalization from
                    // the same material instead of trusting a copied digest.
                    "policy_neutral_component_hashes":
                        policy_neutral_component_hashes(&envelope.component_hashes),
                    "snapshot_fingerprint": item.snapshot_fingerprint,
                    "revision_hash": envelope.revision_hash,
                    "revision_v2_body": revision_v2_body,
                    "revision_v2_hash": envelope.revision_v2_hash,
                    "content_hash": envelope.content_hash,
                    "hash_epoch": envelope.hash_epoch,
                    "content_canonical_bytes": canonical_bytes.len(),
                    "envelope_bytes": serde_json::to_vec(&envelope).expect("serialize envelope").len(),
                }));
            }
        }
        let actual = json!({
            "schema_version": "semantic_envelope_golden:v3",
            "component_contract_version": SNAPSHOT_SEMANTIC_CONTRACT_VERSION,
            "revision_contract_version": SNAPSHOT_REVISION_CONTRACT_VERSION,
            "revision_v2_contract_version": SNAPSHOT_REVISION_V2_CONTRACT_VERSION,
            "canonicalization": crate::canonical_json::CANONICAL_JSON_CONTRACT_VERSION,
            "content_hash_epoch": SNAPSHOT_CONTENT_HASH_EPOCH,
            "policy_neutral_components": POLICY_NEUTRAL_COMPONENTS,
            "cases": cases,
        });
        if std::env::var_os("UPDATE_SEMANTIC_ENVELOPE_GOLDEN").is_some() {
            fs::write(
                Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("../../fixtures/snapshot-audit/semantic-envelope-golden.json"),
                format!(
                    "{}\n",
                    serde_json::to_string_pretty(&actual).expect("serialize golden")
                ),
            )
            .expect("write semantic envelope golden");
        }
        let expected: Value = serde_json::from_str(include_str!(
            "../../../fixtures/snapshot-audit/semantic-envelope-golden.json"
        ))
        .expect("parse semantic envelope golden");
        assert_eq!(actual, expected);
        assert_eq!(actual["cases"].as_array().expect("cases").len(), 60);
        assert!(actual["cases"]
            .as_array()
            .expect("cases")
            .iter()
            .all(|case| case["envelope_bytes"].as_u64().expect("size")
                <= MAX_SEMANTIC_ENVELOPE_BYTES as u64));
        // The policy toggles are what the corpus sweeps, so the corpus itself
        // is the strongest available statement that identity survives them: for
        // each source, all twenty policies must agree on `content_hash` while
        // the full component set does not.
        for source in ["pi", "codex", "claude_code"] {
            let per_source = actual["cases"]
                .as_array()
                .expect("cases")
                .iter()
                .filter(|case| case["source"] == source)
                .collect::<Vec<_>>();
            assert_eq!(per_source.len(), 20);
            let content_hashes = per_source
                .iter()
                .map(|case| case["content_hash"].as_str().expect("content hash"))
                .collect::<BTreeSet<_>>();
            assert_eq!(
                content_hashes.len(),
                1,
                "content_hash must not depend on upload policy"
            );
            let fingerprints = per_source
                .iter()
                .map(|case| case["snapshot_fingerprint"].as_str().expect("fingerprint"))
                .collect::<BTreeSet<_>>();
            assert!(
                fingerprints.len() > 1,
                "the policy-scoped fingerprint must still move with policy"
            );
        }
    }

    #[test]
    fn content_hash_ignores_scan_state_parser_provenance_and_display_policy() {
        // The exclusion list from the identity contract, one mutation each. Any
        // of these changing `content_hash` would re-mint every session's
        // identity on a scan, a parser bump, or a privacy toggle.
        let source = SnapshotSource::ClaudeCode;
        let base = valid_v6_batch_request()
            .snapshots
            .into_iter()
            .next()
            .expect("fixture snapshot");
        let content_hash = |item: &SnapshotItem| {
            snapshot_content_hash(
                source,
                &item.source_session_id,
                &snapshot_semantic_component_hashes(source, item),
            )
        };
        let expected = content_hash(&base);

        let mut scan_time = base.clone();
        scan_time.collected_at = "2027-01-01T00:00:00Z".to_string();
        assert_eq!(content_hash(&scan_time), expected, "scan time");

        let mut fingerprint = base.clone();
        fingerprint.source_file_fingerprint = Some("f".repeat(32));
        assert_eq!(content_hash(&fingerprint), expected, "file fingerprint");
        assert_ne!(
            snapshot_revision_hash(
                source,
                &fingerprint,
                &snapshot_semantic_component_hashes(source, &fingerprint)
            ),
            snapshot_revision_hash(
                source,
                &base,
                &snapshot_semantic_component_hashes(source, &base)
            ),
            "the revision hash — the re-upload trigger — must still move"
        );

        let mut collector = base.clone();
        collector.provenance.collector = "some_other_collector".to_string();
        collector.provenance.source_file_count = 41;
        assert_eq!(content_hash(&collector), expected, "collector provenance");

        let mut display = base.clone();
        display.session_display_name = Some("a title".to_string());
        display.session_display_name_source = Some("fixture".to_string());
        display.workspace_display_label = Some("a workspace".to_string());
        display.workspace_label_source = Some("fixture".to_string());
        display.session_artifacts = vec![SessionArtifact {
            kind: "pull_request".to_string(),
            value: "https://github.com/example/repo/pull/7".to_string(),
        }];
        assert_eq!(content_hash(&display), expected, "display identity");
        let mut suppressed = display.clone();
        apply_upload_policy(
            source,
            std::slice::from_mut(&mut suppressed),
            SnapshotUploadPolicy {
                session_titles_enabled: false,
                workspace_labels_enabled: false,
                session_artifacts_enabled: false,
                session_attribution_enabled: false,
                session_attribution_labels_enabled: false,
            },
        );
        assert_eq!(content_hash(&suppressed), expected, "policy suppression");

        // Session-start facts are additive wire evidence: content hash,
        // fingerprint and upload-body witness all ignore them.
        let mut session_start = base.clone();
        session_start.session_start = Some(Box::new(SnapshotSessionStart {
            client_version: Some("2.1.300".to_string()),
            opening_request_count: Some(3),
            opening_files: vec![SnapshotOpeningFile {
                request: 2,
                tool: "Read".to_string(),
                repo_path: Some("docs/guide.md".to_string()),
                chars: 10,
                reads: 1,
                instruction_segments: 2,
                ..SnapshotOpeningFile::default()
            }],
            opening_file_overflow: Some(0),
            start_chars_tools: Some(16),
            ..SnapshotSessionStart::default()
        }));
        assert_eq!(content_hash(&session_start), expected, "session start");
        assert_eq!(
            snapshot_fingerprint(source, &session_start),
            snapshot_fingerprint(source, &base),
            "session start fingerprint"
        );
        assert_eq!(
            snapshot_upload_body_witness_payload(&session_start),
            snapshot_upload_body_witness_payload(&base),
            "session start witness"
        );
        assert_eq!(
            snapshot_upload_body_witness(&session_start),
            snapshot_upload_body_witness(&base),
            "session start witness digest"
        );

        // Parser and scan-identity versions are compile-time constants, so the
        // statement that they are outside identity is made structurally: the
        // canonical body carries neither, and it carries exactly five keys.
        let body = snapshot_content_identity_body(
            source,
            &base.source_session_id,
            &snapshot_semantic_component_hashes(source, &base),
        );
        assert_eq!(
            body.as_object()
                .expect("body object")
                .keys()
                .map(String::as_str)
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([
                "canonicalization",
                "components",
                "hash_epoch",
                "source",
                "source_session_id",
            ])
        );
        let encoded = body.to_string();
        for excluded in [
            source.parser_version(),
            source.scan_identity_version(),
            &base.collected_at,
        ] {
            assert!(
                !encoded.contains(excluded),
                "identity body must not carry {excluded}"
            );
        }
    }

    #[test]
    fn revision_v2_ignores_retry_clock_and_unrelated_inventory_but_binds_entity_witness() {
        let source = SnapshotSource::Codex;
        let policy = SnapshotUploadPolicy::default();
        let mut base = valid_v6_batch_request()
            .snapshots
            .into_iter()
            .next()
            .expect("fixture snapshot");
        let hashes = snapshot_semantic_component_hashes(source, &base);
        let expected = snapshot_revision_v2_hash(source, &base, policy, &hashes);

        base.collected_at = "2030-01-01T00:00:00Z".to_string();
        base.provenance.source_file_count = 9_999;
        assert_eq!(
            snapshot_revision_v2_hash(source, &base, policy, &hashes),
            expected,
            "retry wall clock and unrelated transcript inventory are not revision evidence"
        );

        base.source_file_fingerprint = Some("changed-opened-object-witness".to_string());
        assert_ne!(
            snapshot_revision_v2_hash(source, &base, policy, &hashes),
            expected,
            "the exact opened/source-file witness is revision evidence"
        );
    }

    #[test]
    fn content_hash_moves_with_every_policy_neutral_component() {
        let source = SnapshotSource::ClaudeCode;
        let base = valid_v6_batch_request()
            .snapshots
            .into_iter()
            .next()
            .expect("fixture snapshot");
        let content_hash = |item: &SnapshotItem| {
            snapshot_content_hash(
                source,
                &item.source_session_id,
                &snapshot_semantic_component_hashes(source, item),
            )
        };
        let expected = content_hash(&base);

        let mut usage = base.clone();
        usage.input_tokens += 1;
        assert_ne!(content_hash(&usage), expected, "usage_accounting");

        let mut lifecycle = base.clone();
        lifecycle.status = "completed".to_string();
        assert_ne!(content_hash(&lifecycle), expected, "lifecycle_activity");

        let mut latency = base.clone();
        latency.avg_duration_ms = Some(4_321);
        assert_ne!(content_hash(&latency), expected, "latency");

        let mut posture = base.clone();
        posture.peak_context_fill_tokens = Some(123_456);
        assert_ne!(content_hash(&posture), expected, "context_posture");

        let mut session = base.clone();
        session.source_session_id = "another-session".to_string();
        assert_ne!(content_hash(&session), expected, "session scope");
        assert_ne!(
            snapshot_content_hash(
                SnapshotSource::Codex,
                &base.source_session_id,
                &snapshot_semantic_component_hashes(source, &base)
            ),
            expected,
            "source scope"
        );
    }

    pub(super) fn manifest_index_entry(fingerprint: Option<&str>) -> ScanIndexEntry {
        ScanIndexEntry {
            codex_fragment: None,
            size_bytes: 1,
            modified_unix_seconds: 2,
            modified_unix_nanos: Some(3),
            source_file_fingerprint: "source".to_string(),
            last_snapshot_fingerprint: fingerprint.map(str::to_string),
            last_upload_body_witness: None,
            effective_upload_body_witness_revision: 0,
            scan_identity_version: Some("semantic_sync:v1".to_string()),
            codex_joined_member_set: None,
            codex_captured_joined_member_set: None,
            codex_protected_owner: None,
            codex_applied_tier_receipt: None,
            codex_applied_tier_receipt_required: false,
            codex_captured_tier_receipt: None,
            codex_captured_tier_receipt_required: false,
            codex_captured_uncommitted: false,
            codex_counting_v2: false,
            codex_counting_owner: None,
            opened_changed_nanos: 0,
            opened_birth_nanos: 0,
            upload_context_receipt: None,
        }
    }

    #[test]
    fn committable_subset_commits_only_what_the_server_holds() {
        let mut committed = ScanIndex::default();
        committed.files.insert(
            "unchanged.jsonl".to_string(),
            manifest_index_entry(Some("aa")),
        );
        committed.files.insert(
            "pending.jsonl".to_string(),
            manifest_index_entry(Some("old")),
        );
        committed.files.insert(
            "became-empty.jsonl".to_string(),
            manifest_index_entry(Some("old-empty-entity")),
        );
        committed.file_snapshot_fingerprints.insert(
            "became-empty.jsonl".to_string(),
            BTreeSet::from(["old-empty-entity".to_string()]),
        );

        let mut scanned = committed.clone();
        // A semantic no-op: same fingerprint as the committed entry, so the
        // server already holds this content even though nothing was uploaded.
        scanned.files.insert(
            "unchanged.jsonl".to_string(),
            ScanIndexEntry {
                codex_fragment: None,
                size_bytes: 42,
                ..manifest_index_entry(Some("aa"))
            },
        );
        // Changed and accepted this pass.
        scanned.files.insert(
            "accepted.jsonl".to_string(),
            manifest_index_entry(Some("bb")),
        );
        // Changed and NOT accepted: committing it would drop the entity, because
        // the next scan skips an unchanged transcript.
        scanned.files.insert(
            "pending.jsonl".to_string(),
            manifest_index_entry(Some("cc")),
        );
        // Parsed to nothing at all: there is no entity to lose.
        scanned
            .files
            .insert("empty.jsonl".to_string(), manifest_index_entry(None));
        scanned
            .confirmed_empty_files
            .insert("empty.jsonl".to_string());
        // This file previously had a server entity. Its absence cannot become
        // authoritative during a shed/partial commit.
        scanned
            .files
            .insert("became-empty.jsonl".to_string(), manifest_index_entry(None));
        scanned
            .confirmed_empty_files
            .insert("became-empty.jsonl".to_string());
        scanned
            .file_snapshot_fingerprints
            .remove("became-empty.jsonl");

        let accepted = BTreeSet::from(["bb".to_string()]);
        let committable = scanned.committable_subset(&committed, &accepted, &BTreeMap::new());

        assert_eq!(
            committable.files["unchanged.jsonl"].size_bytes, 42,
            "a semantic no-op advances: the server already has that content"
        );
        assert!(committable.files.contains_key("accepted.jsonl"));
        assert!(committable.files.contains_key("empty.jsonl"));
        assert_eq!(
            committable.files["became-empty.jsonl"]
                .last_snapshot_fingerprint
                .as_deref(),
            Some("old-empty-entity")
        );
        assert!(!committable
            .confirmed_empty_files
            .contains("became-empty.jsonl"));
        assert_eq!(
            committable.files["pending.jsonl"]
                .last_snapshot_fingerprint
                .as_deref(),
            Some("old"),
            "an unaccepted entity keeps its committed entry so the next scan retries it"
        );

        // Persist accepted siblings even when a page leaves a held file and
        // missing prior files behind. Rebuild the next subset before saving it.
        let retry = scanned.committable_subset_with_local_holds(
            &committable,
            &BTreeSet::from(["bb".to_string()]),
            &BTreeMap::new(),
            &BTreeSet::from(["cc".to_string()]),
        );
        assert_eq!(
            retry.files["pending.jsonl"]
                .last_snapshot_fingerprint
                .as_deref(),
            Some("old")
        );
        let accepted_retry = scanned.committable_subset(
            &retry,
            &BTreeSet::from(["bb".to_string(), "cc".to_string()]),
            &BTreeMap::new(),
        );
        let mut removed = accepted_retry.clone();
        removed.files.remove("accepted.jsonl");
        state_v2::money_test_support::assert_selected_saves(
            scan_index_persistence::Source::Claude,
            &committed,
            &[committable.clone(), retry, accepted_retry, removed],
        );

        // A first-time file that was not accepted has no committed entry to fall
        // back to, so it must not appear at all.
        let mut fresh = ScanIndex::default();
        fresh
            .files
            .insert("new.jsonl".to_string(), manifest_index_entry(Some("dd")));
        let committable =
            fresh.committable_subset(&ScanIndex::default(), &BTreeSet::new(), &BTreeMap::new());
        assert!(committable.files.is_empty());
    }

    /// One upload page that ended in a refused item: a re-read sibling whose
    /// unchanged entity was not resent (its committed witness was cleared),
    /// a sibling accepted this pass, and the refused item's file.
    fn refused_item_page() -> (ScanIndex, ScanIndex, BTreeSet<String>, BTreeSet<String>) {
        let mut committed = ScanIndex::default();
        let mut cleared = manifest_index_entry(Some("unchanged"));
        cleared.source_file_fingerprint.clear();
        committed.files.insert("reread.jsonl".into(), cleared);
        committed
            .files
            .insert("refused.jsonl".into(), manifest_index_entry(Some("old")));
        for (key, fingerprint) in [("reread.jsonl", "unchanged"), ("refused.jsonl", "old")] {
            committed
                .file_snapshot_fingerprints
                .insert(key.into(), BTreeSet::from([fingerprint.to_string()]));
            committed
                .accepted_snapshot_fingerprints
                .insert(fingerprint.to_string());
        }
        let mut scanned = committed.clone();
        for (key, fingerprint) in [
            ("reread.jsonl", "unchanged"),
            ("accepted.jsonl", "accepted"),
            ("refused.jsonl", "refused"),
        ] {
            scanned
                .files
                .insert(key.into(), manifest_index_entry(Some(fingerprint)));
            scanned
                .file_snapshot_fingerprints
                .insert(key.into(), BTreeSet::from([fingerprint.to_string()]));
        }
        (
            committed,
            scanned,
            BTreeSet::from(["accepted".to_string()]),
            BTreeSet::from(["refused".to_string()]),
        )
    }

    /// [regress] A page ending in one refused item kept only this pass's
    /// ACKs, so its re-read siblings returned to their cleared witnesses and
    /// were read again next pass. Only the refused file stays owed now.
    #[test]
    fn refused_item_keeps_only_its_own_file_owed() {
        let (committed, scanned, accepted, refused) = refused_item_page();
        let no_holds = BTreeSet::new();
        let ack_only = scanned.committable_subset_for_upload(
            &committed,
            &accepted,
            &BTreeMap::new(),
            &no_holds,
            false,
        );
        assert!(ack_only.files["reread.jsonl"]
            .source_file_fingerprint
            .is_empty());

        let scoped = scanned.committable_subset_for_upload(
            &committed,
            &accepted,
            &BTreeMap::new(),
            &refused,
            true,
        );
        assert_eq!(
            scoped.files["reread.jsonl"].source_file_fingerprint,
            "source"
        );
        assert_eq!(
            scoped.files["refused.jsonl"]
                .last_snapshot_fingerprint
                .as_deref(),
            Some("old"),
            "the refused item keeps its committed entry, so the next scan retries it"
        );
    }

    /// [money] Siblings of a refused item commit exactly as on a clean page;
    /// the refused entity gets no credit and its file keeps its prior debt.
    #[test]
    fn refused_item_siblings_commit_as_a_clean_page() {
        let (committed, scanned, accepted, refused) = refused_item_page();
        let mut clean = scanned.clone();
        clean.record_accepted_snapshot_fingerprints(&accepted);
        let scoped = scanned.committable_subset_for_upload(
            &committed,
            &accepted,
            &BTreeMap::new(),
            &refused,
            true,
        );
        let entry = |index: &ScanIndex, key: &str| {
            (
                serde_json::to_value(&index.files[key]).unwrap(),
                index.file_snapshot_fingerprints[key].clone(),
            )
        };
        for key in ["reread.jsonl", "accepted.jsonl"] {
            assert_eq!(entry(&scoped, key), entry(&clean, key), "{key}");
        }
        assert_eq!(
            entry(&scoped, "refused.jsonl"),
            entry(&committed, "refused.jsonl")
        );
        let mut credited = scoped.accepted_snapshot_fingerprints.clone();
        assert!(credited.remove("old"), "the prior acceptance stays");
        assert!(!credited.contains("refused"));
        assert_eq!(credited, clean.accepted_snapshot_fingerprints);
    }

    #[test]
    fn partial_commit_preserves_rearm_debt_without_accepting_held_revision() {
        let key = "/opaque/rearmed.jsonl".to_string();
        let mut previous = ScanIndex::default();
        let mut entry = manifest_index_entry(Some("old-entity"));
        entry.last_upload_body_witness = Some("old-body".to_string());
        previous.files.insert(key.clone(), entry);
        previous
            .file_snapshot_fingerprints
            .insert(key.clone(), BTreeSet::from(["old-entity".to_string()]));
        previous
            .accepted_snapshot_fingerprints
            .insert("old-entity".to_string());

        let mut scanned = previous.clone();
        let working = scanned.files.get_mut(&key).unwrap();
        working.source_file_fingerprint.clear();
        working.last_snapshot_fingerprint = Some("held-entity".to_string());
        working.last_upload_body_witness = Some("held-body".to_string());
        working.size_bytes = 42;
        scanned
            .file_snapshot_fingerprints
            .insert(key.clone(), BTreeSet::from(["held-entity".to_string()]));

        let checkpoint = scanned.committable_subset(&previous, &BTreeSet::new(), &BTreeMap::new());
        let saved: ScanIndex =
            serde_json::from_slice(&serde_json::to_vec(&checkpoint).unwrap()).unwrap();
        let retained = &saved.files[&key];
        assert!(retained.source_file_fingerprint.is_empty());
        assert_eq!(retained.size_bytes, previous.files[&key].size_bytes);
        assert_eq!(
            retained.last_snapshot_fingerprint.as_deref(),
            Some("old-entity")
        );
        assert_eq!(
            retained.last_upload_body_witness.as_deref(),
            Some("old-body")
        );
        assert_eq!(
            saved.file_snapshot_fingerprints[&key],
            previous.file_snapshot_fingerprints[&key]
        );
        assert_eq!(
            saved.accepted_snapshot_fingerprints,
            previous.accepted_snapshot_fingerprints
        );

        // Without an explicit re-arm, the unaccepted entry still retains its
        // complete old source/body checkpoint; this change grants no receipt.
        scanned.files.get_mut(&key).unwrap().source_file_fingerprint = "changed-source".into();
        let ordinary = scanned.committable_subset(&previous, &BTreeSet::new(), &BTreeMap::new());
        assert_eq!(
            ordinary.files[&key].source_file_fingerprint,
            previous.files[&key].source_file_fingerprint
        );
    }

    /// A held-page subset copies no file entry that no carry changes: safe
    /// and restored entries keep the source's shared handle.
    #[test]
    fn held_page_subset_shares_every_entry_no_carry_changes() {
        let mut previous = ScanIndex::default();
        for n in 0..3 {
            let key = format!("/opaque/{n}.jsonl");
            let entity = format!("entity-{n}");
            previous
                .files
                .insert(key.clone(), manifest_index_entry(Some(entity.as_str())));
            previous
                .file_snapshot_fingerprints
                .insert(key, BTreeSet::from([entity]));
        }
        let mut scanned = previous.clone();
        let held = scanned.files.get_mut("/opaque/0.jsonl").unwrap();
        held.last_snapshot_fingerprint = Some("held-entity".into());
        held.size_bytes = 42;
        scanned.file_snapshot_fingerprints.insert(
            "/opaque/0.jsonl".into(),
            BTreeSet::from(["held-entity".to_string()]),
        );

        let subset = scanned.committable_subset_with_local_holds(
            &previous,
            &BTreeSet::from(["entity-1".to_string()]),
            &BTreeMap::new(),
            &BTreeSet::from(["held-entity".to_string()]),
        );
        assert_eq!(subset.files.len(), 3);
        for (key, entry) in subset.files.iter_shared() {
            assert!(
                Shared::ptr_eq(entry, previous.files.get_shared(key).unwrap()),
                "{key} was copied"
            );
        }
    }

    /// The subset still applies both carries where they change an entry,
    /// with today's values, and copies no entry its carry leaves equal.
    #[test]
    fn held_page_subset_applies_debt_and_audit_carries() {
        let mut previous = ScanIndex::default();
        let mut add = |key: &str, version: String| {
            let mut entry = manifest_index_entry(Some(format!("{key}-entity").as_str()));
            entry.scan_identity_version = Some(version);
            previous.files.insert(key.into(), entry);
        };
        add("owed", "semantic_sync:v1".into());
        add("v1", "semantic_sync:v2+sampled_unverified:v1:500".into());
        add("v2-earlier", sampled_audit::marker(300));
        add("v2-same", sampled_audit::marker(200));
        let mut scanned = previous.clone();
        let owed = scanned.files.get_mut("owed").unwrap();
        owed.source_file_fingerprint.clear();
        owed.last_snapshot_fingerprint = Some("held-owed".into());
        let earlier = scanned.files.get_mut("v2-earlier").unwrap();
        earlier.scan_identity_version = Some(sampled_audit::marker(200));
        earlier.last_snapshot_fingerprint = Some("held-v2".into());

        let subset = scanned.committable_subset_with_local_holds(
            &previous,
            &BTreeSet::new(),
            &BTreeMap::new(),
            &BTreeSet::from(["held-owed".to_string(), "held-v2".to_string()]),
        );
        let owed = &subset.files["owed"];
        assert!(owed.source_file_fingerprint.is_empty());
        assert_eq!(
            owed.last_snapshot_fingerprint.as_deref(),
            Some("owed-entity")
        );
        assert_eq!(
            subset.files["v1"].scan_identity_version.as_deref(),
            Some("semantic_sync:v2+sampled_unverified:v2:500:p")
        );
        assert_eq!(
            subset.files["v2-earlier"].scan_identity_version.as_deref(),
            Some("semantic_sync:v2+sampled_unverified:v2:200:c")
        );
        assert_eq!(
            subset.files["v2-earlier"]
                .last_snapshot_fingerprint
                .as_deref(),
            Some("v2-earlier-entity")
        );
        assert!(Shared::ptr_eq(
            subset.files.get_shared("v2-same").unwrap(),
            previous.files.get_shared("v2-same").unwrap()
        ));
    }

    /// R11/R12: an exact refusal re-offer lease re-reads an unchanged,
    /// already-passed file through the ordinary retry predicate, but a
    /// Claude family hold keeps its own earlier gate.
    #[test]
    fn reason_reoffer_lease_reparses_unchanged_file_but_never_bypasses_a_family_hold() {
        let root = "2338a80a-f36e-4cbc-a5bb-50fc66430ba5";
        let key = format!("/opaque/{root}.jsonl");
        let mut index = ScanIndex::default();
        let mut entry = manifest_index_entry(Some("old-entity"));
        entry.scan_identity_version = Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
        // A family hold binds a well-formed source revision.
        entry.source_file_fingerprint = "a".repeat(64);
        index.files.insert(key.clone(), entry.clone());
        index
            .file_snapshot_fingerprints
            .insert(key.clone(), BTreeSet::from(["old-entity".to_string()]));
        index
            .snapshot_activity_at
            .insert("old-entity".into(), Some("2026-10-14T10:00:00Z".into()));
        // The exact refusal's terminal record, as the uploader leaves it.
        index.quarantined_snapshot_fingerprints.insert(
            "old-entity".into(),
            SnapshotQuarantineRecord {
                contract_retry_claims: None,
                reconstruction_contract:
                    crate::snapshots::terminal_contract_retry::current_contract(),
                witness: snapshot_quarantine_witness(SnapshotSource::ClaudeCode),
                retry_after_unix_seconds: 0,
                upload_body_witness: Some("old-body".into()),
                failed_reconstruction_count: MAX_SNAPSHOT_RECONSTRUCTION_FAILURES,
                disposition: SnapshotQuarantineDisposition::UnprovenTerminal,
            },
        );
        let mut candidate = test_candidate(PathBuf::from(&key));
        candidate.size_bytes = entry.size_bytes;
        candidate.modified_unix_seconds = entry.modified_unix_seconds;
        candidate.modified_unix_nanos = entry.modified_unix_nanos.unwrap();
        candidate.source_file_fingerprint = entry.source_file_fingerprint.clone();
        assert_eq!(
            index.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip
        );
        assert!(!index.quarantine_requires_retry_body("old-entity", "old-body"));

        let hinted = index.activate_reason_reoffer_retries(BTreeMap::from([(
            "old-entity".to_string(),
            "old-body".to_string(),
        )]));
        assert_eq!(hinted, vec![PathBuf::from(&key)], "only the leased file");
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            (
                CandidateDecision::Parse,
                Some(CandidateParseReason::ActivityOrQuarantineRetry)
            )
        );
        assert!(
            index.quarantine_requires_retry_body("old-entity", "old-body"),
            "finalization keeps the leased body instead of a semantic no-op"
        );
        // Runtime only: neither a save nor a committable subset persists it.
        let saved: ScanIndex =
            serde_json::from_slice(&serde_json::to_vec(&index).unwrap()).unwrap();
        assert_eq!(
            saved.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip
        );

        index.insert_unproven_terminal_claude_authority_for_test(
            root,
            &candidate.source_file_fingerprint,
        );
        assert_eq!(
            index.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip,
            "a lease is scheduling permission only, never a family-hold bypass"
        );
        assert!(index
            .activate_reason_reoffer_retries(BTreeMap::new())
            .is_empty());
    }

    /// [regress] O1: an exact-body cooldown defers only the ordinary retry of its own
    /// retained conflict on an unchanged file. A changed file, a lease, a
    /// changed quarantine contract, another body or an unrelated due sibling
    /// in the same file still selects it. The conflict debt is untouched,
    /// the view is runtime only, and deferrals count distinct entities.
    #[test]
    fn reason_reoffer_cooldown_defers_only_the_retained_exact_body_retry() {
        let key = "/opaque/cooldown.jsonl".to_string();
        let mut index = ScanIndex::default();
        index.activate_quarantine_witness(SnapshotSource::ClaudeCode);
        let mut entry = manifest_index_entry(Some("refused-entity"));
        entry.scan_identity_version = Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
        index.files.insert(key.clone(), entry.clone());
        index
            .file_snapshot_fingerprints
            .insert(key.clone(), BTreeSet::from(["refused-entity".to_string()]));
        index
            .snapshot_activity_at
            .insert("refused-entity".into(), Some("2026-10-14T10:00:00Z".into()));
        // The newer conflict on the exact refused body, its timer due.
        let conflict = SnapshotQuarantineRecord {
            contract_retry_claims: None,
            reconstruction_contract: crate::snapshots::terminal_contract_retry::current_contract(),
            witness: snapshot_quarantine_witness(SnapshotSource::ClaudeCode),
            retry_after_unix_seconds: 0,
            upload_body_witness: Some("refused-body".into()),
            failed_reconstruction_count: 0,
            disposition: SnapshotQuarantineDisposition::RetryPending,
        };
        index
            .quarantined_snapshot_fingerprints
            .insert("refused-entity".into(), conflict.clone());
        let mut candidate = test_candidate(PathBuf::from(&key));
        candidate.size_bytes = entry.size_bytes;
        candidate.modified_unix_seconds = entry.modified_unix_seconds;
        candidate.modified_unix_nanos = entry.modified_unix_nanos.unwrap();
        candidate.source_file_fingerprint = entry.source_file_fingerprint.clone();
        let reread = (
            CandidateDecision::Parse,
            Some(CandidateParseReason::ActivityOrQuarantineRetry),
        );
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            reread
        );

        let cooldown = BTreeMap::from([("refused-entity".to_string(), "refused-body".to_string())]);
        index.activate_reason_reoffer_cooldowns(cooldown.clone());
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            (CandidateDecision::Skip, None)
        );
        assert!(
            index.quarantine_requires_retry("refused-entity"),
            "the conflict debt itself is unchanged"
        );
        index.note_reason_reoffer_cooldown_candidate(&candidate, true);
        index.note_reason_reoffer_cooldown_candidate(&candidate, true);
        assert_eq!(index.reason_reoffer_cooldown_deferred_count(), 1);
        assert!(index.reason_reoffer_conflict_is_deferred("refused-entity", "refused-body"));
        assert!(!index.reason_reoffer_conflict_is_deferred("refused-entity", "another-body"));
        // Non-blocking debt remains counted before the ordinary timer is due.
        index
            .quarantined_snapshot_fingerprints
            .get_mut("refused-entity")
            .unwrap()
            .retry_after_unix_seconds = u64::MAX;
        index.activate_reason_reoffer_cooldowns(cooldown.clone());
        index.note_reason_reoffer_cooldown_candidate(&candidate, true);
        assert_eq!(index.reason_reoffer_cooldown_deferred_count(), 1);
        index
            .quarantined_snapshot_fingerprints
            .insert("refused-entity".into(), conflict.clone());
        let saved: ScanIndex =
            serde_json::from_slice(&serde_json::to_vec(&index).unwrap()).unwrap();
        assert!(saved.reason_reoffer_cooldowns.is_empty(), "never persisted");
        assert_eq!(saved.reason_reoffer_cooldown_deferred_count(), 0);

        // Any file change still re-reads. Once any incidence breaks the bound,
        // another unchanged incidence cannot restore it during this traversal.
        let mut grown = candidate.clone();
        grown.size_bytes += 1;
        index.note_reason_reoffer_cooldown_candidate(&grown, false);
        index.note_reason_reoffer_cooldown_candidate(&candidate, true);
        assert_eq!(index.reason_reoffer_cooldown_deferred_count(), 0);
        assert!(!index.reason_reoffer_conflict_is_deferred("refused-entity", "refused-body"));
        index.activate_reason_reoffer_cooldowns(cooldown.clone());
        assert_eq!(
            index.candidate_decision_with_reason_at(&grown, 0),
            (
                CandidateDecision::Parse,
                Some(CandidateParseReason::TranscriptChanged)
            )
        );
        let mut resourced = candidate.clone();
        resourced.source_file_fingerprint = "changed-sidecars".into();
        assert_eq!(
            index.candidate_decision_with_reason_at(&resourced, 0),
            (
                CandidateDecision::Parse,
                Some(CandidateParseReason::SourceChanged)
            )
        );

        // An unrelated due obligation in the same file still selects it.
        index
            .file_snapshot_fingerprints
            .get_mut(&key)
            .unwrap()
            .insert("sibling-entity".into());
        index
            .snapshot_activity_at
            .insert("sibling-entity".into(), Some("2026-10-14T10:00:00Z".into()));
        index.quarantined_snapshot_fingerprints.insert(
            "sibling-entity".into(),
            SnapshotQuarantineRecord {
                upload_body_witness: Some("sibling-body".into()),
                ..conflict.clone()
            },
        );
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            reread
        );
        index
            .file_snapshot_fingerprints
            .get_mut(&key)
            .unwrap()
            .remove("sibling-entity");
        assert_eq!(
            index.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip
        );

        // A different body is new work, never the refused one.
        index.activate_reason_reoffer_cooldowns(BTreeMap::from([(
            "refused-entity".to_string(),
            "other-body".to_string(),
        )]));
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            reread
        );

        // A release label alone keeps the cooldown; a changed contract re-reads.
        index.activate_reason_reoffer_cooldowns(cooldown.clone());
        let mut older = conflict.clone();
        older.witness.parser_version.push_str("-older");
        index
            .quarantined_snapshot_fingerprints
            .insert("refused-entity".into(), older.clone());
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            (CandidateDecision::Skip, None)
        );
        older.witness.contract.push_str("-older");
        index
            .quarantined_snapshot_fingerprints
            .insert("refused-entity".into(), older);
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            reread
        );
        index
            .quarantined_snapshot_fingerprints
            .insert("refused-entity".into(), conflict.clone());
        assert_eq!(
            index.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip
        );

        // The daily lease alone lets the exact body through.
        let hinted = index.activate_reason_reoffer_retries(cooldown.clone());
        assert_eq!(hinted, vec![PathBuf::from(&key)]);
        assert_eq!(
            index.candidate_decision_with_reason_at(&candidate, 0),
            reread
        );
        index.activate_reason_reoffer_cooldowns(cooldown);
        index.note_reason_reoffer_cooldown_candidate(&candidate, true);
        assert_eq!(index.reason_reoffer_cooldown_deferred_count(), 0);
    }

    #[test]
    fn partial_commit_reparses_unchanged_rearmed_file_after_held_sibling() {
        let key = "/opaque/rearmed.jsonl".to_string();
        let mut previous = ScanIndex::default();
        let mut entry = manifest_index_entry(Some("old-entity"));
        entry.scan_identity_version = Some(LOCAL_SCAN_INDEX_IDENTITY_VERSION.into());
        previous.files.insert(key.clone(), entry.clone());
        previous
            .file_snapshot_fingerprints
            .insert(key.clone(), BTreeSet::from(["old-entity".to_string()]));
        previous
            .snapshot_activity_at
            .insert("old-entity".into(), Some("2026-10-14T10:00:00Z".into()));
        let mut candidate = test_candidate(PathBuf::from(&key));
        candidate.size_bytes = entry.size_bytes;
        candidate.modified_unix_seconds = entry.modified_unix_seconds;
        candidate.modified_unix_nanos = entry.modified_unix_nanos.unwrap();
        candidate.source_file_fingerprint = entry.source_file_fingerprint.clone();
        assert_eq!(
            previous.candidate_decision_at(&candidate, 0),
            CandidateDecision::Skip
        );

        let sibling = "/opaque/held.jsonl".to_string();
        previous
            .files
            .insert(sibling.clone(), manifest_index_entry(Some("old-sibling")));
        previous
            .file_snapshot_fingerprints
            .insert(sibling.clone(), BTreeSet::from(["old-sibling".into()]));
        let mut scanned = previous.clone();
        scanned
            .files
            .get_mut(&key)
            .unwrap()
            .source_file_fingerprint
            .clear();
        scanned
            .files
            .get_mut(&sibling)
            .unwrap()
            .last_snapshot_fingerprint = Some("held-sibling".into());
        scanned
            .file_snapshot_fingerprints
            .insert(sibling.clone(), BTreeSet::from(["held-sibling".into()]));
        let checkpoint = scanned.committable_subset(&previous, &BTreeSet::new(), &BTreeMap::new());
        let saved: ScanIndex =
            serde_json::from_slice(&serde_json::to_vec(&checkpoint).unwrap()).unwrap();
        assert_eq!(
            saved.candidate_decision_at(&candidate, 0),
            CandidateDecision::Parse
        );
        assert_eq!(
            saved.files[&sibling].last_snapshot_fingerprint.as_deref(),
            Some("old-sibling")
        );
        assert_eq!(
            saved.file_snapshot_fingerprints[&key],
            previous.file_snapshot_fingerprints[&key]
        );
    }

    #[test]
    fn partial_commit_grants_no_upload_context_proof_and_forces_policy_reparse() {
        let mut previous = ScanIndex::default();
        previous.files.insert(
            "/opaque/accepted.jsonl".to_string(),
            manifest_index_entry(Some("old-accepted")),
        );
        previous.files.insert(
            "/opaque/pending.jsonl".to_string(),
            manifest_index_entry(Some("old-pending")),
        );

        let mut scanned = previous.clone();
        scanned.activate_upload_context("context-b".to_string());
        scanned.files.insert(
            "/opaque/accepted.jsonl".to_string(),
            manifest_index_entry(Some("new-accepted")),
        );
        scanned.files.insert(
            "/opaque/pending.jsonl".to_string(),
            manifest_index_entry(Some("new-pending")),
        );
        let mut committable = scanned.committable_subset(
            &previous,
            &BTreeSet::from(["new-accepted".to_string()]),
            &BTreeMap::new(),
        );
        committable.mark_bounded_sweep_unsettled();

        committable.activate_upload_context("context-b".to_string());
        let mut candidate = test_candidate(PathBuf::from("/opaque/accepted.jsonl"));
        let entry = committable
            .files
            .get("/opaque/accepted.jsonl")
            .expect("accepted file is safely checkpointed");
        candidate.size_bytes = entry.size_bytes;
        candidate.modified_unix_seconds = entry.modified_unix_seconds;
        candidate.modified_unix_nanos = entry.modified_unix_nanos.unwrap_or_default();
        candidate.source_file_fingerprint = entry.source_file_fingerprint.clone();
        assert_eq!(
            committable.candidate_decision(&candidate),
            CandidateDecision::Parse,
            "an accepted page without its own context proof is re-derived"
        );
        assert!(committable.bounded_sweep_had_unsettled_upload);
    }

    #[test]
    fn committable_subset_uses_exact_multi_entity_set_and_preserves_quarantine() {
        let accepted = "a".repeat(64);
        let quarantined = "b".repeat(64);
        let mut scanned = ScanIndex::default();
        scanned.files.insert(
            "split.jsonl".to_string(),
            manifest_index_entry(Some("set-hash")),
        );
        scanned.file_snapshot_fingerprints.insert(
            "split.jsonl".to_string(),
            BTreeSet::from([accepted.clone(), quarantined.clone()]),
        );

        let committable = scanned.committable_subset(
            &ScanIndex::default(),
            &BTreeSet::from([accepted]),
            &BTreeMap::from([(
                quarantined.clone(),
                snapshot_quarantine_record(SnapshotSource::Codex),
            )]),
        );
        assert!(committable.files.contains_key("split.jsonl"));
        assert_eq!(
            committable.file_snapshot_fingerprints["split.jsonl"].len(),
            2
        );
        assert_eq!(
            committable.quarantined_snapshot_fingerprints,
            BTreeMap::from([(
                quarantined,
                snapshot_quarantine_record(SnapshotSource::Codex),
            )])
        );
        assert_eq!(
            committable
                .manifest(SnapshotSource::Codex, 183)
                .entity_count,
            1,
            "quarantine is checkpointed but never advertised as server-held"
        );
        let retry = scanned.committable_subset(
            &committable,
            &scanned.file_snapshot_fingerprints["split.jsonl"],
            &BTreeMap::new(),
        );
        state_v2::money_test_support::assert_selected_saves(
            scan_index_persistence::Source::Claude,
            &ScanIndex::default(),
            &[committable, retry],
        );
    }

